\label{lem:3cosets} Let $\{ A,B,C\}$ be a
rainbow--free $3$--coloring of an abelian group $G$ with odd order
$n$. Let $H<G$ be a subgroup of $G$ and let $(X,Y,Z)$ be a triple of
$H$--cosets in arithmetic progression.

If each of $X_A$, $Y_B$ and $Z_C$ is non--empty, then
\begin{equation}\label{eq:3cosets}
\max\{ |X_A|+|Y_B|, |X_A|+|Z_C|,|Z_C|+|Y_B|\}\leq |H|.
\end{equation}

\textcolor{black}{In particular, none of the three cosets can be monochromatic.}

Moreover, if equality holds then there is a proper subgroup $K<H$
such that two of the sets $X_A, Y_B, Z_C$ are $K$--periodic (the two
involved in the equality holding) and the third one is contained in
a single coset of $K$.
\label{lem:A=1} \textcolor{black}{If
$|A|=1$ then the coloring is $H$--regular  with $H=\{ 0\}$.}
\label{lem:onecoset}
\textcolor{black}{If $A$ is contained in a single coset of a proper
subgroup $H'<G$ and $|A|>1$, then the coloring is $H$--regular for some proper subgroup  $H<G$.}
\label{lem:A=2} \textcolor{black}{If
$|A|=2$ then the coloring is $H$--regular for some $H<G$.}
\label{lem:a=b=3}
 \textcolor{black}{If
$|A|=|B|=3$ and $|A+B|=6$, then the coloring is $H$--regular  for some $H<G$.}
\label{lem:almost_p}
Assume that $4\le |A|\le |B|\le |C|$. \textcolor{black}{If $A$ and $B$
are almost--progressions with the same difference $d$, then the coloring is $H$--regular  for some $H<G$.}
\label{lem:periodic}
\textcolor{black}{If the three color classes $A,B,$ and $C$ are
$K$--periodic for some subgroup $K<G$, then the coloring is $H$--regular
for some $H<G$.}
\label{lem:qp}
\textcolor{black}{If $A=A_0\cup A_1$ and $B=B_0\cup B_1$ are
 $K$--quasiperiodic decompositions of $A$ and $B$
with  $K$ a nontrivial proper subgroup of $G$,
 then the coloring is $H$--regular for some $H<G$.}
\label{lem:A+Bperiodic}
If $A+B$ is \textcolor{black}{$K$}--periodic for some proper nontrivial subgroup \textcolor{black}{$K$} of
$G$, \textcolor{black}{then the coloring is $H$--regular for some subgroup $H<G$. }
\label{lem:aqp}
