\includegraphics[width=7cm]{Gamma_x}
\caption{Realization of the event $\Gamma_x$.}
\label{fig Gamma_x}
\end{center}
\end{figure}


Observe that for $x,y \in V$
\begin{eqnarray*}
\lefteqn{ \{ x \mbox{ connected to } y \} } \\
&\supset& \{ x \mbox{ connected to } S(x,\textstyle{\frac{1}{2n_x}}) \} \cap \Gamma_x \cap \{ y \mbox{ connected to } S(y,\textstyle{\frac{1}{2n_y}}) \} \cap \Gamma_y.
\end{eqnarray*}
 Since all four events on the right-hand side are increasing and have positive probability, we can apply the FKG inequality to conclude that for all $x,y\in V$ we have $\ensuremath{\mathbb{P}}(x \mbox{ connected to } y) > 0$.

