lemma:
\label{prop:minsol}
Assume that all parameters $\tilde{\alpha}_{N,n}$, $\alpha_{N,n}$, and $\beta_N$ are positive. Then there exist unique minimizers $\Phi_N\in\textnormal{Pol}_{N}$ and $\tilde{\Psi}_N\in\textnormal{Pol}_{\lfloor\kappa N\rfloor}$ of the functional $\mathcal{F}$ in \eqref{eqn:mineq2} that are determined by the symbols $\phi=(\Phi_N^\wedge(1)\sigma_1,\ldots,\Phi_N^\wedge(N)\sigma_{N},\tilde{\Phi}_{N}^\wedge(1),\ldots,\tilde{\Phi}_{N}^\wedge(\lfloor\kappa N\rfloor))^T$ which solve the linear equations
\begin{align}\label{eqn:lineq1}
\mathbf{M}\phi=\alpha,
\end{align}
where 
\begin{align}
\mathbf{M}=\left(\begin{array}{c|c}\mathbf{D}_1+\mathbf{P}_1&-\mathbf{P}_2\\\hline-\mathbf{P}_3&\mathbf{D}_2+\mathbf{P}_4\end{array}\right),
\end{align}
and $\alpha=(\alpha_{N,1},\ldots,\alpha_{N,N},\tilde{\alpha}_{N,1},\ldots,\tilde{\alpha}_{N,\lfloor\kappa N\rfloor})^T$. The diagonal matrices $\mathbf{D}_1$, $\mathbf{D}_2$ are given by 
\begin{align}
\mathbf{D}_1=\textnormal{diag}\left(\frac{\beta_N}{\sigma_n^2}+\alpha_{N,n}\right)_{n=0,\ldots,N}, \qquad\mathbf{D}_2=\textnormal{diag}\big(\tilde{\alpha}_{N,n}\big)_{n=0,\ldots,\lfloor\kappa N\rfloor},
\end{align}
whereas $\mathbf{P}_1$,\ldots, $\mathbf{P}_4$ are submatrices of the Gram matrix $\big(P_{n,m}^\rho\big)_{n,m=0,\ldots, \lfloor\kappa N\rfloor}$. More precisely,
\begin{align}
\mathbf{P}_1=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,N},&\qquad \mathbf{P}_2=\big(P_{n,m}^\rho\big)_{n=0,\ldots,N\atop m=0,\ldots,\lfloor\kappa N\rfloor},
\\\mathbf{P}_3=\big(P_{n,m}^\rho\big)_{n=0,\ldots,\lfloor\kappa N\rfloor\atop m=0,\ldots,N},&\qquad\mathbf{P}_4=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}.
\end{align}
with
\begin{align}
P_{n,m}^\rho=\frac{(2n+1)(2m+1)}{2}\int_{-1}^{1-\rho}P_n(t)P_m(t)dt.
\end{align}
\label{lem:loc}
Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some fixed $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor\kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+( \lfloor\kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty.\label{eqn:ass11}
\end{align}
The same relation shall hold true for $\tilde{\alpha}_{N,n}$. If the scaling kernel $\Phi_N\in\textnormal{Pol}_{N}$ and the wavelet kernel $\tilde{\Psi}_N\in\textnormal{Pol}_{\lfloor\kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq2}, then
\begin{align} \label{eqn:optloc2}
\lim_{N\to\infty}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}=0.
\end{align}
\label{prop:minsol4}
Assume that all parameters $\tilde{\alpha}_{N,n}$, $\alpha_{N,n}$, and $\beta_N$ are positive. Then there exists unique minimizers $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor\kappa N\rfloor}$ of the functional $\mathcal{F}$ in \eqref{eqn:mineq4} that are determined by $\phi=(\mathbf{\Phi}_N^\wedge(1)\sigma_1,\ldots,\mathbf{\Phi}_N^\wedge(N)\sigma_{N},\tilde{\mathbf{\Phi}}_{N}^\wedge(1),\ldots,\tilde{\mathbf{\Phi}}_{N}^\wedge(\lfloor\kappa N\rfloor))^T$ which solves the linear equations
\begin{align}\label{eqn:lineq4}
\mathbf{M}{\phi}=\alpha,
\end{align}
where 
\begin{align}
\mathbf{M}=\left(\begin{array}{c|c}\mathbf{D}_1+\mathbf{P}_1&-\mathbf{P}_2\\\hline-\mathbf{P}_3&\mathbf{D}_2+\mathbf{P}_4\end{array}\right),
\end{align}
and $\alpha=(\alpha_{N,1},\ldots,\alpha_{N,N},\tilde{\alpha}_{N,1},\ldots,\tilde{\alpha}_{N,\lfloor\kappa N\rfloor})^T$. The diagonal matrices $\mathbf{D}_1$, $\mathbf{D}_2$ are given by 
\begin{align}
\mathbf{D}_1=\textnormal{diag}\left(\frac{\beta_N}{\sigma_n^2}+\alpha_{N,n}\right)_{n=0,\ldots,N}, \qquad\mathbf{D}_2=\textnormal{diag}\big(\tilde{\alpha}_{N,n}\big)_{n=0,\ldots,\lfloor\kappa N\rfloor},
\end{align}
whereas $\mathbf{P}_1$,\ldots, $\mathbf{P}_4$ are submatrices of the Gram matrix $\big(P_{n,m}^\rho\big)_{n,m=0,\ldots, \lfloor\kappa N\rfloor}$. More precisely,
\begin{align}
\mathbf{P}_1=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,N},&\qquad \mathbf{P}_2=\big(P_{n,m}^\rho\big)_{n=0,\ldots,N\atop m=0,\ldots,N\lfloor\kappa N\rfloor},
\\\mathbf{P}_3=\big(P_{n,m}^\rho\big)_{n=0,\ldots,\lfloor\kappa N\rfloor\atop m=0,\ldots,N},&\qquad\mathbf{P}_4=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}.
\end{align}
with
\small\begin{align}
P_{n,m}^\rho=&\frac{(2n+1)(2m+1)}{16\pi^2}\int_{-1}^{1-\rho}P_n\left(t\right)P_m\left(t\right)dt
\\&+\frac{(2n+1)(2m+1)}{16\pi^2n(n+1)m(m+1)}\bigg(\int_{-1}^{1-\rho}(1+t^2)P_n'(t)P_m'(t)dt+\int_{-1}^{1-\rho}(1-t^2)^2P_n''(t)P_m''(t)dt\nonumber
\\&\quad-\int_{-1}^{1-\rho}t(1-t^2)P_n''(t)P_m'(t)dt-\int_{-1}^{1-\rho}t(1-t^2)P_n'(t)P_m''(t)dt\bigg),\nonumber
\end{align}\normalsize
for $n\not=0$ and $m\not=0$. If $n=0$ or $m=0$, then $P_{n,m}^\rho=\frac{(2n+1)(2m+1)}{16\pi^2}\int_{-1}^{1-\rho}P_n\left(t\right)P_m\left(t\right)dt$. By $P_n'$, $P_n''$ we mean the first and second order derivatives of the Legendre polynomials.
\label{lem:lockernel2}
Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor \kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+(\lfloor \kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty.\label{eqn:ass5}
\end{align}
An analogous relation shall hold true for $\tilde{\alpha}_{N,n}$. If the scaling kernel $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and the wavelet kernel $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor \kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq4}, then
\begin{align} \label{eqn:optloc3}
\lim_{N\to\infty}\frac{\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1])}}=0.
\end{align}

proof:
First we observe that the representation \eqref{eqn:psin} of the kernel $\tilde{\Psi}_N$ and its zonality together with the addition theorem for spherical harmonics imply 
\small
\begin{align}\label{eqn:psinorm}
&8\pi^2 r^4\left\|\tilde{\Psi}_N\right\|^2_{L^2([-1,1-\rho])}
\\&=\frac{8\pi^2 r^4}{r^4}\int_{-1}^{1-\rho}\Bigg|\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi}\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)P_n(t)\Bigg|^2dt\nonumber
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\frac{(2n+1)(2m+1)}{2}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)\int_{-1}^{1-\rho}\!\!\!\!\!\!\!P_n(t)P_m(t)dt\nonumber
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)P_{n,m}^\rho.\nonumber
\end{align}
\normalsize
Inserting \eqref{eqn:psinorm} into \eqref{eqn:mineq2} and then differentiating the whole expression with respect to $\Phi_N^\wedge(n)\sigma_n$ and $\tilde{\Phi}_{N}^\wedge(n)$ leads to 
\begin{align}
-2\alpha_{N,n}(1-\Phi_N^\wedge(n)\sigma_n)+2\beta_N\frac{\Phi_N^\wedge(n)\sigma_n}{\sigma_n^2}-2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align} 
for $n=0,\ldots,N$, and
\begin{align}
-2\tilde{\alpha}_{N,n}(1-\tilde{\Phi}_{N}^\wedge(n))+2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align}
for $n=0,\ldots,\lfloor\kappa N\rfloor$, respectively. Setting the two expressions above equal to zero, a proper reordering leads to the linear equation \eqref{eqn:lineq1}. At last, we observe that the matrix $(P_{n,m}^\rho)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}$ is positive definite (since it represents a Gram matrix of linearly independent functions) and that all appearing diagonal matrices are positive definite due to positive matrix entries. Thus, the matrix $\mathbf{M}$ is positive definite and the linear system \eqref{eqn:lineq1} is uniquely solvable and leads to a minimum of \eqref{eqn:mineq2}.

As an auxiliary set of kernels, we define the Shannon-type kernels $\Phi_N^{Sh}$ and $\tilde{\Psi}_N^{Sh}$ via the symbols
\begin{align}
\big(\Phi_N^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}\frac{1}{\sigma_n},&n\leq N,\\0,&\textnormal{else},\end{array}\right.\qquad \big(\tilde{\Phi}_{N}^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}1,&n\leq \lfloor\kappa N\rfloor,\\0,&\textnormal{else},\end{array}\right.
\end{align}
and $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=\big(\tilde{\Phi}_N^{Sh}\big)^\wedge(n)-\big(\Phi_N^{Sh}\big)^\wedge(n)\sigma_n$. $\Phi_N^{Sh}$ represents the kernel of the so-called truncated singular value decomposition for the downward continuation operator ${T}^{down}$. By using the addition theorem for spherical harmonics and properties of the Legendre polynomials, we obtain
\begin{align}
\mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})&=\beta_N\sum_{n=0}^{N}\frac{1}{\sigma_n^2}+8\pi^2 r^4\big\|\tilde{\Psi}_N^{Sh}\big\|^2_{L^2([-1,1-\rho])}\label{eqn:shannonest}
\\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+8\pi^2\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left\|P_n\right\|^2_{L^2([-1,1])}\nonumber
\\&= \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2.\nonumber
\end{align}
The kernels that minimize $\mathcal{F}$ are denoted by $\Phi_N$ and $\tilde{\Psi}_N$. In consequence,
\begin{align}
\tilde{\alpha}_{N,n}\big(1-\tilde{\Phi}_{N}^\wedge(n)\big)^2&\leq\mathcal{F}(\Phi_N,\tilde{\Psi}_N)\leq \mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})
\\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2,\nonumber
\end{align}
for all $n\leq \lfloor\kappa N\rfloor$. In combination with \eqref{eqn:ass1}, this leads to
\begin{align}\label{eqn:conphij}
\big|1-\tilde{\Phi}_{N}^\wedge(n)\big|= \mathcal{O}(N^{-1-\delta}),
\end{align}
uniformly for all $n\leq \lfloor\kappa N\rfloor$ and $N\to\infty$. The estimate $|1-\Phi_N^\wedge(n)\sigma_n|=\mathcal{O}(N^{-1-\delta})$ follows in the same manner and holds uniformly for all $n\leq N$ and $N\to\infty$. Finally, since $\tilde{\Phi}_{N}^\wedge(n)=0$ for $n> \lfloor\kappa N\rfloor$, we end up with
\begin{align}
\lim_{N\to\infty}\sup_{n=0,1,\ldots}\frac{|1-\tilde{\Phi}_{N}^\wedge(n)|}{(n+\frac{1}{2})^{s}}=0,
\end{align}
which shows that the first term on the right hand side of the error estimate \eqref{eqn:errorestfinal} vanishes. The second term can be treated analogously. 

Due to the uniform boundedness of $|\Phi_J^\wedge(n)\sigma_n|$, there exists some constant $C>0$ such that \eqref{eqn:propx} implies
\begin{align}
\lim_{N\to\infty}\ensuremath{\varepsilon}_1\sup_{n=0,1,\ldots}\left|\Phi_N^\wedge(n)\right|\leq C\lim_{N\to\infty}\ensuremath{\varepsilon}_1\left(\frac{R}{r}\right)^{N}=0.
\end{align}
so that the third term on the right hand side of \eqref{eqn:errorestfinal} vanishes as well. The fourth term does not vanish. However, taking a closer look at the derivation of this term, we see that it suffices to show that $\big\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\big\|_{L^2(\Omega_r)}$ tends to zero (where $F$ stands for $U^+$ or $E_2$). Using the previous results and $|\tilde{\Psi}_N^\wedge(n)|\leq |1-{\Phi}_N^\wedge(n)\sigma_n|+|1-\tilde{\Phi}_N^\wedge(n)|$, it follows that
\begin{align}
\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}^2\leq \mathcal{O}(N^{-2\delta})+C\sum_{n=N+1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\left|F_r^\wedge(n,k)\right|^2,
\end{align}
for some constant $C>0$. Latter vanishes for $N\to\infty$ since $F$ (i.e., $U^+$ or $E_2$) is of class $L^2(\Omega_r)$. In order to handle the last term of the error estimate \eqref{eqn:errorestfinal}, it has to be shown that $\|\tilde{\Psi}_N\|_{L^2([-1,1-\rho])}$ tends to zero. This, again, is generally not true. But, taking a closer look at the derivation of the estimate indicates that it suffices to show that
\small\begin{align}\label{eqn:altterms}
\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}, \qquad \ensuremath{\varepsilon}_2\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) E_2(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\end{align}\normalsize
vanish as $N\to\infty$. For the left expression we obtain
\begin{equation}\label{eqn:locest}
\begin{aligned}
&\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\tilde{\Psi}^{Sh}_{N}(\cdot,y)-\tilde{\Psi}_{N}(\cdot,y)\right) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+2\pi r^2\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\|_{L^2([-1,1-\rho])} \|U^+\|_{L^1(\Omega_r)},
\end{aligned}
\end{equation}
where Young's inequality has been used in the last row. Since $U^+\in \mathcal{H}_s(\Omega_r)$, $s\geq 2$, Proposition \ref{prop:loc1} implies that the first term on the right hand side of \eqref{eqn:locest} tends to zero as $N\to\infty$. The second term on the right hand side of \eqref{eqn:locest} can be treated as follows 
\begin{equation}
\begin{aligned}
&\big\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\big\|_{L^2([-1,1-\rho])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left|\tilde{\Psi}_N^\wedge(n)-\left(\tilde{\Psi}^{Sh}_N\right)^\wedge(n)\right|^2\|P_n\|_{L^2([-1,1])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\left|\left|\tilde{\Phi}_{N}^\wedge(n)-1\right|+\left|{\Phi}_N^\wedge(n)\sigma_n-1\right|\chi_{[0,N]}(n)\right|^2
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\mathcal{O}\left(N^{-2(1+\delta)}\right)=\mathcal{O}\left(N^{-2\delta}\right).
\end{aligned}
\end{equation}
By $\chi_{[0,N]}(n)$ we mean the characteristic function, i.e., it is equal to 1 if $n=0,\ldots,N$, and equal to 0 otherwise. In conclusion, the left expression in \eqref{eqn:altterms} vanishes as $N\to\infty$. For the right expression in \eqref{eqn:altterms}, we obtain the desired result in a similar but easier manner. Finally, combining all steps of the proof, we have shown that the right hand side of the error estimate \eqref{eqn:errorestfinal} converges to zero, which yields \eqref{eqn:convres}. 

The function $F_N(t)={|\tilde{\Psi}_N(t)|^2}/{\|\tilde{\Psi}_N\|^2_{L^2([-1,1])}}$ can be regarded as the density function of a random variable $t\in[-1,1]$. Thus, we can write
\begin{align}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}&=\int_{-1}^{1-\rho}F_N(t)dt=P_N(t< 1-\rho)=1-P_N\big(t-E_N(t)\geq 1-\rho-E_N(t)\big)\nonumber
\\&\leq \frac{V_N(t)}{V_N(t)+ (1-\rho-E_N(t))^2},
\end{align}
where we have used Cantelli's inequality for the last estimate. By $P_N(t< a)$ we mean the probability (with respect to the density function $F_N$) that $t$ lies in the interval $[-1,a)$ while $P_N(t\geq a)$ means the probability of $t$ being in the interval $[a,1]$. Furthermore, $E_N(t)$ denotes the expected value of $t$ and $V_N(t)=E(t^2)-(E(t))^2$ the variance of $t$. In other words, we are done if we can show that $\lim_{N\to\infty}E_N(t)=1$ and $\lim_{N\to \infty}V_N(t)=0$. 

First, we use the addition theorem for spherical harmonics and the recurrence relation  $tP_n(t)=\frac{1}{2n+1}\left((n+1)P_{n+1}(t)+nP_{n-1}(t)\right)$ to obtain  
\begin{align}\label{eqn:et1}
\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt&= \frac{1}{r^2} \sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi}\frac{2m+1}{4\pi}\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(m)\int_{-1}^1tP_n(t)P_m(t)dt
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{16\pi^2r^2}\tilde{\Psi}_N^\wedge(n)\left(n\tilde{\Psi}_N^\wedge(n-1)+(n+1)\tilde{\Psi}_N^\wedge(n+1)\right)\int_{-1}^1|P_n(t)|^2 dt\nonumber
\\&=\frac{1}{8\pi^2r^2}\sum_{n=0}^{\lfloor\kappa N\rfloor}n\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(n-1)+(n+1)\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(n+1).\nonumber
\end{align}
From \eqref{eqn:conphij} and the corresponding estimate for $\Phi_N^\wedge(n)\sigma_n$ we find $|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2(1+\delta)})$ for $n\leq N$, and $|1-\tilde{\Psi}_N^\wedge(n)|^2=|1-\tilde{\Phi}_{N}^\wedge(n)|^2=\mathcal{O}(N^{-2(1+\delta)})$, for $N+1\leq n\leq \lfloor\kappa N\rfloor$. As a consequence,  \eqref{eqn:et1} implies
\begin{align}\label{eqn:et11}
&\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt
\\&=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2\left(\frac{n}{2n+1}\frac{\tilde{\Psi}_N^\wedge(n-1)}{\tilde{\Psi}_N^\wedge(n)}+\frac{n+1}{2n+1}\frac{\tilde{\Psi}_N^\wedge(n+1)}{\tilde{\Psi}_N^\wedge(n)}\right),\nonumber
\end{align}
where $\sup_{N+1\leq n\leq\lfloor \kappa N\rfloor}\big|1-\big(\frac{n}{2n+1}{\tilde{\Psi}_N^\wedge(n-1)}/{\tilde{\Psi}_N^\wedge(n)}+\frac{n+1}{2n+1}{\tilde{\Psi}_N^\wedge(n+1)}/{\tilde{\Psi}_N^\wedge(n)}\big)\big|\leq\varepsilon_N$, for  some $\varepsilon_N>0$ that satisfies $\varepsilon_N\to0$ as $N\to\infty$. The term $\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2$ can be expressed similarly by
\begin{align}\label{eqn:et2}
\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2=\sum_{n=0}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2.
\end{align}
Thus, combining \eqref{eqn:et1}--\eqref{eqn:et2}, we obtain
\begin{align}
\lim_{N\to\infty}E_N(t)=\lim_{N\to\infty}\int_{-1}^1 t|F_N(t)| dt=\lim_{N\to\infty}\frac{\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt}{\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2}=1.
\end{align}
In a similar fashion it can be shown that $\lim_{N\to\infty}E_N(t^2)=1$, implying $\lim_{N\to\infty}V_N(t)=0$, which concludes the proof.

We first observe that
\begin{align}\label{eqn:vectloceq1}
&\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\tilde{\mathbf{\Psi}}^{Sh}_{N}(x,y) f(y)d\omega(y)
\\&=\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\left(\sum_{i=1}^2\sum_{n=N+1}^{\lfloor\kappa N\rfloor}\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(i)}\left(\xi\right)\otimes \frac{1}{r}y_{n,k}^{(i)}\left(\eta\right)\right) f(r\eta)d\omega(r\eta)\nonumber
\\&=\sum_{i=1}^2\sum_{n=N+1}^{\lfloor\kappa N\rfloor}\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(i)}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}y_{n,k}^{(i)}\left(\eta\right)\cdot f(r\eta)d\omega(r\eta),\nonumber
\end{align}
where, as always, $\xi=\frac{x}{|x|}$ and $\eta=\frac{y}{|y|}$. Since $f$ is of class $\mathfrak{h}_s(\Omega_r)$, $s\geq 2$, it follows that $f(x)=\xi F_1(x)+\nabla^*_\xi F_2(x)$ for some scalar functions $F_1$ of class $\mathcal{H}_s(\Omega_r)$ and $F_2$ of class $\mathcal{H}_{s+1}(\Omega_r)$. Taking a closer look at the terms of type $i=1$ in \eqref{eqn:vectloceq1}, using the orthogonality of $\xi$ and $\nabla^*_\xi$, we obtain
\begin{align}
&\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(1)}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}y_{n,k}^{(1)}\left(\eta\right)\cdot f(r\eta)d\omega(r\eta)\label{eqn:eqn1}
\\&=\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(1)}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}y_{n,k}^{(1)}\left(\eta\right)\cdot \left(\eta F_1(r\eta)+\nabla^*_{\eta}F_2(r\eta)\right)d\omega(r\eta)\nonumber
\\&=\sum_{k=1}^{2n+1}\frac{1}{r^2}\xi Y_{n,k}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}Y_{n,k}\left(\eta\right)F_1(r\eta)d\omega(r\eta)\nonumber
\\&=\frac{1}{r^2}\xi\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{2n+1}{4\pi}P_n\left(\xi\cdot\eta\right)F_1(r\eta)d\omega(r\eta).\nonumber
\end{align}
For the terms of type $i=2$, the use of Green's formulas (cf. \cite{ger11} for more details) and the addition theorem for spherical harmonics implies
\begin{align}
&\xi\wedge\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(2)}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}y_{n,k}^{(2)}\left(\eta\right)\cdot f(r\eta)d\omega(r\eta)\label{eqn:shit}
\\&=\xi\wedge\sum_{k=1}^{2n+1}\frac{1}{r}y_{n,k}^{(2)}\left(\xi\right)\nonumber
\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{1}{r}\frac{1}{\sqrt{n(n+1)}}\nabla^*_{\eta}Y_{n,k}\left(\eta\right)\cdot \nabla^*_{\eta}F_2(r\eta)d\omega(r\eta)\nonumber
\\&=-\xi\wedge\sum_{k=1}^{2n+1}\frac{1}{r^2}\frac{1}{{n(n+1)}}\nabla^*_{\xi}Y_{n,k}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\left(\Delta^*_{\eta}Y_{n,k}\left(\eta\right)\right)F_2(r\eta)d\omega(r\eta)\nonumber
\\&\quad+\xi\wedge\sum_{k=1}^{2n+1}\frac{1}{r^2}\frac{1}{{n(n+1)}}\nabla^*_{\xi}Y_{n,k}\left(\xi\right)\int_{\partial\mathcal{C}_r(x,\rho)}F_2(r\eta)\frac{\partial}{\partial\nu_\eta}Y_{n,k}\left(\eta\right)d\sigma(r\eta)\nonumber



\\&=\sum_{k=1}^{2n+1}\frac{1}{r^2}L^*_{\xi}Y_{n,k}\left(\xi\right)\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}Y_{n,k}\left(\eta\right)F_2(r\eta)d\omega(r\eta)\nonumber
\\&\quad+\frac{1}{r^2}\frac{1}{{ n(n+1)}}\int_{\partial\mathcal{C}_r(x,\rho)}F_2(r\eta)\frac{2n+1}{{4\pi}}L^*_{\xi}\frac{\partial}{\partial\nu_\eta}P_{n}\left(\xi\cdot\eta\right)d\sigma(r\eta)\nonumber
\\&=-\frac{1}{r^2}\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}F_2(r\eta)\frac{2n+1}{4\pi}L_{\eta}^*P_n\left(\xi\cdot\eta\right)d\omega(r\eta)\nonumber
\\&\quad+\frac{1}{r^2}\frac{1}{{ n(n+1)}}\int_{\partial\mathcal{C}_r(x,\rho)}F_2(r\eta)\frac{2n+1}{{4\pi}}L^*_{\xi}\frac{\partial}{\partial\nu_\eta}P_{n}\left(\xi\cdot\eta\right)d\sigma(r\eta)\nonumber
\\&=\frac{1}{r^2}\int\limits_{\Omega_r\setminus\mathcal{C}_r(x,\rho)}\frac{2n+1}{4\pi}P_n\left(\xi\cdot\eta\right)L_{\eta}^*F_2(r\eta)d\omega(r\eta)\nonumber
\\&\quad+\frac{1}{r^2}\int_{\partial\mathcal{C}_r(x,\rho)}\tau_{\eta}F_2(r\eta)\frac{2n+1}{{4\pi}}P_{n}\left(\xi\cdot\eta\right)d\sigma(r\eta)\nonumber
\\&\quad+\frac{1}{r^2}\frac{1}{{ n(n+1)}}\int_{\partial\mathcal{C}_r(x,\rho)}F_2(r\eta)\frac{2n+1}{{4\pi}}L^*_{\xi}\frac{\partial}{\partial\nu_\eta}P_{n}\left(\xi\cdot\eta\right)d\sigma(r\eta)\nonumber
\end{align}\normalsize
By $\frac{\partial}{\partial\nu_\eta}$ we mean the normal derivative at $r\eta\in\partial\mathcal{C}_r(x,\rho)$, and $\tau_\eta$ denotes the tangential unit vector at $r\eta\in\partial\mathcal{C}_r(x,\rho)$. The reason for the application of $\xi\wedge$ in \eqref{eqn:shit} is that we can then work with the operator $L_{\xi}^*$ instead of $\nabla_\xi ^*$. The surface curl gradient has the nice property $L_{\xi}^*P_{n}\left(\xi\cdot\eta\right)=-L_{\eta}^*P_{n}\left(\xi\cdot\eta\right)$ which we have used in the seventh line of Equation \eqref{eqn:shit}. Furthermore, since $\xi$ and $\nabla_{\xi}^*$ are orthogonal, the convergence of \eqref{eqn:shit} for $N\to \infty$ also implies convergence for the same expression without the application of  $\xi\wedge$. 
Now, we can use the scalar localization result from Proposition \ref{prop:loc} to obtain 
\begin{align}
\lim_{N\to\infty}\Bigg\|\frac{\cdot}{|\cdot|}\int\limits_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\Bigg(\underbrace{\sum_{n=N+1}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi r^2}P_n\left(\frac{\cdot}{|\cdot|}\cdot\eta\right)}_{=\tilde{\Psi}_N^{Sh}(\cdot,y)}\Bigg)F_1(r\eta)d\omega(r\eta)\Bigg\|_{l^2(\Omega_r)}=0
\end{align}
and
\begin{align}
\lim_{N\to\infty}\Bigg\|\int\limits_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\sum_{n=N+1}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi r^2}P_n\left(\frac{\cdot}{|\cdot|}\cdot\eta\right) \right)L_{\eta}^*F_2(r\eta)d\omega(r\eta)\Bigg\|_{l^2(\Omega_r)}=0,
\end{align}
which deals with the relevant contributions to the asymptotic behaviour of \eqref{eqn:eqn1} and \eqref{eqn:shit}. It remains to investigate the boundary integrals appearing on the right hand side of \eqref{eqn:shit}. Observing the differential equation $(1-t^2)P_n''(t)-2tP_n'(t)+n(n+1)P_n(t)=0$, $t\in[-1,1]$, for Legendre polynomials leads to
\begin{align}\label{eqn:bvintzero}
&\!\!\!\!\!\!\frac{1}{r^2}\int_{\partial\mathcal{C}_r(x,\rho)}\tau_{\eta}F_2(r\eta)\frac{2n+1}{{4\pi}}P_{n}\left(\xi\cdot\eta\right)d\sigma(r\eta)
\\&\!\!\!\!\!\!+\frac{1}{r^2}\frac{1}{{ n(n+1)}}\int_{\partial\mathcal{C}_r(x,\rho)}F_2(r\eta)\frac{2n+1}{{4\pi}}L^*_{\xi}\frac{\partial}{\partial\nu_\eta}P_{n}\left(\xi\cdot\eta\right)d\sigma(r\eta)\nonumber
\\=&\frac{1}{r^2}\int_{\partial\mathcal{C}_r(x,\rho)}\tau_{\eta}F_2(r\eta)\frac{2n+1}{{4\pi}}\bigg(P_{n}(\xi\cdot\eta)+\frac{1}{ n(n+1)}\big(1-(\xi\cdot\eta)^2\big)P_{n}''(\xi\cdot\eta)\nonumber
\\&\qquad\qquad\qquad\qquad\qquad\qquad-\frac{2}{ n(n+1)}(\xi\cdot\eta)P_{n}'(\xi\cdot\eta)\bigg)d\sigma(r\eta)\nonumber
\\=&0.\nonumber
\end{align}
Combining \eqref{eqn:vectloceq1}--\eqref{eqn:bvintzero} implies the desired property \eqref{eqn:locpropvect}.

Set $F_N(t)={|\tilde{\mathbf{\Psi}}_N(x,y)|^2}/{\|\tilde{\mathbf{\Psi}}_N\|^2_{L^2([-1,1])}}$, where $t=\xi \cdot\eta $. Since $\tilde{\mathbf{\Psi}}_N$ is tensor-zonal, $F_N$ is well-defined and can be regarded as a density function of a random variable $t\in[-1,1]$. From here on, the proof is essentially the same as for Lemma \ref{lem:loc} and we have to show $\lim_{N\to\infty}E_N(t)=1$ and $\lim_{N\to\infty}V_N(t)=0$. We just indicate the proof for $E_N(t)$, the case of $V_N(t)$ follows analogously. Setting $\tilde{\Psi}_N(t)=|\tilde{\mathbf{\Psi}}_N(x,y)|$, again with  $t=\xi \cdot\eta $, we get
\begin{align}\label{eqn:ejtvect}
&2\pi r^2\int_{-1}^1t|\tilde{\Psi}_N(t)|^2dt=\int_{\Omega_r}\xi \cdot\eta \left|\tilde{\mathbf{\Psi}}_N\left(r\xi ,r\eta \right)\right|^2d\omega(r\eta)
\\&=\frac{1}{r^2}\sum_{i=1}^2\sum_{n=0_i}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=0_i}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)y_{n,k}^{(i)}\left(\xi \right)\cdot y_{m,l}^{(i)}\left(\xi \right)\nonumber
\\&\qquad\qquad\qquad\qquad\qquad\qquad\quad\times\int_{\Omega_r}(\xi \cdot\eta)\,  y_{n,k}^{(i)}\left(\eta \right)\cdot y_{m,l}^{(i)}\left(\eta \right)d\omega(r\eta)\nonumber
\\&=\frac{1}{r^2}\sum_{n=0}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=0}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)Y_{n,k}\left(\xi \right)Y_{m,l}\left(\xi \right)\nonumber
\\&\qquad\qquad\qquad\qquad\qquad\quad\times\int_{\Omega_r}(\xi \cdot\eta)\, Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&\quad+\frac{1}{r^2}\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\frac{\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)}{n(n+1)m(m+1)}\nabla^*_{\xi }Y_{n,k}\left(\xi \right)\cdot\nabla^*_{\xi }Y_{m,l}\left(\xi \right)\nonumber
\\&\qquad\qquad\qquad\qquad\qquad\quad\times\xi \cdot\int_{\Omega_r}\eta \left(\nabla^*_{\eta }Y_{n,k}\left(\eta \right)\cdot\nabla^*_{\eta }Y_{m,l}\left(\eta \right)\right)d\omega(r\eta)\nonumber
\end{align}\normalsize
The first term on the right hand side of \eqref{eqn:ejtvect} can be written as a one-dimensional integral
\begin{align}\label{eqn:firstsum}
&\frac{1}{r^2}\sum_{n=0}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=0}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)Y_{n,k}\left(\xi \right)Y_{m,l}\left(\xi \right)
\\&\qquad\qquad\qquad\qquad\quad\,\,\,\times\int_{\Omega_r}(\xi \cdot\eta)\, Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&=\sum_{n=0}^{\lfloor \kappa N\rfloor}\sum_{m=0}^{{\lfloor \kappa N\rfloor}}\frac{(2n+1)(2m+1)}{8\pi}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)\int_{-1}^1tP_{n}\left(t\right)P_{m}\left(t\right)dt.\nonumber
\end{align}
The second term requires significantly more effort. We start by observing that
\begin{align}
&\int_{\Omega_r}\eta \left(\nabla^*_{\eta }Y_{n,k}\left(\eta \right)\cdot\nabla^*_{\eta }Y_{m,l}\left(\eta \right)\right)d\omega(r\eta)\label{eqn:1green}
\\&=-\frac{1}{2}\int_{\Omega_r}Y_{m,l}\left(\eta \right)\nabla_{\eta }^*\cdot\left(\eta \otimes\nabla^*_{\eta }Y_{n,k}\left(\eta \right)\right)+Y_{n,k}\left(\eta \right)\nabla_{\eta }^*\cdot\left(\eta \otimes\nabla^*_{\eta }Y_{m,l}\left(\eta \right)\right)d\omega(r\eta)\nonumber
\end{align}

\begin{align}
&=-\frac{1}{2}\int_{\Omega_r}\nabla_{\eta }^*\left(Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)\right)d\omega(r\eta)\nonumber
+\frac{n(n+1)}{2}\int_{\Omega_r}\eta  Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&\quad+\frac{m(m+1)}{2}\int_{\Omega_r}\eta  Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&=\frac{n(n+1)}{2}\int_{\Omega_r}\eta  Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
+\frac{m(m+1)}{2}\int_{\Omega_r}\eta  Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta),\nonumber
\end{align}\normalsize
where we have used $\nabla_{\eta}^*\cdot\left(\eta\otimes\nabla^*_{\eta}Y_{n,k}\left(\eta\right)\right)=\eta\Delta_\eta^*Y_{n,k}\left(\eta\right)+\nabla_\eta^*Y_{n,k}\left(\eta\right)$. Plugging  \eqref{eqn:1green} into the second term on the right hand side of Equation \eqref{eqn:ejtvect}, and using the expression $2\nabla_\xi ^*Y_{n,k}(\xi )\cdot \nabla_\xi ^*Y_{m,l}(\xi )=\Delta_\xi ^*(Y_{n,k}(\xi )Y_{m,l}(\xi ))+(n(n+1)+m(m+1))Y_{n,k}(\xi )Y_{m,l}(\xi )$, leads to
\begin{align}
&\frac{1}{r^2}\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\frac{\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)}{n(n+1)m(m+1)}\nabla^*_{\xi }Y_{n,k}\left(\xi \right)\cdot\nabla^*_{\xi }Y_{m,l}\left(\xi \right)\label{eqn:2term}
\\&\qquad\qquad\qquad\qquad\quad\times\xi \cdot\int_{\Omega_r}\eta \nabla^*_{\eta }Y_{n,k}\left(\eta \right)\cdot\nabla^*_{\eta }Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&=\frac{1}{2r^2}\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)\frac{n(n+1)}{m(m+1)}\nonumber
\\&\qquad\qquad\qquad\quad\qquad\qquad\times\int_{\Omega_r}(\xi\cdot\eta)\, Y_{n,k}\left(\xi \right)Y_{m,l}\left(\xi \right)Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&\quad+\frac{1}{2r^2}\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)\nonumber
\\&\qquad\qquad\qquad\quad\qquad\qquad\times\int_{\Omega_r}(\xi\cdot\eta)\, Y_{n,k}\left(\xi \right)Y_{m,l}\left(\xi \right)Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&\quad+\frac{1}{2r^2}\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\sum_{l=1}^{2m+1}\frac{\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)}{n(n+1)}\nonumber
\\&\qquad\qquad\qquad\quad\qquad\qquad\times\xi \cdot\Delta_{\xi }^*\int_{\Omega_r}\eta Y_{n,k}\left(\xi \right)Y_{m,l}\left(\xi \right)Y_{n,k}\left(\eta \right)Y_{m,l}\left(\eta \right)d\omega(r\eta)\nonumber
\\&=\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)\left(\frac{1}{2}+\frac{n(n+1)-2}{2m(m+1)}\right)\frac{(2n+1)(2m+1)}{8\pi}\int_{-1}^1tP_n(t)P_m(t)dt,\nonumber
\end{align}\normalsize
where we have used the addition theorem, the property $\Delta_{\xi }^*P_n(\xi \cdot\eta)=\Delta_{\eta}^*P_n(\xi \cdot\eta)$, Green's formulas, and $\Delta_{\eta}^*\,\eta=-2\eta$ in the last row. Eventually, combining \eqref{eqn:ejtvect}, \eqref{eqn:firstsum}, and \eqref{eqn:2term}, we are lead to
\begin{align}\label{eqn:inttpsiN}
&\int_{-1}^1t|\tilde{\Psi}_N(t)|^2dt
\\&=\sum_{n=1}^{\lfloor \kappa N\rfloor}\sum_{m=1}^{{\lfloor \kappa N\rfloor}}\tilde{\mathbf{\Psi}}_N^\wedge(n)\tilde{\mathbf{\Psi}}_N^\wedge(m)\left(\frac{3}{4}+\frac{n(n+1)-2}{4m(m+1)}\right)\frac{(2n+1)(2m+1)}{8\pi^2r^2}\int_{-1}^1tP_n(t)P_m(t)dt.\nonumber
\end{align}\normalsize
Observing $\lim_{m,n\to\infty}\frac{3}{4}+\frac{n(n+1)-2}{4m(m+1)}=1$ if $m\in\{n-1,n,n+1\}$, we can proceed with \eqref{eqn:inttpsiN} in a similar manner as in  \eqref{eqn:et1} and \eqref{eqn:et11}. Together with
\begin{align}\label{eqn:etvect}
\|\tilde{\mathbf{\Psi}}_N\|_{L^2([-1,1])}^2=\sum_{n=0}^{\lfloor \kappa N\rfloor} \frac{2n+1}{4\pi^2r^2}|\tilde{\mathbf{\Psi}}_N^\wedge(n)|^2=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor \kappa N\rfloor} \frac{2n+1}{4\pi^2r^2}|\tilde{\mathbf{\Psi}}_N^\wedge(n)|^2,
\end{align}
this leads to the desired property
\begin{align}
\lim_{N\to\infty}E_N(t)=\lim_{N\to\infty}\int_{-1}^1 t|F_N(t)|^2 dt=\lim_{N\to\infty}\frac{\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt}{\|\tilde{\mathbf{\Psi}}_N\|_{L^2([-1,1])}^2}=1,
\end{align}
concluding the proof.

proposition:
\label{prop:loc1} 
If $F\in\mathcal{H}_s(\Omega_r)$, $s\geq 2$, it holds that
\begin{align}\label{eqn:locprop}
\lim_{N\to\infty}\left\|\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_N(\cdot,y)F(y)d\omega(y)\right\|_{L^2 (\Omega_r)}=0,
\end{align}
where $\tilde{\Psi}^{Sh}_N$ is the Shannon-type kernel with symbols $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=1$, if $N +1\leq n\leq \lfloor\kappa N\rfloor$, and $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=0$, else.
\label{prop:loc} 
If $f\in\mathfrak{h}_s(\Omega_r)$, $s\geq 2$, it holds that
\begin{align}\label{eqn:locpropvect}
\lim_{N\to\infty}\left\|\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\mathbf{\Psi}}^{Sh}_N(\cdot,y)f(y)d\omega(y)\right\|_{l^2 (\Omega_r)}=0,
\end{align}
where $\tilde{\mathbf{\Psi}}^{Sh}_N$ is the tensorial Shannon-type kernel with symbols $\big(\tilde{\mathbf{\Psi}}_N^{Sh}\big)^\wedge(n)=1$, if $N +1\leq n\leq \lfloor\kappa N\rfloor$, and $\big(\tilde{\mathbf{\Psi}}_N^{Sh}\big)^\wedge(n)=0$, else.

claim:
Downward Continuation
\label{subsec:dc}

We return to Equations \eqref{eqn:11}--\eqref{eqn:13} in order to derive the approximation \eqref{eqn:firstapprox}, reminding that we are interested in $U^+=U|_{\Omega_r}$ (or $U^+=U|_{\Gamma_r}$, respectively). We start by considering only the equations \eqref{eqn:11} and \eqref{eqn:12}, leading to the reconstruction of $U^+$ from knowledge of $F_1$ on $\Omega_R$, $r<R$. Opposed to this, the determination of $F_1$ from $U^+$ is known as upward continuation. The operator $T^{up}:L^2(\Omega_r)\to L^2(\Omega_R)$, given by
\begin{align}\label{eqn:TrR}
F_1(x)={T}^{up}[U^+](x)=\int_{\Omega_r}K^{up}(x,y) U^+(y)d\omega(y),\quad x\in\Omega_R,
\end{align}
with 
\begin{align}\label{eqn:KrR}
K^{up}(x,y)&=\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\sigma_n\frac{1}{R}Y_{n,k}\left(\xi\right)\frac{1}{r}Y_{n,k}\left(\eta\right)
\end{align}
and $\sigma_n=\left(\frac{r}{R}\right)^n$, describes this process. The downward continuation operator $T^{down}$ and acts in the following way:  
\begin{align}\label{eqn:TRr}
U^+(x)={T}^{down}[F_1](x)=\int_{\Omega_R}K^{down}(x,y) U^+(y)d\omega(y),\quad x\in\Omega_r,
\end{align}
with 
\begin{align}\label{eqn:KRr}
K^{down}(x,y)&=\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\frac{1}{\sigma_n}\frac{1}{r}Y_{n,k}\left(\xi\right)\frac{1}{R}Y_{n,k}\left(\eta\right).
\end{align}
One way to deal with the unboundedness of $T^{down}$ is a multiscale representation where $T^{down}$ is approximated by a sequence of bounded operators. Following the course of \cite{freeden99} and \cite{schneider98}, we assume $\Phi_N$ to be a scaling kernel of the form \eqref{eqn:phin} with truncation index $\lfloor\kappa N\rfloor$ and symbols $\Phi_N^\wedge(n)$ that satisfy
\begin{itemize}
\item[(a)] $\lim_{N\to\infty}\Phi_N^\wedge(n)=\frac{1}{\sigma_n}$, uniformly with respect to $n=0,1,\ldots$,
\item[(b)] $\sum_{n=0}^\infty \frac{2n+1}{4\pi} \big|\Phi_N^\wedge(n)\big|< \infty$,  for all $N=0,1,\ldots$.
\end{itemize}
The bounded scaling transform $T_N:L^2(\Omega_R)\to L^2(\Omega_r)$ is then defined via 
\begin{align}\label{eqn:TjRr}
{{T}_N[F_1](x)=\int_{\Omega_R}\Phi_N(x,y) F_1(y)d\omega(y),\quad x\in\Omega_r,}
\end{align}
and represents an approximation of $T^{down}[F_1]$. This operator can be refined further by use of the wavelet transform
\begin{align}\label{eqn:WjRr}
{W}_N[F_1](x)=\int_{\Omega_R}\Psi_N(x,y) F_1(y)d\omega(y),\quad x\in\Omega_r,
\end{align}
where the kernel $\Psi_N$ is of the form \eqref{eqn:psin} with symbols $\Psi_N^\wedge(n)=\Phi_{\lfloor\kappa N\rfloor}^\wedge(n)-\Phi_N^\wedge(n)$. An approximation of $T^{down}[F_1]$ at the higher scale $\lfloor\kappa N\rfloor$, for some fixed $\kappa>1$, is then given by 
\begin{align}\label{eqn:multirep1}
{T}_{\lfloor\kappa N\rfloor}[F_1](x)={T}_N[F_1](x)+W_N[F_1](x),\quad x\in\Omega_r.
\end{align}
It has to be noted that the kernel $\Psi_N$ and the wavelet transform $W_N$ lack a tilde (as opposed to representations \eqref{eqn:firstapprox} and \eqref{eqn:psin}). This indicates that we have not taken data $F_2$ in $\Gamma_r$ into account yet. Operators and kernels with a tilde mean that information is mapped from $\Gamma_r$ to $\Gamma_r$ while a lack of the tilde typically indicates the mapping of information from $\Omega_R$ to $\Omega_r$ (or $\Gamma_r$, respectively).

remark:
\label{rem:lockernels}
The condition $U^+\in \mathcal{H}_s(\Omega_r)$, $s\geq 2$, in Theorem \ref{thm:convres} can be relaxed to $U^+\in \mathcal{H}_s(\Omega_r)$, $s>0$, if the minimizing functional $\mathcal{F}$ in \eqref{eqn:mineq2} is substituted by
\begin{align}\label{eqn:mineq3}
\mathcal{F}_{Filter}(\Phi_N,\tilde{\Psi}_N)=&\sum_{n=0}^{\lfloor \kappa N\rfloor}\tilde{\alpha}_{N,n}\big|K_N^\wedge(n)-\tilde{\Phi}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|K_N^\wedge(n)-{\Phi}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\Phi_N^\wedge(n)\big|^2+8\pi^2 r^4\left\|\tilde{\Psi}_N\right\|^2_{L^2([-1,1-\rho])},\nonumber
\end{align}
where $K_N^\wedge(n)$ are the symbols of a filtered kernel (compare, e.g., \cite{yuguang132} and references therein for more information)
\begin{align}
\tilde{\Phi}_{N}^{Filter}(x,y)=\sum_{n=0}^{N}\sum_{k=1}^{2n+1}K_N^\wedge(n)Y_{n,k}\left(\frac{x}{|x|}\right)Y_{n,k}\left(\frac{y}{|y|}\right).
\end{align}
Then the proof of Theorem \ref{thm:convres} follows in a very similar manner as before, just that the minimizing kernels are not compared to the Shannon-type kernel but to the filtered kernel. Opposed to the Shannon-type kernel, an appropriately filtered kernel has the localization property $\lim_{N\to\infty}\|\tilde{\Phi}_{N}^{Filter}\|_{L^1([-1,1-\rho])}=0$  which makes the condition $s\geq 2$ on the smoothness of $U^+$ (required for Proposition \ref{prop:loc1}) obsolete.

