\label{IVt:1iv}
Suppose that $f$, $g^*$, $h$, and $j$ satisfy Condition~\ref{IVC:1},
and that $\nabla h$ and $\nabla j$ are uniformly continuous on 
every bounded subset of $\ensuremath{\text{\rm int\,dom}\,} h$ and $\ensuremath{\text{\rm int\,dom}\,} j$, respectively.
Then $x_n\to\overline{x}$ and $y_n^*\to\overline{y}^*$.
\end{enumerate}

lemma:
 {\rm\cite[Lemma~3.2]{Sico03}}
\label{l:2002}
Let $\ensuremath{\boldsymbol{\mathcal X}}$ be a reflexive real Banach space, and let 
$\boldsymbol{C}_1$ and $\boldsymbol{C}_2$ be convex subsets
of $\ensuremath{\boldsymbol{\mathcal X}}$ such that $\boldsymbol{C}_1$ is closed and 
$\boldsymbol{C}_1\cap\ensuremath{\text{\rm int}\,}\boldsymbol{C}_2\neq\ensuremath{{\varnothing}}$. Then 
$\overline{\boldsymbol{C}_1\cap\ensuremath{\text{\rm int}\,}\boldsymbol{C}}_2=
\boldsymbol{C}_1\cap\overline{\boldsymbol{C}}_2$.

\label{l:20}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$ and let $M\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$.
Suppose that one of the following holds:
\begin{enumerate}
\item
\label{l:20i}
$\ensuremath{\text{\rm dom}\,} M$ is nonempty and bounded.
\item
\label{l:20ii}
$M$ is uniformly monotone at some point $z\in\ensuremath{\text{\rm dom}\,} M$ with a
supercoercive modulus: there exists a strictly increasing function 
$\phi\colon\left[0,+\infty\right[\to\left[0,+\infty\right]$ that 
vanishes only at $0$ such that 
$\lim\limits_{t\to+\infty}\phi(t)/t=+\infty$ and
\begin{equation}
(\forall (x,x^*)\in\ensuremath{\text{\rm gra}\,} M)(\forall z^*\in Mz)\quad 
\pair{x-z}{x^*-z^*}\ensuremath{\geqslant}\phi(\|x-z\|).
\end{equation}
\item
\label{l:20iii}
$M=\partial\varphi$, where $\varphi$ is a supercoercive function 
in $\Gamma_0(\ensuremath{{\mathcal X}})$.
\end{enumerate}
Then $M$ is coercive. 

\label{IVlhHg7yG02}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$, let $M_1\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$, and let 
$M_2\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$ be monotone. Suppose that there 
exists $z\in\ensuremath{\text{\rm dom}\,} M_1\cap\ensuremath{\text{\rm dom}\,} M_2$ such that
\begin{equation}
\label{e:M1}
\lim\limits_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{M_1x}}{\|x\|}
=\ensuremath{{+\infty}}.
\end{equation} 
Then $M_1+M_2$ is coercive.

\label{IVlKKnhf74g12}
Let $\ensuremath{{\mathcal X}}$ be a reflexive real Banach space such that 
$\ensuremath{{\mathcal X}}\neq\{0\}$, let $M_1\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$, let 
$M_2\colon\ensuremath{{\mathcal X}}\to 2^{\ensuremath{{\mathcal X}}^*}$ be monotone, let $(x_n^*)_{n\in\ensuremath{\mathbb N}}$ 
be a bounded sequence in $\ensuremath{{\mathcal X}}^*$, and let $(\gamma_n)_{n\in\ensuremath{\mathbb N}}$ 
be a bounded sequence in $\ensuremath{\left]0,+\infty\right[}$. Suppose that there exists 
$z\in\ensuremath{\text{\rm dom}\,} M_1\cap\ensuremath{\text{\rm dom}\,} M_2$ such that
\begin{equation}
\label{eKKnhf74g13b}
\lim_{\|x\|\to+\infty}\inf\dfrac{\pair{x-z}{M_1x}}{\|x\|}=\ensuremath{{+\infty}},
\end{equation} 
and that
\begin{equation}
\label{eKKnhf74g12a}
(\forall n\in\ensuremath{\mathbb N})\quad x_n\in(M_1+\gamma_n M_2)^{-1}x_n^*.
\end{equation}
Then $(x_n)_{n\in\ensuremath{\mathbb N}}$ is bounded.

\label{IVlKKnhf74g10}
Let $\ensuremath{{\mathcal X}}$ and $\ensuremath{{\mathcal Y}}$ be real Banach spaces, let $D\subset\ensuremath{{\mathcal X}}$
be a nonempty open set, and let $C$ be a nonempty bounded convex 
subset of $D$. Suppose that $T\colon D\to\ensuremath{{\mathcal Y}}$ is uniformly 
continuous on $C$ in the sense that 
\begin{equation}
\label{eKKnhf74g15t}
(\forall\varepsilon\in\ensuremath{\left]0,+\infty\right[})(\ensuremath{\exists\,}\delta\in\ensuremath{\left]0,+\infty\right[})(\forall x\in C)
(\forall y\in C)\quad
\|x-y\|\ensuremath{\leqslant}\delta\;\Rightarrow\;
\|Tx-Ty\|\ensuremath{\leqslant}\varepsilon.
\end{equation}
Then $T$ is bounded on $C$.

\label{lkIuh727}
Let $\ensuremath{{\mathcal X}}$ be a finite-dimensional real Banach space and let
$f\in\Gamma_0(\ensuremath{{\mathcal X}})$ be a Legendre function. Then the following
hold:
\begin{enumerate}
\item
\label{lkIuh727i--}
$f$ and $\nabla f$ are continuous on $\ensuremath{\text{\rm int\,dom}\,} f$
{\rm \cite[Corollaries~8.30(iii),~17.34, and~17.35]{Livre1}}.
\item
\label{lkIuh727i-}
$\nabla f\colon\ensuremath{\text{\rm int\,dom}\,} f\to\ensuremath{\text{\rm int\,dom}\,} f^*$ is bijective with inverse
$\nabla f^*\colon\ensuremath{\text{\rm int\,dom}\,} f^*\to\ensuremath{\text{\rm int\,dom}\,} f$
{\rm \cite[Theorem~5.10]{Ccm01}}.
\item
\label{lkIuh727i}
Let $x\in\ensuremath{\text{\rm int\,dom}\,} f$, let $y\in\overline{\ensuremath{\text{\rm dom}\,}}f$, and let 
$(y_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm int\,dom}\,} f)^{\ensuremath{\mathbb N}}$. Suppose that $y_n\to y$
and that $(D^f(x,y_n))_{n\in\ensuremath{\mathbb N}}$ is bounded. Then $y\in\ensuremath{\text{\rm int\,dom}\,} f$
and $D^f(y,y_n)\to 0$ {\rm \cite[Theorem~3.8(ii)]{BB97}}.
\item
\label{lkIuh727ii}
Let $x\in\ensuremath{\text{\rm int\,dom}\,} f$, let $y\in\ensuremath{\text{\rm int\,dom}\,} f$, let 
$(x_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm dom}\,} f)^{\ensuremath{\mathbb N}}$, and let
$(y_n)_{n\in\ensuremath{\mathbb N}}\in(\ensuremath{\text{\rm int\,dom}\,} f)^{\ensuremath{\mathbb N}}$. Suppose that 
$D^f(x_n,y_n)\to 0$. Then $x=y$
{\rm \cite[Theorem~3.9(iii)]{BB97}}.
\item
\label{lkIuh727iii}
Let $y\in\ensuremath{\text{\rm int\,dom}\,} f$. Then $D^f(\cdot,y)$ is coercive
{\rm \cite[Lemma~7.3(v)]{Ccm01}}.
\item
\label{lkIuh727iv}
Let $\{x,y\}\subset\ensuremath{\text{\rm int\,dom}\,} f$. Then 
$D^f(x,y)=D^{f^*}(\nabla f(y),\nabla f(x))$
{\rm \cite[Lemma~7.3(vii)]{Ccm01}}.
\end{enumerate}

proof:
Set $\boldsymbol{M}\colon\boldsymbol{\mathcal{X}}\to
2^{\boldsymbol{\mathcal{X}}^*}\colon(x,y^*)\mapsto 
Ax\times B^{-1}y^*$ and
$\boldsymbol{S}\colon\boldsymbol{\mathcal{X}}
\to\boldsymbol{\mathcal{X}}^*\colon (x,y^*)\mapsto (L^*y^*,-Lx)$.
Since $A$ and $B^{-1}$ are maximally monotone, so is 
$\boldsymbol{M}$. On the other hand, $\boldsymbol{S}$ is linear, 
bounded, and positive since 
\begin{equation}
\label{egVxZ5y821}
(\forall(x,y^*)\in\ensuremath{\boldsymbol{\mathcal X}})\quad
\pair{\boldsymbol{S}(x,y^*)}{(x,y^*)}=
\pair{x}{L^*y^*}+\pair{-Lx}{y^*}=0. 
\end{equation}
Thus, it follows from \cite[Section~17]{Simo08} that 
$\boldsymbol{S}$ is maximally monotone with 
$\ensuremath{\text{\rm dom}\,}\boldsymbol{S}=\ensuremath{\boldsymbol{\mathcal X}}$. In turn, we derive from 
\cite[Theorem~24.1(a)]{Simo08} that
\begin{equation}
\label{egVxZ5y820}
\boldsymbol{M}+\boldsymbol{S}\;\text{is maximally monotone.}
\end{equation}

\ref{ppOlk28ha12ia}:
Let $(x,y^*)\in\ensuremath{\boldsymbol{\mathcal X}}$. Then
\begin{eqnarray}
\label{egVxZ5y828}
\boldsymbol{0}\in\boldsymbol{M}(x,y^*)+\boldsymbol{S}(x,y^*)
&\Leftrightarrow& 0\in Ax+L^*y^*\quad\text{and}\quad 0\in 
B^{-1}y^*-Lx\nonumber\\
&\Leftrightarrow& -L^*y^*\in Ax
\quad\text{and}\quad Lx\in B^{-1}y^*\nonumber\\
&\Leftrightarrow& (x,y^*)\in \boldsymbol{Z}.
\end{eqnarray}
Therefore, we derive from \eqref{egVxZ5y820} and
\cite[Lemma~1.1(a)]{IVBro65} that
$\boldsymbol{Z}=\ensuremath{\text{\rm zer}\,}(\boldsymbol{M}+\boldsymbol{S})=
(\boldsymbol{M}+\boldsymbol{S})^{-1}(0)$ is closed and convex.

\ref{ppOlk28ha12ib}: Let $x\in\ensuremath{{\mathcal X}}$. Then
$x\in\mathscr{P}\Leftrightarrow
0\in Ax+L^*BLx\Leftrightarrow (\ensuremath{\exists\,} y^*\in\ensuremath{{\mathcal Y}}^*)\; 
[-L^*y^*\in Ax\;\text{and}\;y^*\in BLx]
\Leftrightarrow (\ensuremath{\exists\,} y^*\in\ensuremath{{\mathcal Y}}^*)\;(x,y^*)
\in\boldsymbol{Z}$. 
Hence $\mathscr{P}\neq\ensuremath{{\varnothing}}$
$\Leftrightarrow$ $\boldsymbol{Z}\neq\ensuremath{{\varnothing}}$.
Likewise, let $y^*\in\ensuremath{{\mathcal Y}}^*$. Then 
$y^*\in\mathscr{D}\Leftrightarrow
0\in-LA^{-1}(-L^*y^*)+B^{-1}y^*
\Leftrightarrow(\ensuremath{\exists\,} x\in\ensuremath{{\mathcal X}})\; 
[x\in A^{-1}(-L^*y^*)\;\text{and}\;0\in-Lx+B^{-1}y^*]
\Leftrightarrow(\ensuremath{\exists\,} x\in\ensuremath{{\mathcal X}})\; 
[-L^*y^*\in Ax\;\text{and}\; Lx\in B^{-1}y^*]
\Leftrightarrow(\ensuremath{\exists\,} x\in\ensuremath{{\mathcal X}})\;(x,y^*)\in\boldsymbol{Z}$.

\ref{ppOlk28ha12ic}: Clear from \ref{ppOlk28ha12ib} (see also
\cite[Corollary 2.4]{IVPe00}).

\ref{ppOlk28ha12iia} :
Let $\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A$ and $\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B$. Then
$\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}=\boldsymbol{0}$
$\Rightarrow$ 
[$-L^*b^*=a^*\in Aa$ and $La=b\in B^{-1}b^*$] 
$\Rightarrow$ $(a,b^*)\in\boldsymbol{Z}$. In 
addition, 
\begin{multline}
\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}=\boldsymbol{0}
\quad\Rightarrow\quad
\eta_{\mathsf{a},\mathsf{b}}=\pair{a}{a^*}
+\pair{b}{b^*}=\pair{a}{-L^*b^*}+\pair{La}{b^*}\\
=-\pair{La}{b^*}+\pair{La}{b^*}=0.
\end{multline}
Thus 
$\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}=\boldsymbol{0}$
$\Rightarrow$ $\boldsymbol{H}_{\mathsf{a},\mathsf{b}}=\ensuremath{\boldsymbol{\mathcal X}}$. 
Conversely, 
$\boldsymbol{H}_{\mathsf{a},\mathsf{b}}=\ensuremath{\boldsymbol{\mathcal X}}$ $\Rightarrow$ 
$\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}=\boldsymbol{0}$
$\Rightarrow$ $\eta_{\mathsf{a},\mathsf{b}}=0$.

\ref{ppOlk28ha12iib}: First, suppose that
$\boldsymbol{x}=(x,y^*)\in\bigcap_{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A}
\bigcap_{\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}
\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$. Then 
\begin{align}
\label{epOlk28ha11}
&\hskip -2mm
(\forall\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A)(\forall\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B)\quad
\pair{(a,b^*)-(x,y^*)}{(a^*,b)-(-L^*y^*,Lx)}\nonumber\\
&\hskip 60mm =\pair{(a-x,b^*-y^*)}{(a^*+L^*y^*,b-Lx)}\nonumber\\
&\hskip 60mm =\pair{a-x}{a^*+L^*y^*}+\pair{b-Lx}{b^*-y^*}\nonumber\\
&\hskip 60mm =\eta_{\mathsf{a},\mathsf{b}}-\pair{\boldsymbol{x}}
{\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}}\nonumber\\
&\hskip 60mm \ensuremath{\geqslant} 0.
\end{align}
On the other hand, since 
\begin{equation}
\label{epOlk28ha18x}
\menge{\big((a,b^*),(a^*,b)\big)}{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A, 
\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}=\ensuremath{\text{\rm gra}\,}\boldsymbol{M}, 
\end{equation}
it follows from \eqref{egVxZ5y820} and \eqref{epOlk28ha11} that
$((x,y^*),(-L^*y^*,Lx))\in\ensuremath{\text{\rm gra}\,}\boldsymbol{M}$, i.e., 
$\boldsymbol{x}\in\boldsymbol{Z}$. Thus 
\begin{equation}
\label{epOlk28ha19}
\bigcap_{\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A}\bigcap_{\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B}
\boldsymbol{H}_{\mathsf{a},\mathsf{b}}\subset\boldsymbol{Z}.
\end{equation}
Conversely, let $\mathsf{a}\in\ensuremath{\text{\rm gra}\,} A$, let $\mathsf{b}\in\ensuremath{\text{\rm gra}\,} B$,
and let $(x,y^*)\in\boldsymbol{Z}$. 
Then $(x,-L^*y^*)\in\ensuremath{\text{\rm gra}\,} A$ and $(Lx,y^*)\in\ensuremath{\text{\rm gra}\,} B$. Since
$A$ and $B$ are monotone, we obtain
\begin{equation}
\pair{a-x}{a^*+L^*y^*}\ensuremath{\geqslant} 0
\quad\text{and}\quad
\pair{b-Lx}{b^*-y^*}\ensuremath{\geqslant} 0.
\end{equation}
Adding these two inequalities yields
\begin{equation}
\pair{x-a}{a^*+L^*y^*}+\pair{Lx-b}{b^*-y^*}\ensuremath{\leqslant} 0
\end{equation}
and, therefore,
\begin{align}
\label{epOlk28ha18}
\pair{\boldsymbol{x}}{\boldsymbol{s}^*_{\mathsf{a},\mathsf{b}}}
&=\pair{x}{a^*+L^*b^*}+\pair{b-La}{y^*}\nonumber\\
&=\pair{x}{a^*+L^*y^*}+\pair{Lx}{b^*-y^*}
+\pair{b-Lx}{y^*}+\pair{x-a}{L^*y^*}\nonumber\\
&=\pair{x-a}{a^*+L^*y^*}+\pair{a}{a^*}+\pair{La}{y^*}\nonumber\\
&\quad\;+\pair{Lx-b}{b^*-y^*}+\pair{b}{b^*}-\pair{b}{y^*}
+\pair{b-Lx}{y^*}+\pair{x-a}{L^*y^*}\nonumber\\
&\ensuremath{\leqslant}\pair{a}{a^*}+\pair{b}{b^*}+\pair{La-b}{y^*}
+\pair{b-Lx}{y^*}+\pair{x-a}{L^*y^*}\nonumber\\
&=\pair{a}{a^*}+\pair{b}{b^*}\nonumber\\
&=\eta_{\mathsf{a},\mathsf{b}}.
\end{align}
This implies that 
$(x,y^*)\in\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$. Hence, 
$\boldsymbol{Z}\subset\boldsymbol{H}_{\mathsf{a},\mathsf{b}}$. 

\ref{ppOlk28ha12iii}: 
Set $(\forall n\in\ensuremath{\mathbb N})$ $\boldsymbol{x}_n=(a_n,b_n^*)$ and 
$\boldsymbol{x}_n^*=(a_n^*+L^*b_n^*,b_n-La_n)$. Then 
$\boldsymbol{x}_n\ensuremath{\:\rightharpoonup\:} (x,y^*)$, 
$\boldsymbol{x}_n^*\to \boldsymbol{0}$, and $(\forall n\in\ensuremath{\mathbb N})$ 
$(\boldsymbol{x}_n,\boldsymbol{x}_n^*)\in
\ensuremath{\text{\rm gra}\,}(\boldsymbol{M}+\boldsymbol{S})$. 
However, it follows from \eqref{egVxZ5y820} that 
$\ensuremath{\text{\rm gra}\,}(\boldsymbol{M}+\boldsymbol{S})$ is sequentially closed 
in $\ensuremath{\boldsymbol{\mathcal X}}^{\text{weak}}\times\ensuremath{\boldsymbol{\mathcal X}}^{*\text{strong}}$ 
\cite[Lemma~1.2]{IVBro65}. Hence, 
$\boldsymbol{0}\in(\boldsymbol{M}+\boldsymbol{S})(x,y^*)$, 
i.e., by \eqref{egVxZ5y828}, $(x,y^*)\in\boldsymbol{Z}$.

\ref{pvb8uh4504i}:
Since $f$ and $g$ are Legendre functions, so are $f^*$ and $g^*$  
\cite[Corollary~5.5]{Ccm01}. Therefore, it follows from 
\cite[Theorem~5.6(iii)]{Ccm01} that $\partial f$ and 
$\partial g^*$ are single-valued on $\ensuremath{\text{\rm dom}\,}\partial f=\ensuremath{\text{\rm int\,dom}\,} f$ 
and $\ensuremath{\text{\rm dom}\,}\partial g^*=\ensuremath{\text{\rm int\,dom}\,} g^*$, respectively. 
On the other hand, we derive from \eqref{epOlk28ha14} that 
$\ensuremath{\text{\rm dom}\,}\boldsymbol{f}=\ensuremath{\text{\rm dom}\,} f\times\ensuremath{\text{\rm dom}\,} g^*$ and that
\begin{equation}
\partial\boldsymbol{f}\colon\boldsymbol{\ensuremath{{\mathcal X}}}\to 
2^{\boldsymbol{\ensuremath{{\mathcal X}}^*}}\colon (x,y^*)\mapsto 
\partial f(x)\times\partial g^*(y^*).
\end{equation}
Thus, $\partial\boldsymbol{f}$ is single-valued on 
\begin{equation}
\label{ebcn5y731}
\ensuremath{\text{\rm dom}\,}\partial\boldsymbol{f}=\ensuremath{\text{\rm dom}\,}\partial f\times\ensuremath{\text{\rm dom}\,}\partial g^*
=\ensuremath{\text{\rm int\,dom}\,} f\times\ensuremath{\text{\rm int\,dom}\,} g^*=\ensuremath{\text{\rm int}\,}(\ensuremath{\text{\rm dom}\,} f\times\ensuremath{\text{\rm dom}\,} g^*)
=\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}.
\end{equation}
Likewise, since 
\begin{equation}
\boldsymbol{f}^*\colon\ensuremath{{\mathcal X}}^*\to\ensuremath{\left]-\infty,+\infty\right]}\colon 
(x^*,y)\mapsto f^*(x^*)+g(y), 
\end{equation}
we deduce that $\partial\boldsymbol{f}^*$ is single-valued on 
$\ensuremath{\text{\rm dom}\,}\partial\boldsymbol{f}^*=\ensuremath{\text{\rm int\,dom}\,}\boldsymbol{f}^*$. 
Consequently, \cite[Theorems~5.4 and~5.6]{Ccm01} assert that 
$\boldsymbol{f}$ is a Legendre function.

\ref{pvb8uh4504ii}: It follows from 
Proposition~\ref{ppOlk28ha12}\ref{ppOlk28ha12ia} that 
$\boldsymbol{Z}$ is a closed convex subset of $\ensuremath{\boldsymbol{\mathcal X}}$.
Hence, since
$\boldsymbol{Z}\cap\text{\rm int\,dom}\,\boldsymbol{f}\neq\ensuremath{{\varnothing}}$,
we derive from \ref{pvb8uh4504i} and 
\cite[Corollary~7.9]{Ccm01} that
$(\overline{x},\overline{y}^*)=P^{\boldsymbol{f}}_{\boldsymbol{Z}}
(x_0,y_0^*)$ is uniquely defined.

Item~\ref{p:2i-} is found in 
\cite[Proof of Proposition~3.3]{Pams03}.
The first equivalence in \ref{p:2iv} follows from
\cite[Propositions~2.2(ii)]{Pams03}. To establish the remaining
