theorem:
\label{thr:general-polar}
Suppose that Assumption~\ref{assumption:X} holds.  Let $\mathcal{H}$ be a
countable family of measurable functions $h:\mathbb{X}\mapsto\mathbb{R}_+$ such
that for all $h \in \mathcal{H}$ and $x \in \mathbb{X}$ the function $ t \mapsto
h(tx)$ is right-continuous (or left-continuous) on $\mathbb{R}_{++}$.

A $\sigma$-finite measure $\nu$ on $\mathbb{X}$ is $\alpha$-homogeneous and
satisfies
\begin{equation}
  \label{eq:nu-h-integral}
  \int_\mathbb{X} h(x) \, \nu(dx) <\infty,\qquad h\in\mathcal{H},
\end{equation}
and 
\begin{equation}
  \label{Eq:nu-support-h}
  \nu\left(\bigcap_{h\in\mathcal{H}} \{x\in\mathbb{X}:\; h(x)=0\}\right)=0
\end{equation}
if and only if there exists a probability measure $\pi$ on $\mathbb{X}$
such that \eqref{Eq:nu-rep} holds, 
\begin{equation}
  \label{Eq:levy-condition-pi-general}
  \int_{\mathbb{X}}\int_0^\infty h(tx) t^{-(\alpha+1)} \, dt \, \pi(dx) <\infty,
  \qquad h\in\mathcal{H},
\end{equation}
and 
\begin{displaymath}
  \pi\left((0,\infty) \bigcap_{h \in \mathcal{H}} \{x\in\mathbb{X}:\; h(x)=0\}\right)=0. 
\end{displaymath}

\label{thr:levy-k-separating-countable}
Let $\xi$ be a strictly stable random element that admits a
$\sigma$-finite L\'evy measure $\nu$.  Assume that there is a
countable, closed under finite products, separating family of
characters $\hat{\bK}$ such that $t \mapsto \mathrm{Re}\,\chi(tx)$, $t\in\mathbb{R}_{++}$,
is right- (or left-) continuous for all $x\in\mathbb{K}'$ and $\chi \in
\hat{\bK}$. Assume also that Assumption~\ref{assumption:X} holds and
\eqref{Eq:lim-chi-positive} holds for all $\chi\in\hat{\bK}$.

Then $\nu$ admits the polar representation
$\pi\otimes\theta_\alpha$, where $\pi$ is a probability measure on
$\mathbb{K}'$ satisfying
\begin{equation}
  \label{eq:eps-condition}
  \int_0^\infty \mathbb{E}[1-\mathrm{Re}\,\chi(t\epsilon)] t^{-(\alpha+1)} \, dt <\infty,
  \qquad \chi\in\hat{\bK}.
\end{equation}
The Poisson process with intensity measure $\nu$ can be represented
as $\{\Gamma_i^{-1/\alpha}\epsilon_i\}_{i\in\mathbb{N}}$, where
$\{\epsilon_i\}_{i\in\mathbb{N}}$ is a sequence of i.i.d. copies of a random
element $\epsilon$ in $\mathbb{K}'$ with distribution $\pi$, and
$\{\Gamma_i\}_{i\in\mathbb{N}}$ are successive points of a unit intensity
Poisson process on $\mathbb{R}_+$.  If $\xi$ is symmetric, then $\epsilon$ can
also be chosen to have a symmetric distribution.

lemma:
  \label{lemma:extend_homo_completion}
  Suppose that $\nu$ is an $\alpha$-homogeneous measure on $(\mathbb{X},
  \mathfrak{B})$.  Write $\mathfrak{B}^\nu$ for the completion of the
  $\sigma$-algebra $\mathfrak{B}$ with respect to the measure $\nu$.  Then $s
  B \in \mathfrak{B}^\nu$ with $\nu(sB)=s^{-\alpha}\nu(B)$ for all $s > 0$
  and $B \in \mathfrak{B}^\nu$.

  \label{lemma:projection}
  Let $\nu$ be a $\sigma$-finite $\alpha$-homogeneous measure on
  $(\mathbb{X}, \mathfrak{B})$ and suppose that $\mathfrak{B}$ is $\nu$-complete.
  \begin{itemize}
  \item[i)] For $B \in \mathfrak{B}$ and a Borel set $I \subseteq \mathbb{R}_{++}$,
    the set $I B$ also belongs to $\mathfrak{B}$.
  \item[ii)] If $\nu([t,u) B) < \infty$ for $B \in \mathfrak{B}$ and $0 < t <
    u < \infty$, then $\nu([s,\infty) B) < \infty$ for all $s > 0$.
\end{itemize}

  \label{lemma:pair-of-maps}
  Suppose that $\nu$ is a $\sigma$-finite $\alpha$-homogeneous measure
  on $(\mathbb{X},\mathfrak{B})$ and that Assumption~\ref{assumption:X} is
  satisfied.  For $x \in \mathbb{X}$, define $\tau(x) \in \mathbb{R}_{++}$ by the
  requirement that $\tau(x)^{-1}x\in\mathbb{S}$.  Then the following hold.
  \begin{itemize}
  \item[i)] The maps $(x,t)\mapsto tx$ from $\mathbb{S}\times\mathbb{R}_{++}$ to
    $\mathbb{X}$ and $x\mapsto(\tau(x)^{-1}x,\tau(x))$ from $\mathbb{X}$ to
    $\mathbb{S}\times\mathbb{R}_{++}$ are mutually inverse.
  \item[ii)] If $\mathfrak{B}$ is $\nu$-complete, then
    $x\mapsto(\tau(x)^{-1}x,\tau(x))$ is $\mathfrak{B} / \mathfrak{B}_{| \mathbb{S}}
    \otimes \mathcal{B}(\mathbb{R}_{++})$-measurable, where $\mathfrak{B}_{| \mathbb{S}}$ is the
    $\sigma$-algebra induced by $\mathfrak{B}$ on $\mathbb{S}$.
  \item[iii)] If $(\mathbb{X},\mathfrak{B})$ is a Borel space, then
    $x\mapsto(\tau(x)^{-1}x,\tau(x))$ is $\mathfrak{B} / \mathfrak{B}_{| \mathbb{S}}
    \otimes \mathcal{B}(\mathbb{R}_{++})$-measurable.
  \end{itemize}

  \label{lemma:non-zero}
  Assume for some $\chi\in\hat{\bK}$ that
  \begin{equation}
    \label{Eq:lim-chi-positive}
    \liminf_{t\downarrow0} \mathrm{Re}\,\chi(tx)>0
  \end{equation}
  for all $x\in\mathbb{K}$.  If $\xi$ is a strictly $\alpha$-stable random
  element, then $\mathbb{E}\chi(\xi)\neq 0$.

