algorithm:
\renewcommand\algorithmicensure {\textbf{Output:} }
\caption{CS Based Adaptive CSI Acquisition Scheme}
\label{alg1} 
\begin{algorithmic}[1]
\STATE Determine the initial time slot overhead $G_0$, and set the iteration index $i=0$.
\REPEAT
\STATE Collect ${\bf r}_p^{[q,G_i]}$ and ${\bf \Phi}_p^{[q,G_i]}$ in (\ref{equ:joint_process2})
 for given $G_i$, $1\le p \le P$. {\scriptsize \%~$G_i$ is the required overhead at the
 $i$th iteration.}
\STATE Acquire the channel vectors $\widehat{\bar{\bf h}}_p^{(q)}$ $\forall p$ by using
 the proposed DSAMP algorithm (Algorithm~\ref{alg:Framwork}).
\STATE $G_{i+1} = G_i + 1$; $i = i+1$.
\UNTIL {$\sum\limits_{p=1}^{P}\!\left\| {\bf r}_p^{[q,G_{i-1}]}\!-\!{\bf \Phi}_p^{[q,G_{i-1}]}\widehat{\bar{\bf h}}_p^{(q)}
 \!\right\|_2^2\!\!/\!({P}G_{i-1})\!\!\le\! \varepsilon$}. {\scriptsize \%~If the error is smaller than the
 threshold $\varepsilon$, end repeat; otherwise, continue transmitting the pilot in the next time~slot.}
\STATE $G_0=G_i-1$. ${\kern 5pt}$ {\scriptsize \%~Optional, determine the initial time slot
 overhead for the next CS based adaptive CSI acquisition.}
\end{algorithmic}

{\small

\renewcommand\algorithmicensure {\textbf{Output:} }
\caption{Proposed DSAMP Algorithm}
\label{alg:Framwork} 
\begin{algorithmic}[1]
\REQUIRE
 Noisy feedback signals ${\bf r}_p^{[q,G]}$ and sensing matrices ${\bf{\Phi}}_p^{[q,G]}$
 in (\ref{equ:target_func}), $1\le p \le P$; termination threshold $p_{\rm th}$.
\ENSURE
 Estimated channel vectors in the virtual angular domain at multiple pilot subcarriers
 $\widehat{\bar{\bf h}}_p^{(q)}$, $\forall p$.
\STATE ${\cal{T}} = 1$; $i = 1$; $j =1$. {\scriptsize \%~$\cal{T}$, $i$, $j$ are the sparsity
 level of the current stage, iteration index, and stage index, respectively.}
\STATE ${\bf c}_p\!=\!{\bf t}_p\! ={\bf c}_p^{\rm{last}}\!=\!{\bf{0}}\in \mathbb{C}^{M\times 1}$, $\forall p$.
 {\scriptsize \%~${\bf c}_p$ and ${\bf t}_p$ are intermediate variables, and ${\bf c}_p^{\rm{last}}$
 is the channel estimation of the last stage.}
\STATE $\Omega^0\!\!=\!\!\! \ {\Gamma}\!=\! \widetilde{\Gamma}\!=\!\Omega\!=\!\widetilde{\Omega}\!=\!
 \emptyset$; $l_{\text{min}}\!=\!\widetilde l\!=\!0$. {\scriptsize \%~$\Omega^i$ is the estimated
 support set in the $i$th iteration, $\Gamma$, $\widetilde{\Gamma}$, $\Omega$, and $\widetilde{\Omega}$
 are sets, $l_{\text{min}}$ and $\widetilde l$ denote the support indexes.}
\STATE ${\bf b}^0_p \!=\!{\bf r}_p^{[q,G]}\!\!\in \!\!\mathbb{C}^{G\times 1}\!$, $\forall p$.
 {\scriptsize \%~${\bf b}^i_p$ is the residual of the $i$th iteration.}
\STATE $\sum\nolimits_{p = 1}^P {\left\| {{\bf{b}}_p^{{\rm{last}}}} \right\|_2^2}=+\infty$.
 {\scriptsize \%~${{\bf{b}}_p^{{\rm{last}}}}$ is the residual of the last stage.}
\REPEAT
\STATE ${\bf a}_p=\left( {\bf{\Phi}}_p^{[q,G]} \right)^{*} {\bf b}^{i-1}_p$, $\forall p$.
 {\scriptsize \%~Signal proxy is saved in ${\bf a}_p$.}
\STATE $\Gamma \! = \!\arg \max\limits_{\widetilde{\Gamma}} \left\{ \! \sum\nolimits_{p=1}^{P} \!
 \left\| \left( {\bf a}_p \right)_{\widetilde{\Gamma}} \right\|_2^2 ,\left| \widetilde{\Gamma}
 \right| \! = \! {\cal{T}} \! \right\}$. {\scriptsize \%~Identify support.}
\STATE $\left( {\bf t}_p \right)_{ \Omega^{i-1} \cup \Gamma} \!\!=\!\!
 \left(\left( {\bf{\Phi}}_p^{[q,G]} \right)_{ \Omega^{i-1} \cup \Gamma}\right)^{\dag}
\!\!\! {\bf r}_p^{[q,G]}$, $\forall p$. {\scriptsize \%~LS estimation.}
\STATE $\Omega \! = \!\arg \max\limits_{\widetilde{\Omega}} \left\{ \! \sum\nolimits_{p=1}^{P} \!
 \left\| \left( {\bf t}_p \right)_{\widetilde{\Omega}} \right\|_2^2 ,
