	$$ a(t,\varphi) = \int_{\mathbf{F} \backslash \ag{A} \times \mathbf{F}^{\times} \backslash \ag{A}^{(1)} \times \gp{K}} \varphi(n(x)a(t^+y)k) dx d^{\times}y dk, $$
