	$$ R(s,\varphi) = \int_0^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t}; \quad R^*(s,\varphi) = \Lambda_{\mathbf{F}}(1+2s) R(s,\varphi). $$
