\noindent The following function together with its Taylor expansion plays an important role:
\begin{equation}
	\lambda_{\mathbf{F}}(s) := \frac{\Lambda_{\mathbf{F}}(-2s)}{\Lambda_{\mathbf{F}}(2+2s)} = \frac{\lambda_{\mathbf{F}}^{-1}(0)}{s} + \sum_{n=0}^{\infty} \frac{s^n}{n!} \lambda_{\mathbf{F}}^{(n)}(0).
\label{lambdaFDef}
\end{equation}
Recall the truncation operator $\Lambda^c$ defined in \cite[(5.5)]{GJ79}. Let $f_0 \in {\rm Ind}_{\gp{B}(\ag{A}) \cap \gp{K}}^{\gp{K}} (1,1)$ be constant equal to $1$ on $\gp{K}$.
\begin{theorem}
	(Adelic version of regularization due to Zagier \cite{Za82})
\begin{itemize}
	\item[(1)] Let $\varphi: {\rm GL}_2(\mathbf{F})\gp{Z}(\ag{A}) \backslash {\rm GL}_2(\ag{A}) \to \ag{C}$ be a slowly increasing function. For $s \in \ag{C}, \Re s \gg 1$ and any $T \gg 1$ we have
	$$ \int_{[{\rm PGL}_2]} \varphi(g) \Lambda^T {\rm E}(s,f_0)(g) dg = \int_0^T a(t,\varphi)t^{s-\frac{1}{2}} \frac{dt}{t} - \int_T^{\infty} a(t,\varphi) t^{-s-\frac{1}{2}} \frac{dt}{t} \cdot \lambda_{\mathbf{F}}(s-1/2). $$
	\item[(2)] If $\varphi$ is, in addition, regularizable, then we have for $T \gg 1$
\begin{align*}
	&\quad R^*(s,\varphi) + \Lambda_{\mathbf{F}}(1+2s) h_T(s) + \Lambda_{\mathbf{F}}(1-2s) h_T(-s) \\
	&= \int_{[{\rm PGL}_2]} \varphi(g) \Lambda^T {\rm E}^*(s,f_0)(g) dg + \\
	&\quad \Lambda_{\mathbf{F}}(1+2s) \int_T^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t} + \Lambda_{\mathbf{F}}(1-2s) \int_T^{\infty} (a(t,\varphi)-f(t)) t^{-s-\frac{1}{2}} \frac{dt}{t}.
\end{align*}
	In particular, $R(s,\varphi)$ has a meromorphic continuation to $s \in \ag{C}$ with possible poles at $s=\pm 1/2, \pm \alpha_i, (\rho-1)/2$ for $\rho$ running over the non-trivial zeros of $\zeta_{\mathbf{F}}$, and satisfies the functional equation
	$$ R^*(s,\varphi) = R^*(-s,\varphi). $$
	\item[(3)] Under the condition of (2), if $\Re \alpha_i < 0$ for all $1 \leq i \leq l$, then we have
	$$ R(s,\varphi) = \int_{[{\rm PGL}_2]} \varphi(g) {\rm E}(s,f_0)(g) dg, \quad \max_{1 \leq i \leq l} \alpha_i < \Re s < -\max_{1 \leq i \leq l} \alpha_i. $$
	\item[(4)] Under the condition of (2), if $\varphi$ is integrable on $ [{\rm PGL}_2] := {\rm GL}_2(\mathbf{F})\gp{Z}(\ag{A}) \backslash {\rm GL}_2(\ag{A}) $, then we have $\Re \alpha_i < 1/2$ for all $1 \leq i \leq l$, and
	$$ \int_{[{\rm PGL}_2]} \varphi(g) dg = \frac{1}{\lambda_{\mathbf{F}}^{(-1)}(0)} \left( {\rm Res}_{s=\frac{1}{2}} R(s,\varphi) + c_i \delta_{\substack{\alpha_i=-\frac{1}{2} \\ n_i=0}} \right), \quad {\rm Vol}([{\rm PGL}_2]) = \lambda_{\mathbf{F}}^{(-1)}(0). $$
\end{itemize}
\label{AdelicRegThm}
\end{theorem}
\begin{proof}
	Since the proofs of (1) to (3) are quite similar to that in \cite{Za82}, we only mention some essential points of them. Only (4) needs more explanation.

\noindent (1) This is standard Rankin-Selberg unfolding together with
	$$ \Lambda^T {\rm E}(s,f_0)(g) = \sum_{\gamma \in \gp{B}(\mathbf{F}) \backslash {\rm GL}_2(\mathbf{F})} f_{0,s}(\gamma g) 1_{{\rm Ht}(\gamma g) \leq T} - \sum_{\gamma \in \gp{B}(\mathbf{F}) \backslash {\rm GL}_2(\mathbf{F})} \mathcal{M} f_{0,s}(\gamma g) 1_{{\rm Ht}(\gamma g) > T}. $$

\noindent (2) It follows from rewriting the two terms at the right hand side of (1). For the first term we have
\begin{align*}
	\int_0^T a(t,\varphi) t^{s-\frac{1}{2}} \frac{dt}{t} &= R(s,\varphi) - \int_T^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t} + \sum_{i=1}^l \frac{c_i}{n_i!} \int_0^T t^{s+\alpha_i} \log^{n_i} t \frac{dt}{t} \\
	&= R(s,\varphi) - \int_T^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t} + h_T(s).
\end{align*}
For the second term we have a similar equality.

\noindent (3) In the case $\Re \alpha_i < 0$ for all $i$, we let $T \to \infty$, taking into account Proposition \ref{GlobRDEisWhi} and $h_T(s) \to 0$, to get the asserted equation.

\noindent (4) The integrability of $\varphi$ implies $\Re \alpha_i < 1/2$ for all $i$ by Lemma \ref{IntExpBd}. We take residue at $s=1/2$ on both sides of the equation obtained in (2) and divide by $\Lambda_{\mathbf{F}}(1+2s)$ to see for $T \gg 1$
\begin{align*}
	&\quad {\rm Res}_{s=\frac{1}{2}} R(s,\varphi) + {\rm Res}_{s=\frac{1}{2}} h_T(s) + \lambda_{\mathbf{F}}^{(-1)}(0) h_T(-\frac{1}{2}) \\
	&= \lambda_{\mathbf{F}}^{(-1)}(0) \int_{\mathcal{D}_T} \varphi(g)dg + {\rm Res}_{s=\frac{1}{2}} \int_{\mathcal{D}-\mathcal{D}_T} \varphi(g) \left( {\rm E}(s,f_0)(g) - {\rm E}(s,f_0)_N(g) \right) dg \\
	&\quad + \lambda_{\mathbf{F}}^{(-1)}(0) \int_T^{\infty} (a(t,\varphi)-f(t)) \frac{dt}{t^2},
\end{align*}
	where $\mathcal{D}$ is the standard fundamental domain for $[{\rm PGL}_2]$ and $\mathcal{D}_T$ is the set of $g \in \mathcal{D}$ such that ${\rm Ht}(g) \leq T$. It is easy to see that as $T \to \infty$
	$$ h_T(-\frac{1}{2}) \to 0; \quad \int_T^{\infty} (a(t,\varphi)-f(t)) \frac{dt}{t^2} \to 0. $$
	By Proposition \ref{GlobRDEisWhi}, ${\rm E}(s,f_0)(g) - {\rm E}(s,f_0)_N(g)$ is of uniformly rapid decay with respect to ${\rm Ht}(g), g \in \mathcal{D}$ as $s$ remains in a compact neighborhood of $1/2$. Hence
	$$ \int_{\mathcal{D}-\mathcal{D}_T} \varphi(g) \left( {\rm E}(s,f_0)(g) - {\rm E}(s,f_0)_N(g) \right) dg $$
	is holomorphic at $s=1/2$. We compute ${\rm Res}_{s=\frac{1}{2}} h_T(s)$ by noting that the second summand of
	$$ \frac{d^n}{d s^n} \left( \frac{T^s}{s} \right) = \frac{(-1)^n n!}{s^{n+1}} + \int_0^{\log T} t^n e^{st} dt $$
is holomorphic at $s=0$, and get
	$$ {\rm Res}_{s=\frac{1}{2}} h_T(s) = c_i \delta_{\substack{\alpha_i=-\frac{1}{2} \\ n_i=0}}. $$
\end{proof}
\begin{definition}
	We define the \emph{regularized integral} of a regularizable function $\varphi: [{\rm PGL}_2] \to \ag{C}$ as
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi(g) dg = \frac{1}{\lambda_{\mathbf{F}}^{(-1)}(0)} \left( {\rm Res}_{s=\frac{1}{2}} R(s,\varphi) + c_i \delta_{\substack{\alpha_i=-\frac{1}{2} \\ n_i=0}} \right), $$
	where $c_i, \alpha_i, n_i$ are associated with $a(t,\varphi)$ as in Definition \ref{RegFuncRDef}. We call the first term the \emph{principal part} of the regularized integral, the second the \emph{degenerate part} of the regularized integral. The regularized integral is linear and extends the integral on $\mathcal{A}^{{\rm reg}}({\rm GL}_2) \cap {\rm L}^1({\rm GL}_2, 1)$.
\label{RegIntDef}
\end{definition}

Basic Properties
\begin{definition}
	Let $\omega$ be a unitary character of $\mathbf{F}^{\times} \backslash \ag{A}^{\times}$. Let $\varphi$ be a smooth function on ${\rm GL}_2(\mathbf{F}) \backslash {\rm GL}_2(\ag{A})$ with central character $\omega$. We call $\varphi$ \emph{finitely regularizable} if there exist characters $\chi_i: \mathbf{F}^{\times} \backslash \ag{A}^{\times} \to \ag{C}^{(1)}$, $\alpha_i \in \ag{C}, n_i \in \ag{N}$ and smooth functions $f_i \in {\rm Ind}_{\gp{B}(\ag{A}) \cap \gp{K}}^{\gp{K}} (\chi_i, \omega \chi_i^{-1})$ for $1 \leq i \leq l$, such that for any $M \gg 1$
	$$ \varphi(n(x)a(y)k) = \varphi_{\gp{N}}^*(n(x)a(y)k) + O(\norm[y]_{\ag{A}}^{-M}), \text{ as } \norm[y]_{\ag{A}} \to \infty, $$
	where we have written the \emph{essential constant term}
	$$ \varphi_{\gp{N}}^*(n(x)a(y)k)=\varphi_{\gp{N}}^*(a(y)k)=\sum_{i=1}^l \chi_i(y) \norm[y]_{\ag{A}}^{\frac{1}{2}+\alpha_i} \log^{n_i} \norm[y]_{\ag{A}} f_i(k). $$
	In this case, we call $\mathcal{E}{\rm x}(\varphi)=\{ \chi_i \norm^{\frac{1}{2}+\alpha_i}: 1 \leq i \leq l \}$ the \emph{exponent set} of $\varphi$, and define
	$$ \mathcal{E}{\rm x}^+(\varphi) = \{ \chi_i \norm^{\frac{1}{2}+\alpha_i} \in \mathcal{E}{\rm x}(\varphi): \Re \alpha_i \geq 0 \}; \quad \mathcal{E}{\rm x}^-(\varphi) = \{ \chi_i \norm^{\frac{1}{2}+\alpha_i} \in \mathcal{E}{\rm x}(\varphi): \Re \alpha_i < 0 \}. $$
	The space of finitely regularizable functions with central character $\omega$ is denoted by $\mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$.
\label{FinRegFuncDef}
\end{definition}
\begin{remark}
	In the case $\omega=1$, a finitely regularizable is smooth and regularizable in the sense of Definition \ref{RegFuncDef}. But a smooth regularizable function doesn't need to be finitely regularizable.
\end{remark}
\begin{definition}
	In the case $\omega^{-1}\xi^2(t)=\norm[t]_{\ag{A}}^{i\mu}$ for some $\mu \in \ag{R}$, we introduce the \emph{regularizing Eisenstein series} for $f \in V_{\xi,\omega\xi^{-1}}^{\infty}$ and $s$ in a neighborhood of $(1-i\mu)/2$
	$$ {\rm E}^{{\rm reg}}(s,f)(g) = {\rm E}(s,f)(g) - \frac{\Lambda_{\mathbf{F}}(1-2s-i\mu)}{\Lambda_{\mathbf{F}}(1+2s+i\mu)} \int_{\gp{K}} f(\kappa) d\kappa \cdot \chi^{-1}(\det g) \norm[\det g]_{\ag{A}}^{\frac{i\mu}{2}}. $$
	It is holomorphic at $s=(1-i\mu)/2$.
\label{RegEisDef}
\end{definition}
\begin{remark}
	Let $e_0 \in {\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(1,1)$ be the spherical function taking value $1$ on $\gp{K}$. Let $T(\mathfrak{p})$ denote the order $1$ Hecke operator at a finite place $\mathfrak{p}$ with cardinality of the residue field $q$. For $s \neq 0$, we have
	$$ T(\mathfrak{p}). {\rm E}(\frac{1}{2}+s, e_0) = \lambda_{\mathfrak{p}}(s) {\rm E}(\frac{1}{2}+s, e_0), \quad \lambda_{\mathfrak{p}}(s) = \frac{q^{1/2+s} + q^{-(1/2+s)}}{q^{1/2}+q^{-1/2}}; $$
	$$ \text{or} \quad T(\mathfrak{p}). {\rm E}^{{\rm reg}}(\frac{1}{2}+s, e_0) = \lambda_{\mathfrak{p}}(s) {\rm E}^{{\rm reg}}(\frac{1}{2}+s, e_0) + (\lambda_{\mathfrak{p}}(s)-1) \cdot \lambda_{\mathbf{F}}(s). $$
	The pole of $\lambda_{\mathbf{F}}(s)$, defined in (\ref{lambdaFDef}), at $s=0$ is compensated by the zero of $\lambda_{\mathfrak{p}}(s)-1$, hence we get
	$$ T(\mathfrak{p}). {\rm E}^{{\rm reg}}(\frac{1}{2}, e_0) = {\rm E}^{{\rm reg}}(\frac{1}{2}, e_0) + \lambda_{\mathfrak{p}}^{(1)}(0) \cdot \lambda_{\mathbf{F}}^{(-1)}(0). $$
	In particular, $(T(\mathfrak{p})-1)^2$ annihilates ${\rm E}^{{\rm reg}}(1/2,e_0)$.
\label{KillRegEis}
\end{remark}
\begin{remark}{(Violation of Covariance)}
	Unlike the usual Eisenstein series, the map
	$$ \pi^{\infty}(\xi \norm^{(1-i\mu)/2}, \omega\xi^{-1} \norm^{-(1-i\mu)/2}) \to {\rm C}^{\infty}({\rm GL}_2, \omega), \quad f_{(1-i\mu)/2} \mapsto {\rm E}^{{\rm reg}}((1-i\mu)/2, f) $$
is \emph{NOT} ${\rm GL}_2(\ag{A})$-covariant. But it's still $\gp{K}$-covariant.
\end{remark}
\begin{remark}
	By Proposition \ref{GlobRDEisWhi}, \ref{GlobRDEisCst} and the definition of cusp forms, $\mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$ contains:
\begin{itemize}
	\item $\chi(\det g)$ for quasi-characters $\chi$ such that $\chi^2=\omega$;
	\item smooth cusp forms, i.e., $\mathcal{A}_{{\rm cusp}}^{\infty}({\rm GL}_2,\omega)$;
	\item $\frac{\partial^n}{\partial s^n}{\rm E}(s,f)$ for some $n \in \ag{N}$ and smooth $f \in {\rm Ind}_{\gp{B}(\ag{A})}^{{\rm GL}_2(\ag{A})}(\xi, \omega\xi^{-1})$ with $\Re s \geq 0$ and $s \neq -i\mu/2, 1/2-i\mu/2$ for $\mu=\mu(\omega^{-1}\xi^2)$ if $\omega\xi^{-2}$ is trivial on $\ag{A}^{(1)}$;
	\item $\frac{\partial^n}{\partial s^n} \mid_{s=-i\frac{\mu}{2}} (s+i\frac{\mu}{2}){\rm E}^*(s,f)$ for some $n \in \ag{N}$ and smooth $f$, $\mu$ the same as above;
	\item $\frac{\partial^n}{\partial s^n}{\rm E}^{{\rm reg}}(\frac{1-i\mu}{2},f)$ for some $n \in \ag{N}$ and $f,\mu$ the same as above;
	\item $\varphi=\Pi_{j=1}^l \varphi_j$ where $\varphi_j \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega_j)$ with $\omega = \Pi_j \omega_j$.
\end{itemize}
	In the last case, we have $ \varphi_{\gp{N}}^* = \Pi_j \varphi_{j,\gp{N}}^* $. Note that we have excluded ${\rm E}(s,f)$ for $\Re s < 0$. But they are actually present since they are related to the case $\Re s > 0$ by functional equation.
\end{remark}
\begin{definition}
	Let $\omega$ be a unitary character of $\mathbf{F}^{\times} \backslash \ag{A}^{\times}$. The ${\rm L}^2$-\emph{residual space} of central character $\omega$, denoted by $\mathcal{E}({\rm GL}_2,\omega)$, is the direct sum of the vector spaces $\mathcal{E}^+({\rm GL}_2,\omega)$ resp. $\mathcal{E}^{{\rm reg}}({\rm GL}_2,\omega)$ spanned by functions
	$$ \frac{\partial^n}{\partial s^n} {\rm E}(s,f), \text{if } s \neq \frac{1-i\mu}{2} \quad \text{resp.} \quad \frac{\partial^n}{\partial s^n} {\rm E}^{{\rm reg}}(\frac{1-i\mu}{2},f) $$
	where $s \in \ag{C}, \Re s > 0$ and for some unitary character $\xi$ of $\mathbf{F}^{\times} \backslash \ag{A}^{\times}$, $f \in V_{\xi,\omega\xi^{-1}}^{\infty}$ and $\mu$ as above.
\end{definition}
\noindent We have the following simple fact of which we omit the proof.
\begin{proposition}
	$\mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$ is stable under the right translation by ${\rm GL}_2(\ag{A})$. Moreover, for any $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$ and any $g \in {\rm GL}_2(\ag{A})$, their sets of exponents are the same:
	$$ \mathcal{E}{\rm x}(g.\varphi) = \mathcal{E}{\rm x}(\varphi). $$
\label{FregStab}
\end{proposition}
\begin{proof}
	Take $f \in {\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(\xi, \omega\xi^{-1})$ and the flat section $f_s \in \pi(\xi \norm^s, \omega\xi^{-1} \norm^{-s})$ associated to it. It suffices to show that for any $s_0 \in \ag{C}, n \in \ag{N}$ and fixed $g \in {\rm GL}_2(\ag{A})$, the right translate by $g$ of the partial derivative of this flat section, as a function on ${\rm GL}_2(\ag{A})$
	$$ x \mapsto g.f_{s_0}^{(n)}(x) := \frac{\partial^n}{\partial s^n} \mid_{s=s_0} f_s(xg) $$
is a linear combination of such functions. The above function is clearly left invariant by $\gp{N}(\ag{A})$, of central character $\omega$. Taking $x=a(y)\kappa$ for $y \in \ag{A}^{\times}, \kappa \in \gp{K}$ and writing
	$$ \kappa g = z' n' a(y') \kappa', \quad \text{for} \quad z' \in \gp{Z}(\ag{A}), n' \in \gp{N}(\ag{A}), y' \in \ag{A}^{\times}, \kappa' \in \gp{K}, $$
where $z',n',y',\kappa'$ are viewed as functions in $\kappa$, we obtain
	$$ \frac{\partial^n}{\partial s^n} \mid_{s=s_0} f_s(a(y)\kappa g) = \sum_{k=0}^n \binom{n}{k} \xi(y) \norm[y]_{\ag{A}}^{\frac{1}{2}+s_0} (\log \norm[y]_{\ag{A}})^k \cdot \norm[y']_{\ag{A}}^{\frac{1}{2}+s_0} (\log \norm[y']_{\ag{A}})^{n-k} \omega(z') \xi(y') f(\kappa'). $$
	Although $z',n',y',\kappa'$ are not uniquely determined by $\kappa$, both $\norm[y']_{\ag{A}}$ and $\omega(z') \xi(y') f(\kappa')$ are, and define smooth functions on $\gp{K}$. Moreover, the function
	$$ f_k(\kappa) := \norm[y']_{\ag{A}}^{\frac{1}{2}+s_0} (\log \norm[y']_{\ag{A}})^{n-k} \omega(z') \xi(y') f(\kappa') \in {\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(\xi, \omega\xi^{-1}). $$
	Hence we get the relation
	$$ \frac{\partial^n}{\partial s^n} \mid_{s=s_0} f_s = \sum_{k=0}^n \binom{n}{k} \frac{\partial^k}{\partial s^k} \mid_{s=s_0} f_{k,s} $$
and conclude.
\end{proof}
\begin{proposition}
	The vector space $\mathcal{E}^+({\rm GL}_2, \omega)$ is stable under the right translation by ${\rm GL}_2(\ag{A})$.
\label{Reis+Stab}
\end{proposition}
\begin{proof}
	Take a flat section $f_s$ as in the proof of Proposition \ref{FregStab}. Fix $s_0 \in \ag{C}, n \in \ag{N}, g \in {\rm GL}_2(\ag{A})$ with $\Re s_0 > 0$. Let $e_{\vec{k}}$ be an orthonormal $\gp{K}$-isotypic basis of ${\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(\xi, \omega\xi^{-1})$. There is an orthonormal $\gp{K}$-isotypic basis $\tilde{e}_{\vec{k}}$ of ${\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(\omega\xi^{-1}, \xi)$ and for any $n \in \ag{N}$ there is $A > 0$ such that (c.f. \cite[\S 3]{Wu5})
	$$ \mathcal{M}_s e_{\vec{k},s} = \mu_{\vec{k}}(s) \tilde{e}_{\vec{k},-s}, \quad \extnorm{\mu_{\vec{k}}^{(n)}(s)} \ll \lambda_{\vec{k}}^A $$
for some meromorphic function $\mu_{\vec{k}}(s)$, regular in $\Re s > 0, s \neq 1/2$. Here $\lambda_{\vec{k}}$ is the eigenvalue of the Laplacian on $\gp{K}_{\infty}$ for $e_{\vec{k}}$, and the bound is uniform for $s$ lying in any  compact subset of the regular region. We also have an expansion
	$$ g.f_s = \sideset{}{_{\vec{k}}} \sum a_{\vec{k}}(s,g) e_{\vec{k},s}, $$
for some functions $a_{\vec{k}}(s,g)$ holomorphic in $s$ and smooth in $g$, since
	$$ a_{\vec{k}}(s,g) = \int_{\gp{K}} f_s(\kappa g) \overline{e_{\vec{k}}(\kappa)} d\kappa. $$
	Moreover, we have $ a_{\vec{k}}(s,g) \ll_{g,f,N} \lambda_{\vec{k}}^{-N} $ for any $N \in \ag{N}$, uniformly for $s$ lying in any compact neighborhood of $s_0$. It follows that for any $l \in \ag{N}$
	$$ a_{\vec{k}}^{(l)}(s,g) := \frac{\partial^l}{\partial s^l} \mid_{s=s_0} a_{\vec{k}}(s,g) \ll_{g,f,N} \lambda_{\vec{k}}^{-N}. $$
	We thus get
	$$ g.f_{s_0}^{(n)} = \sideset{}{_{k=0}^n} \sum \sideset{}{_{\vec{k}}} \sum \binom{n}{k} a_{\vec{k}}^{(n-k)}(s_0,g) e_{\vec{k},s_0}^{(k)}. $$
	The inner sum coincides with the value at $s=s_0$ of a flat section $f_{k,s}^{(k)}$ defined by
	$$ f_k = \binom{n}{k} \sideset{}{_{\vec{k}}} \sum a_{\vec{k}}^{(n-k)}(s_0,g) e_{\vec{k}}, $$
which is smooth. We can also verify that
\begin{align*}
	\sideset{}{_{k=0}^n} \sum \frac{\partial^k}{\partial s^k} \mid_{s=s_0} \mathcal{M}_s f_{k,s} &= \sideset{}{_{k=0}^n} \sum \sideset{}{_{\vec{k}}} \sum \binom{n}{k} a_{\vec{k}}^{(n-k)}(s_0,g) \frac{\partial^k}{\partial s^k} \mid_{s=s_0} (\mu_{\vec{k}}(s) \tilde{e}_{\vec{k},-s}) \\
	&= \sideset{}{_{\vec{k}}} \sum \frac{\partial^n}{\partial s^n} \mid_{s=s_0} (a_{\vec{k}}(s,g) \mu_{\vec{k}}(s) \tilde{e}_{\vec{k},-s}) = \frac{\partial^n}{\partial s^n} \mid_{s=s_0} \mathcal{M}_s f_s,
\end{align*}
	hence we deduce that
	$$ g.{\rm E}_{\gp{N}}^{(n)}(s_0,f) = \sideset{}{_{k=0}^n} \sum {\rm E}_{\gp{N}}^{(k)}(s_0,f_k). $$
	We conclude by
	$$ g.{\rm E}^{(n)}(s_0,f) = \sideset{}{_{k=0}^n} \sum {\rm E}^{(k)}(s_0,f_k) $$
since both sides are orthogonal to the cusp forms and have the same constant term.
\end{proof}
\begin{remark}
	$f_k$ constructed in both proofs of Proposition \ref{FregStab} and \ref{Reis+Stab} coincide with each other.
\end{remark}
\begin{remark}
	The subspace $\mathcal{E}^{{\rm reg}}({\rm GL}_2,\omega)$ is stable under right translation by $\gp{K}$ but not by ${\rm GL}_2(\ag{A})$. Take $\omega = 1$ for example. Choose a finite place $\mathfrak{p}_0$ with uniformizer $\varpi_0$. Let $e_0 \in {\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(1,1)$ be the spherical function taking value $1$ on $\gp{K}$. Let $e_1$ be defined by $e_{1,v} = e_{0,v}$ for $v \neq \mathfrak{p}_0$; while $e_{1,\mathfrak{p}_0}$ is unitary, $\gp{K}_0[\mathfrak{p}_0]$-invariant and orthogonal to $e_{0,\mathfrak{p}_0}$. For example, if $q = {\rm Nr}(\mathfrak{p}_0)$, we can take
	$$ e_{1,\mathfrak{p}_0} = \sqrt{1+q^{-1}} \cdot \left\{ \sqrt{q+1} \cdot 1_{\gp{K}_0[\mathfrak{p}]} - \frac{1}{\sqrt{q+1}} \cdot 1_{\gp{K}_{\mathfrak{p}}} \right\}. $$
	It can be computed, writing $\tilde{\lambda}_{\mathbf{F}}(s) = \lambda_{\mathbf{F}}(s-1/2)$, that
	$$ \mathcal{M}_s e_{0,s} = \tilde{\lambda}_{\mathbf{F}}(s) e_{0,-s}, \quad \mathcal{M}_s e_{1,s} = \tilde{\lambda}_{\mathbf{F}}(s) \mu_1(s) e_{0,-s}, \quad {\rm E}_{\gp{N}}^{{\rm reg}}(1/2,e_0) = e_{0,1/2} - \lambda_{\mathbf{F}}^{(-1)}(0) e_{0,-1/2}^{(1)}, $$
	$$ a(\varpi_0^{-1}).e_{0,s} = c_1(s) e_{1,s} + c_0(s) e_{0,s}; \quad \text{where} $$
	$$ \mu_1(s) = q^{-2s} \frac{1-q^{-(1-2s)}}{1+q^{-(1+2s)}}, \quad c_1(s) = \frac{q^{s+1/2} - q^{-(s+1/2)}}{q^{1/2}+q^{-1/2}}, \quad c_0(s) = \frac{q^s+q^{-s}}{q^{1/2}+q^{-1/2}}. $$





	We deduce that
	$$ \varphi := a(\varpi_0^{-1}).{\rm E}^{{\rm reg}}(1/2,e_0) - c_0(1/2) {\rm E}^{{\rm reg}}(1/2,e_0) - c_1(1/2) {\rm E}^{{\rm reg}}(1/2,e_1) $$
has constant term
	$$ \varphi_{\gp{N}} = \lambda_{\mathbf{F}}^{(-1)}(0) (c_1^{(1)}(-1/2) - c_1(1/2) \mu_1^{(1)}(1/2)) \cdot e_{1,-1/2} + \lambda_{\mathbf{F}}^{(-1)}(0) c_0^{(1)}(-1/2) e_{0,-1/2} \neq 0, $$
hence $0 \neq \tilde{\varphi} \notin \mathcal{E}({\rm GL}_2,1)$. Consequently, $a(\varpi_{\mathfrak{p}}^{-1}).{\rm E}^{{\rm reg}}(1/2,e_0) \notin \mathcal{E}({\rm GL}_2,1)$. We also deduce that
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} a(\varpi_0^{-1}).{\rm E}^{{\rm reg}}(1/2,e_0) = \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi = \lambda_{\mathbf{F}}^{(-1)}(0) c_0^{(1)}(-1/2) \neq 0, $$
hence the regularized integral is in general not ${\rm PGL}_2(\ag{A})$-invariant (c.f. Proposition \ref{RegGInv} (1) below).
\label{RegIntGinvLoss}
\end{remark}
\begin{proposition}
	Let $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$.
\begin{itemize}
	\item[(1)] We can always find (not unique) $\mathcal{E}(\varphi) \in \mathcal{E}({\rm GL}_2,\omega)$ such that $\varphi - \mathcal{E}(\varphi) \in {\rm L}^1({\rm GL}_2, \omega)$.
	\item[(2)] If for any $\chi \in \mathcal{E}{\rm x}(\varphi)$, we have $\Re \chi \neq 1/2$, then there is a unique function $\mathcal{E}(\varphi) \in \mathcal{E}({\rm GL}_2,\omega)$ such that $\varphi - \mathcal{E}(\varphi) \in {\rm L}^2({\rm GL}_2, \omega)$. Moreover, for any $X$ in the universal enveloping algebra of ${\rm GL}_2(\ag{A}_{\infty})$, we have $X.\varphi - X.\mathcal{E}(\varphi) \in {\rm L}^2({\rm GL}_2, \omega)$, i.e., $\mathcal{E}(X.\varphi) = X.\mathcal{E}(\varphi)$.
\end{itemize}
\label{ResSp}
\end{proposition}
\begin{proof}
	By Lemma \ref{IntExpBd} and Proposition \ref{GlobRDEisWhi}, it is not difficult to see that $\mathcal{E}({\rm GL}_2,\omega) \cap {\rm L}^2({\rm GL}_2(\mathbf{F}) \backslash {\rm GL}_2(\ag{A}), \omega) = \{0\}$, which implies the uniqueness of $\mathcal{E}(\varphi)$ in (2). For the existence, we find $\chi_i, \alpha_i, n_i, f_i$ as in Definition \ref{FinRegFuncDef}. Then we take, writing $\mu_i = \mu(\omega^{-1}\chi_i^2)$,
\begin{equation}
	\mathcal{E}(\varphi) = \sum_{\substack{\Re \alpha_j > 0 \\ \alpha_j \neq \frac{1}{2}+i\mu_j}} \frac{\partial^{n_j}}{\partial s^{n_j}}{\rm E}(\alpha_j,\omega,\omega^{-1}\chi_j;f_j) + \sum_{\substack{\Re \alpha_j > 0 \\ \alpha_j = \frac{1}{2}+i\mu_j}} \frac{\partial^{n_j}}{\partial s^{n_j}}{\rm E}^{{\rm reg}}(\alpha_j,\omega,\omega^{-1}\chi_j;f_j).
\label{ReisDef}
\end{equation}
	Thus for any $\chi \in \mathcal{E}{\rm x}(\varphi-\mathcal{E}(\varphi))$, we have $\Re \chi \leq 1/2$ resp. $\Re \chi < 1/2$ under the condition in (2). Hence $\varphi-\mathcal{E}(\varphi) \in {\rm L}^1({\rm GL}_2, \omega)$ resp. ${\rm L}^2({\rm GL}_2, \omega)$. For the ``moreover'' part, it suffices to see that the differential operator $X$ does not increase the real part of elements in $\mathcal{E}{\rm x}(\varphi)$, which is essentially due to the following calculation:
	$$ y \frac{d}{dy} (y^{\sigma} \log^k y) = y^{\sigma} \log^k y + k y^{\sigma} \log^{k-1}y, \forall y>0, \sigma \in \ag{C}, k \in \ag{N}. $$
\end{proof}
\begin{definition}
	In the case (2), we call $\mathcal{E}(\varphi)$ the ${\rm L}^2$-residue of $\varphi$. For definiteness, we shall write $\mathcal{E}(\varphi)$ to be the one given by (\ref{ReisDef}).
\end{definition}
\begin{proposition}
\begin{itemize}


	\item[(1)] For any $\mathcal{E} \in \mathcal{E}({\rm GL}_2,1)$, we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} \mathcal{E}(g) dg = 0. $$
	If moreover $\mathcal{E} \in \mathcal{E}^+({\rm GL}_2,1)$, then for any $g_0 \in {\rm GL}_2(\ag{A})$, we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} g_0.\mathcal{E}(g) dg = 0. $$
	\item[(2)] Let $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,1)$. For any $\mathcal{E} \in \mathcal{E}({\rm GL}_2,1)$ such that $\varphi - \mathcal{E} \in {\rm L}^1([{\rm PGL}_2])$ we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi(g) dg = \int_{[{\rm PGL}_2]} (\varphi-\mathcal{E})(g) dg. $$
	In particular, $\int_{[{\rm PGL}_2]}^{{\rm reg}}$ is always $\gp{K}$-invariant. It is ${\rm GL}_2(\ag{A})$-invariant on the subspace of $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,1)$ such that $\mathcal{E}{\rm x}(\varphi)$ does not contain $\norm_{\ag{A}}$.
\end{itemize}
\label{RegGInv}
\end{proposition}
\begin{proof}
	For (1), the second assertion follows from the first by Proposition \ref{Reis+Stab}. We calculate $a(t,\mathcal{E})$ for $\mathcal{E}(g) = \frac{\partial^n}{\partial s^n} {\rm E}(s,f)(gg_0)$ with $s \neq 1/2-i\mu(\chi)$ resp. $\frac{\partial^n}{\partial s^n} {\rm E}^{{\rm reg}}(\frac{1}{2}-i\mu(\chi),f)(g)$ for some $f \in V_{\chi,\chi^{-1}}^{\infty}$ with $\Re s > 0$, a unitary character $\chi$ of $\mathbf{F}^{\times} \backslash \ag{A}^{\times}$ if $\chi \mid_{\mathbf{F}^{\times} \backslash \ag{A}^{(1)}} = 1$. Due to the integral $\int_{\mathbf{F}^{\times} \backslash \ag{A}^{(1)}} d^{\times}y$, it is easy to see that $a(t,\varphi)$ is non-vanishing only if $\chi$ is trivial on $\mathbf{F}^{\times} \backslash \ag{A}^{(1)}$, in which case $\mu(\omega\chi^2)=2\mu(\chi)$. We also notice that we can interchange the order of $\mathcal{M}$ and $\int_{\gp{K}} dk$ since they commute with each other.
\begin{itemize}

	\item $\mathcal{E}(g) = \frac{\partial^n}{\partial s^n} {\rm E}(s,f)(g)$ with $s \neq 1/2-i\mu(\chi)$: We get
	$$ a(t,\mathcal{E}) = \zeta_{\mathbf{F}}^*(1) \int_{\gp{K}} f(k)dk \cdot \left\{ t^{\frac{1}{2}+s+i\mu(\chi)} \log^n t + \frac{\partial^n}{\partial s^n} \left( t^{\frac{1}{2}-s-i\mu(\chi)} \frac{\Lambda_{\mathbf{F}}(1-2s-2i\mu(\chi))}{\Lambda_{\mathbf{F}}(1+2s+2i\mu(\chi))} \right) \right\}, $$
	and conclude by the fact that $a(t,\mathcal{E})$ has no constant term as a function of $t$.
	\item $\mathcal{E}(g)=\frac{\partial^n}{\partial s^n} {\rm E}^{{\rm reg}}(\frac{1}{2}-i\mu(\chi),f)(g)$: We get
\begin{align*}
	a(t,\mathcal{E}) &= \zeta_{\mathbf{F}}^*(1) \int_{\gp{K}} f(k)dk \cdot \\
	&\quad \left\{ t \log^n t + \frac{\partial^n}{\partial s^n} \mid_{s=\frac{1}{2}-i\mu(\chi)} \left( (t^{\frac{1}{2}-s-i\mu(\chi)}-1) \frac{\Lambda_{\mathbf{F}}(1-2s-2i\mu(\chi))}{\Lambda_{\mathbf{F}}(1+2s+2i\mu(\chi))} \right) \right\} \\
	&= \zeta_{\mathbf{F}}^*(1) \int_{\gp{K}} f(k)dk \cdot \\
	&\quad \left\{ t \log^n t + \sum_{l=0}^n \binom{n}{l} \frac{(-1)^l}{l+1} \cdot \log^{l+1}t \cdot \frac{d^{n-l}}{d s^{n-l}} \mid_{s=0} \left( \frac{s\Lambda_{\mathbf{F}}(2s)}{\Lambda_{\mathbf{F}}(2-2s)} \right) \right\},
\end{align*}
	and conclude the same way as in the previous case.
\end{itemize}
	For (2), the first part is trivial. For the second part, we note that $\varphi-\mathcal{E}(\varphi) \in {\rm L}^1$ implies $g_0.\varphi-g_0.\mathcal{E}(\varphi) \in {\rm L}^1$ for any $g_0 \in {\rm GL}_2(\ag{A})$, and $g_0.\mathcal{E}(\varphi)$ has regularized integral $0$ by (1) if either $\mathcal{E} \in \mathcal{E}^+({\rm GL}_2,1)$ or $g_0 \in \gp{K}$.
\end{proof}
\begin{remark}
	The above proof of (2) is to be compared with \cite[\S 4.3.6]{MV10}, where another simpler but indirect proof was given for the ``regular case''.
\end{remark}

Some Complement of Regularized Integral
Let $\xi_1,\xi_2, \omega$ be Hecke characters with $\xi_1 \xi_2 \omega =1$. Let $f \in \pi(\xi_1,\xi_2)$ and $\varphi \in {\rm C}^{\infty}({\rm GL}_2, \omega)$, i.e., a smooth function on ${\rm GL}_2(\mathbf{F}) \backslash {\rm GL}_2(\ag{A})$ with central character $\omega$. Suppose $\varphi$ is \emph{finitely regularizable} defined in Definition \ref{FinRegFuncDef}.
\begin{proposition}
	For $\Re s \gg 1$ sufficiently large,
	$$ R(s,\varphi; f) := \int_{\mathbf{F}^{\times} \backslash \ag{A}^{\times}} \int_{\gp{K}} (\varphi_{\gp{N}} - \varphi_{\gp{N}}^*)(a(y)\kappa) f(\kappa) \xi_1(y) \norm[y]_{\ag{A}}^{s-\frac{1}{2}} d\kappa d^{\times}y $$
is absolutely convergent. It has a meromorphic continuation to $s \in \ag{C}$. If in addition
	$$ \Theta := \max_j \{ \Re \alpha_j \} < 0, $$
then we have, with the right hand side absolutely converging
	$$ R(s,\varphi; f) = \int_{[{\rm PGL}_2]} \varphi \cdot {\rm E}(s,f), \quad \Theta < \Re s < -\Theta.  $$
	In the above region, the possible poles of $R(s, \varphi; f)$ are
\begin{itemize}
	\item $1/2 + i\mu(\xi_1\xi_2^{-1})$ if $\xi_1 \xi_2^{-1}$ is trivial on $\ag{A}^{(1)}$;
	\item $(\rho - 1)/2$ where $\rho$ runs over the non-trivial zeros of $L(s,\xi_1\xi_2^{-1})$.
\end{itemize}
	In particular $R(s,\varphi; f)$ is holomorphic for $0 \leq \Re s < \min(-\Theta,1/2)$.
\label{VRI}
\end{proposition}
\begin{proof}
	The proof is quite similar to that of Theorem \ref{AdelicRegThm} (3), except that $\mathcal{M} f_s$ is no longer explicitly computable. In fact, we have for $T > 1, \Re s \gg 1$, using the standard Rankin-Selberg unfolding
\begin{align*}
	\int_{[{\rm PGL}_2]} \varphi \cdot \Lambda^T {\rm E}(s,f) &= R(s,\varphi; f) \\
	&- \int_{\mathbf{F}^{\times} \backslash \ag{A}^{\times}} \left( \int_{\gp{K}} (\varphi_{\gp{N}} - \varphi_{\gp{N}}^*)(a(y)\kappa) f(\kappa) d\kappa \right) \xi_1(y) \norm[y]_{\ag{A}}^{s-1/2} 1_{\norm[y]_{\ag{A}} > T} d^{\times} y \\
	&- \int_{\mathbf{F}^{\times} \backslash \ag{A}^{\times}} \left( \int_{\gp{K}} (\varphi_{\gp{N}} - \varphi_{\gp{N}}^*)(a(y)\kappa) \mathcal{M} f_s(\kappa) d\kappa \right) \xi_2(y) \norm[y]_{\ag{A}}^{-s-1/2} 1_{\norm[y]_{\ag{A}} > T} d^{\times} y \\
	&+ {\rm Vol}(\mathbf{F}^{\times} \backslash \ag{A}^{(1)}) \left( \sum_{j=1}^l \int_{\gp{K}} f_j(\kappa) f(\kappa) d\kappa \cdot 1_{\chi_j \xi_1(\ag{A}^{(1)}) = 1} \cdot \frac{1}{n_j !} \frac{\partial^{n_j}}{\partial s^{n_j}} \left( \frac{T^{s+\alpha_j + i\mu_j}}{s+\alpha_j + i\mu_j} \right) \right. \\
	&- \left. \sum_{j=1}^l \int_{\gp{K}} f_j(\kappa) \mathcal{M} f_s(\kappa) d\kappa \cdot 1_{\chi_j \xi_2(\ag{A}^{(1)}) = 1} \cdot \frac{(-1)^{n_j}}{n_j !} \frac{\partial^{n_j}}{\partial s^{n_j}} \left( \frac{T^{-s+\alpha_j + i\mu_j'}}{-s+\alpha_j + i\mu_j'} \right) \right),
\end{align*}
where $\mu_j$ resp. $\mu_j'$ is such that
	$$ \chi_j \xi_1(y) = \norm[y]_{\ag{A}}^{i\mu_j}, \quad \text{resp.} \quad \chi_j \xi_2(y) = \norm[y]_{\ag{A}}^{i\mu_j'}. $$
	We conclude by first shifting $s$ to the desired region, then letting $T \to \infty$. The possible poles are encoded in the possible poles of $\mathcal{M} f_s$, which are included in those of $L(1+2s, \xi_1\xi_2^{-1})^{-1}$ in the above region (c.f. for example \cite[Corollary 3.7, 3.10 \& Lemma 3.18]{Wu5}).
\end{proof}
\begin{proposition}
	Let notations be as in the previous proposition with $\Theta \leq -1/2$. Recall
	$$ \varphi_{\gp{N}}^*(n(x)a(y)k)=\varphi_{\gp{N}}^*(a(y)k)=\sum_{j=1}^l \chi_j(y) \norm[y]_{\ag{A}}^{\frac{1}{2}+\alpha_j} \log^{n_i} \norm[y]_{\ag{A}} f_j(k). $$
\begin{itemize}
	\item[(1)] If $\xi_1 \neq \xi_2$, then
	$$ \left( \frac{\partial^n R}{\partial s^n} \right)^{{\rm hol}}(\frac{1}{2},\varphi;f) = \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi \cdot {\rm E}^{(n)}(\frac{1}{2},f) - \sideset{}{_j'}\sum \frac{\lambda_{\mathbf{F}}^{(n+n_j)}(0)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_j f), $$
	where the summation is over $j$ such that $\xi_1 \chi_j (\ag{A}^{(1)}) =1, \alpha_j + i \mu(\xi_1\chi_j) = -1/2$.
	\item[(2)] If $\xi_1 = \xi_2 = \xi$, then
\begin{align*}
	\left( \frac{\partial^n R}{\partial s^n} \right)^{{\rm hol}}(\frac{1}{2},\varphi;f) &= \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi \cdot {\rm E}^{{\rm reg},(n)}(\frac{1}{2},f) - \sideset{}{_j'}\sum \frac{\lambda_{\mathbf{F}}^{(n+n_j)}(0)}{\lambda_{\mathbf{F}}^{(-1)}(0)}  {\rm P}_{\gp{K}}(f_j f) \\
	&+ \lambda_{\mathbf{F}}^{(n)}(0) \cdot {\rm P}_{\gp{K}}(f \cdot (\xi^{-1} \circ \det)) \cdot \int_{[{\rm PGL}_2]} \varphi \cdot (\xi \circ \det),
\end{align*}
	where the summation over $j$ is as in the previous case.
\end{itemize}
\label{TripleToDouble}
\end{proposition}
\begin{proof}
	The case (1) being simpler, we only give details for (2). By twisting, we may assume $\xi=1$. Let $s$ be small with $\Re s < 0$. The ${\rm L}^2$-residue of $\varphi \cdot {\rm E}(1/2+s,f)$ is given by
	$$ \mathcal{E}(s) := \sideset{}{_j} \sum {\rm E}^{(n_j)}(s+1+\alpha_j, f_j f), $$
	where the summation is over $j$ such that $\Re \alpha_j > -1$. Define
	$$ \mathcal{E}^{{\rm reg}}(s) := \sideset{}{_j'} \sum {\rm E}^{{\rm reg},(n_j)}(s+1+\alpha_j, f_j f) + \sideset{}{_j^*} \sum {\rm E}^{(n_j)}(s+1+\alpha_j, f_j f) $$
where $\sideset{}{_j'} \sum$ is the summation as in the statement and $\sideset{}{_j^*} \sum$ is the rest. By the previous proposition, we have
\begin{align*}
	R(\frac{1}{2}+s,\varphi;f) &= \int_{[{\rm PGL}_2]} \varphi \cdot {\rm E}(\frac{1}{2}+s,f) = \int_{[{\rm PGL}_2]} \varphi \cdot {\rm E}^{{\rm reg}}(\frac{1}{2}+s,f) + \lambda_{\mathbf{F}}(s) {\rm P}_{\gp{K}}(f) \cdot \int_{[{\rm PGL}_2]} \varphi \\
	&= \int_{[{\rm PGL}_2]} \left( \varphi \cdot {\rm E}^{{\rm reg}}(\frac{1}{2}+s,f) - \mathcal{E}^{{\rm reg}}(s) \right) - \int_{[{\rm PGL}_2]} \left( \mathcal{E}(s) - \mathcal{E}^{{\rm reg}}(s) \right) \\
	&\quad + \lambda_{\mathbf{F}}(s) {\rm P}_{\gp{K}}(f) \cdot \int_{[{\rm PGL}_2]} \varphi.
\end{align*}
	Since $\mathcal{E}^{{\rm reg},(n)}(s)$ is the ${\rm L}^2$-residue of $\varphi \cdot {\rm E}^{{\rm reg},(n)}(\frac{1}{2}+s,f)$, we can compare the holomorphic part of both sides and conclude by
	$$ \mathcal{E}(s) - \mathcal{E}^{{\rm reg}}(s) = \sideset{}{_j'} \sum \lambda_{\mathbf{F}}^{(n_j)}(s) {\rm P}_{\gp{K}}(f_jf). $$
\end{proof}

Behavior of Constant Term
Consider $f \in V_{\xi,\omega\xi^{-1}}^{\infty}$ and take its Fourier expansion into $\gp{K}$-isotypic types
	$$ f = \sum_{\vec{n}} \hat{f}_{\vec{n}} \cdot e_{\vec{n}}(\xi,\omega\xi^{-1}) $$
for some $\hat{f}_{\vec{n}} \in \ag{C}$, where $e_{\vec{n}}(\xi,\omega\xi^{-1})$ is unitary with $\gp{K}$-type parametrized by $\vec{n}$ as in \cite[Section 3.5]{Wu5}. For $\Re s \gg 1$, we have
	$$ {\rm E}_{\gp{N}}(s,\xi,\omega\xi^{-1};f) = f(s,\xi,\omega\xi^{-1}) + \sum_{\vec{n}} \hat{f}_{\vec{n}} \cdot \mu(s,\xi,\omega\xi^{-1};\vec{n}) e_{\vec{n}}(-s,\omega\xi^{-1},\xi), $$
where $\mu(s,\xi,\omega\xi^{-1};\vec{n})$ are the explicit coefficients of the intertwining operator on the $\gp{K}$-type $\vec{n}$ part as in \textit{loc.cit.}
\begin{proposition}
	The possible poles of the collection of meromorphic functions $\{ \mu(s,\xi,\omega\xi^{-1};\vec{n}) : \vec{n} \}$ are
\begin{itemize}
	\item The pole of $\Lambda(1-2s,\omega\xi^{-2})$ at $s=(1+i\mu(\omega\xi^{-2}))/2$ with order at most $1$, when $\omega\xi^{-2}$ is trivial on $\ag{A}^{(1)}$ and $\vec{n}=\vec{0}$. We call this pole the \emph{spherical pole}.
	\item The (both trivial and non-trivial) zeros of $L(1+2s,\omega^{-1}\xi^2)$ with order at most that of the zero.
\end{itemize}
\end{proposition}
\begin{proof}
	This can be seen either from our explicit computation of $\mu(s,\xi,\omega\xi^{-1};\vec{n})$ in \cite{Wu5}, or from (\ref{RelSec}) and
	$$ \mathcal{M} f_{\Phi}(s,\xi,\omega\xi^{-1}) = f_{\widehat{\Phi}}(-s,\omega\xi^{-1},\xi), $$
which is meromorphic with a simple pole at $s=(1+i\mu(\omega\xi^{-2}))/2$ (the other pole is cancelled by that of $f_{\Phi}(s,\xi,\omega\xi^{-1})$) by Tate's theory.
\end{proof}
\begin{lemma}
	Assume $\mu(s,\xi,\omega\xi^{-1};\vec{n}_0)$ has a pole at $s_0$ with order $n$ ($n=0$ if it is holomorphic at $s_0$) for some $\vec{n}_0$. Define
	$$ \Norm[\vec{n}] = \prod_v (\norm[n_v]+1) \text{ for } \vec{n} = (n_v)_v. $$
	Then as $s$ lying in any small compact neighborhood $K$ of $s_0$ where no other pole occur, we have
	$$ \extnorm{(s-s_0)^n \mu(s,\xi,\omega\xi^{-1};\vec{n})} \ll \Norm[\vec{n}]^N $$
for some $N$ and the implied constant depending only on $K$, $\xi$ and $\omega\xi^{-1}$ (i.e., independent of $\vec{n}$).
\end{lemma}
\begin{proof}
	This follows from the explicit computation of $\mu(s,\xi,\omega\xi^{-1};\vec{n})$ in \cite{Wu5} together with the following obvious bound
	$$ \prod_{k=1}^n \extnorm{\frac{k-s}{k+s}} \leq \prod_k \left( 1+\frac{2\norm[s]}{\norm[k+s]} \right) \leq \exp \left\{ \sum_k \frac{2\norm[s]}{\norm[k+s]} \right\} \ll (n+1)^N. $$
\end{proof}
\begin{proposition}
	Under the condition of the lemma we have
	$$ (s-s_0)^n {\rm E}_{\gp{N}}(s,\xi,\omega\xi^{-1};f) = (s-s_0)^n f(s,\xi,\omega\xi^{-1}) + \sum_{\vec{n}} \hat{f}_{\vec{n}} \cdot (s-s_0)^n \mu(s,\xi,\omega\xi^{-1};\vec{n}) e_{\vec{n}}(-s,\omega\xi^{-1},\xi). $$
	Consequently, for any $m \in \ag{N}$, $y \in \ag{A}^{\times}$ and $\kappa \in \gp{K}$ we can write
\begin{align*}
	&\quad \frac{d^m}{d s^m} \mid_{s=s_0} (s-s_0)^n {\rm E}_{\gp{N}}(s,\xi,\omega\xi^{-1};f)(a(y)\kappa) \\
	&= \frac{m!}{(m-n)!} \norm[y]_{\ag{A}}^{\frac{1}{2}+s_0} \xi(y) (\log \norm[y]_{\ag{A}})^{m-n} f(\kappa) + \sum_{k=0}^m \norm[y]_{\ag{A}}^{\frac{1}{2}-s_0} \omega\xi^{-1}(y) (\log \norm[y]_{\ag{A}})^k f_k(\kappa),
\end{align*}
where $(\log \norm[y]_{\ag{A}})^{m-n}$ is understood as $0$ if $m<n$ and where the maps
	$$ V_{\xi,\omega\xi^{-1}}^{\infty} \to V_{\omega\xi^{-1},\xi}^{\infty}, f \to f_k \text{ for } 0 \leq k \leq m $$
are $\gp{K}$-maps and continuous with respect to the Sobolev norms on $\gp{K}_{\infty}$.
\label{GlobRDEisCst}
\end{proposition}
\begin{proof}
	The lemma shows that $(s-s_0)^n \mu(s,\xi,\omega\xi^{-1};\vec{n})$ is polynomially increasing in $\vec{n}$. But $\hat{f}_{\vec{n}}$ is rapidly decreasing in $\vec{n}$ by smoothness of $f$. The sum over $\vec{n}$ is thus absolutely and uniformly convergent for $s$ lying in $K$, hence defines an analytic function in $s$. By uniqueness of analytic continuation, we get the first equation. The rest follows from the polynomial increase of $(s-s_0)^n \mu(s,\xi,\omega\xi^{-1};\vec{n})$ and Cauchy's integral formula for derivatives.
\end{proof}
\begin{remark}
	If $s_0$ is the spherical pole, then $n=1$ and for $m=0$ we have $f_k=0$ unless $k=0$. Then
	$$ f_0(\kappa) = \lim_{s \to s_0} \frac{(s-s_0)\Lambda_{\mathbf{F}}(2(s_0-s)}{\Lambda_{\mathbf{F}}(2-2(s_0-s)))} \int_{\gp{K}} f(\kappa) d\kappa = - \frac{\Lambda_{\mathbf{F}}^*(0)}{\Lambda_{\mathbf{F}}(2)} \int_{\gp{K}} f(\kappa) d\kappa. $$
\end{remark}

definition:
\label{def:compostion}
A \emph{strict composition} for a parameterized problem $L$ is an algorithm that receives as input $t$ instances $(x_1,k),\ldots,(x_t,k)\in \{0,1\}^* \times \mathbb{N}$, and outputs in polynomial~time a single instance $(y,k')\in \{0,1\}^* \times \mathbb{N}$ such that


\begin{inparaenum}[(i)]
\item $(y,k') \in L \iff (x_i,k) \in L$ for some $i \in \{1,\ldots,t\}$ and
\item $k' \leq k + c$ for some constant $c$.
\end{inparaenum}

