\end{list}

proof:
For the first claim, let $n'$ be an arbitrary subsequence. From Equation \eqref{EQ:mom} we see that $\mathbb{E}_n(r_n) = 0$ and that $\mathbb{V}_n(r_n)$ is norm-bounded and, hence, that $\mathbb{P}_n \circ r_n$ is tight. Therefore, there exists a subsequence $n''$ of $n'$ along which $\mathbb{V}_n(r_n)$ converges to $\Sigma$, say, and along which $\mathbb{P}_n \circ r_n$ converges weakly. We now need to show that $d_w(\mathbb{P}_{n''} \circ r_{n''}, N(0, \Sigma)) \rightarrow 0$, which then proves the statement in view of the triangle inequality, continuity of $\Gamma \mapsto N(0, \Gamma)$ w.r.t. $d_w$, and the fact that $n'$ was arbitrary. That the weak limit of $\mathbb{P}_{n''} \circ r_{n''}$ must be normal follows from Equations \eqref{EQ:conv} and \eqref{EQ:neg}, applying Corollary 2 in \cite{pollak1972}. The mean vector of the limiting distribution of $\mathbb{P}_{n''} \circ r_{n''}$ is $0$ from \eqref{EQ:conv}. It remains to verify that the covariance matrix of the limiting distribution is $\Sigma$. From Equations \eqref{EQ:mom} and \eqref{EQ:conv} and, e.g., Theorem 5.4 in \cite{bill2} it follows that $[r_{n}^{(j)}]^2$ is uniformly integrable for $j = 1, \hdots, k$. The inequality $ab \leq \frac{1}{2}(a^2 + b^2)$, together with the fact that the sum of two uniformly integrable sequences is uniformly integrable, then shows uniform integrability of $r_n^{(s)}r_n^{(t)}$, and hence (e.g., again Theorem 5.4 in \cite{bill2} together with weak convergence of $\mathbb{P}_{n''} \circ r_{n''}$ and the continuous mapping theorem) that the covariance matrix of the limiting distribution of $\mathbb{P}_{n''} \circ r_{n''}$ coincides with $\Sigma$.

To prove the second claim, we start with the observation that it suffices to verify that for every $\varepsilon > 0$ and every $\gamma \in {\mathbb R}^k$ it holds that

\begin{equation}
\mathbb{P}_n \left(|\gamma'\left( S_n - \mathbb{V}_n(r_n) \right) \gamma | \geq \varepsilon \right) \to 0.
\end{equation}

To see this, it suffices to first take $\gamma$ equal to the elements of the standard basis in ${\mathbb R}^k$ in order to show that the diagonal entries converge to zero. Then, taking $\gamma$ equal to $(1,1,0,\dots, 0)'$, $(0,1,1,0,\dots, 0)'$, etc., and using symmetry shows that also the entries above and below the main diagonal converge. Continuing this process with vectors containing exactly three, four, five, etc., consecutive ones, establishes the claim.
Next, to verify the statement in the previous display, let $\gamma \in {\mathbb R}^k$, $\varepsilon > 0$, and let $n'$ be an arbitrary subsequence. Choose $n''$ a subsequence of $n'$ along which $\mathbb{P}_n \circ r_n \Rightarrow N(0, \Sigma)$ - such a subsequence exists because of the already established part of the lemma. We also already know from the uniform integrability argument above, that then $\mathbb{V}_{n''}(r_{n''}) \rightarrow \Sigma$, and hence that $\sigma_{n''}^2 := \gamma' \mathbb{V}_{n''}(r_{n''}) \gamma \rightarrow \gamma' \Sigma \gamma =: \sigma^2$. Now, if $\sigma^2 = 0$, then eventually $\sigma_{n''}^2 < \varepsilon/2$, and by Markov's inequality

\begin{equation}
 \mathbb{P}_{n''} \left(\big|\gamma'\left(S_{n''}-\mathbb{V}_{n''}(r_{n''}) \right)\gamma \big| \geq \varepsilon   \right) 
\leq 

\mathbb{P}_{n''} \left(\gamma' S_{n''} \gamma \geq \frac{\varepsilon}{2}   \right) 

\leq 

\frac{2 \sigma_{n''}^2}  { \varepsilon}  \to 0.
\end{equation}

Suppose next that $\sigma^2 > 0$. Then, we can assume without loss of generality that $0 <\delta_1 \le \sigma_{n''}^2 \leq \delta$ for some $\delta,\delta_1 \in {\mathbb R}$, and it remains to verify that

\begin{equation}\label{eq:remains}
\mathbb{P}_{n''} \left( \left|\frac{\gamma' S_{n''} \gamma}{\sigma_{n''}^2 } - 1 \right| \geq \frac{\varepsilon}{\delta}   \right) \to 0.
\end{equation}

To that end, define

\begin{equation}
\xi_{i,n''} \quad = \quad \frac{\gamma' z_{i, n''}}{\sigma_{n''}}
\end{equation}

where $\sigma_{n''}$ denotes the positive square root of $\sigma_{n''}^2$, and note that by Equation~\eqref{EQ:mom} we have $\mathbb{E}_{n''} (\xi_{i,n''} ) = 0$, that by construction $\sigma_{n''}^{-2} \gamma' S_{n''} \gamma = \sum_{i = 1}^{n''} \xi_{i,n''}^2$, and that $\mathbb{V}_{n''}(\sum_{i = 1}^{n''} \xi_{i,n''}) = 1$. Note also that it follows from Equation~\eqref{EQ:neg} that for every $\bar{\delta} > 0$ we have

\begin{equation}
\max_{1 \leq i \leq n''} \mathbb{P}_{n''} \left(|\xi_{i, n''}| \geq \bar{\delta} \right) \to 0 \text{ as } n'' \rightarrow \infty.
\end{equation}

Furthermore, since $\mathbb{P}_{n''} \circ r_{n''} \Rightarrow N(0, \Sigma)$, we see that $\sum_{i = 1}^{n''} \xi_{i,n''}$ is asymptotically normal with mean $0$ and variance $1$. But then Equation~\eqref{eq:remains} follows from Raikov's theorem (\cite{gnedenko}, p. 143, Theorem 4). Since $n'$ was arbitrary, this proves the second statement. 

The statement in Equation \eqref{eqn:empclt} is an immediate consequence of the triangle inequality and the first two statements.

For the statements in Equations \eqref{EQ:diags} and \eqref{EQ:corrs} we first note that the triangular array $z_{i,n,*}^{(j)}$, and the corresponding quantities $r_{n, *}$ and $r_{n,*}^{(j)}$, satisfy Condition \ref{cond:zmom}. Hence, Lemma \ref{lemma:zmom} is applicable, and shows, in particular, for every $\varepsilon > 0$ and with the abbreviation $S_{n,*} = \sum_{i = 1}^n z_{i,n,*} z_{i,n,*}'$, that

\begin{equation}
\mathbb{P}_n \left(\| S_{n,*} -\mathbb{V}_n(r_{n, *}) \| \geq \varepsilon   \right) \to 0 \quad \text{ as } n \rightarrow \infty .
\end{equation}

Noting that the diagonal entries of $\mathbb{V}_n(r_{n, *})$ are all equal to $1$ (in fact $\mathbb{V}_n(r_{n, *})$ $=$ $\corr (\mathbb{V}_n(r_{n}))$) and that $\diag \left(S_{n,*}\right) = \diag(\mathbb{V}_n(r_n))^{-1} \diag(S_n)$ holds, establishes the claimed convergence in \eqref{EQ:diags}. But this together with the preceding display then establishes the convergence in \eqref{EQ:corrs}, because, using the abbreviation $A_n = \diag(S_n)^{\dagger/2}\diag(\mathbb{V}_n(r_n))^{1/2}$, we have $A_n \to I_k$ in $\mathbb{P}_n$-probability and
\begin{align*}
\corr(S_n) - \corr(\mathbb{V}_n(r_n))
&=
\diag(S_n)^{\dagger/2} S_n \diag(S_n)^{\dagger/2} - \mathbb{V}_n(r_{n,*})\\
&=
A_n (S_{n,*} - \mathbb{V}_n(r_{n,*}) ) A_n' \\
&\quad+ A_n \mathbb{V}_n(r_{n,*}) A_n' -  \mathbb{V}_n(r_{n,*}),
 \end{align*}
 which converges to zero in $\mathbb{P}_n$-probability.
The last part is an application of the statements already established, together with 

\begin{equation}
\mathbb{P}_n \left( d_w\left( \mathbb{P}_n \circ r_{n, *}, N(0, S_{n,*})  \right)  \geq \varepsilon \right) \to 0 \text{ for every } \varepsilon > 0,
\end{equation}

which we obtain (as above) from Lemma \ref{lemma:zmom}.

Let $\Gamma_n$ be a sequence of covariance matrices converging to $\Gamma$. By definition, $K_{1-\alpha}(\Gamma_n)$ is the $1-\alpha$-quantile of the distribution of $\|Z_n\|_{\infty}$, where $Z_n$ is a Gaussian random vector with mean $0$ and covariance matrix $\Gamma_n$. By the continuous mapping theorem, $\|Z_n\|_{\infty}$ converges weakly to $\|Z\|_{\infty}$, where $Z$ is a Gaussian random vector with mean $0$ and covariance matrix $\Gamma$. In case $\Gamma \neq 0$ it is easy to see that the distribution function of $\|Z\|_{\infty}$ is everywhere continuous and strictly increasing on $[0,\infty)$, and the result then follows, because weak convergence of distribution functions is equivalent to weak convergence of the corresponding quantile functions. Consider now the case where $\Gamma = 0$. Fix $0 < \varepsilon < 1$. Let $z$ be a random variable taking values in $[0, \infty)$, with continuous and strictly increasing (on $[0,\infty)$) distribution function and $1-\alpha$-quantile equal to $\varepsilon$. Clearly, $\|Z_n\|_{\infty} + z$ converges weakly to $z$. Hence $K_n$, say, the $1-\alpha$ quantile of $\|Z_n\|_{\infty} + z$ converges to $\varepsilon$. From $K_{1-\alpha}(\Gamma_n) \leq K_n$ it then follows that

\begin{equation*}
0 \quad \leq \quad \limsup_{n \rightarrow \infty} K_{1-\alpha}(\Gamma_n) \quad \leq \quad \varepsilon.
\end{equation*}

Therefore, $K_{1-\alpha}(\Gamma_n) \to 0 = K_{1-\alpha}(0)$.

For the first part note that the quotient under consideration is well defined with probability converging to one, that

\begin{equation}
\frac{\sum_{i = 1}^n b^2_{i,n} }{\sum_{i = 1}^n  a^2_{i,n}} - 1 = o_{\mathbb{P}_n}(1) + 2 \frac{\sum_{i = 1}^n  a_{i,n} [b_{i,n} - a_{i,n}]}{\sum_{i = 1}^n  a^2_{i,n}},
\end{equation}

and that by the Cauchy-Schwarz inequality 

\begin{equation}
\bigg| \frac{\sum_{i = 1}^n  a_{i,n} [b_{i,n} - a_{i,n}]}{\sum_{i = 1}^n  a^2_{i,n}} \bigg|
\leq 
\sqrt{\frac{\sum_{i = 1}^n (a_{i,n} - b_{i,n})^2}{\sum_{i = 1}^n  a^2_{i,n}}} = o_{\mathbb{P}_n}(1).
\end{equation}

For the second part note that the quotients are well defined with probability converging to 1 (by applying Part 1), and write

\begin{equation}
\frac{\sum_{i = 1}^n a_{i,n}(1)  a_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}} - \frac{\sum_{i = 1}^n b_{i,n}(1)  b_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  b_{i,n}^2(1)}  \sqrt{\sum_{i = 1}^n  b^2_{i,n}(2)}}
\end{equation}

as the sum of

\begin{align}
A_n &:= \frac{\sum_{i = 1}^n \big(a_{i,n}(1) - b_{i,n}(1)\big)\big(a_{i,n}(2) - b_{i,n}(2)\big)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}}
\\[7pt]
B_n &:= \frac{\sum_{i = 1}^n b_{i,n}(2) \big(a_{i,n}(1) - b_{i,n}(1)\big)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}}
\\[7pt]
C_n &:= \frac{\sum_{i = 1}^n b_{i,n}(1)\big(a_{i,n}(2) - b_{i,n}(2)\big)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}}
\end{align}

and
\begin{align}
D_n :&= \frac{\sum_{i = 1}^n b_{i,n}(1)b_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  a_{i,n}^2(1) } \sqrt{  \sum_{i = 1}^n  a^2_{i,n}(2)}} - \frac{\sum_{i = 1}^n b_{i,n}(1)  b_{i,n}(2)}{\sqrt{\sum_{i = 1}^n  b_{i,n}^2(1)}  \sqrt{\sum_{i = 1}^n  b^2_{i,n}(2)}}.
\end{align}

Using Cauchy-Schwarz inequality, the assumptions, and the first part of the lemma, we now see that $A_n$, $B_n$, $C_n$, and $D_n$ are $o_{\mathbb{P}_n}(1)$. 


For the third part we note that (eventually)

\begin{equation}
\frac{\sum_{i = 1}^n (b_{i,n} + c_{i,n})^2}{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} - 1 \quad = \quad F_n + G_n + H_n,
\end{equation}

where

\begin{align}\label{eqn:Fn}
F_n \quad &:= \quad \frac{\sum_{i = 1}^n (b_{i,n} - a_{i,n})^2}{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} = o_{\mathbb{P}_n}(1) \\[7pt]
\label{eqn:Gn}
G_n \quad &:= \quad \frac{\sum_{i = 1}^n (a_{i,n} + c_{i,n})^2}{ \mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} - 1 = \frac{\sum_{i = 1}^n c_{i,n}(2a_{i,n} + c_{i,n})}{ \mathbb{V}_n(\sum_{i = 1}^n a_{i,n})}+ o_{\mathbb{P}_n}(1)  \\[7pt]
\label{eqn:Hn}
H_n \quad &:= \quad 2 \frac{\sum_{i = 1}^n(b_{i,n} - a_{i,n})(a_{i,n} + c_{i,n})}{ \mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} 
\end{align}

where the second equality for $F_n$ follows from the last assumption appearing in Part 3 together with \eqref{eqn:consia}, and the second equality for $G_n$ follows from \eqref{eqn:consia}. By the Cauchy-Schwarz inequality and the last assumption appearing in Part 3

\begin{equation}\label{eqn:Hnbound}
|H_n| \leq o_{\mathbb{P}_n}(1) \sqrt{G_n + 1}.
\end{equation}

Now, define

\begin{equation}
\kappa_n \quad = \quad \frac{\sum_{i = 1}^n c_{i,n}(2a_{i,n} + c_{i,n})}{ \mathbb{V}_n(\sum_{i = 1}^n a_{i,n})}
\end{equation}

and note that, since by assumption $\mathbb{E}_n(a_{i,n}) = 0$, we have

\begin{equation}
\mathbb{E}_n(\kappa_n) = \frac{\sum_{i = 1}^n c_{i,n}^2}{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} =: d_n \geq 0,
\end{equation}

and it holds, using uncorrelatedness of $a_{i,n}$ for $i = 1, \hdots, n$, that

\begin{equation}\label{eqn:kappavb}
\mathbb{V}_n(\kappa_n) = 4 \frac{\sum_{i = 1}^n c_{i,n}^2 \mathbb{V}_n(a_{i,n})}{\mathbb{V}^2_n(\sum_{i = 1}^n a_{i,n})}  \leq 4 \frac{\max_{i = 1, \hdots, n} \mathbb{V}_n(a_{i,n})}{\mathbb{V}_n(\sum_{i = 1}^n a_{i,n})} ~ d_n.
\end{equation}

We need to verify that for every $\varepsilon > 0$ it holds that

\begin{equation}
\mathbb{P}_n \left( F_n + G_n + H_n \leq - \varepsilon \right) \to 0.
\end{equation}

We argue by contradiction: Suppose there exists an $\varepsilon > 0$ so that the convergence in the previous display does not hold. Then, by compactness of the Cartesian product of the extended real line with the unit interval, there exists a subsequence $n'$ along which $d_n$ converges to a $c \in [0, \infty]$ and along which the probability in the previous display converges to a $\gamma \in (0, 1] $. Suppose first that $0 \leq c < \infty$. Then, from Equation \eqref{eqn:kappavb} and Assumption \eqref{eqn:maxto0}, we see that $\kappa_{n'}$, and hence $G_{n'}$, converges to $c$ in $\mathbb{P}_{n'}$-probability, and, by Equation \eqref{eqn:Hnbound}, that $H_{n'}$ converges to $0$ in $\mathbb{P}_{n'}$-probability, showing that $F_{n'} + G_{n'} + H_{n'}$ converges to $c \geq 0$ in $\mathbb{P}_{n'}$-probability, and hence that the sequence in the previous display converges along $n'$ to $0<\gamma$, a contradiction. Assume next that $c = \infty$, and assume then, without loss of generality, that $d_{n'} > 0$ holds. We show that $(F_{n'} + G_{n'} + H_{n'})/d_{n'}$ converges to $1$ in $\mathbb{P}_{n'}$-probability, which then again contradicts $\gamma \in (0, 1]$. Note that it suffices to verify that $\kappa_{n'}/d_{n'}$ converges to $1$  in $\mathbb{P}_{n'}$-probability. But this follows, because the expectation of $\kappa_{n'}/d_{n'}$ is $1$, and because, by relation~\eqref{eqn:kappavb}, its variance is bounded from above by

\begin{equation}
4 d_{n'}^{-1} \frac{\max_{i = 1, \hdots, n'} \mathbb{V}_{n'}(a_{i,n'})}{ \mathbb{V}_{n'}(\sum_{i = 1}^{n'} a_{i,n'})} \to 0,
\end{equation}

where we used $d_{n'} \to \infty$ and Assumption~\eqref{eqn:maxto0} to obtain the limit.

Lemma \ref{lemma:nonstd} applied to the array $z_{i,n} = g_{i,n} \circ \pi_{i,n}$ defined on the space $({\mathbb R}^{n \times \ell}, \mathcal{B}({\mathbb R}^{n \times \ell}), \mathbb{P}_n)$, where $\pi_{i,n}: {\mathbb R}^{n \times \ell} \to {\mathbb R}^{1 \times \ell}$ extracts the $i-th$ row of an $n \times \ell$ matrix (to verify Condition~\ref{cond:zmomstd} we use Condition \ref{cond:sum} and replace the Lindeberg condition as discussed in Remark \ref{rem:lindeequiv}), shows that for every $\varepsilon > 0$ we have

\begin{align}\label{eqn:varconvintro}
&\mathbb{P}_n \left( \|\diag(\mathbb{V}_n(r_n))^{-1} \diag(S_n)  - I_k\| \geq \varepsilon \right) \to 0, \\

&\mathbb{P}_n \left( \|\corr \left( S_n \right) - \corr \left(  \mathbb{V}_n(r_n) \right)\| \geq \varepsilon \right) \to 0
\end{align}

and

\begin{equation}
\mathbb{P}_n \left( d_w\left(\mathbb{P}_n \circ  \hat{r}_{n,*}  , N(0, \corr(S_n))\right) \geq \varepsilon \right) \to 0,
\end{equation}

where $\hat{r}_{n, *} = \diag(S_n)^{\dagger/2} r_n$. The last part of Condition~\ref{cond:sum} together with Equation \eqref{eqn:varconvintro} now shows that $ \diag(S_n)^{\dagger/2} \Delta_n \to 0$ w.r.t. $\mathbb{P}_n$, so that 

\begin{equation}
\hat{r}_{n, *} = \diag(S_n)^{\dagger/2} \left( \hat{\theta}_n - \theta^*_n \right) + o_{\mathbb{P}_n}(1),
\end{equation}

which then proves the claim.

First, fix $n$ large enough, such that the bound of Condition~\ref{cond:X2}\eqref{cX2:Huber} holds, the pseudo parameter of Lemma~\ref{lemma:pseudo} exists and the bound of Lemma~\ref{lemma:pseudoBound} applies. Fix $\mathbb M\in\mathsf{M}_n$ and ${\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{bin})}(\tau)$. Since $H_{\mathbb M,n}(y,\beta) =$ \linebreak $X_n[M]'D_{\mathbb M,n}(y,\beta)X_n[M]$, for a diagonal matrix $D_{\mathbb M,n}(y,\beta)$ whose $i$-th diagonal entry is given by 
$$
-y_i\ddot{\phi}_1(X_{i,n}[M]\beta) - (1-y_i)\ddot{\phi}_2(X_{i,n}[M]\beta)\;>\;0,
$$
in view of Conditions~\ref{cond:H}(\ref{cH:cdf},\ref{cH:concave},\ref{cH:C2}), we see that $H_{\mathbb M,n}^*(y)$ is positive definite. Moreover, from continuity and positivity of $-\ddot{\phi}_j$, $j=1,2$, Lemma~\ref{lemma:pseudoBound} and finiteness of $\mathcal H$, we conclude that the diagonal entries of $D_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*({\mathbb P}_n))$ are lower and upper bounded by positive constants that depend only on $\tau$ and $C$. This finishes the claim in \ref{l:Hcont:A}. Consider now
\begin{align}
&\sup_{\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)} \|H_{\mathbb M,n}^*(y)^{-1/2} H_{\mathbb M,n}(y,\beta) H_{\mathbb M,n}^*(y)^{-1/2} - I_{m(\mathbb M)}\| \notag\\
&\quad\le\; 
\|X_n[M]H_{\mathbb M,n}^*(y)^{-1/2}\|^2 \sup_{\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)} \|D_{\mathbb M,n}(y,\beta)  - D_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*({\mathbb P}_n)\| \notag\\
&\quad\le\;
\frac{\|X_n[M](X_n[M]'X_n[M])^{-1}X_n[M]'\|}{\min_{i=1,\dots, n}(-y_i\ddot{\phi}_1(X_{i,n}[M]\beta_{\mathbb M,n}^*) - (1-y_i)\ddot{\phi}_2(X_{i,n}[M]\beta_{\mathbb M,n}^*))} \times\notag\\
&\quad\quad\quad
\sup_{\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)}\max_{\substack{i=1,\dots, n\\j=1,2}} |\ddot \phi_j(X_{i,n}[M]\beta) - \ddot \phi_j(X_{i,n}[M]\beta_{\mathbb M,n}^*)|. \label{eq:Hcontinuity}
\end{align}
We have just seen that the minimum on the far right side of the previous display is lower bounded by a positive constant that depends only on $\tau$ and $C$. To finish the proof, note that for $\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)$, we have 
\begin{align*}
&|X_{i,n}[M]\beta - X_{i,n}[M]\beta_{\mathbb M,n}^*| \\ &\le \|X_{i,n}[M](X_n[M]'X_n[M])^{-1/2}\| \|(X_n[M]'X_n[M])^{1/2}(\beta - \beta_{\mathbb M,n}^*)\|\le \delta \sqrt{C/n}
\end{align*} 
and that $|X_{i,n}[M]\beta_{\mathbb M,n}^*|\le K^*(\tau,C)$, by Lemma~\ref{lemma:pseudoBound}. Therefore, by uniform continuity of $\ddot{\phi}_j$ on the compact interval $[-K^*(\tau,C) - \delta \sqrt{C}, K^*(\tau,C) + \delta \sqrt{C}]$, for every $\eta>0$, there exists $n_0 = n_0(\eta, \tau, \delta, C,h)$, such that the supremum in \eqref{eq:Hcontinuity} is bounded by $\eta$, for all $n\ge n_0$. Since $\mathcal H$ is finite, the proof of \ref{l:Hcont:B} is finished. 
For part~\ref{l:Hcont:C}, simply combine part~\ref{l:Hcont:A} and Condition~\ref{cond:X2}\eqref{cX2:eigen}.

}

For any (measurable) model selection procedure $\hat{\mathbb{M}}_n$ we have

\begin{align}
& \mathbb{P}_n\left( \theta^{*(j)}_{\hat{\mathbb{M}}_n, n} \in \mathrm{CI}_{1- \alpha, \hat{\mathbb{M}}_n}^{(j), \mathrm{est}} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n) \right) \\
\geq \quad &
\mathbb{P}_n \left(\theta^{*(j)}_{\mathbb{M}, n}   \in  \mathrm{CI}_{1-\alpha, \mathbb{M}}^{(j), \mathrm{est}} \text{ for all } \mathbb{M} \in \mathsf{M}_n \text{ and } j \in \{1, \hdots, m(\mathbb{M})\}  \right).
\end{align}

It hence suffices to verify that the lower bound converges to $1-\alpha$. And for that (cf. Equation \eqref{eqn:hvarconv} below, and Condition \ref{cond:sum}) it suffices to verify that the following quantity converges to $1-\alpha$:

\begin{equation}
\mathbb{P}_n \left( \| \diag(\hat{S}_n)^{\dagger/2} (\hat{\theta}_n - \theta^*_n) \|_{\infty} \leq K_{1-\alpha}(\corr(\hat{S}_n)) \right).
\end{equation}

Lemma \ref{lemma:equivSn:full} shows that for every $\varepsilon > 0$ we have

\begin{align}\label{eqn:varconv}
&\mathbb{P}_n \left( \|\diag(\mathbb{V}_n(r_n))^{-1} \diag(S_n)  - I_k\| \geq \varepsilon \right) \to 0 \\

\label{eqn:corrconv}
&\mathbb{P}_n \left( \|\corr \left( S_n \right) - \corr \left(  \mathbb{V}_n(r_n) \right)\| \geq \varepsilon \right) \to 0 \\

\label{eqn:wconv}
&\mathbb{P}_n \left( d_w\left(\mathbb{P}_n \circ  \left[ \diag(S_n)^{\dagger/2} (\hat{\theta}_n - \theta^*_n) \right]  , N(0, \corr(S_n))\right) \geq \varepsilon\right) \to 0.
\end{align}

This also shows that the two conditions imposed  on $\hat{S}_n$ in the statement of the theorem are indeed equivalent. Furthermore, we immediately see that from any of these two assumptions, together with the previous display, it follows that for every $\varepsilon > 0$ we have

\begin{align}\label{eqn:hvarconv}
&\mathbb{P}_n \left( \|\diag(\mathbb{V}_n(r_n))^{-1} \diag(\hat{S}_n)  - I_k\| \geq \varepsilon \right) \to 0 \\

\label{eqn:hcorrconv}
&\mathbb{P}_n \left( \|\corr \left( \hat{S}_n \right) - \corr \left(  \mathbb{V}_n(r_n) \right)\| \geq \varepsilon \right) \to 0 \\

\label{eqn:hwconv}
&\mathbb{P}_n \left( d_w\left(\mathbb{P}_n \circ  \bar{r}_{n, *}  , N(0, \corr(\hat{S}_n))\right) \geq \varepsilon\right) \to 0,
\end{align}

where $\bar{r}_{n, *} = \diag(\hat{S}_n)^{\dagger/2} (\hat{\theta}_n - \theta^*_n)$. Next, let $n'$ be an arbitrary subsequence of $n$, and let $n''$ be a subsequence of $n'$ along which the norm-bounded sequence $\corr(\mathbb{V}_n(r_n))$ converges to $\bar{\Sigma}$, say. By \eqref{eqn:hcorrconv} it holds that $\corr(\hat{S}_{n''})$ converges to $\bar{\Sigma}$ in $\mathbb{P}_{n''}$-probability, and from the previous display it follows that $\mathbb{P}_{n''} \circ  \bar{r}_{n'',*}  \Rightarrow N(0, \bar{\Sigma})$. Combining these two statements, it then follows that 

\begin{equation}
\mathbb{P}_{n''} \circ (\bar{r}_{{n''}, *}, \corr(\hat{S}_{n''})) \Rightarrow Q_{\bar{\Sigma}} \otimes \delta_{\bar{\Sigma}},
\end{equation}

