\end{equation}

where $Q(x_i)$ puts mass $1/2$ to $x_i + 1$ and to $x_i - 1$, respectively, and $Q(x_i) \ast N(0, \rho)$ denotes the convolution of $Q(x_i)$ and $N(0, \rho)$, where we interpret $N(0, 0)$ as point mass at $0$, i.e., $Q(x_i) \ast N(0, 0) = Q(x_i)$. For simplicity, denote the $q$-th absolute central moment of a distribution $F$ on the Borel sets of ${\mathbb R}$ by $m_q(F)$. We note that $Q_n(x, 0) \in \mathbf{P}_n^{(\mathrm{lm})}(\delta, \tau)$, because $m_{2+h}( Q(x_i))^{\frac{2}{2+h}} = 1$ for every $h \geq 0$, and since $\tau > 1$ holds by assumption. It is easy to verify that for every $h \geq 0$ the quantity $m_{2+h}( Q(x_i)  \ast N(0, \rho) )^{\frac{2}{2+h}}$ does not depend on $x_i$, and that we have $m_{2+h}( Q(x_i)  \ast N(0, \rho) )^{\frac{2}{2+h}} \to 1$ as $\rho \to 0$. Hence there exists a $\rho^* > 0$, so that for every $\rho \in[0,\rho^*]$ and every $x \in \mathbb{R}^n$ we have $Q_n(x, \rho) \in \mathbf{P}_n^{(\mathrm{lm})}(\delta, \tau)$. Therefore, by our assumption, it holds for every $\varepsilon > 0$ that

\begin{equation}\label{eqn:contra}
\sup_{x \in \mathbb{R}^n}  \sup_{0 \leq \rho \le \rho^*} ~ Q_n(x, \rho) \left( \bigg | \frac{\hat{\sigma}^2_n}{1 + \rho} - 1 \bigg | > \varepsilon \right) \to 0.
\end{equation}

Next, let $(F, \mathcal{F}, \mathbb{Q})$ be a probability space on which, for every $n$, there are defined two independent random $n$-vectors $X_n^{(1)}$ and $X_n^{(2)}$, so that $\mathbb{Q}
\circ X_n^{(1)} \sim Q_n(0, 0)$ and $\mathbb{Q}
\circ X_n^{(2)} \sim N(0, \rho^*I_n)$, and hence the distribution of $Y_n := X_n^{(1)} + X_n^{(2)}$ is $Q_n(0, \rho^*)$. Let $\varepsilon > 0$ be fixed. From the previous display it follows that $\mathbb{Q}(|\hat{\sigma}^2_n(Y_n) - (1 + \rho^*)  | > \varepsilon )$ converges to $0$. Since the conditional distribution of $Y_n$ given $X_n^{(2)}$ is $Q_n(X_n^{(2)}, 0)$, it furthermore holds that

\begin{equation}
\mathbb{Q}(|\hat{\sigma}^2_n(Y_n) - (1 + \rho^*)  | > \varepsilon ) = \mathbb{E}_{\mathbb{Q}} \left( Q_n(X_n^{(2)}, 0)(|\hat{\sigma}^2_n - (1 + \rho^*)  | > \varepsilon )\right) \to 0,
\end{equation}

from which it now follows that $I_n(\omega) = Q_n(X_n^{(2)}(\omega), 0)(|\hat{\sigma}^2_n - (1 + \rho^*)  | > \varepsilon ) \to 0$ in $\mathbb{Q}$-probability as $n \to \infty$. Thus, there exists a subsequence $n'$ so that $I_{n'} \to 0$, $\mathbb{Q}$-almost surely. As a consequence, there exists $\bar{\omega} \in \Omega$ for which $I_{n'}(\bar{\omega}) \to 0$ as $n' \to \infty$. But this now means that for $x_{n'} = X_{n'}^{(2)}(\bar{\omega})$ it holds that $Q_{n'}(x_{n'}, 0)(|\hat{\sigma}^2_{n'} - (1 + \rho^*)  | > \varepsilon ) \to 0$. Since $\rho^* > 0$, this contradicts Equation \eqref{eqn:contra} which implies $Q_{n'}(x_{n'}, 0)(|\hat{\sigma}^2_{n'} - 1  | > \varepsilon ) \to 0$.
