	g_i\big(x_i(t+1)\big) + \frac{1}{2\eta}\|x_i(t+1) &- x_i(t) + \eta\nabla_{i} f\big(\mathbf{x}^i(t)\big)\|^2 \\
	&\le 
	g_i\big(z\big) + \frac{1}{2\eta}\left\|z - x_i(t) + \eta \nabla_{i} f\big(\mathbf{x}^i(t)\big)\right\|^2. \nonumber
	\end{flalign}
	Set $z = x_i(t)$ and simplify, we obtain:
	\begin{flalign}
	\label{prog_g}
	g_i\big(x_i(t+1)\big) - &g_i\big(x_i(t)\big)  \\
	&\le 
	- \frac{1}{2\eta}\|x_i(t+1) - x_i(t)\|^2 -\left\langle \nabla_{i} f\big(\mathbf{x}^i(t)\big),  x_i(t+1) - x_i(t) \right\rangle. \nonumber
	\end{flalign}
	Note that if $t \notin T_i$, then $x_i(t+1) = x_i(t)$ and \cref{prog_g} still holds. 
	On the other hand, \Cref{assum:smooth} implies that for all $t$ ({cf.}\xspace \eqref{eq:qb}):
	\begin{flalign}\label{prog_f}
	f\big(\mathbf{x}(t+1)\big) - f\big(\mathbf{x}(t)\big) 
	\le 
	\langle \mathbf{x}(t+1)-\mathbf{x}(t), \nabla f\big(\mathbf{x}(t)\big) \rangle + \frac{L}{2} \|\mathbf{x}(t+1)-\mathbf{x}(t)\|^2.
	\end{flalign}
	Adding up \cref{prog_f} and \cref{prog_g} (for all $i$) and recall $F = f+ \sum_i g_i$, we have
	\begin{flalign}
	F\big(\mathbf{x}(t+1)\big) - F\big(\mathbf{x}(t)\big) & - \tfrac{1}{2}(L - 1/\eta) \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 \nonumber\\
	&\le 
	 \sum_{i=1}^{p} \left\langle x_i(t+1)-x_i(t), \nabla_i f(\mathbf{x}(t)) -  \nabla_{i} f\big(\mathbf{x}^{i}(t)\big)\right\rangle
	\nonumber\\

	&\le 
	 \sum_{i=1}^{p} \|x_i(t+1)-x_i(t)\| \cdot \|\nabla_i f(\mathbf{x}(t)) -  \nabla_{i} f\big(\mathbf{x}^{i}(t)\big) \|
	\nonumber\\
	&\overset{\mathrm{(i)}}{\le} 
	 \sum_{i=1}^{p} \|x_i(t+1)-x_i(t)\| \cdot L \|\mathbf{x}(t) - \mathbf{x}^{i}(t) \|
	\label{eq:Lip}\\
	&\overset{\mathrm{(ii)}}{\le} 
	 L \cdot \sum_{i=1}^{p} \|x_i(t+1)-x_i(t)\| \cdot  \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \|
	\nonumber\\
	&\overset{\mathrm{(iii)}}{\le}  
	\sqrt{p} L \|\mathbf{x}(t+1)-\mathbf{x}(t)\| \cdot  \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \| \label{eq: func_moment}
	\\
	&\overset{\mathrm{(iv)}}{\le} 
	 \frac{\sqrt{p} L}{2}\sum_{k=(t-s)_+}^{t-1} \Big[\|\mathbf{x}(k+1) - \mathbf{x}(k) \|^2 + \|\mathbf{x}(t+1)-\mathbf{x}(t)\|^2 \Big]
	\nonumber\\
	&\le  \label{eq: progress}
	\frac{\sqrt{p} L s}{2} \|\mathbf{x}(t+1) \!-\! \mathbf{x}(t)\|^2 + \frac{\sqrt{p} L}{2} \!\sum_{k=(t-s)_+}^{t-1} \!\!\!\|\mathbf{x}(k+1) \!-\! \mathbf{x}(k) \|^2,
	\end{flalign}
	where (i) is due to the $L$-Lipschitz continuity of $\nabla f$, (ii) follows from \cref{incon_bound}, (iii) is the Cauchy-Schwarz inequality, and (iv) follows from the elementary inequality $ab\leq \tfrac{a^2+b^2}{2}$.
	Summing the above inequality over $t$ from $0$ to $n-1$ and rearranging we obtain
	\begin{flalign*}
	F\big(\mathbf{x}(n)\big) - F\big(\mathbf{x}(0)\big) 
	& \leq
	\frac{1}{2}(L + \sqrt{p} Ls - 1/\eta) \sum_{t=0}^{n-1} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 \\
	&\quad+ \frac{L}{2} \sum_{t=0}^{n-1} \sum_{k=(t-s)_+}^{t-1} \|\mathbf{x}(k+1) - \mathbf{x}(k) \|^2
	\\
	&\leq
	\frac{1}{2}(L + 2\sqrt{p}Ls - 1/\eta)  \sum_{t=0}^{n-1} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2.
	\end{flalign*}
	Therefore, if we choose $0 < \eta < \frac{1}{L (1 + 2\sqrt{p}s)}$, then let $n\rightarrow \infty$ we deduce
	\begin{align}
	\sum_{t=0}^{\infty} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 
	\leq 
	\frac{2}{1/\eta - L - 2\sqrt{p}Ls} [F\big(\mathbf{x}(0)\big) - \inf_{\mathbf{z}} F(\mathbf{z})].
	\end{align}
	By \Cref{assum:bb}, $F$ is bounded from below, hence the right-hand side is finite. 

	It is clear from \Cref{thm:limitcon} that $\{\mathbf{x}(t)\}$ and $\{\mathbf{x}^i(t)\}, i=1, \ldots, p$, share the same set of limit points, and we need to show that any limit point of $\{\mathbf{x}(t)\}$ is also a critical point of $F$.

	Let $\mathbf{x}^*$ be a limit point of $\{\mathbf{x}(t)\}$. By \Cref{def:sub} it suffices to exhibit a sequence $\mathbf{x}(k)$ satisfying\footnote{Technically, from \Cref{def:sub} we should have the Frech\'et subdifferential $\hat{\partial} F$ in \cref{crit_want}, however, a standard argument allows us to use the more convenient subdifferential \cite[Proposition 8.7]{vari_ana}.} 
	\begin{align}\label{crit_want}
	\mathbf{x}(k) \to \mathbf{x}^*, ~ F(\mathbf{x}(k)) \to F(\mathbf{x}^*), ~ \mathbf{0} \leftarrow \mathbf{u}(k) \in \partial F(\mathbf{x}(k)).
	\end{align} 

	Let us first construct the subgradient sequence $\mathbf{u}(k)$. Consider machine $i$ and any $\hat t \in T_i$, the optimality condition of \cref{update_exp} gives
	\begin{flalign}
	u_i( \hat t+1) := -\tfrac{1}{\eta} \left[x_i(\hat t+1) - x_i(\hat t) + \eta \nabla_{i} f\big(\mathbf{x}^i(\hat t)\big)\right] \in \partial g_i(x_i( \hat t+1)).
	\end{flalign}
	It then follows that 
	\begin{flalign}
	\|u_i( \hat t+1) & + \nabla_i f(\mathbf{x}( \hat t+1))\| \nonumber\\
	&\leq 
	\|u_i( \hat t+1) + \nabla_i f(\mathbf{x}( \hat t ))\| + \|\nabla_i f(\mathbf{x}( \hat t+1)) - \nabla_i f(\mathbf{x}(\hat t))\|
	\nonumber\\
	&\overset{\mathrm{(i)}}{\le} 
	\left\| \tfrac{1}{\eta} \left[ x_i( \hat t+1) - x_i(\hat t) \right] + \nabla_{i} f\big(\mathbf{x}^{i}(\hat t)\big) - \nabla_{i} f\big(\mathbf{x}(\hat t)\big) \right\| + L\|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\|
	\nonumber\\
	&\overset{\mathrm{(ii)}}{\le} 
	\tfrac{1}{\eta} \| x_i(\hat t+1) - x_i(\hat t) \| + L \|\mathbf{x}^{i}(\hat t) - \mathbf{x}(\hat t)\| + L \|\mathbf{x}(\hat t+1) - \mathbf{x}(\hat t)\|
	\nonumber\\
	\label{sub_zero_1}
	&\overset{\mathrm{(iii)}}{\le}
	\tfrac{1}{\eta} \| x_i(\hat t+1) - x_i(\hat t) \| + L \sum_{k=(\hat t-s)_+}^{\hat t} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|,
	\end{flalign}
	where (i) and (ii) are due to the $L$-Lipschitz continuity of $\nabla f$, and (iii) follows from \cref{incon_bound}.
	Next, consider any other $t\not\in T_i$ and $t\geq s$, we denote $\hat t$ as the \emph{largest} element in the set $\{ k \leq t: k \in T_i \}$. By \Cref{assum:skip} $\hat t$ always exists and $t - \hat t\leq s$. Since no update is performed on machine $i$ at any clock in $[\hat{t}+1, t]$, we have $x_i(t+1) = x_i(\hat t + 1)$. Thus, we can choose $u_i(t+1) = u_i(\hat t+1) \in \partial g_i (x_i(\hat{t}+1)) = \partial g_i (x_i(t+1))$, and obtain
	\begin{align}
	\| u_i(t+1) + \nabla_i f(\mathbf{x}(t+1)) - & u_i(\hat t + 1) - \nabla_i f(\mathbf{x}(\hat t + 1)) \|  \\
	&= 
	\| \nabla_i f(\mathbf{x}(t+1)) - \nabla_i f(\mathbf{x}(\hat t + 1)) \|
	\nonumber\\
    &\leq
	\sum_{k = \hat t
		+1}^t \|\nabla_i f(\mathbf{x}(k+1)) - \nabla_i f(\mathbf{x}(k))\|
	\nonumber\\
	&\leq 
	\sum_{k = (t-s+1)_+}^{ t} \|\nabla_i f(\mathbf{x}(k+1)) - \nabla_i f(\mathbf{x}(k))\|
	\nonumber\\
	\label{sub_zero_2}
	&{\le}
	\sum_{k = (t-s+1)_+}^{t} L \|\mathbf{x}(k+1) - \mathbf{x}(k)\|.
	\end{align}
	Combining the two cases in \cref{sub_zero_1} and \cref{sub_zero_2} we have for all $t$:
	\begin{align}
	\label{subdiff_bound}
	\| \mathbf{u}(t+1) + \nabla f(\mathbf{x}(t+1))\| 
	\leq 
	(\sqrt{p}/\eta + 2L) {\sum_{k = (t-2s)_+}^t} \| \mathbf{x}(k+1) - \mathbf{x}(k) \|,
	\end{align}
	where $\mathbf{u}(t+1) = \big( u_1(t+1),~ \ldots~,~ u_p(t+1) \big) \in \partial g (\mathbf{x}(t+1))$, and the factor $\sqrt{p} \geq 1$ is artificially introduced for the convenience of subsequent analysis. Therefore, by \cref{subdiff_bound} and \Cref{thm:limitcon} we deduce
	\begin{align}
	\label{crit_1}
	\lim_{t\to\infty} \mathrm{dist}_{\partial F(\mathbf{x}(t+1))}(\mathbf{0}) \leq  \lim_{t\to\infty } 	\| \mathbf{u}(t+1) + \nabla f(\mathbf{x}(t+1))\| = 0.
	\end{align}

	Recall that $\mathbf{x}^*$ is a limit point of $\{\mathbf{x}(t)\}$, thus there exists a  subsequence $\mathbf{x}(t_m) \to \mathbf{x}^*$. Next we verify the function value convergence in \cref{crit_want}. 
	The challenge here is that the component function $g$ is only closed, hence may not be continuous. 
	For any $t \in T_i$, applying \cref{usc} with $z = x_i^*$ and rearranging gives 
	\begin{align}
	g_i(x_i(t + 1)) 
	&\le 
	g_i\big(x^*_i\big) + \frac{1}{2\eta}\|x_i^* - x_i(t)\|^2  - \frac{1}{2\eta}\|x_i(t+1) - x_i(t)\|^2  \nonumber\\
	&\quad + \inner{x_i^* - x_i(t+1)}{\nabla_i f(\mathbf{x}^i(t))}  \nonumber\\
	\label{uniform}
	&= 
	g_i\big(x^*_i\big) + \frac{1}{2\eta}\|x_i^* - x_i(t)\|^2  - \frac{1}{2\eta}\|x_i(t+1) - x_i(t)\|^2  
	\\
	& \quad + \inner{x_i^* - x_i(t+1)}{\nabla_i f(\mathbf{x}^*)} + \inner{x_i^* - x_i(t+1)}{\nabla_i f(\mathbf{x}^i(t)) - \nabla_i f(\mathbf{x}^*)}.
	\nonumber
	\end{align}
	 Observe from \Cref{thm:limitcon} that 
	\begin{align*}
	\lim_{m\to\infty} \max_{t \in [t_m-s, t_m + s]} \|\mathbf{x}(t+1) - \mathbf{x}^*\| = 0, \qquad \lim_{m\to\infty} \max_{t \in [t_m-s, t_m + s]} \|\mathbf{x}^i(t+1) - \mathbf{x}^*\| = 0.
	\end{align*}
	By \Cref{assum:skip}, $[t_m -s, t_m + s] \cap T_i \ne \emptyset$ for all $i$. Then using the Lipschitz continuity of $\nabla f$ we deduce from \cref{uniform} that
	\begin{align}
	\label{eq:func_con}
	\limsup_{m \to \infty} \max_{t\in[t_m-s, t_m+s] \cap T_i} g_i(x_i(t+1)) \leq g_i(x_i^*).
	\end{align}
	Since each machine updates at least once during $[t_m-s, t_m]$, let $\hat t_m$ be the largest element of $[t_m-s, t_m] \cap T_i$.
	Also notice that each machine $i$ only updates at its active clocks $T_i$, it then follows that
	\begin{align*}
	\max_{t\in[t_m, t_m+s]} g_i(x_i(t+1)) = \max_{t\in[\hat t_m, t_m+s] \cap T_i} g_i(x_i(t+1)) \leq \max_{t\in[t_m -s, t_m+s] \cap T_i} g_i(x_i(t+1)),
	\end{align*}
	and hence by \eqref{eq:func_con}
	\begin{align}\label{eq: usc}
	\limsup_{m \to \infty} \max_{t\in[t_m, t_m+s]} g_i(x_i(t+1)) \leq  g_i(x_i^*).
	\end{align}

	To complete the proof, choose any $k_m\in [t_m, t_m+s]$. Since $\mathbf{x}(t_m) \to \mathbf{x}^*$, \Cref{thm:limitcon} implies that 
	\begin{align}
	\label{crit_2}
	\mathbf{x}(k_m) \to \mathbf{x}^*.
	\end{align}	
	From \cref{eq: usc} we know for all $i$, $\limsup\limits_{m\to\infty} g_i(x_i(k_m)) \leq g_i(x_i^*)$. On the other hand, it follows from the closedness of the function $g_i$ ({cf.}\xspace \Cref{assum:separable}) that $\liminf\limits_{m\to\infty} g_i(x_i(k_m)) \geq g_i(x_i^*)$, thus in fact $ \lim\limits_{m\to\infty} g_i(x_i(k_m)) = g_i(x_i^*) $. Since $f$ is continuous, we know 
	\begin{align}
	\label{crit_3}
	\lim_{m\to \infty} F(\mathbf{x}(k_m)) = \lim_{m\to \infty} f(\mathbf{x}(k_m)) + \sum_i g_i(x_i(k_m)) = F(\mathbf{x}^*).
	\end{align}
	Combining \cref{crit_1}, \cref{crit_2} and \cref{crit_3} we know  from \Cref{def:sub} that $\mathbf{x}^* \in \mathop{\mathrm{crit}}{F}$.

	The first inequality is obtained by summing the inequality \cref{eq: progress} over $t, t+1, \cdots, t+s$. So we need only prove the second inequality. 

	Let us introduce some notations to simplify the proof.
	For each machine $i$ let $t_i$  be the largest clock in $[t, t+s] \cap T_i$, and denote
	\begin{align}
	\label{eq:z}
	\mathbf{z} &= \big(x_1(t_1), ~\ldots~, x_p(t_p)\big) \\
	\label{eq:z2} \mathbf{z}^+ &= \big(x_1(t_1+1), ~\ldots~, x_p(t_p+1)\big) = \big(x_1(t+s+1), ~\ldots~, x_p(t+s+1)\big),
	\end{align}
	where the last equality is due to the maximality of each $t_i$.
	From the optimality condition of the proximal map $z^+_i = \prox{g_i}(z_i - \eta \nabla_i f(\mathbf{x}^i(t_i)))$ we deduce
	\begin{align}
	\label{eq:subgrad}
	\eta^{-1} (z_i - z_i^+) - \nabla_i f(\mathbf{x}^i (t_i)) \in \partial g_i (z_i^+).
	\end{align}
	Since the gradient of $f$ is $L$-Lipschitz continuous and the function $g$ is convex, we obtain
	\begin{align*}
	f(\mathbf{z}^+) - f(\bar\mathbf{z}) &\le \sum_{i=1}^p \langle z^+_i -  \bar z_i, \nabla_i f(\bar\mathbf{z})\rangle + \frac{L}{2} \|\mathbf{z}^+ - \bar\mathbf{z}\|^2, \\
	g(\mathbf{z}^+) - g(\bar\mathbf{z}) &\le \sum_{i=1}^p \langle z^+_i -  \bar z_i, \eta^{-1} (z_i - z_i^+) - \nabla_i f(\mathbf{x}^i (t_i)) \rangle,
	\end{align*}
	where we define $\bar \mathbf{z} := \proj{\mathop{\mathrm{crit}} F}(\mathbf{z})$, {i.e.}\xspace, the projection of $\mathbf{z}$ onto the set of critical points of $F$, and the last inequality follows from \cref{eq:subgrad}.

	Adding up the above two inequalities we obtain
	\begin{align*}
	F(&\mathbf{z}^+) - F^* - \tfrac{L}{2} \|\mathbf{z}^+ - \bar\mathbf{z}\|^2 \le \sum_{i=1}^p \langle z^+_i -  \bar z_i, \nabla_i f(\bar\mathbf{z}) + \eta^{-1} (z_i - z_i^+) - \nabla_i f(\mathbf{x}^i (t_i))\rangle \\
	&\overset{\mathrm{(i)}}{\le} \sum_{i=1}^{p} [\|z_i^+ - z_i\| + \|z_i - \bar z_i\|] [\|\nabla_i f(\mathbf{x}^i (t_i)) - \nabla_i f(\bar\mathbf{z})\| + \eta^{-1} \|z_i - z_i^+\|] \\	
	&\overset{\mathrm{(ii)}}{\le} \sum_{i=1}^{p} 4\left[ \|z_i^+ - z_i\|^2 + \|z_i - \bar z_i\|^2 + \eta^{-2} \|z_i^+ - z_i\|^2 + \|\nabla_i f(\mathbf{x}^i (t_i)) - \nabla_i f(\bar\mathbf{z})\|^2 \right] \\
	&\le 4\left[ \|\bar\mathbf{z} - \mathbf{z}\|^2 + (1+\eta^{-2}) \|\mathbf{z}^+ - \mathbf{z}\|^2 +  \sum_{i=1}^{p} L^2 \|\mathbf{x}^i (t_i) - \bar\mathbf{z}\|^2 \right],
	\end{align*}
	where (i) is due to the Cauchy-Schwarz inequality and the triangle inequality, (ii) is due to the elementary inequality $(a+b)(c+d) \leq 4(a^2+b^2+c^2+d^2)$, and the last inequality is due to the $L$-Lipschitz continuity of $\nabla f$.

	Using again the triangle inequality we obtain from the above inequality that
	\begin{align}
	F(\mathbf{z}^+) - F^* &\le (L+4)\|\bar\mathbf{z} - \mathbf{z}\|^2 + (L+4+\tfrac{4}{\eta^{2}}) \|\mathbf{z}^+ - \mathbf{z}\|^2 + 4L^2\sum_{i=1}^{p} \|\mathbf{x}^i (t_i) - \mathbf{z}\|^2 \nonumber\\
	\nonumber&\overset{\mathrm{(i)}}{=} (L\!+\!4)\|\bar\mathbf{z} \!-\! \mathbf{z}\|^2 \!+\! \sum_{i=1}^{p} [(L\!+\!4\!+\!\tfrac{4}{\eta^{2}})\|x_i(t_i\!+\!1) \!-\! x_i(t_i)\|^2 \!+\! 4L^2\|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2],\\
	&\overset{\mathrm{(ii)}}{\leq} (L\!+\!4)\|\bar\mathbf{z} \!-\! \mathbf{z}\|^2 + (L\!+\!4\!+\!\tfrac{4}{\eta^{2}}) B(t+s+1) + 4L^2\sum_{i=1}^{p}  \|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2,	
	\label{eq:Fgap}
	\end{align}
	where (i) is due to our definition of $\mathbf{z}$ and $\mathbf{z}^+$ in \eqref{eq:z} and \eqref{eq:z2}, and (ii) is due to the fact that $t_i \in [t, t+s]$ for all $i$.

	We next bound the terms $\|\bar\mathbf{z} - \mathbf{z}\|^2$ and $\|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2$. First, note that

	\begin{align*}
	\| x_i(t_i+1) - x_i(t_i)\| &= \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{x}^i (t_i))) - x_i(t_i)\| \\
	&\ge \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{z})) - x_i(t_i)\| \\
	&\quad - \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{x}^i (t_i))) - \prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{z})) \| \\
	&\overset{\mathrm{(i)}}{\ge} \|\prox{g_i}(x_i(t_i) - \eta \nabla_i f(\mathbf{z})) - x_i(t_i)\| - \eta L \|\mathbf{z} - \mathbf{x}^i(t_i)\|,
	\end{align*}
	where (i) follows from the non-expansiveness of $\prox{g}$ (recall that $g$ is convex) and the $L$-Lipschitz continuity of $\nabla f$.
	Rearranging the above inequality and summing over all $i$, we obtain
	\begin{align}
	\nonumber \|\prox{g}(\mathbf{z}- \eta \nabla f(\mathbf{z})) - \mathbf{z}\|^2 &\le \sum_{i=1}^p \left[\| x_i(t_i+1) - x_i(t_i)\| +  \eta L \|\mathbf{z} - \mathbf{x}^i(t_i)\| \right]^2 \\
	\label{eq:proxb}&\le 2\sum_{i=1}^p \left[\| x_i(t_i+1) - x_i(t_i)\||^2 +  \eta^2 L^2 \|\mathbf{z} - \mathbf{x}^i(t_i)\|^2 \right]. 


	\end{align}
	The last term $\|\mathbf{z} - \mathbf{x}^i(t_i)\|^2$ can be further bounded as follows:  
	\begin{align}
	\nonumber
	\|\mathbf{z} - \mathbf{x}^i(t_i)\|^2 &= \sum_{j=1}^p \|x_j(t_j) - x_j (\tau_j^i (t_i))\|^2 \\
	&= \sum_{j=1}^p \Big\|\sum_{k = \min\{ t_j, \tau_j^i(t_i) \} }^{\max\{ t_j, \tau_j^i(t_i) \}-1} x_j(k+1) - x_j(k) \Big\|^2 \nonumber\\
	&\le \sum_{j=1}^p \Big[\sum_{k = \min\{ t_j, \tau_j^i(t_i) \} }^{\max\{ t_j, \tau_j^i(t_i) \}-1} \| x_j(k+1) - x_j(k) \| \Big]^2 \nonumber\\	
	&\overset{\mathrm{(i)}}{\le} \sum_{j=1}^p 2s \sum_{k= t-s}^{t+s-1} \| x_j(k+1) - x_j(k) \|^2 \nonumber\\

	\nonumber &= 2s \sum_{k=t-s}^{t+s-1} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|^2 \\
	\label{eq:diff} & \leq 2s [B(t) + B(t+s+1)],
	\end{align}
	where (i) is due to the fact that $t_j \in [t, t+s]$ and $\tau_j^i(t_i) \in [t-s, t+s]$.
	Combining \eqref{eq:proxb} and \eqref{eq:diff} we obtain
	\begin{align}
	\label{eq:pb} \|\prox{g}(\mathbf{z} - \eta \nabla f(\mathbf{z})) &- \mathbf{z}\|^2 
	\leq 2 B(t+s+1) +  4ps\eta^2 L^2 [B(t) + B(t+s+1)].

	\end{align}

	Thanks to \Cref{thm:limitcon}, we know for $t$ sufficiently large, $\|\prox{g}(\mathbf{z} \!-\! \eta \nabla f(\mathbf{z})) \!-\! \mathbf{z}\| \leq \eta\delta$. Since the function $\eta \mapsto \frac{1}{\eta}\|\prox{g}(\mathbf{z} \!-\! \eta \nabla f(\mathbf{z})) \!-\! \mathbf{z}\|$ is monotonically decreasing \cite{Sra12}, we can apply the error bound condition in \Cref{assum:eb} for $\eta < 1$ and $t$ sufficiently large, and obtain
	\begin{align}
	\label{eq:projdist}
	\|\bar\mathbf{z} - \mathbf{z}\|^2 \le \kappa \|\mathbf{z} - \prox[]{g}(\mathbf{z} - \nabla f(\mathbf{z}))\|^2 \le \kappa \eta^{-2} \|\mathbf{z} - \prox{g}(\mathbf{z} - \eta\nabla f(\mathbf{z}))\|^2.
	\end{align}













	Finally, combining \eqref{eq:Fgap}, \eqref{eq:diff}, \eqref{eq:pb} and \eqref{eq:projdist} we arrive at:
	\begin{align}
	\nonumber
	F(\mathbf{x}(t\!+\!s\!+\!1)) - F^* &= F(\mathbf{z}^+) - F^* \\
	\nonumber&\le (L\!+\!4)\|\bar\mathbf{z} \!-\! \mathbf{z}\|^2 + (L\!+\!4\!+\!\tfrac{4}{\eta^{2}}) B(t\!+\!s\!+\!1) + 4L^2\sum_{i=1}^{p}  \|\mathbf{x}^i (t_i) \!-\! \mathbf{z}\|^2,\\	

	&\le  a_\eta B(t+s+1) +  b B(t),
	\end{align}
	where the coefficients are
	\begin{align}
	\label{eq:ab}
	a_\eta &= L+4+8psL^2 + 4ps\kappa L^2(L+4) + \tfrac{2}{\eta^2}(2+4\kappa+\kappa L), \\
	b &= 8psL^2+4ps\kappa L^2(L+4).
	\end{align}


















































































	We first show that \cref{global_finite} implies \cref{local_finite}. Indeed, recall from \eqref{eq:local_diff}:
	\begin{align*}
	\|\mathbf{x}^i(t+1) - \mathbf{x}^i(t)\| 
	&\leq 
	\sum_{k=(t-s)_+}^{t} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|.
	\end{align*}

	Therefore, summing for $t=0, 1, \cdots, n$ gives
	\begin{align*}
	\sum_{t=0}^n \|\mathbf{x}^i(t+1) - \mathbf{x}^i(t)\| 
	&\leq 
	\sum_{t=0}^n  \sum_{k=(t-s)_+}^{t} \|\mathbf{x}(k+1) - \mathbf{x}(k)\|
	\\
	&\leq 
	(2s+1) \sum_{t=0}^n \|\mathbf{x}(t+1) - \mathbf{x}(t)\|.
	\end{align*}
	The claim then follows by letting $n$ tend to infinity. 

	By \Cref{thm:limitcon}, the limit points of $\{\mathbf{x}(t)\}$ and $\{\mathbf{x}^i(t)\}_{i=1}^p$ coincide and are critical points of $F$. Thus, the only thing left to prove is the finite length property in \cref{global_finite}. 
	By \Cref{assum:sd} and \Cref{assum:bb}, the objective value $F(\mathbf{x}(t))$   decreases to a finite limit $F^*$. 

	Since $\{\mathbf{x}(t)\}$ is assumed to be bounded, the set of its limit points $\Omega$ is nonempty and compact. Summing \cref{usc} over all $i$ and set $\mathbf{z} \in \Omega$, we obtain
	\[
	g(\mathbf{x}(t+1)) \le g(\mathbf{z}) - \frac{1}{2\eta} \|\mathbf{x}(t+1) - \mathbf{x}(t)\|^2 - \sum_{i=1}^{p}\inner{\nabla_i f(\mathbf{x}^i(t))}{\mathbf{x}(t+1) - \mathbf{x}(t)}.
	\]
	Note that $\mathbf{x}(t+1) - \mathbf{x}(t) \to 0$.  Also, since $\{\mathbf{x}(t)\}$ is bounded and $\mathbf{x}(t) - \mathbf{x}^i(t)\to 0$ for all $i$, $\{\mathbf{x}^i(t)\}_{i=1}^p$ are all bounded.  we then take limsup on both sides and obtain that $\limsup_{t\to\infty} g(\mathbf{x}(t+1)) \le g(\mathbf{z})$. Together with the closedness of $g$ we further obtain that $\lim_{t\to\infty} g(\mathbf{x}(t+1)) = g(\mathbf{z})$. Note that $f$ is continuous, we thus conclude that $\lim_{t\to\infty} F(\mathbf{x}(t+1)) = F(\mathbf{z})$ for all $\mathbf{z}\in \Omega$. Note that $F(\mathbf{x}(t)) \downarrow F^*$. Thus for all $\mathbf{x}^* \in \Omega$, we have $F(\mathbf{x}^*) \equiv F^*$. 
	Now fix $\varepsilon > 0$. Since $\Omega$ is compact, for $t$ sufficiently large we have $\mathrm{dist}_{\Omega}(\mathbf{x}(t)) \leq \varepsilon$. We now have all ingredients to apply the  K\L\xspace inequality in \Cref{def:KL}: for all sufficiently large $t$,
	\begin{flalign}\label{uKL}
	\varphi'\big(F(\mathbf{x}(t)) - F^*\big) \cdot \mathrm{dist}_{\partial F(\mathbf{x}(t))}(\mathbf{0}) \ge 1.
	\end{flalign}
	Since $\varphi$ is concave, we obtain
	\begin{flalign}
	\Delta_{t,t+1} &:= \varphi\big(F(\mathbf{x}(t)) - F^*\big) - \varphi\big(F(\mathbf{x}(t+1)) - F^*\big) \nonumber\\
	&\ge \varphi'\big(F(\mathbf{x}(t)) - F^*\big) \big(F(\mathbf{x}(t)) -F(\mathbf{x}(t+1))\big)
	\nonumber\\
	\label{Lyapunov}
	&\ovset{(i)}{\ge} 
	\frac{\alpha \|\mathbf{x}(t+1) - \mathbf{x}(t) \|^2}{\mathrm{dist}_{\partial F(\mathbf{x}(t))}(\mathbf{0})},
	\end{flalign}
	where (i) follows from \Cref{assum:sd} and \cref{uKL}.
	It is clear that the function $\varphi$ (composed with $F$) serves as a Lyapunov function. Using the elementary inequality $2\sqrt{ab} \le a + b$ we obtain from \cref{Lyapunov} that for $t$ sufficiently large,
	\begin{flalign*}
	2\|\mathbf{x}(t+1) - \mathbf{x}(t)\| 
	\le 
	\tfrac{\delta}{\alpha} \Delta_{t,t+1} + \tfrac{1}{\delta}\mathrm{dist}_{\partial F(\mathbf{x}(t))}(\mathbf{0}),
	\end{flalign*}
	where $\delta > 0$ will be specified later. Recalling the bound for $\partial F(\mathbf{x}(t))$ in \cref{subdiff_bound}, and summing over $t$ from $m$ (sufficiently large) to $n$ gives:
	\begin{flalign*}
	2\sum_{t=m}^{n}&\|\mathbf{x}(t+1) - \mathbf{x}(t)\| 
	\le  
	\sum_{t=m}^{n} \frac{\delta}{\alpha} \Delta_{t, t+1} + 
	\sum_{t=m}^{n} \frac{1}{\delta} \mathrm{dist}_{\partial F(\mathbf{x}(t))}(\mathbf{0})
	\\
	&\ovset{(i)}{\le}
	\frac{\delta}{\alpha} \varphi\big(F(\mathbf{x}(m)) - F^*\big) + 
	\sum_{t=m}^{n} \frac{\sqrt{p}/\eta + 2L}{\delta} \sum_{k = (t-2s)_+}^t \| \mathbf{x}(k+1) - \mathbf{x}(k) \|
	\\
	&\le
	\frac{\delta}{\alpha} \varphi\big(F(\mathbf{x}(m)) - F^*\big) + 
	\frac{(2s+1)(\sqrt{p}/\eta + 2L)}{\delta}
	\sum_{k=(m-2s)_+}^{m-1} \| \mathbf{x}(k+1) - \mathbf{x}(k) \|
	\\
	&\qquad\qquad \qquad\qquad + 
	\frac{(2s+1)(\sqrt{p}/\eta + 2L)}{\delta}
	\sum_{t=m}^{n} \| \mathbf{x}(t+1) - \mathbf{x}(t) \|,
	\end{flalign*}
	where (i) is due to \cref{subdiff_bound}.
	Setting $\delta = (2s+1)(\sqrt{p}/\eta + 2L)$ and rearranging gives 
	\begin{flalign*}
	\sum_{t=m}^{n}\|\mathbf{x}(t+1) - \mathbf{x}(t)\| 
	&\le 
	\frac{(2s+1)(\sqrt{p}/\eta + 2L)}{\alpha} \varphi\big(F(\mathbf{x}(m)) - F^*\big) \\
	&\quad+ 
	\sum_{k=(m-2s)_+}^{m-1} \| \mathbf{x}(k+1) - \mathbf{x}(k) \|.
	\end{flalign*}
	Since the right-hand side is finite, let $n$ tend to infinity completes the proof for \cref{global_finite}.

Let us denote $L_f$ and $L_g$ as the Lipschitz constant of the gradient $\nabla f$ and $\nabla g$, respectively. Since $\Delta_\eta(\mathbf{x}) \in \prox{g}(\mathbf{x} - \eta \nabla f(\mathbf{x})) - \mathbf{x}$, using the optimality condition for the proximal map, see for instance \cite[Proposition 7(iii)]{YuZMX15}, we have
$$
\mathbf{x} + \Delta_\eta(\mathbf{x}) + \eta \nabla g\big(\mathbf{x} + \Delta_\eta(\mathbf{x})\big) = \mathbf{x} - \eta \nabla f(\mathbf{x}),
$$
and similarly
$$
\mathbf{z} + \Delta_\eta(\mathbf{z}) + \eta \nabla g\big(\mathbf{z} + \Delta_\eta(\mathbf{z})\big) = \mathbf{z} - \eta \nabla f(\mathbf{z}).
$$
Subtracting one inequality from another, we obtain
\begin{align*}
\|\Delta_\eta(\mathbf{x}) - \Delta_\eta(\mathbf{z})\|  &=  \|\eta \nabla g\big(\mathbf{z} + \Delta_\eta(\mathbf{z})\big) - \eta \nabla g\big(\mathbf{x} + \Delta_\eta(\mathbf{x})\big) + \eta \nabla f(\mathbf{z}) - \eta \nabla f(\mathbf{x})\|
\\
&\leq
\eta L_g \| \mathbf{z} - \mathbf{x} + \Delta_\eta(\mathbf{z}) - \Delta_\eta(\mathbf{x}) \| + \eta L_f \|\mathbf{z} - \mathbf{x}\|
\\
&\leq
\eta L_g \| \Delta_\eta(\mathbf{z}) - \Delta_\eta(\mathbf{x}) \| + \eta (L_f+L_g) \|\mathbf{z} - \mathbf{x}\|.
\end{align*}
Rearranging we obtain
$$
\|\Delta_\eta(\mathbf{x}) - \Delta_\eta(\mathbf{z})\| \leq \frac{\eta(L_f+L_g)}{1-\eta L_g} \|\mathbf{z}-\mathbf{x}\|,
$$
when $0 < \eta < 1/L_g$. Clearly, when $\eta$ is mall, the leading coefficient $\tfrac{\eta(L_f+L_g)}{1-\eta L_g} \in \mathcal{O}(\eta) \subseteq o(1)$, and our proof is complete.




















Using the elementary inequality $\|a\|^2 - \|b\|^2 \le 2\|a\|\|a - b\|$, we have for all $t$:
\begin{flalign}
\|\mathbf{x}(t+1) - &\mathbf{x}(t)\|^2 - \left\|\mathbf{x}(t+2) - \mathbf{x}(t+1)\right\|^2 \nonumber\\
&\le 2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \cdot \left\|(\mathbf{x}(t+1) - \mathbf{x}(t)) - (\mathbf{x}(t+2) - \mathbf{x}(t+1))\right\|
 \nonumber\\
 &\leq  2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \cdot \sum_{i=1}^{p}\left\|(x_i(t+1) - x_i(t)) - (x_i(t+2) - x_i(t+1))\right\|\nonumber\\
&\ovset{(i)}{\leq}  2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \cdot \sum_{i=1}^{p} \left \|\Delta_\eta(\mathbf{x}^{i} (t)) - \Delta_\eta(\mathbf{x}^{i} (t+1))\right\|\nonumber\\

&\ovset{(ii)}{\le} 2\left\|\mathbf{x}(t+1) - \mathbf{x}(t)\right\| \left(\sum_{i=1}^{p} L_\eta \|\mathbf{x}^{i} (t) - \mathbf{x}^{i} (t+1)\| \right)\nonumber\\
