theorem:
\label{theorem: geometry of s-concavity}
Let $\mathcal{D}$ be an isotropic $s$-concave distribution in $\mathbb{R}^n$. Then there exist \textbf{closed-form} functions $\gamma(s,m)$, $f_1(s, n)$, $f_2(s, n)$, $f_3(s, n)$, $f_4(s, n)$, and $f_5(s, n)$ such that
\begin{enumerate}[leftmargin=*]\setlength{\itemsep}{-0.1cm}

\item
\emph{(Weakly Closed under Marginal)} The marginal of $\mathcal{D}$ over $m$ arguments (or cumulative distribution function, CDF) is isotropic $\gamma(s,m)$-concave. (Theorems \ref{theorem: marginal}, \ref{theorem: distribution function})
\item
\emph{(Lower Bound on Hyperplane Disagreement)} For any two unit vectors $u$ and $v$ in $\mathbb{R}^n$, $f_1(s, n)\theta(u,v)\le\Pr_{x\sim \mathcal{D}}[\textup{sign}(u\cdot x)\not=\textup{sign}(v\cdot x)]$, where $\theta(u,v)$ is the angle between $u$ and $v$. (Theorem \ref{theorem: disagreement and angle})
\item
\emph{(Probability of Band)} There is a function $d(s, n)$ such that for any unit vector $w\in\mathbb{R}^n$ and any $0<t\le d(s,n)$, we have $f_2(s, n)t< \Pr_{x\sim\mathcal{D}}[|w\cdot x|\le t]\le f_3(s, n)t$. (Theorem \ref{theorem: probability within margin})
\item
\emph{(Disagreement outside Margin)} For any absolute constant $c_1>0$ and any function $f(s,n)$, there exists a function $f_4(s,n)>0$ such that $\Pr_{x\sim\mathcal{D}}[\mathrm{sign}(u\cdot x)\not=\mathrm{sign}(v\cdot x)\ \text{and}\ |v\cdot x|\ge f_4(s,n)\theta(u,v)]\le c_1f(s,n)\theta(u,v)$. (Theorem \ref{theorem: disagreement outside band})
\item
\emph{(Variance in 1-D Direction)} There is a function $d(s, n)$ such that for any unit vectors $u$ and $a$ in $\mathbb{R}^n$ such that $\|u-a\|\le r$ and for any $0<t\le d(s, n)$, we have $\mathbb{E}_{x\sim \mathcal{D}_{u,t}}[(a\cdot x)^2]\le f_5(s, n)(r^2+t^2)$, where $\mathcal{D}_{u,t}$ is the conditional distribution of $\mathcal{D}$ over the set $\{x:\ |u\cdot x|\le t\}$. (Theorem \ref{theorem: 1-D variance})
\item
\emph{(Tail Probability)}
We have
$\Pr[\|x\|>\sqrt{n}t]\le \left[1-\frac{cst}{1+ns}\right]^{(1+ns)/s}$. (Theorem \ref{theorem: tail probability})
\end{enumerate}

If $s\rightarrow 0$ (i.e., the distribution is log-concave), then $\gamma(s,m)\rightarrow 0$ and the functions $f(s,n)$, $f_1(s,n)$, $f_2(s,n)$, $f_3(s,n)$, $f_4(s,n)$, $f_5(s,n)$, and $d(s,n)$ are all absolute constants.

\label{theorem: generalized prekopa-leindler inequality}
Let $0<\lambda<1$, and $H_s$, $G_1$, and $G_2$ be non-negative integrable functions on $\mathbb{R}^m$ such that $H_s(\lambda x+(1-\lambda) y)\ge [\lambda G_1(x)^s\oplus(1-\lambda) G_2(y)^s]^{1/s}$ for every $x,y\in\mathbb{R}^m$. Then
$
\int_{\mathbb{R}^m}H_s(x)dx\ge \left[\lambda\left(\int_{\mathbb{R}^m}G_1(x)dx\right)^\gamma+(1-\lambda)\left(\int_{\mathbb{R}^m}G_2(x)dx\right)^\gamma\right]^{1/\gamma}
$ for $s\ge -1/m$,
with $\gamma=s/(1+ms)$.

\label{theorem: marginal}
Let $f(x,y)$ be an $s$-concave density on a convex set $K\subseteq \mathbb{R}^{n+m}$ with $s\ge -\frac{1}{m}$. Denote by $K|_{\mathbb{R}^n}=\{x\in\mathbb{R}^n: \exists y\in\mathbb{R}^m\ \mbox{s.t.}\ (x,y)\in K\}$. For every x in $K|_{\mathbb{R}^n}$, consider the section $K(x)\triangleq\{y\in\mathbb{R}^m: (x,y)\in K\}$. Then the marginal density $g(x)\triangleq\int_{K(x)}f(x,y)dy$ is $\gamma$-concave on $K|_{\mathbb{R}^n}$, where $\gamma=\frac{s}{1+ms}$. Moreover, if $f(x,y)$ is isotropic, then $g(x)$ is isotropic.

\label{theorem: distribution function}
The CDF of $s$-concave distribution in $\mathbb{R}^n$ is $\gamma$-concave, where $\gamma=\frac{s}{1+ns}$ and $s\ge -\frac{1}{n}$.

\label{theorem: tail probability}
Let $x$ come from an isotropic distribution over $\mathbb{R}^n$ with an $s$-concave density. Then for every $t\ge 16$, we have
$\Pr[\|x\|>\sqrt{n}t]\le \left[1-\frac{cst}{1+ns}\right]^{(1+ns)/s}$,
where $c$ is an absolute constant.

\label{theorem: upper and lower bounds}
Let $f:\mathbb{R}^n\rightarrow\mathbb{R}_+$ be an isotropic $s$-concave density. Then

(a) Let $d(s,n)=(1+\gamma)^{-1/\gamma}\frac{1+3\beta}{3+3\beta}$, where $\beta=\frac{s}{1+(n-1)s}$ and $\gamma=\frac{\beta}{1+\beta}$. For any $u\in\mathbb{R}^n$ such that $\|u\|\le d(s,n)$, we have \red{$f(u)\ge \left(\frac{\|u\|}{d}((2-2^{-(n+1)s})^{-1}-1)+1\right)^{1/s}f(0)$}.

(b) $f(x)\le f(0)\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}-1\right]^{1/s}$ for every $x$.

(c) There exists an $x\in\mathbb{R}^n$ such that $f(x)>(4e\pi)^{-n/2}$.

(d) $(4e\pi)^{-n/2}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+\frac{1}{s}}\right)^{s}-1\right]^{-\frac{1}{s}}<f(0)\le \red{(2-2^{-(n+1)s})^{1/s}\frac{n\Gamma(n/2)}{2\pi^{n/2}d^n}}$.

(e) \red{$f(x)\le (2-2^{-(n+1)s})^{1/s}\frac{n\Gamma(n/2)}{2\pi^{n/2}d^n}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{n-1+1/s}\right)^{s}-1\right]^{1/s}$} for every $x$.

(f) For any line $\ell$ through the origin, $\int_{\ell} f \le \red{(2-2^{-ns})^{1/s}\frac{(n-1)\Gamma((n-1)/2)}{2\pi^{(n-1)/2}d^{n-1}}}$.

\label{theorem: probability within margin}
Let $\mathcal{D}$ be an isotropic $s$-concave distribution in $\mathbb{R}^n$. Denote by $f_3(s,n)=2(1+ns)/(1+(n+2)s)$. Then for any unit vector $w$,
$
\Pr_{x\sim\mathcal{D}}[|w\cdot x|\le t]\le f_3(s,n)t.
$
Moreover, if $t\le d(s,n)\triangleq\left(\frac{1+2\gamma}{1+\gamma}\right)^{-\frac{1+\gamma}{\gamma}}\frac{1+3\gamma}{3+3\gamma}$ where $\gamma=\frac{s}{1+(n-1)s}$, then
$
\Pr_{x\sim\mathcal{D}}[|w\cdot x|\le t]> f_2(s,n)t,
$
where $f_2(s,n)=2(2-2^{-2\gamma})^{-1/\gamma}(4e\pi)^{-1/2}\left(2\left(\frac{1+\gamma}{1+3\gamma}\sqrt{3}\left(\frac{1+2\gamma}{1+\gamma}\right)^{\frac{3+3\gamma}{2\gamma}}\right)^\gamma-1\right)^{-1/\gamma}$.

\label{theorem: disagreement and angle}
Assume $\mathcal{D}$ is an isotropic $s$-concave distribution in $\mathbb{R}^n$. Then for any two unit vectors $u$ and $v$ in $\mathbb{R}^n$, we have $d_\mathcal{D}(u,v)=\Pr_{x\sim\mathcal{D}}[\textup{sign}(u\cdot x)\not=\textup{sign}(v\cdot x)]\ge f_1(s,n)\theta(u,v)$, where $f_1(s,n)=c\red{(2-2^{-3\alpha})^{-\frac{1}{\alpha}}\hspace{-0.1cm}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1+\gamma)^{3/\gamma}}2^{1+1/\alpha}\right)^{\alpha}\hspace{-0.2cm}-1\right]^{-\frac{1}{\alpha}}}(1+\gamma)^{-2/\gamma}\left(\frac{1+3\beta}{3+3\beta}\right)^2$, $c$ is an absolute constant, $\alpha=\frac{s}{1+(n-2)s}$, $\beta=\frac{s}{1+(n-1)s}$, $\gamma=\frac{s}{1+ns}$.

\label{theorem: disagreement outside band}
Let $u$ and $v$ be two vectors in $\mathbb{R}^n$ and assume that $\theta(u,v)=\theta<\pi/2$. Let $\mathcal{D}$ be an isotropic $s$-concave distribution. Then for any absolute constant $c_1>0$ and any function $f_1(s,n)>0$, there exists a function $f_4(s,n)>0$ such that
$
\Pr_{x\sim\mathcal{D}}[\mathrm{sign}(u\cdot x)\not=\mathrm{sign}(v\cdot x)\ \text{and}\ |v\cdot x|\ge f_4(s,n)\theta]\le c_1f_1(s,n)\theta,
$
where $f_4(s,n)=\frac{4\beta_1(2,\alpha)B(-1/\alpha-3,3)}{-c_1f_1(s,n)\alpha^3\beta_2(2,\alpha)^3}$, $B(\cdot,\cdot)$ is the beta function, $\alpha=s/(1+(n-2)s)$, $\beta_1(2,\alpha)$ and $\beta_2(2,\alpha)$ are given by Lemma \ref{lemma: more refined upper bound}.

\label{theorem: 1-D variance}
Assume that $\mathcal{D}$ is isotropic $s$-concave. For $d$ given by Theorem \ref{theorem: upper and lower bounds} (a), there is an absolute $C_0$ such that for all $0<t\le d$ and for all $a$ such that $\|u-a\|\le r$ and $\|a\|\le 1$,
$
\mathbb{E}_{x\sim \mathcal{D}_{u,t}}[(a\cdot x)^2]\le f_5(s,n)(r^2+t^2),
$
where $f_5(s,n)=16+C_0\frac{8\beta_1(2,\eta)B(-1/\eta-3,2)}{f_2(s,n)\beta_2(2,\eta)^3(\eta+1)\eta^2}$, $(\beta_1(2,\eta), \beta_2(2,\eta))$ and $f_2(s,n)$ are given by Lemma \ref{lemma: more refined upper bound} and Theorem \ref{theorem: probability within margin}, and $\eta=\frac{s}{1+(n-2)s}$.

\label{theorem: margin-based active learning realizable case}
In the realizable case, let $\mathcal{D}$ be an isotropic $s$-concave distribution in $\mathbb{R}^n$. Then for $0<\epsilon<1/4$, $\delta>0$, and absolute constants $c$, there is an algorithm (see the supplementary material) that runs in $T=\lceil\log \frac{1}{c\epsilon}\rceil$ iterations, requires $m_k\hspace{-0.1cm}=\hspace{-0.1cm}O\hspace{-0.1cm}\left(\frac{f_3\min\{2^{-k}f_4f_1^{-1},d\}}{2^{-k}}\left(n\log \frac{f_3\min\{2^{-k}f_4f_1^{-1},d\}}{2^{-k}}\hspace{-0.1cm}+\hspace{-0.1cm}\log \frac{1+s-k}{\delta}\right)\hspace{-0.1cm}\right)$ labels in the $k$-th round, and outputs a linear separator of error at most $\epsilon$ with probability at least $1-\delta$. In particular, when $s\rightarrow 0$ (a.k.a. log-concave), we have $m_k=O\left(n+\log(\frac{1+s-k}{\delta})\right)$.

\label{theorem: margin-based active learning adversarial noise}
Let $\mathcal{D}$ be an isotropic $s$-concave distribution in $\mathbb{R}^n$ over $x$ and the label $y$ obey the adversarial noise model. If the rate $\eta$ of adversarial noise satisfies $\eta<c_0\epsilon$ for some absolute constant $c_0$, then for $0<\epsilon<1/4$, $\delta>0$, and an absolute constant $c$, Algorithm \ref{algorithm: margin based active learning adversarial noise} runs in $T=\lceil\log \frac{1}{c\epsilon}\rceil$ iterations, outputs a linear separator $w_T$ such that $\Pr_{x\sim \mathcal{D}}[\textup{sign}(w_T\cdot x)\not=\textup{sign}(w^*\cdot x)]\le\epsilon$ with probability at least $1-\delta$. The label complexity in the $k$-th round is $m_k=O\left( \frac{[b_{k-1}s+\tau_k(1+ns)[1-(\delta/(\sqrt{n}(k+k^2)))^{s/(1+ns)}]+\tau_ks]^2}{\kappa^2\tau_k^2s^2}n\left(n+\log \frac{k+k^2}{\delta}\right)\right)$, where $\kappa=\max\left\{\frac{f_3\tau_k}{f_2\min\{b_{k-1},d\}},\frac{b_{k-1}\sqrt{f_5}}{\tau_k\sqrt{f_2}}\right\}$, $\tau_k=\Theta\left(f_1^{-2}f_2^{-1/2}f_3f_4^2f_5^{1/2}2^{-(k-1)}\right)$, $b_k=\min\{\Theta(2^{-k}f_4f_1^{-1}),d\}$. In particular, if $s\rightarrow 0$, $m_k=O\left(n\log(\frac{n}{\epsilon\delta})(n+\log(\frac{k}{\delta}))\right)$.

\label{theorem: disagreement coefficient}
Let $\mathcal{D}$ be an isotropic $s$-concave distribution over $\mathbb{R}^n$. For any $w^*$ and $r>0$, the disagreement coefficient is $\Theta_{w^*,\mathcal{D}}(\epsilon)=O\left(\frac{\sqrt{n}(1+ns)^2}{s(1+(n+2)s)f_1(s,n)}(1-\epsilon^{\frac{s}{1+ns}})\right)$. In particular, when $s\rightarrow0$ (a.k.a. log-concave), $\Theta_{w^*,\mathcal{D}}(\epsilon)=O(\sqrt{n}\log(1/\epsilon))$.

\label{theorem: Baum's algorithm}
In the PAC realizable case, there is an algorithm (see the supplementary material) that outputs a hypothesis $h$ of error at most $\epsilon$ with probability at least $1-\delta$ under isotropic $s$-concave distributions. The label complexity is $M(\epsilon/2,\delta/4,n^2)+\max\{2m_2/\epsilon,(2/\epsilon^2)\log(4/\delta)\}$, where $M(\epsilon,\delta,m)$ is defined by $M(\epsilon,\delta,n)=O\left(\frac{n}{\epsilon}\log \frac{1}{\epsilon}+\frac{1}{\epsilon}\log\frac{1}{\delta}\right)$, $m_2=M(\max\{\delta/(4eKm_1),\epsilon/2\},\delta/4,n)$, $d=(1+\gamma)^{-1/\gamma}\frac{1+3\beta}{3+3\beta}$, $K=\beta_1(3,\kappa)\frac{B(-1/\kappa-3,3)}{(-\kappa\beta_2(3,\kappa))^3}\frac{3+1/\kappa}{h(\kappa)d^{3+1/\kappa}}$, $\beta=\frac{\kappa}{1+2\kappa}$, $\gamma=\frac{\kappa}{1+\kappa}$, $\kappa=\frac{s}{1+(n-3)s}$, and $h(\kappa)=\left(\frac{1}{d}((2-2^{-4\kappa})^{-1}-1)+1\right)^{\frac{1}{\kappa}}(4e\pi)^{-\frac{3}{2}}\left[\left(\frac{1+\beta}{1+3\beta}\sqrt{3(1\hspace{-0.1cm}+\hspace{-0.1cm}\gamma)^{3/\gamma}}2^{2+\frac{1}{\kappa}}\right)^{\kappa}\hspace{-0.2cm}-\hspace{-0.1cm}1\right]^{-1/\kappa}$. In particular, if $s\rightarrow 0$ (a.k.a. log-concave), $K$ is an absolute constant.

\label{theorem: lower bounds of learning halfspace}
For a fixed value $-\frac{1}{2n+3}\le s\le 0$ we have: (a) For any $s$-concave distribution $\mathcal{D}$ in $\mathbb{R}^n$ whose covariance matrix is of full rank, the sample complexity of learning origin-centered linear separators under $\mathcal{D}$ in the passive learning scenario is $\Omega\left(nf_1(s,n)/\epsilon\right)$; (b) The label complexity of active learning of linear separators under $s$-concave distributions is $\Omega\left(n\log\left(f_1(s,n)/\epsilon\right)\right)$.

\label{theorem: vc theory}
Denote by $\mathcal{C}$ a class of concepts from a set $X$ to $\{-1,1\}$ with VC dimension $n$. Let $c\in\mathcal{C}$, and assume that
\begin{equation*}
M(\epsilon,\delta,n)=O\left(\frac{n}{\epsilon}\log \frac{1}{\epsilon}+\frac{1}{\epsilon}\log\frac{1}{\delta}\right)
\end{equation*}
examples $x_1,...,x_M$ are sampled from any probability distribution $\mathcal{D}$ over $X$. Then any hypothesis $h\in\mathcal{C}$ which is consistent with $c$ on $x_1,...,x_M$ has error at most $\epsilon$, with probability at least $1-\delta$.

