lemma:
\label{pseudo-conf.lem}
Let $u$ be a global solution of \eqref{inls}. Then, for all $T\in\mathbb{R}$, the function
\[ 
u_T(t,x)=\frac{e^{-i\frac{|x|^2}{4(T-t)}}}{(T-t)^{N/2}}u\left(\frac{1}{T-t},\frac{x}{T-t}\right)
\]
is a solution of \eqref{inls} on $(-\infty, T)$, with $\|u_T\|_{L^2}=\|u\|_{L^2}$.
\label{conc-comp.lemma}
Let $\{v_n\}_{n\in \mathbb{N}}\subset H^1(\real^N)$ satisfy
\[
\lim_{n \rightarrow\infty}\|v_n\|_{L^2}=M<+\infty \quad \text{and} \quad \sup_{n\in\mathbb{N}} H(v_n) <+\infty.
\]
Then there exists a subsequence $\{v_{n_k}\}_{k\in \mathbb{N}}$ that satisfies one of the following properties.

\medskip
\noindent
(V) $\|v_{n_k}\|_{L^q}\rightarrow 0$ as $k\rightarrow\infty$ for all $q\in(2,2^*)$.

\medskip
\noindent
(D) There are sequences ${w_k},{z_k}\in H^1(\real^N)$ and a constant $\alpha\in (0,1)$ such that:
\begin{enumerate}
\item $\dist(\supp(w_k),\supp(z_k))\rightarrow\infty$;
\item $|v_k|+|z_k|\le |v_{n_k}|$;
\item $\sup_{k\in\mathbb{N}} (\|w_k\|_{H^1}+\|z_k\|_{H^1})<+\infty$;
\item $\|w_k\|_{L^2}\rightarrow\alpha M$ and $\|z_k\|_{L^2}\to (1-\alpha)M$ as $k\rightarrow\infty$;
\item $\lim_{k\rightarrow\infty}\big| \int_{\real^N}|v_{n_k}|^q-\int_{\real^N}|w_k|^q-\int_{\real^N}|z_k|^q\big|=0$ 
for all $q\in[2,2^*)$;
\item $\liminf_{k\rightarrow\infty}\big\{  H(v_{n_k})-H(w_k)-H(z_k) \big\}\ge 0$.
\end{enumerate} 

\medskip
\noindent
(C) There exists $v\in H^1(\real^N)$ and a sequence $\{y_k\}_{k\in\mathbb{N}}\subset \real^N$ such that
\[
v_{n_k}(\cdot -y_k)\rightarrow v \quad \text{in} \quad L^q(\real^N), \quad \forall q\in[2,2^*).
\]
\label{virial.lemma}
Let $u$ be a solution of \eqref{inls} on $[0,T)$, such that $u(t)\in \Sigma$ for all $t\in [0,T)$. 
Then for all $t\in[0,T)$ the following identities hold:
\begin{equation} \label{virialone}
\Gamma'(t)=4\im\int_{\real^N} \overline{u}(t,x)(\nabla u(t,x)\cdot x)dx
\end{equation}
and
\begin{equation}\label{virialtwo}
\Gamma''(t)=16E(u)+\frac{4}{p+1}(N-Np+4)\int_{\real^N} |u(t,x)|^{p+1}dx.
\end{equation}
\label{banica.lem}
Let $u\in H^1(\real^N)$ such that $\|u\|_{L^2}=\|Q\|_{L^2}$. Then for all $\theta \in C_0^\infty(\real^N)$ we have that
