\label{IAproto}
Let $X$ be a compact Hausdorff space.  A \emph{(proto) implicit atlas} of dimension $d$ on $X$ is an index set $A$ along with the following data:
\begin{rlist}
\item(Obstruction spaces) A finite-dimensional $\mathbb R$ vector space $E_\alpha$ for all $\alpha\in A$ (let $E_I:=\bigoplus_{\alpha\in I}E_\alpha$).
\item(Thickenings) A Hausdorff space $X_I$ for all finite $I\subseteq A$, and a homeomorphism $X\to X_\varnothing$.
\item(Kuranishi maps) A function $s_\alpha:X_I\to E_\alpha$ for all $\alpha\in I\subseteq A$ (for $I\subseteq J$, let $s_I:X_J\to E_I$ denote $\bigoplus_{\alpha\in I}s_\alpha$).
\item(Footprints) An open set $U_{IJ}\subseteq X_I$ for all $I\subseteq J\subseteq A$.
\item(Footprint maps) A function $\psi_{IJ}:(s_{J\setminus I}|X_J)^{-1}(0)\to U_{IJ}$ for all $I\subseteq J\subseteq A$.
\end{rlist}
which must satisfy the following ``compatibility axioms'':
\begin{rlist}
\item$\psi_{IJ}\psi_{JK}=\psi_{IK}$ and $\psi_{II}=\operatorname{id}$.
\item$s_I\psi_{IJ}=s_I$.
\item$U_{IJ_1}\cap U_{IJ_2}=U_{I,J_1\cup J_2}$ and $U_{II}=X_I$.
\item$\psi_{IJ}^{-1}(U_{IK})=U_{JK}\cap(s_{J\setminus I}|X_J)^{-1}(0)$.
\item(Homeomorphism axiom) $\psi_{IJ}$ is a homeomorphism.
\setcounter{rcountsave}{\value{rcounti}}
\end{rlist}
and the following ``transversality axioms'':
\begin{rlist}
\setcounter{rcounti}{\value{rcountsave}}
\item(Submersion axiom) $s_{J\setminus I}:X_J\to E_{J\setminus I}$ is locally modeled on the projection $\mathbb R^{d+\dim E_J}\to\mathbb R^{\dim E_{J\setminus I}}$ over $0\in E_{J\setminus I}$ for $\#I\geq 1$ (in particular, taking $I=J$ implies that $X_I$ is a topological manifold dimension $d+\dim E_I$ for $\#I\geq 1$).
\item(Covering axiom) $X_\varnothing=\bigcup_{\varnothing\ne I\subseteq A}\psi_{\varnothing I}((s_I|X_I)^{-1}(0))$.
\end{rlist}

define the orbifold fiber product by the following universal property:
\begin{equation}
\operatorname{Hom}(S,\mathcal X\times_\mathcal Z\mathcal Y):=\operatorname{Hom}(S,\mathcal X)\times_{\operatorname{Hom}(S,\mathcal Z)}\operatorname{Hom}(S,\mathcal Y)
\end{equation}
for any smooth manifold $S$.

