This shows that the maps $\check H^d(X;\mathfrak o_{X\operatorname{rel}\partial})\to R$ induced by $B$ and $B'$ coincide.  Since any two $B_1,B_2\subseteq A$ are contained in a third $B_1\cup B_2\subseteq A$, we see that the resulting element:
\begin{equation}
[X]^\mathrm{vir}_A\in\check H^d(X;\mathfrak o_{X\operatorname{rel}\partial})^\vee
\end{equation}
is independent of $B$.  We write $[X]^\mathrm{vir}$ for $[X]_A^\mathrm{vir}$ when the atlas is clear from context.

\label{IAonvectorbundlezeroset}
Let $B$ be a smooth manifold with boundary, let $p:E\to B$ be a smooth vector bundle, and let $s:B\to E$ be a smooth section with $s^{-1}(0)$ compact.  We define an implicit atlas of dimension $\dim B-\dim E$ with boundary on $X:=s^{-1}(0)$ as follows.  The index set $A$ consists of all triples $(V_\alpha,E_\alpha,\lambda_\alpha)$ (called \emph{thickening datums}) where:
\begin{rlist}
\item$V_\alpha\subseteq B$ is an open subset.
\item$E_\alpha$ is a finite-dimensional vector space.
\item$\lambda_\alpha:E_\alpha\times V_\alpha\to p^{-1}(V_\alpha)$ is a smooth homomorphism of vector bundles.
\end{rlist}
The thickened spaces are defined as follows:
\begin{equation}
X_I:=\Bigl\{(x,\{e_\alpha\}_{\alpha\in I})\in\bigcap_{\alpha\in I}V_\alpha\times\bigoplus_{\alpha\in I}E_\alpha\Bigm|s(x)+\sum_{\alpha\in I}\lambda_\alpha(x,e_\alpha)=0\Bigr\}
\end{equation}
The Kuranishi map $s_\alpha:X_I\to E_\alpha$ is the obvious projection map, the footprint $U_{IJ}$ is the locus where $x\in V_\alpha$ for all $\alpha\in J$, and the footprint maps $\psi_{IJ}:(s_{J\setminus I}|X_J)^{-1}(0)\to U_{IJ}$ are the obvious forgetful maps.  The compatibility axioms are an easy exercise.

The regular locus $X_I^\mathrm{reg}\subseteq X_I$ is the locus where $X_I$ is ``cut out transversally''; more precisely, $(x,\{e_\alpha\}_{\alpha\in I})\in X_I$ is in $X_I^\mathrm{reg}$ iff the following map is surjective:
\begin{equation}
\Bigl(ds+\sum_{\alpha\in I}d\lambda_\alpha(\cdot,e_\alpha)\Bigr)\oplus\bigoplus_{\alpha\in I}\lambda_\alpha(x,\cdot):T_xB\oplus\bigoplus_{\alpha\in I}E_\alpha\to E_x
\end{equation}
The transversality axioms are an easy exercise.  Thus $A$ is indeed an implicit atlas on $X$.

Since everything here is in the smooth category, $A$ is in fact a smooth implicit atlas.

Let $X$ be a space with localy orientable implicit atlas $A$ of dimension $d$ with boundary.  Let $B\subseteq A$ be a finite subatlas.  By Propositions \ref{Cpure} and \ref{cechcohomologypurehomotopysheaf}, there is a canonical isomorphism $\check C^\bullet(X;\mathfrak o_{X\operatorname{rel}\partial})=C_\mathrm{vir}^\bullet(X\operatorname{rel}\partial;B)$ in $D(R)$ (observe that the isomorphisms in the proof of Proposition \ref{cechcohomologypurehomotopysheaf} all come from canonical quasi-isomorphisms on the chain level).  There is also a canonical isomorphism $C_{-\bullet}(E;B)=R$ in $D(R)$.    Since $C_\mathrm{vir}^\bullet(X\operatorname{rel}\partial;B)$ is free and bounded above, we have:
\begin{equation}
\operatorname{Hom}_R(C_\mathrm{vir}^\bullet(X\operatorname{rel}\partial;B),C_{-\bullet}(E;B))=R\operatorname{Hom}_{D(R)}(\check C^\bullet(X;\mathfrak o_{X\operatorname{rel}\partial}),R)
\end{equation}
Thus the map $s_\ast:C_\mathrm{vir}^{d+\bullet}(X\operatorname{rel}\partial;B)\to C_{-\bullet}(E;B)$ gives rise to an element:
\begin{equation}\label{steenrodfclasseqndef}
[X]^\mathrm{vir}_A:=[s_\ast]\in\operatorname{Hom}_{D(R)}(\check C^\bullet(X;\mathfrak o_{X\operatorname{rel}\partial}),R[-d])\overset{\text{Lem \ref{steenrodisderiveddualofcech}}}=\overline H_d(X,\partial X;\mathfrak o_X^\vee)
\end{equation}
The commutativity of \eqref{sheafcommforFC} implies that this element is independent of the chosen finite subatlas $B\subseteq A$.

By definition, this fundamental class \eqref{steenrodfclasseqndef} projects to the fundamental class of Definition \ref{fclassdefinition} under the map $\overline H_\bullet(X,\partial X;\mathfrak o_X^\vee)\to\check H^\bullet(X;\mathfrak o_{X\operatorname{rel}\partial})^\vee$.  By chasing the various isomorphisms involved in its definition, it can be checked that $[X]^\mathrm{vir}\in\overline H_d(X,\partial X;\mathfrak o_X^\vee)$ is preserved under extension of scalars.

\label{stratificationdefinition}
Let $X$ be a topological space and let $\mathcal S$ be a poset.  A \emph{stratification} of $X$ by $\mathcal S$ is a lower semicontinuous function $X\to\mathcal S$.  We let $X^{\leq\mathfrak s}$ (resp. $X^\mathfrak s$, $X^{\geq\mathfrak s}$) denote the inverse image of $\mathcal S^{\leq\mathfrak s}$ (resp.\ $\{\mathfrak s\}$, $\mathcal S^{\geq\mathfrak s}$); lower semicontinuity of $X\to\mathcal S$ means by definition that every $X^{\geq\mathfrak s}$ is open.

For a pair of spaces $(X,\partial X)$, a stratification $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$ shall mean a stratification $X\to\mathcal S$ along with a downward closed (i.e.\ closed under taking smaller elements) subset $\partial\mathcal S\subseteq\mathcal S$ such that $X^{\partial\mathcal S}=\partial X$ (note that this implies automatically that $\partial X\subseteq X$ is closed).

\label{celllikedef}
Let $(M,\partial M)$ be a topological manifold with boundary and stratification by $(\mathcal S,\partial\mathcal S)$, and fix a map $\dim:\mathcal S\to\mathbb Z$.  This stratification is called \emph{cell-like} iff each pair $(M^{\leq\mathfrak s},M^{<\mathfrak s})$ is a topological manifold with boundary of dimension $\dim\mathfrak s$.

If $(M,\partial M)\to(\mathcal S,\partial\mathcal S)$ is cell-like, then so is $\partial M\to\partial\mathcal S$ (with empty boundary) and $(M^{\leq\mathfrak s},M^{<\mathfrak s})\to(\mathcal S^{\leq\mathfrak s},\mathcal S^{<\mathfrak s})$.

\label{IAwithstratification}
Let $(X,\partial X)$ be a pair of compact Hausdorff spaces equipped with a stratification $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$ ($\mathcal S$ finite) along with a map $\dim:\mathcal S\to\mathbb Z$.  Also fix ``orientation data'':
\begin{rlist}
\item For every $\mathfrak s\in\mathcal S$, an orientation line $\mathfrak o_\mathfrak s$ (i.e.\ a free $\mathbb Z/2$-graded $\mathbb Z$-module of rank one).
\item For $\operatorname{codim}(\mathfrak s\preceq\mathfrak t)=1$, an odd ``coboundary'' map $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$.
\end{rlist}
An \emph{implicit atlas of dimension $d$ with boundary and cell-like stratification} on $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$ consists of the same data as an implicit atlas with boundary, except that in addition we specify a $\Gamma_I$-invariant stratification $(X_I,\partial X_I)\to(\mathcal S,\partial\mathcal S)$ for all $I\subseteq A$, whose restriction to $X_\varnothing$ is the given stratification.  We add the following ``compatibiltiy axiom'':
\begin{rlist}
\item The restriction of the stratification on $X_J$ to $(s_{J\setminus I}|X_J)^{-1}(0)$ coincides with the pullback of the stratification on $X_I$ via $\psi_{IJ}$.
\setcounter{rcountsave}{\value{rcounti}}
\end{rlist}
and we modify one ``transversality axiom'':
\begin{rlist}
\setcounter{rcounti}{\value{rcountsave}}
\item\label{stratiscelllike}(Submersion axiom) In the local model $\mathbb R^{d+\dim E_I}\times\mathbb R^{\dim E_{J\setminus I}}\to\mathbb R^{\dim E_{J\setminus I}}$ (or $(\mathbb R_{\geq 0}\times\mathbb R^{d+\dim E_I-1})\times\mathbb R^{\dim E_{J\setminus I}}\to\mathbb R^{\dim E_{J\setminus I}}$), we require the stratification on the domain to be pulled back from a cell-like stratification on the first factor (for $\mathfrak s\mapsto\dim\mathfrak s+\dim E_I$).
\end{rlist}
We also specify isomorphisms of sheaves $\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}\otimes\mathfrak o_\mathfrak s\xrightarrow\sim\mathfrak o_{X_I^\mathrm{reg}}$ over $(X_I^\mathrm{reg})^{\leq\mathfrak s}$ which are compatible with $\psi_{IJ}$ and such that the following diagram commutes:
\begin{equation}
\begin{tikzcd}
\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}\otimes\mathfrak o_\mathfrak s\ar{r}\ar{d}&\mathfrak o_{X_I^\mathrm{reg}}\ar[equals]{d}\\
\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak t}}\otimes\mathfrak o_\mathfrak t\ar{r}&\mathfrak o_{X_I^\mathrm{reg}}
\end{tikzcd}
\end{equation}
for $\operatorname{codim}(\mathfrak s\preceq\mathfrak t)=1$ (the left vertical map is the tensor product of the coboundary map $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$ and the inverse of the boundary map $\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak t}}\to\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}$).  In other words, we identify $\mathfrak o_\mathfrak s$ with the orientation line of the normal bundle of $(X_I^\mathrm{reg})^{\leq\mathfrak s}\subseteq X_I^\mathrm{reg}$, so that the coboundary maps $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$ coincide with the geometric coboundary maps on normal bundles.

Given an implicit atlas with boundary and cell-like stratification $A$ on $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$, we may obtain by restriction to the corresponding strata an implicit atlas with cell-like stratification on $\partial X\to\partial\mathcal S$ (empty boundary, tensor every orientation line with $\mathfrak o_\mathbb R$) and an implicit atlas with boundary and cell-like stratification on $(X^{\leq\mathfrak s},X^{<\mathfrak s})\to(\mathcal S^{\leq\mathfrak s},\mathcal S^{<\mathfrak s})$ (tensor every orientation line with $\mathfrak o_\mathfrak s^\vee$).

\label{stratifiedvirtualdef}
Let $(X,\partial X)\to(\mathcal S,\partial\mathcal S)$ be equipped with a finite implicit atlas with boundary and cell-like stratification $A$.  For any compact $K\subseteq X$, we define:
\begin{equation}\label{virtualchainswithcornersdef}
C^\bullet_\mathrm{vir}(K,\mathcal S;A):=\bigoplus_{\mathfrak s\in\mathcal S}C^\bullet_\mathrm{vir}(K\cap X^{\leq\mathfrak s}\operatorname{rel}\partial;A)\otimes\mathfrak o_\mathfrak s
\end{equation}
(on the right, $A$ refers to the restriction of the atlas to $X^{\leq\mathfrak s}$) equipped with the differential given by the sum over $\operatorname{codim}(\mathfrak s\preceq\mathfrak t)=1$ of the pushforwards:
\begin{equation}\label{stratumpushforward}
C^\bullet_\mathrm{vir}(K\cap X^{\leq\mathfrak s}\operatorname{rel}\partial;A)\to C^{\bullet+1}_\mathrm{vir}(K\cap X^{\leq\mathfrak t}\operatorname{rel}\partial;A)
\end{equation}
tensored with the specified coboundary map $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$ (plus the internal differential).  The fact that this differential squares to zero follows from Lemma \ref{celllikelocalstructure} and the compatibility of the coboundary maps $\mathfrak o_\mathfrak s\to\mathfrak o_\mathfrak t$ with the geometric boundary maps $\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak t}}\to\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}$.

There is a natural map:
\begin{align}\label{stratifiedtounstratifiedpushforward}
C^\bullet_\mathrm{vir}(K,\mathcal S;A)&\xrightarrow\sim C^\bullet(K;A)\\
\label{stratifiedtounformula}\{\gamma_\mathfrak s\}_{\mathfrak s\in\mathcal S}&\mapsto\biggl(\sum_{\begin{smallmatrix}\mathfrak s\in\partial\mathcal S\cr\dim\mathfrak s=d-1\end{smallmatrix}}\gamma_\mathfrak s,\sum_{\begin{smallmatrix}\mathfrak s\in\mathcal S\cr\dim\mathfrak s=d\end{smallmatrix}}\gamma_\mathfrak s\biggr)
\end{align}
Note that for $\dim s=d$, the identification $\mathfrak o_{(X_I^\mathrm{reg})^{\leq\mathfrak s}}\otimes\mathfrak o_\mathfrak s=\mathfrak o_{X_I^\mathrm{reg}}$ gives a (locally constant, but possibly not constant) isomorphism $\mathfrak o_\mathfrak s=\mathbb Z$ over $(X_I^\mathrm{reg})^{\leq\mathfrak s}$ (and similarly for $\mathfrak s\in\partial\mathcal S$ with $\dim\mathfrak s=d-1$, see also Remark \ref{bdryorrmk}) which is used implicitly in \eqref{stratifiedtounformula}.  This is a chain map by Lemma \ref{celllikelocalstructure}.

Let $Z_\bullet$ be a semisimplicial set, and let $\mathcal P/Z_0$ be a set of generators.  The notation $(\sigma,p,q)$ \emph{always} means a triple where $\sigma\in Z_n$ is an $n$-simplex and $(p,q)\in\mathcal P_{\sigma(0)}\times\mathcal P_{\sigma(n)}$, where either $\dim\sigma>0$ or $a(p)<a(q)$.  We say that $(\sigma',p',q')\prec(\sigma,p,q)$ (``strictly precedes'') iff one of the two conditions holds:
\begin{rlist}
\item$\sigma'\subsetneqq\sigma$ (i.e.\ $\sigma'$ is a facet of positive codimension of $\sigma$).
\item$\sigma'=\sigma$ and $a(p)\leq a(p')$ and $a(q')\leq a(q)$ with at least one inequality being strict.
\end{rlist}
It is easy to see that $\prec$ is a partial order.

\label{IAonflowcategorydiagramdef}
Let $\mathcal X/Z_\bullet$ be a flow category diagram.  An implicit atlas $\mathcal A$ on $\mathcal X/Z_\bullet$ consists of the following data.  We give index sets $\bar\A(\sigma,p,q)$, and we define:\footnote{Warning: a particular set $\bar\A(\sigma',p',q')$ may appear many times on the right hand side.}
\begin{equation}\label{coproductforA}
\mathcal A(\sigma,p,q)^{\geq\mathfrak s}:=\coprod_{\begin{smallmatrix}0\leq i_0<\cdots<i_m\leq n\cr(p',q')\in\mathcal P_{\sigma(i_0)}\times\mathcal P_{\sigma(i_m)}\cr\exists\mathfrak t\in\mathcal S_\mathcal X(\sigma,p,q)^{\geq\mathfrak s}\text{ containing }([i_0\ldots i_m],p',q')\end{smallmatrix}}\bar\A(\sigma|[i_0\ldots i_m],p',q')
\end{equation}
We explain the notation: recall that $\mathcal S_\mathcal X(\sigma,p,q)$ parameterizes the ``possible left hand sides'' of \eqref{Wtotalcomposition}; the coproduct is over all $([i_0\ldots i_m],p',q')$ which appear as a factor in some $\mathfrak t\in\mathcal S_\mathcal X(\sigma,p,q)$ with $\mathfrak s\preceq\mathfrak t$.

For all $(\sigma,p,q)$ and $\mathfrak s\in\mathcal S_\mathcal X(\sigma,p,q)$, we give an implicit atlas with boundary with cell-like stratification $\mathcal A(\sigma,p,q)^{\geq\mathfrak s}$ on $\mathcal X(\sigma,p,q)^{\leq\mathfrak s}$ (stratified by $\mathcal S_\mathcal X(\sigma,p,q)^{\leq\mathfrak s}$, of virtual dimension $\operatorname{gr}(q)-\operatorname{gr}(p)+\dim\sigma-1-\operatorname{codim}\mathfrak s$), for which the stratification conforms to the following local model.  Given $\mathfrak s'\preceq\mathfrak s$, let $G=G(\mathfrak s',\mathfrak s)$ denote the set of possible product/face operations which may be applied to $\mathfrak s'$ for which the result is still $\preceq\mathfrak s$.  There is a tautological isomorphism of posets $2^G\to\mathcal S_\mathcal X(\sigma,p,q)^{\mathfrak s'\leq\cdot\leq\mathfrak s}$ sending a given set of product/face operations to the result of applying them to $\mathfrak s'$.  Now the local model for the stratification on (regular thickened moduli spaces of) $\mathcal X(\sigma,p,q)^{\leq\mathfrak s}$ near a point of type $\mathfrak s'$ is given by $\mathbb R_{\geq 0}^G\times\mathbb R^N$, stratified in the obvious way by $\mathcal S_\mathcal X(\sigma,p,q)^{\mathfrak s'\leq\cdot\leq\mathfrak s}$.  Clearly this stratification is cell-like.  Moreover, the normal bundle to the $\mathfrak s'$ stratum is canonically identified with $\mathfrak o_\mathbb R^{\otimes G(\mathfrak s',\mathfrak s)}$, and the implicit atlas should use this as the orientation data.

In addition, we give compatible identifications between these atlases as follows:
\begin{rlist}
\item\label{substratumC}Let $\mathfrak s\preceq\mathfrak t\in\mathcal S_\mathcal X(\sigma,p,q)$.  Then by definition:
\begin{equation*}
\mathcal A(\sigma,p,q)^{\geq\mathfrak t}\subseteq\mathcal A(\sigma,p,q)^{\geq\mathfrak s}
\end{equation*}
Both are implicit atlases on $\mathcal X(\sigma,p,q)^{\leq\mathfrak s}$ (the former by restriction to this substratum of $\mathcal X(\sigma,p,q)^{\leq\mathfrak t}$), and we identify the former with the subatlas of the latter corresponding to this tautological inclusion of index sets.
\item\label{faceC}Let $\mathfrak s\in\mathcal S_\mathcal X(\sigma|[0\ldots\hat k\ldots n],p,q)\subseteq\mathcal S_\mathcal X(\sigma,p,q)$.  Then by definition:
\begin{equation*}
\mathcal A(\sigma|[0\ldots\hat k\ldots n],p,q)^{\geq\mathfrak s}\subseteq\mathcal A(\sigma,p,q)^{\geq\mathfrak s}
\end{equation*}
Both are implicit atlases on:
\begin{equation*}
\mathcal X(\sigma|[0\ldots\hat k\ldots n],p,q)^{\leq\mathfrak s}=\mathcal X(\sigma,p,q)^{\leq\mathfrak s}
\end{equation*}
and we identify the former with the subatlas of the latter corresponding to this tautological inclusion of index sets.
\item\label{productC}Let $\mathfrak s_1\times\mathfrak s_2\in\mathcal S_\mathcal X(\sigma|[0\ldots k],p,q)\times\mathcal S_\mathcal X(\sigma|[k\ldots n],q,r)\subseteq\mathcal S_\mathcal X(\sigma,p,r)$.  Then by definition:
\begin{equation*}
\mathcal A(\sigma|[0\ldots k],p,q)^{\geq\mathfrak s_1}\sqcup\mathcal A(\sigma|[k\ldots n],q,r)^{\geq\mathfrak s_2}\subseteq\mathcal A(\sigma,p,r)^{\geq(\mathfrak s_1\times\mathfrak s_2)}
\end{equation*}
Both are implicit atlases on:
\begin{equation*}
\mathcal X(\sigma|[0\ldots k],p,q)^{\leq\mathfrak s_1}\times\mathcal X(\sigma|[k\ldots n],q,r)^{\leq\mathfrak s_2}=\mathcal X(\sigma,p,r)^{\leq(\mathfrak s_1\times\mathfrak s_2)}
\end{equation*}
and we identify the former with the subatlas of the latter corresponding to this tautological inclusion of index sets.
\end{rlist}
An implicit atlas on an $H$-equivariant flow category $\mathcal X/Z_\bullet$ is an implicit atlas along with a lift of the action of $H$ to the implicit atlas structure.

Given an implicit atlas $\mathcal A$ on $\mathcal X/Z_\bullet$ and a map $f:Y_\bullet\to Z_\bullet$, we can form the pullback implicit atlas $f^\ast\mathcal A$ on $f^\ast\mathcal X/Y_\bullet$.

\label{Fmodulecofibrantdef}
Let $\mathcal W_\bullet$ be an $\mathsf{F}$-module complex.  We say that $\mathcal W_\bullet$ is \emph{cofibrant} iff for all $(\sigma,p,q)$:
\begin{rlist}
\item$\mathcal W_\bullet(\sigma,p,q)$ is cofibrant.
\item The map:
\begin{equation}\label{boundaryinjective}
\operatornamewithlimits{colim}_{\mathfrak s\in\partial\mathcal S_\mathcal W(\sigma,p,q)}\mathcal W_\bullet(\sigma,p,q,\mathfrak s)\rightarrowtail\mathcal W_\bullet(\sigma,p,q)
\end{equation}
is a cofibration.
\end{rlist}

\label{systemofcycles}
Let $\mathcal W^\bullet$ be an $\mathsf{F}$-module complex with each $\mathcal S_\mathcal W(\sigma,p,q)$ finite.  A \emph{system of chains} $\lambda\in\mathcal W^\bullet$ (of degree $d(\sigma,p,q)$) is a collection of elements $\lambda_{\sigma,p,q}\in\mathcal W^{d(\sigma,p,q)}(\sigma,p,q)$ satisfying $d\lambda_{\sigma,p,q}=\mu_{\sigma,p,q}$ where:
\begin{equation}\label{lambdamaster}
\mu_{\sigma,p,r}:=\sum_{k=0}^n\sum_{q\in\mathcal P_{\sigma(k)}}(-1)^{k+\operatorname{gr}(p)}\lambda_{\sigma|[0\ldots k],p,q}\cdot\lambda_{\sigma|[k\ldots n],q,r}-\sum_{k=1}^{n-1}(-1)^{k+\operatorname{gr}(p)}\lambda_{\sigma|[0\ldots\hat k\ldots n],p,r}\in\mathcal W^\bullet(\sigma,p,r)
\end{equation}
(using the product/face maps on the right hand side).  Note that this sum is finite since $\mathcal S_\mathcal W(\sigma,p,q)$ is finite.  Also, note that the triples on the right hand side all strictly precede the triple on the left hand side.  We also require that the parity (in the sense of Convention \ref{signconventions}) of $\lambda_{\sigma,p,q}$ equals $\operatorname{gr}(q)-\operatorname{gr}(p)+\dim\sigma-1\in\mathbb Z/2$.  This ensures (via the Koszul rule of signs) that expanding $d\mu_{\sigma,p,q}$ using the identity $d\lambda_{\sigma,p,q}=\mu_{\sigma,p,q}$ yields zero (the signs work out correctly as a consequence of the discussion surrounding \eqref{multiorientationI}--\eqref{multiorientationIV}).  In practice the degrees $d(\sigma,p,q)$ are chosen so that $\mu_{\sigma,p,q}$ (as defined by \eqref{lambdamaster}) is formally homogeneous of the same degree as $d\lambda_{\sigma,p,q}$.

\label{Lambdadef}
Let $\mathcal X/Z_\bullet$ be an $H$-equivariant flow category diagram with implicit atlas $\mathcal A$ and coherent orientations $\omega$.  We construct a \emph{resolution} $\pi:\tilde Z_\bullet\to Z_\bullet$ (which depends on $\mathcal X$, $\mathcal A$, $\omega$) as follows.  A simplex $\Delta^n\to\tilde Z_\bullet$ consists of the following data:
\begin{rlist}
\item A map $f:\Delta^n\to Z_\bullet$ (where $\Delta^n$ is the semisimplicial $n$-simplex).
\item\label{subatlaschoice} An $H$-invariant subatlas $\mathcal B\subseteq f^\ast\mathcal A$ (meaning choices of $\bar\B(\sigma,p,q)\subseteq\bar\A(f(\sigma),p,q)$) where each $\bar\B(\sigma,p,q)$ is finite.
\item An $H$-invariant collection of fundamental cycles $[E_\alpha]\in C_\bullet(E;\alpha)$ for all $\alpha\in\bar\B$.
\item\label{lambdachoice}An $H$-invariant system of chains $\lambda\in C^\bullet_\mathrm{vir}(f^\ast\mathcal X\operatorname{rel}\partial;\mathcal B)^+$ (degree $0$ and supported inside $\operatorname{supp}\mathcal X$) with the following property.  Note that $(\mu,\lambda)$ is a cycle in the mapping cone $[C^\bullet_\mathrm{vir}(\partial f^\ast\mathcal X;\mathcal B)^+\to C^\bullet_\mathrm{vir}(f^\ast\mathcal X\operatorname{rel}\partial;\mathcal B)^+]$, whose homology is identified with $\check H^\bullet(f^\ast\mathcal X;\mathfrak o_{f^\ast\mathcal X})$.  We require that the homology class of $(\mu,\lambda)$ equal $f^\ast\omega\in\check H^0(f^\ast\mathcal X;\mathfrak o_{f^\ast\mathcal X})$.
\item\label{liftschoice}An $H$-invariant system of chains $\tilde\lambda$ for $QC_\bullet(E;\mathcal B)^+$ (degree $\operatorname{gr}(q)-\operatorname{gr}(p)+\dim\sigma-1$ and supported inside $\operatorname{supp}\mathcal X$) whose image in $C_\bullet(E;\mathcal B)^+$ coincides with $s_\ast\lambda$ (recall \eqref{GtoCpushforward}).
\item\label{augmentationschoice}An $H$-invariant map of $\mathsf{F}$-modules $[[E]]:QC_\bullet(E;\mathcal B)^+_\mathbb Z\to\mathbb Z$ which sends the fundamental class to $1$.  The left hand side $QC_\bullet(E;\mathcal B)^+_\mathbb Z$ is defined over $\mathbb Z$, and the right hand side is the $\mathsf{F}$-module which for every $(\sigma,p,q)$ is $\mathbb Z$ concentrated in degree zero (with the product/face maps being multiplication/identity respectively).
\end{rlist}

