\begin{convention}\label{complexconventions}
By a \emph{complex} $C^\bullet$ we mean a $\mathbb Z$-graded object $\bigoplus_{i\in\mathbb Z}C^i$ (in some abelian category) along with a degree $1$ endomorphism $d$ with $d^2=0$.  The \emph{homology} of a complex $C^\bullet$ is denoted $H^\bullet C^\bullet$ (defined by $H^iC^\bullet:=\ker(C^i\xrightarrow dC^{i+1})/\operatorname{im}(C^{i-1}\xrightarrow dC^i)$).  A complex is called \emph{acyclic} iff its homology vanishes.  A map of complexes $f:A^\bullet\to B^\bullet$ is a called a \emph{quasi-isomorphism} iff it induces an isomorphism on homology.  We will often use the fact that a map of complexes is a quasi-isomorphism iff its mapping cone is acyclic.

The \emph{shift} of a complex $C^\bullet[n]$ is defined by $(C^\bullet[n])^i:=C^{i+n}$.  We use the \emph{truncation functors} defined by:
\begin{equation*}
(\tau_{\geq i}C^\bullet)^j:=\begin{cases}C^j&j>i\cr\operatorname{coker}(C^{i-1}\xrightarrow dC^i)&j=i\cr 0&j<i\end{cases}\qquad
(\tau_{\leq i}C^\bullet)^j:=\begin{cases}0&j>i\cr\ker(C^i\xrightarrow dC^{i+1})&j=i\cr C^j&j<i\end{cases}
\end{equation*}
Given a sequence of maps of complexes $A_0^\bullet\to\cdots\to A_n^\bullet$ such that adjacent maps compose to zero, we denote by $[A_0^\bullet\to\cdots\to A_n^{\bullet-n}]$ the associated total complex of this double complex.  For example, $f:A^\bullet\to B^\bullet$ denotes a map, and $[A^\bullet\xrightarrow fB^{\bullet-1}]$ denotes its mapping cone.
\end{convention}

\begin{convention}\label{signconventions}
We fix sign conventions by making everything $\mathbb Z/2$-graded and always using the super tensor product $\otimes$ (namely, where the isomorphism $A\otimes B\xrightarrow\sim B\otimes A$ is given by $a\otimes b\mapsto(-1)^{\left|a\right|\left|b\right|}b\otimes a$ and where $(f\otimes g)(a\otimes b):=(-1)^{\left|g\right|\left|a\right|}f(a)\otimes g(b)$).  We fix $\operatorname{Hom}(A,B)\otimes A\to B$ as given by $f\otimes a\mapsto f(a)$.  Complexes are $(\mathbb Z,\mathbb Z/2)$-bigraded; differentials are always odd and chain maps are always even.  Note that the $\mathbb Z/2$-grading of a complex is often, but not always, the reduction modulo $2$ of the $\mathbb Z$-grading.
\end{convention}

\begin{convention}
Direct limits and inverse limits always take place over directed sets.
\end{convention}

\begin{convention}
In view of the canonical equivalence of categories $\operatorname{Shv} X=\operatorname{Shv}_\mathcal K X$ from Lemma \ref{opencptshvequivalence}, we use the single word ``sheaf'' for an object of either category.
\end{convention}

\begin{convention}
Let $\mathcal F^\bullet$ be a complex of ($\mathcal K$-)presheaves.  The notions from Convention \ref{complexconventions} are applied ``objectwise'', that is, to each complex $\mathcal F^\bullet(U)$ (resp.\ $F^\bullet(K)$) individually.  For example, the homology $H^i\mathcal F^\bullet$ is again a ($\mathcal K$-)presheaf, and a map of ($\mathcal K$-)presheaves $f:\mathcal F^\bullet\to\mathcal G^\bullet$ is a quasi-isomorphism iff it induces an isomorphism of ($\mathcal K$-)presheaves $H^i\mathcal F^\bullet\to H^i\mathcal G^\bullet$ for all $i$.  The homology ($\mathcal K$-)presheaves $H^i\mathcal F^\bullet$ should not be confused with the various flavors of \v Cech (hyper)cohomology $\check H^i(X;\mathcal F^\bullet)$ we introduce in \S\ref{cechsection}.
\end{convention}

\begin{convention}
Throughout this paper, we make no second countability or paracompactness assumptions on manifolds (topological or smooth).
\end{convention}

