\label{cornersinvarianceofdomain}
Let $M$ be a topological manifold with corners and $K\subseteq M$ a closed subset.  Suppose that the restriction of the corner stratification on $M$ induces a topological manifold with corners structure on $K$ of the same dimension.  Then $K\subseteq M$ is open.
\label{stabilizationlemmaforHFSS}
Let $\ell:\coprod_{i=1}^k\mathbb R\to\Delta^n$ and $u:C\to M\times S^1\times\coprod_{i=1}^k\mathbb R$ be a point in $\overline{\mathcal M}(\sigma,p,q)$.  Then there exists $D\subseteq M\times S^1\times\Delta^n$ as in Definition \ref{implicitatlasonFloer}(\ref{implicitatlasFloerD}) which is $S^1$-invariant with $C\pitchfork D$ in the sense of Definition \ref{IAonfloerthickeningsdef}(\ref{transversalitypartIAfloer}) and so that adding these intersections to $C$ as extra marked points makes $C$ stable, except for irreducible components $S^1\times\mathbb R\subseteq C$ on which $u$ is independent of the $S^1$-coordinate (``Morse flow lines'').
\label{homologyhassmallerrank}
Let $M$ be a free module over a commutative ring $R$, and let $d:M\to M$ satisfy $d^2=0$.  If $H=\ker d/\operatorname{im} d$ is free, then $\operatorname{rk} H\leq\operatorname{rk} M$.
\label{freesubhassmallerrank}
Let $\phi:R^{\oplus A}\hookrightarrow R^{\oplus B}$ be an inclusion of free modules over a commutative ring $R$.  Then $A\leq B$.
\label{intersectioncofinal}
Let $K_1,\ldots,K_n\subseteq X$ be compact.  Then $\{U_1\cap\cdots\cap U_n\}_{\text{open }U_i\supseteq K_i}$ forms a cofinal system of neighborhoods of $K_1\cap\cdots\cap K_n$.
\label{opencptshvequivalence}
We have:
\begin{equation}
\begin{tikzcd}\operatorname{Shv}_\mathcal K X\ar[yshift=0.5ex]{r}{\alpha_\ast}&\ar[yshift=-0.5ex]{l}{\alpha^\ast}\operatorname{Shv} X\end{tikzcd}
\end{equation}
and this is an equivalence of categories.\footnote{A similar result appears in Lurie \cite[Corollary 7.3.4.10]{luriehtt}.}
\label{anycompactintersectionworksSH}
Let $\{K_\alpha\}_{\alpha\in A}$ be a filtered directed system of compact subsets of $X$ (i.e.\ for all $\alpha,\beta\in A$ there exists $\gamma\in A$ with $K_\gamma\subseteq K_\alpha\cap K_\beta$).  Then for any $\mathcal F$ satisfying \eqref{sheafcontinuity}, the following is an isomorphism:
\begin{equation}
\varinjlim_{\alpha\in A}\mathcal F(K_\alpha)\to\mathcal F\Bigl(\bigcap_{\alpha\in A}K_\alpha\Bigr)
\end{equation}
\label{qihomotopysheaf}
Properties \eqref{homotopysheafacyclic}--\eqref{homotopysheafcontinuity} are preserved by quasi-isomorphisms.
\label{associatedgradedhomotopysheaf}
Let $\mathcal F^\bullet$ be a complex of $\mathcal K$-presheaves.  If $\mathcal F^\bullet$ has a finite filtration whose associated graded is a homotopy $\mathcal K$-sheaf, then $\mathcal F^\bullet$ is a homotopy $\mathcal K$-sheaf.
\label{lowervanishingimpliessheaf}
If $\mathcal F^\bullet$ is a homotopy $\mathcal K$-sheaf and $H^{-1}\mathcal F^\bullet=0$, then $H^0\mathcal F^\bullet$ is a $\mathcal K$-sheaf.
\label{anycompactintersectionworks}
Let $\{K_\alpha\}_{\alpha\in A}$ be a filtered directed system of compact subsets of $X$ (i.e.\ for all $\alpha,\beta\in A$ there exists $\gamma\in A$ with $K_\gamma\subseteq K_\alpha\cap K_\beta$).  Then for any $\mathcal F^\bullet$ satisfying \eqref{homotopysheafcontinuity}, the following is a quasi-isomorphism:
\begin{equation}
\varinjlim_{\alpha\in A}\mathcal F^\bullet(K_\alpha)\to\mathcal F^\bullet\Bigl(\bigcap_{\alpha\in A}K_\alpha\Bigr)
\end{equation}
\label{properpullbackfinalneighborhood}
Let $f:X\to Y$ be proper.  Then $\{f^{-1}(U)\}_{K\subseteq U}$ is a cofinal system of neighborhoods of $f^{-1}(K)$ for any compact $K\subseteq X$.
\label{pushforwardandsheafproperties}
$f_\ast$ preserves \eqref{opensheafproperty}, \eqref{openhomotopysheafproperty}, \eqref{sheafvanishing}--\eqref{sheafcontinuity}, and \eqref{homotopysheafacyclic}--\eqref{homotopysheafcontinuity}.

If $X$ is compact, then the natural map $\check H^\bullet_\mathrm{fin}(X;\mathcal F)\to\check H^\bullet(X;\mathcal F)$ is an isomorphism, where the left hand side is defined as in \eqref{cechcomplexI} except using only finite open covers.

If $X$ is compact, then the natural map $\check H_c^\bullet(X;\mathcal F)\to\check H^\bullet(X;\mathcal F)$ is an isomorphism.
\label{cptcechembeddingproperty}
Let $f:X\hookrightarrow Y$ be the inclusion of an open subset.  Then there is a natural isomorphism $f_!:\check H^\bullet_c(X;\mathcal F)\to\check H^\bullet_c(Y;f_!\mathcal F)$.
\label{finitemap}
Let $f:X\to Y$ be proper with finite fibers.  Then $f^\ast:\check H^\bullet(Y;f_\ast\mathcal F)\to\check H^\bullet(X;\mathcal F)$ is an isomorphism, as is $f^\ast:\check H^\bullet_c(Y;f_\ast\mathcal F)\to\check H^\bullet_c(X;\mathcal F)$.
\label{cechcohomologyfinitequotient}
Let $X$ be a space and let $\pi:X\to X/\Gamma$ be the quotient map under a finite group action.  Let $\mathcal F$ be any sheaf of $\mathbb Z[\frac 1{\#\Gamma}]$-modules on $X/\Gamma$.  Then the following maps are all isomorphisms:
\begin{align*}
\check H^\bullet(X/\Gamma;\mathcal F)\to\check H^\bullet(X/\Gamma;(\pi_\ast\pi^\ast\mathcal F)^\Gamma)\to\check H^\bullet(X/\Gamma;\pi_\ast\pi^\ast\mathcal F)^\Gamma\to\check H^\bullet(X;\pi^\ast\mathcal F)^\Gamma\\
\check H^\bullet_c(X/\Gamma;\mathcal F)\to\check H^\bullet_c(X/\Gamma;(\pi_\ast\pi^\ast\mathcal F)^\Gamma)\to\check H^\bullet_c(X/\Gamma;\pi_\ast\pi^\ast\mathcal F)^\Gamma\to\check H^\bullet_c(X;\pi^\ast\mathcal F)^\Gamma
\end{align*}
(here we note that by functoriality, $\pi^\ast\mathcal F$ is $\Gamma$-equivariant, and thus $\Gamma$ acts on $\pi_\ast\pi^\ast\mathcal F$).
\label{cHsameforopencompactcovers}
Let $\mathcal F$ be a sheaf on a compact space $X$.  Then there is a natural isomorphism $\check H^\bullet(X;\mathcal F)\to\check H^\bullet(X;\alpha^\ast\mathcal F)$ ($\alpha^\ast\mathcal F$ is a $\mathcal K$-sheaf; c.f.\ Definition \ref{opencptrelationfunctors}).
\label{qicech}
If $\mathcal F^\bullet\to\mathcal G^\bullet$ is a quasi-isomorphism of complexes of $\mathcal K$-presheaves, then the induced map $\check H^\bullet(X;\mathcal F^\bullet)\to\check H^\bullet(X,\mathcal G^\bullet)$ is an isomorphism.
\label{hypercohomologyss}
Let $\mathcal F^\bullet$ be a bounded below complex of $\mathcal K$-presheaves.  Then there is a convergent spectral sequence $E_1^{p,q}=\check H^q(X;\mathcal F^p)\Rightarrow\check H^{p+q}(X;\mathcal F^\bullet)$.
\label{sheafcechHzero}
If $\mathcal F$ satisfies \eqref{sheafvanishing} and \eqref{sheafproperty}, then the canonical map $\mathcal F(X)\to\check H^0(X;\mathcal F)$ is an isomorphism.
\label{localvanishingcechzero}
Let $\mathcal F$ satisfy \eqref{sheafcontinuity}.  If the stalks of $\mathcal F$ vanish, then $\check H^\bullet(X;\mathcal F)=0$.
\label{cechlocalglobalvanishingcomplex}
Let $\mathcal F^\bullet$ satisfy \eqref{homotopysheafcontinuity} and $H^i\mathcal F^\bullet=0$ for $i<<0$.  If $\mathcal F^\bullet$ has acyclic stalks, then $\check H^\bullet(X;\mathcal F^\bullet)=0$.
\label{cechles}
Let $\mathcal F,\mathcal G,\mathcal H$ satisfy \eqref{sheafcontinuity}.  If $0\to\mathcal F\to\mathcal G\to\mathcal H\to 0$ is exact on stalks, then it induces a long exact sequence on $\check H^\bullet$.
\label{cechsimplebasic}
Let $\mathcal F^\bullet$ be a pure homotopy $\mathcal K$-sheaf.  Then:
\begin{rlist}
\item(Strong vanishing) $H^i\mathcal F^\bullet=0$ for $i<0$.
\item$H^0\mathcal F^\bullet$ is a $\mathcal K$-sheaf.
\end{rlist}
\label{openclosedpurity}
Let $\mathcal F^\bullet$ be a homotopy $\mathcal K$-sheaf.  Write $X=U\cup Z$ with $U$ open and $Z$ closed, and suppose that $i^\ast\mathcal F^\bullet$ and $j^\ast\mathcal F^\bullet$ are both pure ($i:Z\hookrightarrow X$ and $j:U\hookrightarrow X$).  Then $\mathcal F^\bullet$ is pure.
\label{singularchainshomotopyKsheaf}
Let $X$ be a topological space.  Then we have:
\begin{rlist}
\item\label{scacyc}$C_\bullet(X,X)$ is acyclic.
\item\label{scpatch}Let $A,B\subseteq X$ be closed.  Then the complex:
\begin{equation*}
\bigl[C_\bullet(X,X\setminus(A\cup B))\to C_{\bullet+1}(X,X\setminus A)\oplus C_{\bullet+1}(X,X\setminus B)\to C_{\bullet+2}(X,X\setminus(A\cap B))\bigr]
\end{equation*}
is acyclic.
\item\label{sccont}Let $K=\bigcap_{\alpha\in A}K_\alpha$ where $\{K_\alpha\}_{\alpha\in A}$ is a family of closed subsets of $X$ which is \emph{filtered} in the sense that for all $\alpha_1,\alpha_2\in A$, there exists $\beta\in A$ with $K_\beta\subseteq K_{\alpha_1}\cap K_{\alpha_2}$.  Then $\varinjlim_{\alpha\in A}C_\bullet(X,X\setminus K_\alpha)\to C_\bullet(X,X\setminus K)$ is a quasi-isomorphism.
