Let $\ensuremath{\mathrm{G}}$ and $\ensuremath{\mathrm{H}}$ be two digraphs. Let $\varphi$ be a homomorphism from $\ensuremath{\mathrm{H}}\times \ensuremath{\mathrm{G}}$ to~$\ensuremath{\mathrm{G}}$.
Then the function $\psi$ defined by $\psi(x)(u)=\varphi(x,u)$ for all $x\in V(\ensuremath{\mathrm{H}})$, $u\in V(\ensuremath{\mathrm{G}})$ 
is a homomorphism from $\ensuremath{\mathrm{H}}$ to $\widehat{\ensuremath{\mathrm{G}}^{\ensuremath{\mathrm{G}}}}$.

A reflexive tournament is endo-trivial if and only if it is retract-trivial.
\label{lem:endo-retraction-trivial}
 Let $\ensuremath{\mathrm{H}}$ be a reflexive digraph. If $(id_\ensuremath{\mathrm{H}},f) \in E(\widehat{\ensuremath{\mathrm{H}}^\ensuremath{\mathrm{H}}})$, where $f$ is different from
$id_\ensuremath{\mathrm{H}}$, then $\ensuremath{\mathrm{H}}$ has a
non-surjective retraction $r$ 
 such that $(id_\ensuremath{\mathrm{H}},r)\in E(\widehat{\ensuremath{\mathrm{H}}^{\ensuremath{\mathrm{H}}}})$.
\label{lem:marzad}
  Let $\ensuremath{\mathrm{H}}$ be a retract-trivial reflexive digraph with at least three vertices. Then 
\begin{enumerate}
\item $\ensuremath{\mathrm{H}}$ has no double edge;
\item $\ensuremath{\mathrm{H}}$ is strongly connected; and
\item the automorphisms of $\ensuremath{\mathrm{H}}$ are isolated vertices in  $\widehat{\ensuremath{\mathrm{H}}^{\ensuremath{\mathrm{H}}}}$. 
\end{enumerate}
\label{lem:Benoit-lemma}

If $\ensuremath{\mathrm{H}}$ is a reflexive tournament that is endo-trivial, then $\ensuremath{\mathrm{H}}$ contains a directed Hamilton cycle.
\label{l-Ham}

If $\ensuremath{\mathrm{H}}$ is a reflexive tournament that is endo-trivial, then any homomorphic image of $\ensuremath{\mathrm{H}}$ of size $1<n<|V(\ensuremath{\mathrm{H}})|$ possesses a double edge.
\label{lem:under-m}

In any homomorphism $h$ from $\Cylm$, with bottom cycle $\DCm$, to a reflexive tournament, if $|h(\DCm)|=1$, then $|h(\Cylm)|=1$.
