		$$
				\|\sigma\bar\bxi_i+\tilde\bDelta_n\|_2^2 > \sigma^2(p+\gamma^2).
		$$
		In view of the triangle inequality, this implies that
		$$
				\sigma\|\bar\bxi_i\|_2 + \|\tilde\bDelta_n\|_2 > \sigma\sqrt{p+\gamma^2}.
		$$			
		In the event $\Omega_1\cap\Omega_2$, the last inequality implies
		$$		
				\sqrt{p+0.5\gamma^2} + \frac{\gamma^2}{4\sqrt{p+\gamma^2}}> \sqrt{p+\gamma^2}.
		$$
		It is easy to see that the last inequality is never true, implying thus that
		$w_i=0$. Indeed,
		\begin{align}
				\sqrt{p+\gamma^2} -\sqrt{p+0.5\gamma^2}  
					& = \frac{0.5\gamma^2}{\sqrt{p+\gamma^2} +\sqrt{p+0.5\gamma^2}}\\
					& > \frac{0.5\gamma^2}{\sqrt{p+\gamma^2} +\sqrt{p+\gamma^2}}
					= \frac{\gamma^2}{4\sqrt{p+\gamma^2}}.
		\end{align}
		The fact that the probability of $\O_2$ is at least $1-\d/2$ is
		a consequence of the tail bound of a chi-squared random variable and the
		union bound.

 The definition of $\bZ_i$ yields
	\begin{align}
	\|\bZ_i-\sigma\bar\bxi_i\|_2|w_i-1|  &= \|\bZ_i-\sigma\bar\bxi_i\|_2 \min\bigg\{ 1,
	\frac{\sigma\gamma}{\big(\|\bZ_i\|^2_2-\sigma_{n,p}^2\big)^{1/2}_+} \bigg\}.
	\end{align}
	Let us introduce the random variables $\eta_i = 
	\frac{n}{n-1}\bt_i^\top\bar\bxi_i/\|\bt_i\|_2$. It is clear that $\eta_i$ is Gaussian
	with zero mean and unit variance. Repeated use of the triangle inequality leads to
	\begin{align}
	\|\bZ_i\|_2^2
		&\ge \|\bZ_i-\sigma\bar\bxi_i\|_2^2  + \|\sigma\bar\bxi_i\|_2^2 + 2\sigma\bar\bxi_i^\top(\bt_i
		+\tilde\bDelta_n) \\
		&\ge \|\bZ_i-\sigma\bar\bxi_i\|_2^2  + \|\sigma\bar\bxi_i\|_2^2 -2\sigma\|\bt_i\|_2|\eta_i|
		+2\sigma\bar\bxi_i^\top\tilde\bDelta_n\\
		&\ge \|\bZ_i-\sigma\bar\bxi_i\|_2^2  + \|\sigma\bar\bxi_i\|_2^2 -2\sigma\|\bZ_i-\sigma\bar\bxi_i\|_2
		|\eta_i| -2\sigma\|\tilde\bDelta_n\|_2|\eta_i|+2\sigma\bar\bxi_i^\top\tilde\bDelta_n\\
		&\ge (\|\bZ_i-\sigma\bar\bxi_i\|_2-\s|\eta_i|)^2 -\sigma^2\eta_i^2 + \|\sigma\bar\bxi_i\|_2^2
		-2\sigma\|\tilde\bDelta_n\|_2|\eta_i|+2\sigma\bar\bxi_i^\top\tilde\bDelta_n.
	\end{align}
	One can check the following simple fact: if $a,b,c,d>0$ then
	$$
	a\min\Big(1,\frac{d}{\{(a-b)^2-c\}_+^{1/2}}\Big)\le  b + d+\sqrt{c_+}.
	$$
	Taking in this inequality $a = \|\bZ_i-\sigma\bar\bxi_i\|_2$, 
	$c = \sigma^2\eta_i^2 - \|\sigma\bar\bxi_i\|_2^2
		+2\sigma\|\tilde\bDelta_n\|_2|\eta_i|-2\sigma\bar\bxi_i^\top\tilde\bDelta_n + 
		\sigma^2_{n,p}$, $b=\s|\eta_i|$ and $d=\sigma\g$, we arrive at
	\begin{align}
	\|\bZ_i-\sigma\bar\bxi_i\|_2|w_i-1|
		&\le 2\s|\eta_i| + \sigma\g+ \|\tilde\bDelta_n\|_2\\
		&\qquad+\sqrt{(\sigma_{n,p}^2-\sigma^2\|\bar\bxi_i\|_2^2)_+}
		+\sqrt{(2\sigma\bar\bxi_i^\top\tilde\bDelta_n -\|\tilde\bDelta_n\|_2^2)_+}.
	\end{align}
	In the event $\O_1\cap\O_2$, we upper bound $\|\tilde\bDelta_n\|_2$ and
	$|\sigma_{n,p}^2-\sigma^2\|\bar\bxi_i\|_2^2|$ respectively by $0.25\sigma\gamma$ 
	and $0.5\sigma^2\gamma^2$. This leads to the claim of the lemma.

	First assume that $x\ge 4d$. Combining the relation
	\begin{align}
		\esp\big(\eta\, \fcar_{\eta\ge d+x}\big) &= (d+x)\prob(\eta\ge d+x)+\int_x^\pinf \prob(\eta\ge d+t)\,dt
	\end{align}
	with Lemma~\ref{lemme_chideux}, we get
	\begin{align}
		\esp\big(\eta\, \fcar_{\eta\ge d+x}\big)
		&\le (d+x) e^{-x/4} + \int_x^\pinf e^{-t/4}\, dt\\
		&\le (4+d+x)e^{-x/4}\le (4d+x)e^{-x/4}\le 2xe^{-x/4}. \phantom{\int_0^\pinf}
	\end{align}
