Further, \begin{eqnarray*}
\mathfrak{S}_{12}\; \mathrm{S}_{\scaleto{\begin{array}{|c|c|}
\cline{1-2}
4 & 3 \\
\cline{1-2}
2 & \multicolumn{1}{c}{\;\;\;} \\
\cline{1-1}
\end{array}}{12pt}} \nabla^2_{x_3,x_4}\kappa(x_1,x_2)
&\;\;=\;\;& \mathfrak{S}_{12}\mathfrak{S}_{34} \big (\nabla^2_{x_3,x_4}\kappa(x_1,x_2) - \nabla^2_{x_3,x_2}\kappa(x_1,x_4) \big )\\
 &\stackrel{\eqref{eq:def_Killing}}{=} & 3\; \mathfrak{S}_{34} \nabla^2_{x_3,x_4}\kappa(x_1,x_2)\\
& \stackrel{\eqref{eq:Killing_alternativ_*}}{=} & 3\; \mathfrak{S}_{12} \; \nabla^2_{x_1,x_2}\kappa(x_3,x_4) - 3\big (\mathfrak{S}_{12}\mathfrak{S}_{34} R_{x_3,x_1}\kappa(x_2,x_4)\big ).
\end{eqnarray*} 
Therefore
\begin{eqnarray*}
\mathrm{P}_{\scaleto{\begin{array}{|c|c|}
\cline{1-2}
1 & 2 \\
\cline{1-2}
3 & 4 \\
\cline{1-2}
\end{array}}{12pt}} \nabla^2_{x_1,x_2}\kappa (x_3,x_4) - \frac{1}{2} \mathfrak{S}_{12}\nabla^2_{x_1,x_2}\kappa(x_3,x_4) & =&
                                                       \frac{1}{4}\; \mathfrak{S}_{12}\mathfrak{S}_{34} R_{x_3,x_1}\kappa(x_2,x_4).
\end{eqnarray*}
Using the Ricci-identity,~\eqref{eq:prolong_2} follows.

On the one hand, taking the trace on~\eqref{eq:prolong_2} with respect to $x_3,\, x_4$ and  $x_1,\, x_2$ gives
\begin{eqnarray*}
\mathrm{tr}_{3,4} \big (\mathrm{P}_{\scaleto{\begin{array}{|c|c|}
\cline{1-2}
1 & 2 \\
\cline{1-2}
3  & 4 \\
\cline{1-2} 
\end{array}}{12pt}} \nabla^2\kappa (x_1,x_2,x_3,x_4)\big ) &=& - \nabla^*\nabla \kappa(x_1,x_2) - \frac{1}{4}\;\sum_{i=1}^n 
\left \lbrace\begin{array}{c} 
2\, \underbrace{R_{e_i,e_i}\kappa(x_3,x_4)}_{=0}\\
+ R_{x_1,e_i}\kappa(e_2,x_i) + R_{x_1,e_i}\kappa(e_i,x_2)\\ +  R_{x_2,e_i}\kappa(e_i,x_1) + R_{x_2,e_i}\kappa(e_i,x_1)  \end{array} \right \rbrace\\
&=&  - \nabla^*\nabla \kappa(x_1,x_2) + \frac{1}{2} q(R)\kappa(x_1,x_2)\;,
\end{eqnarray*}
and
\begin{eqnarray*}
\mathrm{tr}_{1,2} \big (\mathrm{P}_{\scaleto{\begin{array}{|c|c|}
\cline{1-2}
1 & 2 \\
\cline{1-2}
3  & 4 \\
\cline{1-2} 
\end{array}}{12pt}}\nabla^2\kappa (x_1,x_2,x_3,x_4)\big ) &=& \nabla^2_{x_3,x_4 }\mathrm{tr} \, \kappa
+ \frac{1}{4}\;\left \lbrace\begin{array}{c} 
2\, \underbrace{R_{x_3,x_4}\kappa(e_i,e_i)}_{=0}\\
+ R_{x_3,e_i}\kappa(x_4,e_i) + R_{x_4,e_i}\kappa(x_3,e_i)\\  + R_{x_3,e_i}\kappa(x_4,e_i) +
           R_{x_4,e_i}\kappa(x_3,e_i)\end{array} \right \rbrace\\
&=& \nabla^2_{x_3,x_4 }\mathrm{tr} \, \kappa - \frac{1}{2} q(R)\kappa(x_3,x_4).
\end{eqnarray*}
On the other hand, $\mathrm{tr}_{3,4} \big ( \mathrm{P}_{\scaleto{\begin{array}{|c|c|}
\cline{1-2}
1 & 2 \\
\cline{1-2}
3  & 4 \\
\cline{1-2} 
\end{array}}{12pt}}\nabla^2\kappa \big )(u,v) = \mathrm{tr}_{1,2} \big ( \mathrm{P}_{\scaleto{\begin{array}{|c|c|}
\cline{1-2}
1 & 2 \\
\cline{1-2}
3  & 4 \\
\cline{1-2} 
\end{array}}{12pt}}\nabla^2\kappa \big )(u,v)$ by the symmetries of a curvature tensor.

The product rule for the covariant 
derivative of an endomorphism-valued tensor field $A$ acting on $\alpha$ yields
\begin{eqnarray}
\nabla_x \big (A\cdot \alpha(y_2,y_3) \big ) &\;\;=\;\;& \begin{array}{c}\nabla_x A \cdot \alpha(y_2,y_3)
+ A\cdot  \nabla_x \alpha(y_2,y_3) -  \nabla_{A\,x} \alpha(y_2,y_3)\end{array},
\end{eqnarray}
since the endomorphism should in effect not act on the covariant derivative slot. Applying this to~\eqref{eq:def_F21} we obtain~\eqref{eq:F22_ausmultipliziert}.

Using the Killing equation~\eqref{eq:def_Killing} together with the fact that
