\end{array}\right.
\end{align*}
Note that since $G(\x,\y)=G(\y,\x)$ for $\x,\y\in\Om$ and $\Phi(\y-\x)=\Phi(\x-\y)$, we have $H(\x,\y)=H(\y,\x)$ for $\x,\y\in\Om$. Consequently, we have
\begin{align}\label{CorrectorHarmonicSym}
-\Delta_{\x}H(\x,\y)=-\Delta_{\x}H(\y,\x)=0~~~~~\x\in\Om.
\end{align}
Then the solution to \cref{LBV} is represented as
\begin{align*}
b_l(\x)=\int_{\Om}G(\x,\y)P(D_{\y})\chi(\y)\rd\y=\int_{\Om}\Phi(\x-\y)P(D_{\y})\chi(\y)\rd\y+\mH(\x)
\end{align*}
where we used the fact that $\Phi(\y-\x)=\Phi(\x-\y)$, and $\mH(\x)$ is defined as
\begin{align*}\label{HarmonicInterior}
\mH(\x)=-\int_{\Om}H(\x,\y)P(D_{\y})\chi(\y)\rd\y
\end{align*}
for $\x\in\Om$. Then we can see that $\mH(\x)$ satisfies
\begin{align}\label{H_HarmonicEq}
\left\{\begin{array}{rcll}
-\Delta\mH\hspace{-0.65em}&=\hspace{-0.65em}&0&\text{in}~\Om \vspace{0.125em}\\
\mH\hspace{-0.65em}&=\hspace{-0.65em}&-\wt{b}_l&\text{on}~\p\Om
\end{array}\right.
\end{align}
where the first equation of \cref{H_HarmonicEq} comes from \cref{CorrectorHarmonicSym}. Here, $\wt{b}_l$ is induced by the information of $\chi$ only in $\Om$:
\begin{align}\label{TrueLocalField}
\wt{b}_l(\x)=\int_{\Om}\Phi(\x-\y)P(D_{\y})\chi(\y)\rd\y=\int_{\R^3}\Phi(\x-\y)1_{\Om}(\y)P(D_{\y})\chi(\y)\rd\y
\end{align}
with $1_{\Om}$ being the characteristic function of $\Om$.
























Based on the fact that $b_l(\x)=0$ for $\x\in\R^3\setminus\overline{\Om}$, we define
\begin{align*}
v(\x)=\left\{\begin{array}{cccll}
v_{\mathrm i}(\x)\hspace{-0.65em}&=\hspace{-0.65em}&\mH(\x)&\text{if}&\x\in\Om \vspace{0.125em}\\
v_{\mathrm e}(\x)\hspace{-0.65em}&=\hspace{-0.65em}&-\wt{b}_l(\x)&\text{if}&\x\notin\Om.
\end{array}\right.
\end{align*}
Hence, we obtain \cref{NewModeling}, and we can further see that $v_{\mathrm i}$ and $v_{\mathrm e}$ satisfy
\begin{align}
-\Delta v_{\mathrm i}&=0~~~~~~\text{in }  \Om \label{v_iharmonic}\\
-\Delta v_{\mathrm e}&=0~~~~~~\text{in }  \R^3\setminus\overline{\Om} \label{v_eharmonic}\\
v_{\mathrm i}=v_{\mathrm e}&=-\wt{b}_l~~~\text{on } \p\Om, \label{vboundaryconti}
\end{align}
respectively, where \cref{v_eharmonic} comes from \cref{TrueLocalField}; $-\Delta\wt{b}_l=1_{\Om}P(D)\chi$, i.e. $-\Delta\wt{b}_l=P(D)\chi$ in $\Om$, and $-\Delta\wt{b}_l=0$ in $\R^3\setminus\overline{\Om}$.

To prove \cref{DistLapIncompatibility}, let $\varphi\in C_0^{\infty}(\R^3)$, and we consider
\begin{align*}
\int_{\R^3}v(\x)\left(-\Delta\varphi\right)(\x)\rd\x&=\int_{\Om}v_{\mathrm i}(\x)\left(-\Delta\varphi\right)(\x)\rd\x+\int_{\R^3\setminus\overline{\Om}}v_{\mathrm e}(\x)\left(-\Delta\varphi\right)(\x)\rd\x\\
&=I_1+I_2
\end{align*}
Using \cref{v_iharmonic,vboundaryconti} and the Green's identity (e.g. \cite{Evans2010}), we have
\begin{align*}
I_1&=\int_{\Om}\left[\varphi(\x)\left(\Delta v_{\mathrm i}\right)(\x)-v_{\mathrm i}(\x)\left(\Delta\varphi\right)(\x)\right]\rd\x\\
&=\int_{\p\Om}\left[\varphi(\x)\f{\p v_{\mathrm i}}{\p\bn}(\x)-v_{\mathrm i}(\x)\f{\p\varphi}{\p\bn}(\x)\right]\rd\ssi(\x)=\int_{\p\Om}\left[\varphi(\x)\f{\p v_{\mathrm i}}{\p\bn}(\x)+\wt{b}_l(\x)\f{\p\varphi}{\p\bn}(\x)\right]\rd\ssi(\x).
\end{align*}
Similarly using \cref{v_eharmonic,vboundaryconti}, we also have
\begin{align*}
I_2&=\int_{\R^3\setminus\overline{\Om}}\left[\varphi(\x)\left(\Delta v_{\mathrm e}\right)(\x)-v_{\mathrm e}(\x)\left(\Delta\varphi\right)(\x)\right]\rd\x\\
&=\int_{\p\Om}\left[-\varphi(\x)\f{\p v_{\mathrm e}}{\p\bn}(\x)+v_{\mathrm e}(\x)\f{\p\varphi}{\p\bn}(\x)\right]\rd\ssi(\x)=-\int_{\p\Om}\left[\varphi(\x)\f{\p v_{\mathrm e}}{\p\bn}(\x)+\wt{b}_l(\x)\f{\p\varphi}{\p\bn}(\x)\right]\rd\ssi(\x)
\end{align*}
where the second equality comes from the fact that we need to compute the inward normal derivatives on $\p\Om$. Hence, combining these two equalities, we obtain \cref{DistLapIncompatibility}.

To prove 2, we assume on the contrary that there exists $\x\in\p\Om$ such that
\begin{align*}
\f{\p v_{\mathrm i}}{\p\bn}=\f{\p v_{\mathrm e}}{\p\bn}
\end{align*}
for some open and connected set $U\subseteq\p\Om$ such that $\x\in U$ and $\ssi(U)>0$. Choose $r>0$ such that $B(\x,r)\cap\p\Om$ is contained in $U$, where $B(\x,r)$ denotes an open ball centered at $\x$ with radius $r$. Then since $-\Delta v=0$ in $B(\x,r)$ and $v=v_{\mathrm e}=-\wt{b}_l$ in $B(\x,r)\cap\left(\R^3\setminus\overline{\Om}\right)$, it follows that $v=-\wt{b}_l$ in $B(\x,r)$ by the analyticity of $v$ in $B(\x,r)$. Since this means that $v=v_{\mathrm i}=-\wt{b}_l$ in $B(\x,r)\cap\Om$, together with the fact that $v_{\mathrm i}$ is harmonic in $\Om$, we have $v_{\mathrm i}=-\wt{b}_l$ in $\Om$ by the analyticity of $v_{\mathrm i}$ in $\Om$. Since $v=-\wt{b}_l$ on $\p\Om$, we have $v=-\wt{b}_l$ in $\R^3$. Hence, $-\Delta\wt{b}_l=0$ in $\R^3$, and thus, $P(D)\chi=0$ in $\Om$, which is a contradiction.

proposition:
It is easy to see that each subproblem has a closed form solution. The solutions to \cref{chisubproblem,vsubproblem} can be written as
\begin{align}
\chi^{k+1}&=\big(A^TA+I\big)^{-1}\big[A^T(f^k-r^k)+W^T(d^k-p^k)\big] \label{chisubexplicit}\\
v^{k+1}&=\big(I+\msL^T\msL\big)^{-1}\big[g^k-s^k+\msL^T(e^k-q^k)\big]. \label{vsubexplicit}
\end{align}
Since we use the periodic boundary conditions, both \cref{chisubexplicit,vsubexplicit} can be easily solved by using the fast Fourier transform. In addition, the solutions to \cref{dsubproblem,esubproblem} are expressed in terms of the soft thresholding:
\begin{align}
d^{k+1}&=\mT_{\gamma/\beta}\big(W\chi^{k+1}+p^k\big) \label{dsubexplicit}\\
e^{k+1}&=\max\big(|\msL v^{k+1}+q^k|-\lambda/\beta,0\big)\sign\big(\msL v^{k+1}+q^k\big). \label{esubexplicit}
\end{align}
Here, $\mT_{\gamma}$ is the isotropic soft thresholding in \cite{J.F.Cai2012}: given $d$ defined as
\begin{align*}
d=\left\{d_{l,\aal}:(l,\aal)\in\left(\left\{0,\cdots,L-1\right\}\times\BB\right)\cup\left\{(L-1,\0)\right\}\right\}
\end{align*}
and $\gamma=\left\{\gamma_l:l=0,1,\cdots,L-1\right\}$ with $\gamma_l\geq0$, $\mT_{\gamma}\left(d\right)$ is defined as
\begin{align*}
\left(\mT_{\gamma}\left(d\right)\right)_{l,\aal}[\bk]=\left\{\begin{array}{ll}
d_{l,\aal}[\bk],&(l,\aal)=(L-1,\0)\vspace{0.125em}\\
\displaystyle{\max\left(R_l[\bk]-\gamma_l[\bk],0\right)\f{d_{l,\aal}[\bk]}{R_l[\bk]}},&(l,\aal)\in\left\{0,\cdots,L-1\right\}\times\BB
\end{array}\right.
\end{align*}
where $R_l[\bk]=\left(\sum_{\aal\in\BB}\left|d_{l,\aal}[\bk]\right|^2\right)^{1/2}$ for $\bk\in\OO$. Finally, the solutions to \cref{fsubproblem,gsubproblem} are expressed as
\begin{align}
f^{k+1}&=\big(\Sigma+\beta I\big)^{-1}\big[\Sigma(b_l-g^k)+\beta(A\chi^{k+1}+r^k)\big] \label{fsubexplicit}\\
g^{k+1}&=\big(\Sigma+\beta I\big)^{-1}\big[\Sigma(b_l-f^{k+1})+\beta(v^{k+1}+s^k)\big] \label{gsubexplicit}
\end{align}
where $\Sigma+\beta I$ is simply a diagonal matrix and thus, no matrix inversion is needed.

