remark:
\label{RK211}
Since \cite[Proposition A.1.]{J.K.Choi2014} has discussed the equivalence between \cref{Forward1} and the following representation in the literature
\begin{align}\label{Forward_Convention}
b(\x)=\pv\int_{\R^3}d(\x-\y)\chi(\y)\rd\y,
\end{align}
we shall use \cref{Forward1} in the rest of this paper. Note that \cref{Forward1} avoids the singularity of the kernel $d(\x-\y)$ in \cref{Forward_Convention} as $\Phi(\x-\y)$ is locally integrable near $\x=\y$.

\label{RK231} For better understanding of our HIRE model, we temporarily assume that $\Sigma=I$ and consider
\begin{align*}
\min_{\chi,v\in\mI_3}~\f{1}{2}\left\|A\chi+v-b_l\right\|_2^2+\lambda\left\|\msL v\right\|_1+\left\|\gamma\cdot W\chi\right\|_{1,2}.
\end{align*}
	If $v\equiv0$, our model reduces to the integral approach model:
	\begin{align*}
	\min_{\chi\in\mI_3}~\f{1}{2}\left\|A\chi-b_l\right\|_2^2+\left\|\gamma\cdot W\chi\right\|_{1,2}.
	\end{align*}
	In addition, if we fix $v=b_l-A\chi$, our model reduces to the $\ell_1$ fidelity version of the following differential approach model:
	\begin{align*}
	\min_{\chi\in\mI_3}~\f{1}{2}\left\|\msL b_l-\msL A\chi\right\|_2^2+\left\|\gamma\cdot W\chi\right\|_{1,2}
	\end{align*}
	as $\msL A\chi=\msL b_l$ discretizes the PDE \cref{QSM_PDE2} in the sense of \cite[Proposition A.1.]{J.K.Choi2014}.

algorithm:
\caption{Split Bregman Algorithm for \eqref{WaveletFrameHIRE}}\label{Algorithm1}
\begin{algorithmic}
\STATE{\textbf{Initialization:} $\chi^0$, $v^0$, $d^0$, $e^0$, $f^0$, $g^0$, $p^0$, $q^0$, $r^0$, $s^0$}
\FOR{$k=0$, $1$, $2$, $\cdots$}
\STATE{Update $\chi$ and $v$:
\begin{align}
\chi^{k+1}&=\operatornamewithlimits{argmin}_{\chi}~\f{\beta}{2}\|A\chi-f^k+r^k\|_2^2+\f{\beta}{2}\|W\chi-d^k+p^k\|_2^2 \label{chisubproblem}\\
v^{k+1}&=\operatornamewithlimits{argmin}_{v}~\f{\beta}{2}\|v-g^k+s^k\|_2^2+\f{\beta}{2}\|\msL v-e^k+q^k\|_2^2 \label{vsubproblem}
\end{align}
Update $d$, $e$, $f$, and $g$:
\begin{align}
d^{k+1}&=\operatornamewithlimits{argmin}_d~\left\|\gamma\cdot d\right\|_{1,2}+\f{\beta}{2}\|d-W\chi^{k+1}-p^k\|_2^2 \label{dsubproblem}\\
e^{k+1}&=\operatornamewithlimits{argmin}_e~\lambda\left\|e\right\|_1+\f{\beta}{2}\|e-\msL v^{k+1}-q^k\|_2^2 \label{esubproblem}\\
f^{k+1}&=\operatornamewithlimits{argmin}_f~\f{1}{2}\|f+g^k-b_l\|_{\Sigma}^2+\f{\beta}{2}\|f-A\chi^{k+1}-r^k\|_2^2 \label{fsubproblem}\\
g^{k+1}&=\operatornamewithlimits{argmin}_g~\f{1}{2}\|g+f^{k+1}-b_l\|_{\Sigma}^2+\f{\beta}{2}\|g-v^{k+1}-s^k\|_2^2 \label{gsubproblem}
\end{align}
Update $p$, $q$, $r$, and $s$:
\begin{align}
p^{k+1}&=p^k+W\chi^{k+1}-d^{k+1} \label{psubproblem}\\
q^{k+1}&=q^k+\msL v^{k+1}-e^{k+1} \label{qsubproblem}\\
r^{k+1}&=r^k+A\chi^{k+1}-f^{k+1} \label{rsubproblem}\\
s^{k+1}&=s^k+v^{k+1}-g^{k+1} \label{ssubproblem}
\end{align}}
\ENDFOR
\end{algorithmic}

example:
\label{ExA1} The piecewise constant B-spline (or the Haar framelet) \cite{I.Daubechies2003} for $L_2(\R)$ has one refinable function and one framelet
\begin{align*}
\phi(x)=\left\{\begin{array}{ccl}
1&\text{if}&x\in[0,1)\vspace{0.125em}\\
0&\text{if}&x\notin[0,1)
\end{array}\right.~~~\text{and}~~~\psi_1(x)=\left\{\begin{array}{ccl}
1&\text{if}&x\in[0,1/2)\vspace{0.125em}\\
-1&\text{if}&x\in[1/2,1)\vspace{0.125em}\\
0&\text{if}&x\notin[0,1)
\end{array}\right.
\end{align*}
as shown in \cref{IllustrateExA1}. Here, the associated filters are
\begin{align*}
q_0=\f{1}{2}\big[\begin{array}{cc}
1&1
\end{array}\big]~~~\text{and}~~~q_1=\f{1}{2}\big[\begin{array}{cc}
1&-1
\end{array}\big].
\end{align*}
Since this $\left\{q_0,q_1\right\}$ satisfies \cref{UEP}, $\msX\left(\Ps\right)$ with $\Ps=\left\{\psi_1\right\}$ forms a tight frame on $L_2(\R)$.

theorem:
\label{102}
Let $\alpha_0$ is such that $ 0<\alpha_0<\f{\dpr{1}{\varphi_0}}{\|\varphi_0\|^2}$. Then, there exists $h_0=h_0(\alpha_0)>0$, so that for every $h: 0<h<h_0$ and $\alpha:=\alpha_0 h$, there exists a stationary solution $\varphi_{\alpha}=\varphi_{\alpha,1}+i \varphi_{\alpha,2}$ of
\eqref{1.1}  or equivalently  solutions $\varphi_{\alpha,1}(h), \varphi_{\alpha,2}(h)$ of the profile system   \eqref{150}. Moreover, there is the following Taylor expansions formula for the coefficients
\begin{eqnarray}
\label{500}
\varphi_{\alpha,1} &=& (a_0+\f{b_0}{2} h D_2^0+O(h^2))  \varphi_0+h \Psi_1^0 +O_{\{\varphi_0\}^\perp}(h^2)\\
\label{510}
\varphi_{\alpha,2} &=&  (b_0-\f{a_0}{2} h D_2^0+O(h^2))  \varphi_0+h \Psi_2^0 +O_{\{\varphi_0\}^\perp}(h^2)
\end{eqnarray}
where
\begin{eqnarray*}
	& & a_0=\sigma_0  \f{\|\varphi_0\|^2}{\dpr{1}{\varphi_0}}, \ \ \ b_0= \alpha_0  \f{\|\varphi_0\|^2} {\dpr{1}{\varphi_0}},
	\sigma_0=  \pm \sqrt{ \f{\dpr{1}{\varphi_0}^2}{\|\varphi_0\|^4}-\alpha_0^2}; \\
		& & D_2^0 = 8 \f{\dpr{\varphi_0^2 L_+^{-1}[1]}{L_-^{-1}[b_0-\alpha_0 \varphi_0]}}{\dpr{1}{\varphi_0}}; \\
	& &  \Psi_1^0=  a_0^2 L_+^{-1}[1]  + b_0 L_-^{-1}[b_0-\alpha_0\varphi_0];  \\
	& & \Psi_2^0=  a_0 b_0  L_+^{-1}[1]  - a_0 L_-^{-1}[b_0-\alpha_0\varphi_0].
\end{eqnarray*}

\begin{eqnarray}
\label{25}
\varphi_h &=& \varphi_0 + h {\mathcal L}_{+,0}^{-1}[1]+O(h^2),  \\
\label{27}
