\| \Gamma^{A_1, \ldots, A_n}(\varphi)\|_{\mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})} \leq \gamma.
$$
Let $0 < \epsilon < 1$. For any $1 \leq i \leq n-1$, let $X_i \in \mathcal{S}^{\alpha_i}(\mathcal{H}), \tilde{X}_i \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^{\alpha_i}(\mathcal{H})$ such that $\| X_i - \tilde{X}_i \|_{\alpha_i} \leq \epsilon$. Let $Z \in \mathcal{S}^{\alpha'}(\mathcal{H})$ and $Y$ be a finite-rank operator on $\mathcal{H}$ such that $\| Z - Y \|_{\alpha'} \leq \epsilon$. Write, for any $k\geq 1$,
$$\Gamma_{k,X} = \left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi_k)\right](X_1,\ldots, X_{n-1})$$
and
$$\tilde{\Gamma}_{k,X} = \left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi_k)\right](\tilde{X}_1, \ldots, \tilde{X}_{n-1}).
$$
Similarly, write
$$\Gamma_{X} = \left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi)\right](X_1,\ldots,X_{n-1})$$
and
$$\tilde{\Gamma}_X = \left[\Gamma^{A_1,A_2, \ldots, A_n}(\varphi)\right](\tilde{X}_1, \ldots, \tilde{X}_{n-1}).
$$
Since $\left(\Gamma^{A_1, \ldots, A_n}(\varphi_k) \right)_{k\geq 1} \subset \mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})$ is bounded, we can set $C' := \sup_j \|\Gamma^{A_1, \ldots, A_n}(\varphi_j)\|_{\mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})}$. By Remark $\ref{Ineqmulti}$, there exists a constant $C > 0$ depending only on $n, C', \|X_1\|_{\alpha_1}, \ldots, \|X_{n-1}\|_{\alpha_{n-1}}$ such that, for any $k\geq 1$,
\begin{equation}\label{lemma1simp}
\| \Gamma_{k,X} - \tilde{\Gamma}_{k,X} \|_p \leq C \epsilon \ \ \text{and} \ \ \| \Gamma_{X} - \tilde{\Gamma}_{X} \|_p \leq C \epsilon.
\end{equation}
By the first part of the proof, there exists $k_0 \in \mathbb{N}$ such that for any $k\geq k_0$,
\begin{equation}\label{lemma2simp}
| \tr((\tilde{\Gamma}_X - \tilde{\Gamma}_{k,X})Y)| < \epsilon.
\end{equation}
Hence, by \eqref{Proofineqp}, \eqref{lemma1simp} and \eqref{lemma2simp} we have, for any $k\geq k_0$,
\begin{align*}
& | \tr(\Gamma_{X}Z) - \tr(\Gamma_{k,X}Z) | \\
& \leq | \tr(\Gamma_{X}(Z-Y)) | + | \tr((\Gamma_{X} - \tilde{\Gamma}_{X})Y) | + | \tr((\tilde{\Gamma}_{X} - \tilde{\Gamma}_{k,X})Y) | \\
& \ \ \ + | \tr((\tilde{\Gamma}_{k,X} - \Gamma_{k,X})Y) | + | \tr(\Gamma_{k,X}(Y-Z)) | \\
& \leq \left(\gamma \prod_{i=1}^{n-1} \|X_i\|_{\alpha_i} + C \|Y\|_{\alpha'} + 1 + C \|Y\|_{\alpha'} + C'\prod_{i=1}^{n-1} \|X_i\|_{\alpha_i} \right) \epsilon.
\end{align*}
Since $\|Y\|_{\alpha'} \leq \|Z\|_{\alpha'} + \epsilon$, we proved that $$
\left[ \Gamma^{A_1, \ldots, A_n}(\varphi_k) \right](X_1, \ldots, X_{n-1}) \underset{k \to \infty}{\longrightarrow} \left[ \Gamma^{A_1, \ldots, A_n}(\varphi) \right](X_1, \ldots, X_{n-1})
$$
weakly in $\mathcal{S}^{\alpha}(\mathcal{H})$.


Assume that $p=2$. We first prove the result when $\phi_1 = f_1 \otimes \cdots \otimes f_n$ and $\phi_2 = g_j \otimes g_{j+1}$ where for any $1\leq i \leq n, f_i\in L^{\infty}(\lambda_{A_i}), g_j \in L^{\infty}(\lambda_{A_j}), g_{j+1} \in L^{\infty}(\lambda_{A_{j+1}})$. In this case,
$$
\phi_1 \widetilde{\phi_2} = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_j g_j \otimes f_{j+1} g_{j+1} \otimes f_{j+2} \otimes \cdots \otimes f_n
$$
so we have, by \eqref{MOItensor},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) g_j(A_j) K_j g_{j+1}(A_{j+1}) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(g_j\otimes g_{j+1})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right),
\end{align*}
which proves the result for such $\phi_1$ and $\phi_2$. Note that this formula is bilinear in $(\phi_1, \phi_2)$, hence the result holds true whenever $\phi_1 \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $\phi_2 \in L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$.

In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Fix $s\in S$ and assume first that $\phi_{1,s} = f_1 \otimes \cdots \otimes f_n$. By the previous computation, we have, for any $t\in T$,
\begin{align}\label{for1}
\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_{2,t}})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_{2,t})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n).
\end{split}
\end{align}
where $\widetilde{\phi_{2,t}}$ is defined as in \eqref{fortilde}. By the $w^*$-continuity of $\Gamma^{A_j, A_{j+1}}$, we get that the right-hand side of \eqref{for1} converges, in the $w^*$-topology of $\mathcal{S}^2(\mathcal{H})$, to
\begin{align*}
& f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
For the left-hand side of \eqref{for1}, we show that $(\phi_{1,s} \widetilde{\phi_{2,t}})_{t\in T}$ $w^*$-converges to $\phi_{1,s} \widetilde{\phi_2}$. Indeed, let $g\in L^1(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Then, writing $\Omega = \sigma(A_1) \times \cdots \times \sigma(A_n)$, we have, by Fubini's theorem,
\begin{align*}
& \int_{\Omega} \phi_{1,s} \widetilde{\phi_{2,t}} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& = \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \left( \int_{\prod_{i \neq j,j+1} \sigma(A_i)} \phi_{1,s} g \ \prod_{i \neq j,j+1}\text{d}\lambda_{A_j} \right) \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \\
& := \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}.
\end{align*}
By Fubini's theorem, we have the inequality
\begin{align*}
\int_{\sigma(A_j) \times \sigma(A_{j+1})} | \psi_s | \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}
& \leq \int_{\Omega} | \phi_{1,s} g | \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& \leq \| \phi_{1,s} \|_{\infty} \| g\|_{1},
\end{align*}
which shows that $\psi_s \in L^1(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Hence,
$$
\int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \underset{t}{\longrightarrow} \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_2 \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}},
$$
which is in turn equal to $\displaystyle \int_{\Omega} \phi_{1,s} \widetilde{\phi_2} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n}$. This shows that $(\phi_{1,s} \widetilde{\phi_{2,t}})_{t\in T}$ $w^*$-converges to $\phi_{1,s} \widetilde{\phi_2}$. By $w^*$-continuity of multiple operator integrals, we have, taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for1},
\begin{align}\label{for2}
\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}
\end{align}
Note that, by linearity, this equality holds true whenever $\phi_{1,s} \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}).$ Since $(\phi_{1,s} \widetilde{\phi_2})_{s\in S}$ $w^*$-converges to $\phi_1 \widetilde{\phi_2}$ we have, by taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for2},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Assume now that $1\leq p < \infty$ and let $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. By assumption, there exist $A_p, B_p >0$ such that 
\begin{align}\label{densitysimp1}
\begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p \| \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) \|_p \|K_{j+1}\|_p \ldots \| K_{n-1}\|_p \\
& \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{split}
\end{align}
Since for all $1\leq i \leq n-1, K_i \in \mathcal{S}^2(\mathcal{H})$, equality \eqref{fortildeeq} holds and we deduce the inequality
\begin{align}\label{densitysimp2}
\left\| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \right\|_p  \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{align}
By density of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$ in $\mathcal{S}^p(\mathcal{H})$, we get that $\Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2}) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$ and that inequalities \eqref{densitysimp1} and \eqref{densitysimp2} hold true for any $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$.

Finally, to prove equality \eqref{fortildeeq} in the case when $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$, we approximate $K_i, 1\leq i \leq n-1,$ by elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$, using inequalities \eqref{densitysimp1} and \eqref{densitysimp2}.


Assume first that $p=2$. In the case when $\phi_1$ and $\phi_2$ are elementary tensors, it is straightforward to check the identity \eqref{simplificationsepid}. In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_j})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_j})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \cdots \times \lambda_{A_n})$. For any $s \in S$ and any $t\in T$, we have
\begin{align}\label{simplificationsepid2}
\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \phi_{2,t} \right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_j}(\phi_{1,s})\right] (K_1, \ldots, K_{j-1}) \left[ \Gamma^{A_j, \ldots, A_n}(\phi_{2,t})\right] (K_j, \ldots, K_{n-1}).
\end{split}
\end{align}
For a fixed $s\in S$, $(\phi_{1,s} \phi_{2,t})_{t\in T}$ converges to $\phi_{1,s} \phi_2$ and $(\phi_{1,s} \phi_2)_{s\in S}$ converges to $\phi = \phi_1 \phi_2$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Hence by taking the limit on $t\in T$ and then on $s\in S$ in \eqref{simplificationsepid2}, we get \eqref{simplificationsepid}.

Now let $1 \leq p <\infty$ and $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. Then equality \eqref{simplificationsepid} holds and by assumption, there exist $A_p, B_p >0$ such that
\begin{align*}
\begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi)\right] (K_1, \ldots, K_{n-1})\|_p \\
& \leq \| \left[ \Gamma^{A_1, \ldots, A_j}(\phi_1)\right] (K_1, \ldots, K_{j-1}) \|_p \| \left[ \Gamma^{A_j, \ldots, A_n}(\phi_2)\right] (K_j, \ldots, K_{n-1}) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p ~ B_p \|K_j \|_p \ldots \|K_{n+1}\|_p,
\end{split}
\end{align*}
which shows that $\Gamma^{A_1, \ldots, A_n}(\phi) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$. Finally, we deduce \eqref{simplificationsepid} by approximation like in the proof of Lemma $\ref{simplification1}$.


We only prove $(i)$, in the case when $n\geq 3$. The case $n=2$ and the second and third claims can be proved similarly. Assume that $2\leq j \leq n-1$. We first assume that $p=2$. If $\phi = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_{j+1} \otimes \cdots \otimes f_n, f_i \in L^{\infty}(\lambda_{A_i}), 1\leq i\neq j \leq n$, we have
\begin{equation*}
\widetilde{\phi} = f_1 \otimes \cdots \otimes f_{j-1} \otimes 1 \otimes f_{j+1} \otimes \cdots \otimes f_n
\end{equation*}
so that
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) \\
&  = f_1(A_1)K_1 \ldots K_{j-2}f_{j-1}(A_{j-1}) K_{j-1} K_j f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_{j-1}, A_{j+1}, \ldots, A_n}(\phi)\right] \left(K_1, \ldots, K_{j-1}, K_j K_{j+1}, K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
By linearity, this formula holds true whenever $\phi \in L^{\infty}(\lambda_{A_1}) \otimes \cdots L^{\infty}(\lambda_{A_{j-1}}) \otimes L^{\infty}(\lambda_{A_{j+1}}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$.

In the general case, we let $(\phi_s)_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots L^{\infty}(\lambda_{A_{j-1}}) \otimes L^{\infty}(\lambda_{A_{j+1}}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ to be a net converging to $\phi$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_{j-1}} \times \lambda_{A_{j+1}} \times \cdots \times \lambda_{A_n})$. For any $s\in S$, we define $\widetilde{\phi_s}$ as in \eqref{fortilde2}. Then, it is easy to see that $(\widetilde{\phi_s})_{s\in S}$ converges to $\widetilde{\phi}$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. We conclude using the $w^*$-continuity of multiple operator integral like in the proof of Lemma $\ref{simplification1}$.

In the case when $1\leq p < \infty$, we argue as in the end of the proof of Lemma $\ref{simplification1}$. Details are left to the reader.


Define, for any $k\geq 1$, $g_k(t) = k (f^{(n-1)}(t+1/k) - f^{(n-1)}(t)), t\in \mathbb{R}$. Then $(g_k)_{k\geq 1} \subset C(\mathbb{R})$ is pointwise convergent to $f^{(n)}$ and we have the inequality $|g_k| \leq \|f^{(n)}\|_{\infty}$. By \cite[Theorem 5.3]{PSS-SSF}, there exists a constant $c_{p,n} > 0$ depending only on $p$ and $n$ such that, for any $k\geq 1$,
\begin{align}\label{Approxder}
\| \Gamma^{A_1,A_2, \ldots, A_{n+1}}(\varphi_{n,g_k}) \|_{\mathcal{B}_n(\mathcal{S}^{pn} \times \cdots \times \mathcal{S}^{pn},\mathcal{S}^p)} \leq c_{p,n} \|g_k \|_{\infty} \leq c_{p,n} \|f^{(n)}\|_{\infty}.
\end{align}
The proof is given in the case when $A_1 = \cdots = A_{n+1}$ but the arguments from the proof of \cite[Theorem 2.2]{LMS} allow to extend the result in the case when $A_1, \ldots, A_{n+1}$ are distinct.

By Lebesgue's dominated convergence theorem, $\varphi_{n,g_k}$ is pointwise convergent to $\varphi_{n,f^{(n)}}$ on $\mathbb{R}^{n+1}$. Moreover, we have
$$
|\varphi_{n,g_k}| \leq \dfrac{\|g_k\|_{\infty}}{n!} \leq \dfrac{\|f^{(n)}\|_{\infty}}{n!}.
$$
Hence, using Lebesgue's dominated convergence theorem again, we get that $(\varphi_{n,g_k})_{k\geq 1}$ $w^*$-converges to $\varphi_{n,f^{(n)}} = f^{[n]}$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_{n+1}})$. By Lemma $\ref{LemmeUB}$ and \eqref{Approxder} we deduce that
$$
\Gamma^{A_1,A_2, \ldots, A_{n+1}}(f^{[n]}) \in \mathcal{B}_n(\mathcal{S}^{pn} \times \cdots \times \mathcal{S}^{pn},\mathcal{S}^p)
$$
with $\| \Gamma^{A_1,A_2, \ldots, A_{n+1}}(f^{[n]}) \|_{\mathcal{B}_n(\mathcal{S}^{pn} \times \cdots \times \mathcal{S}^{pn},\mathcal{S}^p)} \leq c_{p,n} \|f^{(n)}\|_{\infty}$, from which we deduce inequality \eqref{IneqDDn}. Inequality \eqref{IneqDDn2} follows from the fact that $\|.\|_{pn} \leq \|.\|_p$.


Let $1 \leq j \leq n$. First note that we have the following equality: for any $(x_0, \ldots, x_n) \in \mathbb{R}^{n+1}$,
\begin{align}\label{eqDDsep}
\begin{split}
& f^{[n]}(x_0, \ldots, x_n).(x_{j-1} - x_j) \\
& \ \ \ = f^{[n-1]}(x_0,\ldots,x_{j-1}, x_{j+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{j-2}, x_{j},x_{j+1},\ldots,x_n).
\end{split}
\end{align}
Let $k\geq 1$. Define $\phi_1 = f^{[n]}$, and for any $(x_0, \ldots, x_n) \in \mathbb{R}^{n+1}$,
$$
\phi_2(x_{j-1},x_j) = (x_{j-1} - x_j)\chi_{[-k,k]}(x_{j-1})\chi_{[-k,k]}(x_{j}),
$$
$$\psi_1(x_0, \ldots, x_n) = f^{[n-1]}(x_0,\ldots,x_{j-1}, x_{j+1}, \ldots,x_n)\chi_{[-k,k]}(x_{j-1})\chi_{[-k,k]}(x_{j})$$ and
$$\psi_2(x_0, \ldots, x_n) = f^{[n-1]}(x_0,\ldots,x_{j-2}, x_{j},x_{j+1},\ldots,x_n)\chi_{[-k,k]}(x_{j-1})\chi_{[-k,k]}(x_{j}).$$
Then $\phi_1, \psi_1, \psi_2 \in L^{\infty}(\lambda_{A_1} \times \cdots \times  \lambda_{A_{j-1}} \times \lambda_B \times \lambda_A \times \lambda_{A_j} \times \cdots \times \lambda_{A_n})$, $\phi_2 \in L^{\infty}(\lambda_B \times \lambda_A)$ and after multiplying equality \eqref{eqDDsep} by $\chi_{[-k,k]}(x_{j-1})\chi_{[-k,k]}(x_{j})$ we obtain
\begin{equation}\label{eqfunc}
\phi_1 \widetilde{\phi_2} = \psi_1 - \psi_2,
\end{equation}
where $\widetilde{\phi_2}$ was defined in \eqref{fortilde}.

Assume first that $2 \leq j \leq n-1$. Let $X, K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$. Note that
$$
\left[\Gamma^{B,A}(\chi_{[-k,-k]} \otimes \chi_{[-k,-k]})\right](X) = p_k(B)Xp_k(A)
$$
and
$$
\left[\Gamma^{B,A}(\phi_2)\right](X) = Bp_k(B)Xp_k(A) - p_k(B)Xp_k(A)A,
$$
where $p_k = \chi_{[-k,k]}$.
Denote
$$\Gamma_A = \Gamma^{A_1, \ldots, A_{j-1}, A, A_j, \ldots, A_{n-1}}, \ \Gamma_B = \Gamma^{A_1, \ldots, A_{j-1}, B, A_j, \ldots, A_{n-1}}$$
and
$$\Gamma_{B,A} = \Gamma^{A_1, \ldots, A_{j-1}, B, A, A_j, \ldots, A_{n-1}}.$$
Applying the operator $\left[\Gamma_{B,A}(\cdot)\right](K_1, \ldots, K_{j-1}, X, K_j, \ldots K_{n-1})$ to \eqref{eqfunc} gives, by Lemma $\ref{simplification1}$ and Lemma $\ref{simplification2}$,
\begin{align}\label{eqfunc2}
\begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)Xp_k(A) - p_k(B)Xp_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)Xp_k(A) K_j, K_{j+1} \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)Xp_k(A) K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}
\end{align}


Let $(P_i)_k$ be an increasing sequence of finite rank projections converging strongly to the identity and such that
\begin{equation}\label{existpro}
BP_i - P_iB \underset{i \to \infty}{\longrightarrow} 0 \ \text{in} \ \mathcal{S}^p(\mathcal{H}).
\end{equation}
As explained before the statement of the Proposition, such sequence exists. We apply equality \eqref{eqfunc2} to $X=P_i$ and we obtain, for any $i\geq 1$,
\begin{align}\label{eqfunc3}
\begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)P_ip_k(A) - p_k(B)P_ip_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)P_ip_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)P_ip_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}
\end{align}
Note that for any $K \in \mathcal{S}^p(\mathcal{H}), KP_i \to K$ and $P_iK\to K$ in $\mathcal{S}^p(\mathcal{H})$, as $i$ goes to $\infty$. This implies that $p_k(B)P_ip_k(A) K_j \to p_k(B)p_k(A) K_j$ and that $p_k(B)P_ip_k(A)K_{j-1} \to p_k(B)p_k(A)K_{j-1}$ as $i$ goes to $\infty$. By continuity of multiple operator integrals stated in Theorem $\ref{BddnessMOI}$, this implies that the right-hand side of \eqref{eqfunc3} converges in $\mathcal{S}^p(\mathcal{H})$ to
\begin{align*}
&\left[ \Gamma_B (f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)p_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& - \left[ \Gamma_A (f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)p_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{align*}
Using the identity
$$
Bp_k(B)P_ip_k(A) - p_k(B)P_ip_k(A)A = p_k(B)(BP_i-P_iB)p_k(A) + p_k(B)P_i(B-A)p_k(A),
$$
we have, by \eqref{existpro}, that
$$
Bp_k(B)P_ip_k(A) - p_k(B)P_ip_k(A)A \to p_k(B)(B-A)p_k(A)
$$
in $\mathcal{S}^p(\mathcal{H})$, as $i$ goes to $\infty$. Hence, the left-hand side of \eqref{eqfunc3} converges in $\mathcal{S}^p(\mathcal{H})$ to
$$
\left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, p_k(B)(B-A)p_k(A), K_j, \ldots, K_{n-1})
$$
and we proved that
\begin{align}\label{eqfunc4}
\begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, p_k(B)(B-A)p_k(A), K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)p_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)p_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}
\end{align}
Finally, note that $(p_k(B))_{k\geq 1}$ and $(p_k(A))_{k\geq 1}$ converge strongly to the identity as $k$ goes to $\infty$ so $p_k(B)p_k(A) K_j \to K_j$ and $p_k(B)p_k(A)K_{j-1} \to K_{j-1}$ in $\mathcal{S}^p(\mathcal{H})$, as $k$ goes to $\infty$. By assumption, $B-A \in \mathcal{S}^p(\mathcal{H})$ so we have $p_k(B)(B-A)p_k(A) \to B-A$ as $k$ goes to $\infty$. Hence, taking the limit on $k$ in \eqref{eqfunc4} concludes the proof in the case when $2 \leq j \leq n-1$.\\

In the case when $j=1$, the right-hand side of \eqref{eqfunc2} is replaced by
\begin{align*}
& \left[ \Gamma_B (f^{[n-1]})\right](p_k(B)Xp_k(A)K_1, K_2, \ldots, K_{n-1})\\
& \ \ \ \ - p_k(B)Xp_k(A)\left[ \Gamma_A (f^{[n-1]})\right](K_1,\ldots, K_{n-1})
\end{align*}
and when $j=n$, the right-hand side is replaced by
\begin{align*}
& \left[ \Gamma_B (f^{[n-1]})\right](K_1, \ldots, K_{n-1})p_k(B)Xp_k(A)\\
& \ \ \ \ - \left[ \Gamma_A (f^{[n-1]})\right](K_1,\ldots, K_{n-2}, p_k(B)Xp_k(A)K_{n-1}).
\end{align*}
We then apply the same reasonning as before to obtain the result.


In this proof, we will use the notation introduced before the statement of Theorem $\ref{BddnessMOI}$. For any $k\geq 1$, we let $\psi_k := \varphi_{n,g_k}$ to be the function defined as in the proof of Theorem $\ref{BddnessMOI}$. For any bounded Borel function $g$, we let $\tilde{g}$ to be the function defined on $\mathbb{R}$ by $\tilde{g}_k(x) = g(x, \ldots, x), x\in \mathbb{R}$. Let us prove first that for any $k\geq 1$,
$$
\left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) = \tilde{\psi}_k(A)Z_1\ldots Z_n.
$$
Fix $k\geq 1$. $A$ is bounded so $\sigma(A) \subset \mathbb{R}$ is bounded and by definition,
$$\Gamma^{A, \ldots, A}(\psi_k) = \Gamma^{A, \ldots, A}(\phi_k)$$
where $\phi_k$ is the class in $L^{\infty}(\lambda_A \times \cdots \times \lambda_A)$ of the restriction of $\psi_k$ to $\sigma(A)^{n+1}$. $g_k$ is continuous on the compact $I= \text{conv}(\sigma(A))$ so there exists a sequence $(P^k_j)_{j\geq 1}$ of polynomial functions converging uniformly to $g_k$ on $I$. For any $j\geq 1$, define $Q^k_j = \varphi_{n, P^k_j}$. It is easy to see that $(Q^k_j)_{j\geq 1}$ converges uniformly to $\psi_k$ on $\sigma(A)^{n+1}$. According to \eqref{DDint}, $Q^k_j = (R^k_j)^{[n]}$ where $R^k_j$ is a polynomial function on $\mathbb{R}$ such that $(R^k_j)^{(n)} = P^k_j$. Hence $Q^k_j$ is a $(n+1)$-variable polynomial function, and in particular, $Q^k_j \in \text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$. Note that for an elementary tensor $g = g_1 \otimes \cdots \otimes g_{n+1} \in \text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$, we have
\begin{align*}
\left[ \Gamma^{A, \ldots, A}(g) \right] (Z_1, \ldots, Z_n)
& = g_1(A)Z_1g_2(A)\ldots g_n(A)Z_ng_{n+1}(A) \\
& = g_1(A)\ldots g_{n+1}(A) Z_1 \ldots Z_n \\
& = \tilde{g}(A) Z_1 \ldots Z_n.
\end{align*}
By linearity, this implies that for any $j \geq 1$,
\begin{equation}\label{eqcomm0}
\left[ \Gamma^{A, \ldots, A}(Q^k_j) \right] (Z_1, \ldots, Z_n) = \tilde{Q}^k_j(A)Z_1\ldots Z_n.
\end{equation}
For any $j\geq 1$, we let $v^k_j \in \text{Bor}(\mathbb{R})$ be such that $v^k_j = P^k_j$ on $I$ and  $v^k_j \to g_k$ uniformly on $\mathbb{R}$. Then
$$
\Gamma^{A, \ldots, A}(\varphi_{n, P^k_j}) = \Gamma^{A, \ldots, A}(\varphi_{n, v^k_j})
$$
and by Theorem $\ref{BddnessMOI}$, there exists a constant $c_{p,n}$ such that
\begin{align*}
& \| \left[ \Gamma^{A, \ldots, A}(Q^k_j) \right] (Z_1, \ldots, Z_n) - \left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) \|_p \\
& = \| \left[ \Gamma^{A, \ldots, A}(\varphi_{n, v^k_j} - \varphi_{n, g_k}) \right] (Z_1, \ldots, Z_n) \|_p \\
& \leq c_{p,n} \| v^k_j - g_k\|_{\infty} \|Z_1\|_p \cdots \|Z_n\|_p \\
& \underset{j\to \infty}{\longrightarrow} 0.
\end{align*}
Note that $(\tilde{Q}^k_j)_{j\geq 1}$ converges uniformly to $\tilde{\phi}_k$ on $\sigma(A)$. Hence, $\tilde{Q}^k_j(A)$ converges to $\tilde{\psi}_k(A)$ in $\mathcal{B}(\mathcal{H})$ so that the right-hand side of \eqref{eqcomm0} converges in $\mathcal{S}^p(\mathcal{H})$ to $\tilde{\psi}_k(A)Z_1\ldots Z_n$. By taking the limit on $j$ in \eqref{eqcomm0} we get
\begin{equation}\label{eqcomm}
\left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) = \tilde{\psi}_k(A)Z_1\ldots Z_n.
\end{equation}
Recall that, from the proof of Theorem $\ref{BddnessMOI}$, the sequence $(\psi_k)_{k\geq 1}$ $w^*$-converges to $f^{[n]}$ for the $w^*$-topology of $L^{\infty}(\lambda_A \times \cdots \times \lambda_A)$ and that $(\Gamma^{A, \ldots, A}(\psi_k))_{k\geq 1} \subset \mathcal{B}_n(\mathcal{S}^p(\mathcal{H}))$ is bounded. Hence, by Lemma $\ref{LemmeUB}$,
$$
\left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) \underset{k \to \infty}{\longrightarrow} \left[ \Gamma^{A, \ldots, A}(f^{[n]}) \right] (Z_1, \ldots, Z_n)
$$
weakly in $\mathcal{S}^p(\mathcal{H})$. On the other hand, $(\tilde{\psi}_k)_{k\geq 1}$ is bounded and is pointwise convergent to $\tilde{f}^{[n]}=\dfrac{1}{n!}f^{(n)}$ so $(\tilde{\psi}_k(A))_{k\geq 1}$ converges strongly to $\dfrac{1}{n!} f^{(n)}(A)$ (see e.g. the proof of \cite[Proposition 3.1]{CLSS}). This implies that the right-hand side of \eqref{eqcomm} converges in $\mathcal{S}^p(\mathcal{H})$ to $\dfrac{1}{n!} f^{(n)}(A)Z_1\ldots Z_n.$ We conclude the proof by taking the limit on $k$ in \eqref{eqcomm}, in the weak topology of $\mathcal{S}^p(\mathcal{H})$.


We have the following decomposition
\begin{align*}
&\psi(t) - \psi(0) \\
& = \sum_{k=1}^j \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k-1}}(f^{[n-1]}) - \Gamma^{(A+tK)^{j-k},(A)^{n-j+k}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}).
\end{align*}
For any $1\leq k\leq j$, we have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k-1}}(f^{[n-1]}) - \Gamma^{(A+tK)^{j-k},(A)^{n-j+k}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}) \\
& = t \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k}}(f^{[n]}) \right](X_1, \ldots, X_{j-k}, K, X_{j-k+1}, \ldots, X_{n-1}),
\end{align*}
from which we deduce \eqref{simplification5eq}.

For the continuity of $\psi$ in $0$, note that by Theorem $\ref{BddnessMOI}$ there exists a constant $c_{p,n} > 0$ such that
\begin{align*}
& \| \psi(t) - \psi(0) \|_p \\
& \leq |t| \sum_{k=1}^{j} \| \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k}}(f^{[n]}) \right](X_1, \ldots, X_{j-k}, K, X_{j-k+1}, \ldots, X_{n-1}) \|_p \\
& \leq |t| j c_{p,n} \|f^{(n)} \|_{\infty} \|K\|_p \prod_{i=1}^{n-1} \| X_i \|_p,
\end{align*}
which converges to $0$ as $t$ goes to $0$.


Let $K\in \mathcal{S}^p(\mathcal{H})$ selfadjoint and show that $\psi$ is differentiable in $0$ with
$$
\psi'(0) = n \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K).
$$
Let $\epsilon > 0$ and choose $K_0 \in X_0$ such that $\|K-K_0\|_p \leq \epsilon$. By assumption, $\psi_0$ is differentiable in $0$ and
$$
\psi_0'(0) = n \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0).
$$
Hence, there exists $\mu > 0$ such that for any $|t| < \mu$,
\begin{equation}\label{psiepsilon0}
\|\psi_0(t) - \psi_0(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \leq |t| \epsilon.
\end{equation}
Define $\tilde{\psi} : \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ by
$$
\tilde{\psi}(t) = \left[\Gamma^{A+tK_0, \ldots A+tK_0}(f^{[n-1]}) \right](K, \ldots, K), t\in \mathbb{R}.
$$
By Lemma $\ref{simplification5}$ we have
\begin{align*}
\tilde{\psi}(t) - \tilde{\psi}(0)
& = t \sum_{k=1}^n \left[ \Gamma^{(A+tK_0)^{n-k+1},(A)^k}(f^{[n]}) \right]((K)^{n-k}, K_0, (K)^{k-1}) \\
& = t \sum_{k=1}^n \left[ \Gamma^{(A+tK_0)^{n-k+1},(A)^k}(f^{[n]}) \right](K_0, \ldots, K_0) + t\psi_{\epsilon}(t) \\
& = \psi_0(t) - \psi_0(0) + t\psi_{\epsilon}(t)
\end{align*}
where
$$
\psi_{\epsilon}(t) = \sum_{k=1}^n \left( \Gamma_{A,K_0,k,t}((K)^{n-k}, K_0, (K)^{k-1}) - \Gamma_{A,K_0,k,t}(K_0,\ldots,K_0) \right).
$$
with $\Gamma_{A,K_0,k,t} = \Gamma^{(A+tK_0)^{n-k+1},(A)^k}(f^{[n]})$.
By Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\alpha > 0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that for any $1 \leq k \leq n$ and any $t\in \mathbb{R}$, 
$$
\| \Gamma_{A,K_0,k,t}((K)^{n-k}, K_0, (K)^{k-1}) - \Gamma_{A,K_0,k,t}(K_0, \ldots, K_0) \|_p \leq \alpha \epsilon
$$
so that we have the estimate $\| \psi_{\epsilon}(t) \| \leq n \alpha \epsilon.$ By the estimate \eqref{psiepsilon0} and triangle inequality, we deduce that for any $|t| < \mu$,
\begin{align}\label{psiepsilon4}
\begin{split}
& \| \tilde{\psi}(t) - \tilde{\psi}(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \\
& \leq \| \psi_0(t) - \psi_0(0)  - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p + |t| \| \psi_{\epsilon}(t) \|_p \\
& \leq |t| \epsilon (n\alpha + 1).
\end{split}
\end{align}

By Lemma $\ref{simplification5}$ we have
\begin{align*}
\psi(t) - \tilde{\psi}(t) = t \sum_{k=1}^{n} \left[ \Gamma^{(A+tK)^{n-k+1}, (A+tK_0)^k}(f^{[n]})\right]((K)^{n-k}, K-K_0, (K)^{k-1}).
\end{align*}
Hence, by Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\beta>0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $t\in \mathbb{R}$
\begin{equation}\label{psiepsilon2}
\| \psi(t) - \tilde{\psi}(t) \|_p \leq n \beta |t| \epsilon.
\end{equation}

Let also $\gamma>0$ be a constant depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that
\begin{equation}\label{psiepsilon3}
\| \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) - \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \leq \gamma \epsilon.
\end{equation}

Finally, by triangle inequality and noting that $\psi(0) = \tilde{\psi}(0)$ we have, by \eqref{psiepsilon2}, \eqref{psiepsilon4} and \eqref{psiepsilon3}, 
\begin{align*}
& \| \psi(t) - \psi(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) \|_p \\
& \leq \| \psi(t) - \tilde{\psi}(t)\|_p \\
& \ \ \ \ + \| \tilde{\psi}(t) - \tilde{\psi}(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0)\|_p \\
& \ \ \ \ + \| n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) - nt \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) \|_p \\
& \leq |t| \epsilon (n\beta + n\alpha + n\gamma  + 1),
\end{align*}
for any $|t| < \mu$. This concludes the proof.


Let $\epsilon > 0$. By assumption, there exists $\mu_1 > 0$ such that for any $|t| < \mu_1$,
\begin{equation}\label{nu1}
\| \tilde{\psi}(t) - \tilde{\psi}(0) - t \tilde{\psi}'(0) \|_p \leq |t| \epsilon.
\end{equation}
Moreover, $\nu(0)=A$ and $\nu'(0) = K$ in $\mathcal{S}^p(\mathcal{H})$, so there exists $\mu_2 > 0$ such that for any $|t| < \mu_2$,
\begin{equation*}
\left\| \frac{(A+tK) - \mu(t)}{t} \right\|_p = \left\| \frac{\mu(t)-A}{t} -K \right\|_p \leq \epsilon.
\end{equation*}
We have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \dfrac{\psi(t) - \tilde{\psi}(t)}{t}  \\
& = \dfrac{1}{t} \sum_{k=1}^n \left[ \Gamma^{(A+tK)^{n-k+1}, (\nu(t))^{k-1}}(f^{[n-1]})-\Gamma^{(A+tK)^{n-k}, (\nu(t))^k}(f^{[n-1]}) \right](K, \ldots, K) \\
& = \sum_{k=1}^{n} \left[ \Gamma^{(A+tK)^{n-k+1}, (\nu(t))^k}(f^{[n]})\right]\left( (K)^{n-k}, \frac{(A+tK) - \mu(t)}{t} , (K)^{k-1} \right).
\end{align*}
Hence, by Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\alpha > 0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $t\in \mathbb{R}$,
\begin{equation}\label{nu2}
\| \psi(t) - \tilde{\psi}(t) \|_p \leq |t| n \alpha \epsilon.
\end{equation}
Finally, by \eqref{nu1} and \eqref{nu2} and by triangle inequality we have, noting that $\psi(0) = \tilde{\psi}(0)$,
\begin{align*}
\| \psi(t) - \psi(0) - t \tilde{\psi}'(0) \|_p
& \leq \| \psi(t) -  \tilde{\psi}(t)\|_p + \| \tilde{\psi}(t) - \tilde{\psi}(0) - t \tilde{\psi}'(0) \|_p \\
& \leq (n\alpha + 1) |t| \epsilon,
\end{align*}
for any $|t| < \text{min}(\mu_1, \mu_2)$, which proves the claim.


We first assume that $Y\in \mathcal{S}^2(\mathcal{H})$. Note that the projection $E_m$ commutes with $A + K_m$ so that for any $g\in C_b(\mathbb{R})$ we have, by \cite[(7.25)]{KPSS},
$$
E_m g(A + K_m) = g(A_m + K_m) = g(A + K_m) E_m .
$$
From this equality, we easily deduce that for any $\phi \in C_b(\mathbb{R}) \otimes \cdots \otimes C_b(\mathbb{R})$,
\begin{equation}\label{reducbddeq2}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(\phi) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(\phi) \right](Y_m, \ldots, Y_m).
\end{equation}
By approximation, this implies that \eqref{reducbddeq2} holds true whenever $\phi$ belongs to the uniform closure of $C_b(\mathbb{R})\otimes \cdots \otimes  C_b(\mathbb{R})$, which contains in particular $C_0(\mathbb{R}^{n+1})$.

Assume now that $\phi \in C_b(\mathbb{R}^{n+1})$. Let
$(g_k)_{k\geq 1}$ be a sequence of functions in
$C_0(\mathbb{R})$ satisfying the following two properties:
$$
\forall\, k\in\mbox{${\mathbb N}$}, \quad 0\leq g_k\leq 1,
\qquad\hbox{and}\qquad\forall\, r\in \mathbb{R},\quad
g_k(r)\overset{k\to\infty}{\longrightarrow} 1.
$$
For any $k\geq 1, \phi g_k \in C_0(\mathbb{R}^{n+1})$, so the latter implies that
\begin{equation}\label{reducbddeq1}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(\phi g_k) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(\phi g_k) \right](Y_m, \ldots, Y_m).
\end{equation}
By Lebesgue's dominated convergence theorem, the properties satisfied by the sequence $(g_k)_{k\geq 1}$ imply that $(\phi g_k)_{k\geq 1}$ converges to $\phi$ for the $w^*$-topology of $L^{\infty}\left(\prod_{i=1}^n \lambda_{A + K_m}\right)$ and $L^{\infty}\left(\prod_{i=1}^n \lambda_{A_m + K_m}\right)$. Hence, by the $w^*$-continuity of multiple operator integrals, we obtain, by taking the limit on $k$ in \eqref{reducbddeq1},
\begin{equation}\label{reducbddeq3}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(\phi) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(\phi) \right](Y_m, \ldots, Y_m).
\end{equation}

For any $k\geq 1$, let $\phi_k = \varphi_{n,g_k}$ as defined in the proof of Theorem $\ref{BddnessMOI}$. Then $(\varphi_{n,g_k})_{k\geq 1} \subset C_b(\mathbb{R}^{n+1})$ and the sequence $w^*$-converges to $f^{[n]}$ for the $w^*$-topologies of $L^{\infty}\left(\prod_{i=1}^n \lambda_{A + K_m}\right)$ and $L^{\infty}\left(\prod_{i=1}^n \lambda_{A_m + K_m}\right)$. Hence, $\phi_k$ satisfies \eqref{reducbddeq3} for any $k\geq 1$ and by the $w^*$-continuity of multiple operator integrals, we get that $\phi$ satisfies \eqref{reducbddeq}. 

In the case $1 < p < \infty$, we approximate $Y \in \mathcal{S}^p(\mathcal{H})$ by a sequence $(Y_j)_{j\geq 1}$ of elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$ and then pass to the limit in the equality
\begin{align*}
&\left[\Gamma^{A+K_m, \ldots, A+K_m}(f^{[n]}) \right]((Y_j)_m, \ldots, (Y_j)_m) \\
& \ \ \ \ = \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(f^{[n]}) \right]((Y_j)_m, \ldots, (Y_j)_m)
\end{align*}
as $j \to \infty$, using the estimate in Theorem $\ref{BddnessMOI}$ and the fact that $(Y_j)_m \underset{j \to \infty}{\longrightarrow} Y_m$ in $\mathcal{S}^p(\mathcal{H})$.

The assumptions on $f$ ensure, by \cite[Theorem 7.13]{KPSS}, that $\varphi$ is differentiable on $\mathbb{R}$ and that for any $t\in \mathbb{R}$,
$$
\varphi'(t) = \left[\Gamma^{A+tK, A+tK}(f^{[1]}) \right](K).
$$
Assume now that $\varphi$ is $(n-1)$-times differentiable on $\mathbb{R}$ with
$$
\dfrac{\varphi^{(n-1)}(t)}{(n-1)!} = \left[\Gamma^{A+tK, \ldots, A+tK}(f^{[n-1]}) \right](K, \ldots, K).
$$
We have to show that the function
$$
\psi : t\in \mathbb{R} \mapsto \left[\Gamma^{A+tK, \ldots, A+tK}(f^{[n-1]}) \right](K, \ldots, K)
$$
is differentiable and that for any $t\in \mathbb{R}$,
$$
\psi'(t) = n \left[\Gamma^{A+tK, \ldots, A+tK}(f^{[n]}) \right](K, \ldots, K).
$$
It is clear that we only have to prove the differentiability in $0$, from which we can deduce the differentiabily on $\mathbb{R}$. In this case, by Lemma $\ref{simplification3}$, it is sufficient to prove the differentiability for $K$ belonging to a dense subset of $(\mathcal{S}^p(\mathcal{H}))_{\text{sa}}$. By \cite[Proposition 6.2]{KPSS}, the subspace $X_0$ defined by
$$
X_0 = \left\lbrace i[A,Y] + Z \ \text{with} \ Y,Z \in (\mathcal{S}^p(\mathcal{H}))_{\text{sa}} \ \text{and} \ Z \ \text{commutes with} \ A \right\rbrace \subset (\mathcal{S}^p(\mathcal{H}))_{\text{sa}}
$$
is dense in $(\mathcal{S}^p(\mathcal{H}))_{\text{sa}}$. Let $K = i[A,Y] + Z \in X_0$ and show that
$$
\psi_0 : t\in \mathbb{R} \mapsto \left[\Gamma^{A+tK, \ldots A+tK}(f^{[n-1]}) \right](K, \ldots, K)
$$
is differentiable in $0$ with
$$
\psi_0'(0) = n \left[\Gamma^{A, \ldots, A}(f^{[n]}) \right](K, \ldots, K).
$$
Let $\nu(t) = e^{-itY}(A+tZ)e^{itY}$. We have $\nu(0)=A$ and $\nu$ is $\mathcal{S}^p$-differentiable in $0$ with $\nu'(0)=K$. Hence, by Lemma $\ref{simplification4}$, to prove the latter, it is equivalent to prove that $\tilde{\psi} : \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ defined by
$$
\tilde{\psi}(t) = \left[ \Gamma^{\nu(t),\ldots,\nu(t)}(f^{[n-1]}) \right](K, \ldots, K), t\in \mathbb{R},
$$
is differentiable in $0$ with
$$
\tilde{\psi}'(0) = n \left[\Gamma^{A, \ldots, A}(f^{[n]}) \right](K, \ldots, K).
$$
We have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \dfrac{\tilde{\psi}(t) - \tilde{\psi}(0)}{t}  \\
& = \dfrac{1}{t} \sum_{k=1}^n \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^{k-1}}(f^{[n-1]})-\Gamma^{(\nu(t))^{n-k}, (A)^k}(f^{[n-1]}) \right](K, \ldots, K) \\
& = \sum_{k=1}^{n} \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]})\right]\left( (K)^{n-k}, \frac{\nu(t) - A}{t} , (K)^{k-1} \right).
\end{align*}
For $1\leq k\leq n$ and any $t\neq 0$, let
$$\displaystyle \Gamma_{\nu,k}(t) = \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]})\right]\left( (K)^{n-k}, \frac{\nu(t) - A}{t} , (K)^{k-1} \right).$$
Since $\frac{\nu(t) - A}{t}$ goes to $K$ in $\mathcal{S}^p(\mathcal{H})$ as $t$ goes to $0$, by uniform boundedness of $\Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]}) \in \mathcal{B}_n(\mathcal{S}^p), t\in \mathbb{R}$, we deduce that if one of those limits exists, so does the second one and we have
$$
\underset{t \to 0}{\lim} \ \Gamma_{\nu,k}(t) = \underset{t \to 0}{\lim} \ \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]})\right]\left( K,\ldots,K \right).
$$
Note that
\begin{align*}
& \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(f^{[n]})\right]\left( K,\ldots,K \right) \\
& \ \ \ \ \ \ = e^{-itY}\left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right]\left((e^{itY}Ke^{-itY})^{n-k},e^{itY}K, (K)^{k-1} \right).
\end{align*}
In fact, more generally, for any $t\in \mathbb{R}$, for any $g\in \text{Bor}(\mathbb{R}^{n+1})$ such that $\Gamma^{(\nu(t))^{n-k+1}, (A)^k}(g) \in \mathcal{B}_n(\mathcal{S}^p)$ and any $X \in  \mathcal{S}^p(\mathcal{H})$, we have
\begin{align*}
& \left[ \Gamma^{(\nu(t))^{n-k+1}, (A)^k}(g)\right]\left(X, \ldots, X \right) \\
& \ \ \ \ \ \ = e^{-itY}\left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(g)\right]\left((e^{itY}Xe^{-itY})^{n-k},e^{itY}X, (X)^{k-1} \right).
\end{align*}
Indeed, when $g$ is an element of $\text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$, this equality is a consequence of the fact that for any $h \in \text{Bor}(\mathbb{R})$, $h(e^{-itY}(A+tZ)e^{itY}) = e^{-itY}h(A+tZ)e^{itY}$. Hence, if $p=2$, the general case follows from the $w^*$-continuity of multiple operator integrals. If $1<p<\infty$, we approximate $X\in \mathcal{S}^p(\mathcal{H})$ by elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. Details are left to the reader.

Now, when $t$ goes to $0$, $e^{-itY} \to 1$ in $\mathcal{B}(\mathcal{H})$ so that $e^{itY}Ke^{-itY}, e^{itY}K \to K$ in $\mathcal{S}^p(\mathcal{H})$. Hence, by uniform boundedness of $\Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]}) \in \mathcal{B}_n(\mathcal{S}^p), t\in \mathbb{R}$, we have that if one of those limits exists, so does the second one and then
\begin{align*}
& ~ \ \ \ \underset{t \to 0}{\lim} \ e^{-itY}\left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right]\left((e^{itY}Ke^{-itY})^{n-k},e^{itY}K, (K)^{k-1} \right) \\
& = \underset{t \to 0}{\lim} \ \left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right]\left(K, \ldots, K \right).
\end{align*}
Define
$$
\xi(t) = \displaystyle \sum_{k=1}^n \left[ \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]})\right] (K, \ldots, K), t \in \mathbb{R}.
$$
The latter implies that if $\xi$ has a limit in $0$, then so does $\dfrac{\tilde{\psi}(t) - \tilde{\psi}(0)}{t}$ with the same limit. Hence, in order to prove Formula \eqref{diffenrential}, we have to show that $\xi$ has a limit in $0$ and that
$$
\underset{t \to 0}{\lim} \ \xi(t) = n \left[\Gamma^{A, \ldots, A}(f^{[n]}) \right](K, \ldots, K) \ \ \text{in} \ \ \mathcal{S}^p(\mathcal{H}).
$$
For any $1\leq k\leq n$ and any $t\in \mathbb{R}$, let $\Gamma_k(t) = \Gamma^{(A+tZ)^{n-k+1}, (A)^k}(f^{[n]}).$
Since $K = i[A,Y] + Z$, we have, for any $1\leq k \leq n$,
\begin{align*}
\left[\Gamma_k(t) \right](K,\ldots,K)
&  = \left[ \Gamma_k(t) \right] (Z, \ldots, Z) \\
&  + \sum_{j=1}^n \ \sum_{\substack{K_m = i[A,Y] \\\text{or} \ K_m=Z, \\ 1 \leq m \leq n-1}} i \left[ \Gamma_k(t) \right] (K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})
\end{align*}



Hence,
\begin{align*}
\xi(t) 
& = \sum_{k=1}^{n} \left[ \Gamma_k(t) \right] (Z, \ldots, Z) \\
& + \sum_{k=1}^{n} \sum_{j=1}^n \ \sum_{\substack{K_m = i[A,Y] \\\text{or} \ K_m=Z, \\ 1 \leq m \leq n-1}} i \left[ \Gamma_k(t) \right] (K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1}).
\end{align*}
By Lemma $\ref{simplification5}$ and Lemma $\ref{MOIcomm}$ we have
\begin{align*}
\sum_{k=1}^{n} \left[ \Gamma_k(t) \right] (Z, \ldots, Z)
& = \dfrac{1}{t} \left[ \Gamma^{A+tZ,\ldots, A+tZ}(f^{[n-1]}) - \Gamma^{A,\ldots, A}(f^{[n-1]}) \right](Z, \ldots, Z) \\
& = \dfrac{1}{(n-1)!} \ \dfrac{f^{(n-1)}(A+tZ)-f^{(n-1)}(A) }{t} \ Z^{n-1}.
\end{align*}
By \cite[Lemma 3.4 (ii)]{KS}, this quantity converges as $t$ goes to $0$ in $\mathcal{S}^p(\mathcal{H})$ to
$$
\dfrac{1}{(n-1)!} \ f^{(n)}(A) Z^n.
$$
Since $n! f^{[n]}(x,\ldots,x) = f^{(n)}(x)$, the latter is in turn, by Lemma $\ref{MOIcomm}$, equal to
$$
n \left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](Z, \ldots, Z).
$$

We will now show that for any $1\leq j,k \leq n$ and for any $K_1, \ldots, K_{n-1}$ with $K_m= Z$ or $i[A,Z]$, $1\leq m \leq n-1$, 
$$
\left[\Gamma_k(t)\right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})
$$
goes to $\left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})$ in $\mathcal{S}^p(\mathcal{H})$ as $t$ goes to $0$.

Assume first that $n-k+2 \leq j \leq n$. Since $A$ and $Z$ are bounded operators, we have, by Remark $\ref{approximatebdd}$,
\begin{align*}
& \left[\Gamma_k(t)\right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1}) \\
& = \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& \ \ \ - \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}),
\end{align*}
with a simple modification in the case $j=n$. By Lemma $\ref{simplification5}$ the latter converges, as $t$ goes to $0$, to
\begin{align*}
&\left[\Gamma^{A, \ldots, A}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& - \left[\Gamma^{A, \ldots, A}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}),
\end{align*}
which is in turn equal to $\left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})$.

Assume now that $j=n-k+1$. In this case, by Remark $\ref{approximatebdd}$,
\begin{align*}
& \left[\Gamma^{(A+tZ)^{n-k+1},(A)^k}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, (A+tZ)Y - YA, K_j, \ldots, K_{n-1}) \\
& = \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& \ \ \ - \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}).
\end{align*}
Since $(A+tZ)Y - YA = [A,Y] +tZY$, we get
\begin{align*}
& \left[\Gamma_k(t)\right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1}) \\
& = \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& \ \ \ - \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}) \\
& \ \ \ - t \left[\Gamma^{(A+tZ)^{n-k+1},(A)^k}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, ZY, K_j, \ldots, K_{n-1}).
\end{align*}
The inequality
\begin{align*}
& \| t \left[\Gamma^{(A+tZ)^{n-k+1},(A)^k}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, ZY, K_j, \ldots, K_{n-1}) \|_p \\
& \leq |t| c_{p,n} \|f^{(n)}\|_{\infty} \|K_1\|_p \ldots \|K_{n-1}\|_p \|ZY\|_p
\end{align*}
and the same reasoning as for the case $n-k+2 \leq j \leq n$ show that
$$
\left[\Gamma_k(t)\right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})
$$
converges to $\left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})$.

Finally, assume that $1\leq j \leq n-k$. By Remark $\ref{approximatebdd}$,
\begin{align*}
& \left[\Gamma^{(A+tZ)^{n-k+1},(A)^k}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, [A+tZ,Y], K_j, \ldots, K_{n-1}) \\
& = \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_j, K_{j+1}, \ldots, K_{n-1}) \\
& \ \ \ - \left[\Gamma^{(A+tZ)^{n-k+1},(A)^{k-1}}(f^{[n-1]}) \right](K_1, \ldots, K_{j-1}, YK_{j-1}, K_j, \ldots, K_{n-1}),
\end{align*}
with a simple modification in the case $j=1$ as in Remark $\ref{approximatebdd}$. Note that $[A+tZ,Y] = [A,Y] + t[Z,Y]$ and then reason as in the previous case to show that
$$
\left[\Gamma_k(t)\right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})
$$
goes to $\left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1})$ in $\mathcal{S}^p(\mathcal{H})$ as $t$ goes to $0$.
Hence, we proved that
\begin{align*}
& \underset{t \to 0}{\lim} \ \xi(t) \\
& = n \left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](Z, \ldots, Z) \\
& \ \ \ \ + \sum_{k=1}^n \sum_{j=1}^n \ \sum_{\substack{K_m = i[A,Y] \\\text{or} \ K_m=Z, \\ 1 \leq m \leq n-1}} i \left[ \Gamma^{A, \ldots, A}(f^{[n]}) \right] (K_1, \ldots, K_{j-1}, [A,Y], K_j, \ldots, K_{n-1}) \\
& = n \left[\Gamma^{A,\ldots, A}(f^{[n]}) \right](K, \ldots, K).
\end{align*}
This proves that $\varphi \in D^n(\mathbb{R},\Sc^p(\mbox{${\mathcal H}$}))$ and that for any $1\leq k \leq n$, $\varphi^{(k)}$ is given by \eqref{diffenrential}.

Finally, let $I\subset \mathbb{R}$ be a bounded interval and let $1 \leq i \leq n-1$. We let $J \subset \mathbb{R}$ to be a bounded interval such that, for any $t\in I$, $\sigma(A+tK) \subset J$. There exists $f_i \in C^i(\mathbb{R})$ compactly supported such that $f_i = f$ on $J$. Then for any $t\in I$,
\begin{align*}
\dfrac{1}{k!} \varphi^{(i)}(t)
& = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}((f^{[i]})_{|J^{n+1}}) \right] (K, \ldots, K) \\
& = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f_i^{[i]}) \right] (K, \ldots, K).
\end{align*}



Hence, since $f_i^{(i)}$ is bounded on $\mathbb{R}$, $\varphi^{(i)}$ is bounded on $I$ by Theorem $\ref{BddnessMOI}$. Similarly, since $f^{(n)}$ is bounded on $\mathbb{R}$, $\varphi^{(n)}$ is bounded on $\mathbb{R}$.


By \cite[Theorem 7.18]{KPSS}, $\varphi$ is differentiable on $\mathbb{R}$ and for any $t\in \mathbb{R}$, $\varphi'(t) = \left[\Gamma^{A+tK, A+tK}(f^{[1]}) \right](K).$ 
Assume now that $\varphi$ is $(n-1)$-times differentiable on $\mathbb{R}$ with
$$
\dfrac{\varphi^{(n-1)}(t)}{(n-1)!} = \left[\Gamma^{A+tK, \ldots, A+tK}(f^{[n-1]}) \right](K, \ldots, K).
$$
We will prove that the function
$$
\psi : t\in \mathbb{R} \mapsto \left[\Gamma^{A+tK, \ldots, A+tK}(f^{[n-1]}) \right](K, \ldots, K)
$$
is differentiable in $0$ and that
\begin{equation}\label{unbbproof}
\psi'(0) = n \left[\Gamma^{A, \ldots, A}(f^{[n]}) \right](K, \ldots, K).
\end{equation}


For any $m\geq 1$, let $E_m = \chi_{[-m,m]}(A)$. Then $A_m := AE_m$ is bounded. Note that $(E_m)_{m\geq 1}$ converges strongly to the identity so for any $K\in \mathcal{S}^p(\mathcal{H})$, $K_m:=E_m K E_m$ converges to $K$ in $\mathcal{S}^p(\mathcal{H})$ as $m$ goes to $\infty$. This implies that the set
$$
X_0 = \left\lbrace K_m \ | \ K \in (\mathcal{S}^p(\mathcal{H}))_{\text{sa}}, m\geq 1 \right\rbrace \subset (\mathcal{S}^p(\mathcal{H}))_{\text{sa}}
$$
is dense in $(\mathcal{S}^p(\mathcal{H}))_{\text{sa}}$. Hence, by Lemma $\ref{simplification3}$, we only have to prove \eqref{unbbproof} for $K$ element of $X_0$. Let $K=K_m \in X_0$ for some $m\geq 1$.
By Lemma $\ref{reducbdd}$, we have, for any $t\in \mathbb{R}$,
$$
\psi(t) = \left[\Gamma^{A_m+tK_m, \ldots, A_m+tK_m}(f^{[n-1]}) \right](K_m, \ldots, K_m)
$$
which is, by Theorem $\ref{FormulaSA}$, differentiable in $0$ with
$$
\psi'(0) = n\left[\Gamma^{A_m, \ldots, A_m}(f^{[n]}) \right](K_m, \ldots, K_m).
$$
Using Lemma $\ref{reducbdd}$ again, we see that
$$
\psi'(0) = n\left[\Gamma^{A, \ldots, A}(f^{[n]}) \right](K_m, \ldots, K_m).
$$
This proves that $\varphi \in D^n(\mathbb{R},\Sc^p(\mbox{${\mathcal H}$}))$ and that the derivatives of $\varphi$ are given by \eqref{diffenrentialunbdd}.

Finally, the boundedness of the derivatives follows from Theorem $\ref{BddnessMOI}$.


The existence of the derivatives $\displaystyle \frac{d^k}{dt^k}\Big(f(A+tK)\Big)\Big|_{t=0}, k=1, \ldots, n-1,$ are ensured by Theorem $\ref{FormulaSA}$ and Theorem $\ref{FormulaSAunbdd}$. The representation \eqref{Taylor} can be obtained by induction on $n$, using Theorem $\ref{BddnessMOI}$. See the proof of \cite[Theorem 4.1 (ii)]{CLSS} for more details. From this representation, we obtain the estimate \eqref{Taylorineq} by applying Inequality \eqref{IneqDDn}.


By Theorem $\ref{FormulaSA}$, we know that $\varphi$ is $n$-times differentiable and that for any $t\in \mathbb{R}$,
\begin{equation*}
\dfrac{1}{n!} \varphi^{(n)}(t) = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[n]}) \right] (K, \ldots, K).
\end{equation*}
Hence, to prove the result, we have to show that the mapping
$$
t \in \mathbb{R} \mapsto \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[n]}) \right] (K, \ldots, K) \in \mathcal{S}^p(\mathcal{H})
$$
is continuous. More generally, we will prove that for any $X = (X_1, \ldots, X_n) \in \mathcal{S}^p(\mathcal{H})^n$, the mapping
$$
\varphi_X : t \in \mathbb{R} \mapsto \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[n]}) \right] (X_1, \ldots, X_n) \in \mathcal{S}^p(\mathcal{H})
$$
is continuous. Note that it is sufficient to prove that $\varphi_X$ is continuous in $0$.

Let $h \in C^n(\mathbb{R})$.  Assume that either $A$ is bounded or $h^{(i)}$ is bounded for all $1\leq i\leq n-1$ and further assume that $h^{(n)} \in C_0(\mathbb{R})$. It follows from \cite[Theorem 3.4]{LMS} that $h$ is $n$-times continuously Fr\'echet $\mathcal{S}^p$-differentiable at $A$. This implies that for any $X_1, \ldots, X_n \in \mathcal{S}^p(\mathcal{H})$, the mapping
\begin{equation}\label{casefnC0}
t\in \mathbb{R} \mapsto \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(h^{[n]}) \right] (X_1, \ldots, X_n)
\end{equation}
is continuous in $0$. Hence, if $f^{(n)} \in C_0(\mathbb{R})$, $\varphi \in C^n(\mathbb{R},\Sc^p(\mbox{${\mathcal H}$}))$. The rest of the proof consists in reducing to this particular case.\\

Let $(g_k)_{k\geq 1}$ be a sequence of $C^{\infty}_c(\mathbb{R})$ satisfying the following two properties:
$$
\forall\, k\in\mbox{${\mathbb N}$}, \quad 0\leq g_k\leq 1,
\qquad\hbox{and}\qquad\forall\, r\in \mathbb{R},\quad
g_k(r)\overset{k\to\infty}{\longrightarrow} 1.
$$
Let $k\geq 1$. Define $G_k^n = g_k \otimes \underbrace{1 \otimes \cdots \otimes 1}_{n-1 \ \text{times}} \otimes g_k$ and write
$$
G_k^n(x_1, \ldots, x_n) = h_1(x_1,x_2) h_2(x_{n-1},x_n)
$$
where $h_1 = g_k \otimes 1$ and $h_2 = 1 \otimes g_k$. We have
$$
\left[\Gamma^{A+tK, A+tK}(h_1)\right](X_1) = g_k(A+tK) X_1
$$
and
$$\left[\Gamma^{A+tK, A+tK}(h_2)\right](X_n) = X_n g_k(A+tK).
$$
Hence, by Lemma $\ref{simplification1}$, the function
$$
\varphi_{k,X}^n : t \in \mathbb{R} \mapsto \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[n]}G_k^n) \right] (X_1, \ldots, X_n) \in \mathcal{S}^p(\mathcal{H})
$$
satisfies, for any $t\in \mathbb{R}$,
$$
\varphi_{k,X}^n(t) = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[n]}) \right](g_k(A+tK) X_1, X_2, \ldots, X_{n-1}, X_n g_k(A+tK)).
$$
$(g_k)_{k\geq 1}$ is bounded and pointwise convergent to $1$ so $(g_k(A))_{k\geq 1}$ converges strongly to the identity of $\mathcal{H}$ and hence $g_k(A) X_1 \to X_1$ and $X_n g_k(A) \to X_n$ in $\mathcal{S}^p(\mathcal{H})$ as $k\to \infty$. Moreover, it follows from the arguments of the proof of \cite[Lemma 3.4]{CLSS} that $A + tK \to A$ resolvent strongly as $t \to 0$. This means that for any $u \in C_b(\mathbb{R})$,
$$
u(A+tK) \underset{t \to 0}{\longrightarrow} u(A) \ \ \text{strongly}.
$$
For any $k\geq 1, g_k \in C_b(\mathbb{R})$ so $g_k(A+tK) \to g_k(A)$ strongly as $t \to 0$, which implies that $g_k(A+tK) X_1 \to g_k(A) X_1$ and $X_n g_k(A+tK) \to X_n g_k(A)$ in $\mathcal{S}^p(\mathcal{H})$ as $t\to 0$.

Let $\epsilon > 0$. By the latter, there exists $k_0 \in \mathbb{N}$ such that, for any $k\geq k_0$,
$$
\| X_1 - g_{k_0}(A) K\|_p \leq \epsilon \ \ \text{and} \ \ \| X_n - X_n g_{k_0}(A) \|_p \leq \epsilon
$$
and there exists $t_0 > 0$ such that for any $|t| \leq t_0$,
$$
\| g_{k_0}(A)X_1 - g_{k_0}(A+tK) X_1\|_p \leq \epsilon \ \ \text{and} \ \ \| X_n g_{k_0}(A) - X_n g_{k_0}(A+tK) \|_p \leq \epsilon.
$$
Hence, for any $|t| \leq t_0$,
\begin{align*}
& \| X_1 - g_{k_0}(A+tK) X_1\|_p \\
& \leq \| X_1 - g_{k_0}(A) X_1\|_p + \| g_{k_0}(A)X_1 - g_{k_0}(A+tK) X_1\|_p \\
& \leq 2 \epsilon,
\end{align*}
and similarly,
$$
\| X_n - X_n g_{k_0}(A+tK) \|_p \leq 2\epsilon.
$$
By Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $C > 0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $|t| < t_0$,
$$
\| \varphi_X(t) - \varphi_{k_0,X}^n(t) \|_p \leq C \epsilon.
$$
By the triangle inequality we get that for any $|t| < t_0$,
\begin{align*}
& \| \varphi_X(t) - \varphi_X(0) \|_p \\
& \leq \| \varphi_X(t) - \varphi_{k_0,X}^n(t) \|_p + \|\varphi_{k_0,X}^n(t) - \varphi_{k_0,X}^n(0) \|_p + \| \varphi_{k_0,X}^n(0) - \varphi_X(0)\|_p \\
& \leq 2C \epsilon + \|\varphi_{k_0,X}^n(t) - \varphi_{k_0,X}^n(0) \|_p.
\end{align*}
Hence, to prove the result, it suffices to prove that for any $k\geq 1$ and any $X \in \mathcal{S}^p(\mathcal{H})^n, \varphi_{k,X}^n$ is continuous in $0$.\\

Fix $k\geq 1$ and let $g = g_k$. We will prove the continuity of $\varphi_{k,X}^n$ in $0$ by induction on $n$. For $n=1$, we have, for any $(x_0,x_1)\in \mathbb{R}^2$ with $x_0 \neq x_1$,
\begin{align}\label{calculsn1}
\begin{split}
f^{[1]}(x_0,x_1)g(x_0)g(x_1)
& = \dfrac{g(x_1)(gf)(x_0) - (gf)(x_1) g(x_0)}{x_0 - x_1} \\
& = \dfrac{g(x_1)(gf)(x_0) - g(x_1)(gf)(x_1)}{x_0 - x_1} \\
& \ \ \ \ + \dfrac{(gf)(x_1)g(x_1) - (gf)(x_1) g(x_0)}{x_0 - x_1} \\
& = g(x_1) (gf)^{[1]}(x_0,x_1) - (gf)(x_1)g^{[1]}(x_0,x_1).
\end{split}
\end{align}
By continuity, this equality holds true for any $x_0,x_1 \in \mathbb{R}$. Hence, by Lemma $\ref{simplification1}$, we have, for any $t\in \mathbb{R}$ and any $X\in \mathcal{S}^p(\mathcal{H})$,
\begin{align*}
& \varphi_{k,X}^1(t) \\
& = \left[ \Gamma^{A+tK, A+tK}((gf)^{[1]}) \right](Xg(A+tK)) - \left[ \Gamma^{A+tK, A+tK}(g^{[1]}) \right](X(gf)(A+tK)).
\end{align*}

As explained in the first part of the proof, the mappings $t\in \mathbb{R} \mapsto Xg(A+tK) \in \mathcal{S}^p(\mathcal{H})$ and $t\in \mathbb{R} \mapsto X(gf)(A+tK) \in \mathcal{S}^p(\mathcal{H})$ are continuous in $0$. Note that $g', (gf)' \in C_0(\mathbb{R})$ so that, by continuity of the map defined in \eqref{casefnC0} and the uniform boundedness of the mappings $\Gamma^{A+tK, A+tK}((gf)^{[1]}), \Gamma^{A+tK, A+tK}(g^{[1]}), t\in \mathbb{R}$, we get that
\begin{align*}
\underset{t\to 0}{\lim} ~ \varphi_{k,X}^1(t) = \left[ \Gamma^{A, A}((gf)^{[1]}) \right](Xg(A)) - \left[ \Gamma^{A, A}(g^{[1]}) \right](X(gf)(A)) = \varphi_{k,X}^1(0),
\end{align*}
so that $\varphi_{k,X}^1$ is continuous in $0$.

Now, let $n\geq 2$ and assume that for any $1\leq i \leq n-1$ and any $X=(X_1,\ldots, X_{i}) \in \mathcal{S}^p(\mathcal{H})^i$, $\varphi_{k,X}^{i}$ is continuous in $0$. First, we show by induction the following formula: for every $(x_0,\ldots,x_n) \in \mathbb{R}^{n+1}$,
\begin{align}\label{recfng}
\begin{split}
& f^{[n]}(x_0, \ldots, x_n)g(x_0) \\
& = (gf)^{[n]}(x_0, \ldots, x_n) - f(x_n) g^{[n]}(x_0,\ldots, x_n) - \sum_{l=1}^{n-1} g^{[l]}(x_0, \ldots, x_l)f^{[n-l]}(x_{l} ,\ldots, x_n).
\end{split}
\end{align}
For $n=2$, first note that the computations made in \eqref{calculsn1} give
$$
f^{[1]}(x_0,x_1)g(x_0) = (gf)^{[1]}(x_0,x_1) - f(x_1)g^{[1]}(x_0,x_1)
$$
so that
\begin{align*}
& f^{[2]}(x_0,x_1,x_2)g(x_0) \\
& = \dfrac{f^{[1]}(x_0,x_2)g(x_0) - f^{[1]}(x_1,x_2)g(x_1)}{x_0-x_1} + \dfrac{f^{[1]}(x_1,x_2)g(x_1) - f^{[1]}(x_1,x_2)g(x_0)}{x_0-x_1} \\
& = \dfrac{(gf)^{[1]}(x_0,x_2) - f(x_2)g^{[1]}(x_0,x_2) - (gf)^{[1]}(x_1,x_2) + f(x_2)g^{[1]}(x_1,x_2)}{x_0-x_1} \\
& \ \ \ \ - g^{[1]}(x_0,x_1)f^{[1]}(x_1,x_2) \\
& = (gf)^{[2]}(x_0,x_1,x_2) - f(x_2) g^{[2]}(x_0,x_1,x_2) - g^{[1]}(x_0,x_1)f^{[1]}(x_1,x_2),
\end{align*}
which shows \eqref{recfng} for $n=2$. Assume now that we have \eqref{recfng} at the order $n$ and show that it still holds true at the order $n+1$. We have
\begin{align}\label{recu1}
\begin{split}
& f^{[n+1]}(x_0,\ldots, x_{n+1})g(x_0) \\
& = \dfrac{f^{[n]}(x_0, x_2, \ldots, x_{n+1})g(x_0) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_1)}{x_0-x_1} \\
& \ \ \ \ + \dfrac{f^{[n]}(x_1,\ldots, x_{n+1})g(x_1) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_0)}{x_0-x_1} \\
& = \dfrac{f^{[n]}(x_0, x_2, \ldots, x_{n+1})g(x_0) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_1)}{x_0-x_1} \\
& \ \ \ \ - g^{[1]}(x_0,x_1) f^{[n]}(x_1,\ldots, x_{n+1}).
\end{split}
\end{align}
By assumption, we have
\begin{align}\label{recu2}
\begin{split}
& \dfrac{f^{[n]}(x_0, x_2, \ldots, x_{n+1})g(x_0) - f^{[n]}(x_1,\ldots, x_{n+1})g(x_1)}{x_0-x_1} \\
& = \dfrac{(gf)^{[n]}(x_0, x_2, \ldots, x_{n+1}) - (gf)^{[n]}(x_1, \ldots, x_{n+1})}{x_0-x_1} \\
& \ \ \ \ - f(x_{n+1}) \dfrac{g^{[n]}(x_0,x_2,\ldots, x_{n+1}) - g^{[n]}(x_1,\ldots, x_{n+1})}{x_0-x_1} \\
& \ \ \ \ - \sum_{l=1}^{n-1} \dfrac{g^{[l]}(x_0,x_2, \ldots, x_{l+1})-g^{[l]}(x_1, \ldots, x_{l+1})}{x_0-x_1}f^{[n-l]}(x_{l+1} ,\ldots, x_{n+1}) \\
& = (gf)^{[n+1]}(x_0, \ldots, x_{n+1}) - f(x_{n+1}) g^{[n+1]}(x_0,\ldots, x_{n+1}) \\
& \ \ \ \ - \sum_{l=1}^{n-1} g^{[l+1]}(x_0, \ldots, x_{l+1}) f^{[n-l]}(x_{l+1} ,\ldots, x_{n+1}).
\end{split}
\end{align}
We have
\begin{align*}
& \sum_{l=1}^{n-1} g^{[l+1]}(x_0, \ldots, x_{l+1}) f^{[n-l]}(x_{l+1} ,\ldots, x_{n+1}) + g^{[1]}(x_0,x_1) f^{[n]}(x_1,\ldots, x_{n+1}) \\
& = \sum_{j=2}^{n} g^{[j]}(x_0, \ldots, x_j) f^{[n+1-j]}(x_j ,\ldots, x_{n+1}) + g^{[1]}(x_0,x_1) f^{[n]}(x_1,\ldots, x_{n+1}) \\
& = \sum_{j=1}^{n} g^{[j]}(x_0, \ldots, x_j) f^{[n+1-j]}(x_j ,\ldots, x_{n+1}).
\end{align*}
Hence, by \eqref{recu1} and \eqref{recu2}, Formula \eqref{recfng} is proved at the order $n+1$. Note that the previous computations make sense when $x_0 \neq x_1$ and by continuity, the formula also holds true for $x_0 = x_1$. Let $(x_0, \ldots, x_n)\in \mathbb{R}^{n+1}$. We multiply Formula \eqref{recfng} by $g(x_n)$ and we get
\begin{align*}
f^{[n]}G_k^n(x_0, \ldots, x_n) 
& = g(x_n)(gf)^{[n]}(x_0, \ldots, x_n) - (gf)(x_n) g^{[n]}(x_0,\ldots, x_n) \\
& \ \ \ - g(x_n)\sum_{l=1}^{n-1} g^{[l]}(x_0, \ldots, x_l)f^{[n-l]}(x_{l} ,\ldots, x_n).
\end{align*}
Let $X_1, \ldots, X_n \in \mathcal{S}^p(\mathcal{H})$. Applying the operator
$$
\left[\Gamma^{A+tK, \ldots, A+tK}(\cdot)\right](X_1,\ldots, X_n)
$$
to the previous equality gives, by Lemma $\ref{simplification1}$ and Lemma $\ref{simplificationsep}$,
\begin{align*}
\varphi_{k,X}^n(t) = \varphi_1(t) - \varphi_2(t) - \sum_{l=1}^{n-1} \varphi_{3,l}(t)
\end{align*}
where
$$
\varphi_1(t) = \left[\Gamma^{A+tK, \ldots, A+tK}((gf)^{[n]})\right](X_1,\ldots, X_{n-1}, X_ng(A+tK)),
$$
$$
\varphi_2(t) = \left[\Gamma^{A+tK, \ldots, A+tK}(g^{[n]})\right](X_1,\ldots, X_{n-1}, X_n (gf)(A+tK)),
$$
and for any $1\leq l \leq n-1$,
$$
\varphi_{3,l}(t) = \varphi_{3,l}^1(t)\varphi_{3,l}^2(t)
$$
with 
$$
\varphi_{3,l}^1(t) = \left[\Gamma^{A+tK, \ldots, A+tK}(g^{[l]})\right](X_1,\ldots,X_{l})
$$
and
$$\varphi_{3,l}^2(t) = \left[\Gamma^{A+tK, \ldots, A+tK}(f^{[n-l]})\right](X_{l+1},\ldots, X_{n-1}, X_n g(A+tK)).
$$
The functions $g$ and $gf$ belong to $C_b(\mathbb{R})$ so the mappings $t \in \mathbb{R} \mapsto X_ng(A+tK) \in \mathcal{S}^p(\mathcal{H})$ and $t \in \mathbb{R} \mapsto X_n (gf)(A+tK) \in \mathcal{S}^p(\mathcal{H})$ are continuous in $0$. We have $(gf)^{(n)}, g^{(n)} \in C_0(\mathbb{R})$ so by the continuity of the map defined in \eqref{casefnC0}, we get that $\varphi_1$ and $\varphi_2$ are continuous in $0$.

Now let $1 \leq l \leq n-1$. Since $g^{(l)} \in C_0(\mathbb{R})$, $\varphi_{3,l}^1$ is continuous in $0$. We have $1 \leq n-l \leq n-1$, and by assumption, $\varphi_{k,Y}^{n-l}$ is continuous in $0$ for any $Y \in \mathcal{S}^p(\mathcal{H})^l$. Hence, by composition with the continuous map $t \in \mathbb{R} \mapsto X_ng(A+tK) \in \mathcal{S}^p(\mathcal{H})$, we get that $\varphi_{3,l}^2$ is continuous in $0$, so that $\varphi_{3,l}$ also is. We hence proved that $\varphi_{k,X}$ is continuous in $0$, which concludes the proof of the proposition.

proposition:
\label{simplification0}
Let $1 < p < \infty$, $n \in \mathbb{N}, n \geq 2$. Let $A_1, \ldots, A_{n-1}, A, B$ be selfadjoint operators in $\mathcal{H}$ such that $B-A \in \mathcal{S}^p(\mathcal{H})$. Let $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n-1)}$ and $f^{(n)}$ are bounded. Then, for any $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$ and any $1 \leq j \leq n$ we have
\begin{align*}
& \left[ \Gamma^{A_1, \ldots A_{j-1}, B, A_j, \ldots, A_{n-1}}(f^{[n-1]}) - \Gamma^{A_1, \ldots A_{j-1}, A, A_j, \ldots, A_{n-1}}(f^{[n-1]})\right] (K_1, \ldots, K_{n-1}) \\
& \ = \left[ \Gamma^{A_1, \ldots, A_{j-1}, B, A, A_j, \ldots, A_{n-1}}(f^{[n]})\right](K_1, \ldots, K_{j-1}, B-A, K_j, \ldots K_{n-1}).
\end{align*}
\label{Taylorrmd}
Let $1 < p < \infty$, $n \in\mbox{${\mathbb N}$}, n\geq 2$, $A$ and $K$ be selfadjoint operators in $\mathcal{H}$ with $K\in \mathcal{S}^{np}(\mathcal{H})$. Let $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n)}$ is bounded. Assume that either $A$ is bounded or $f^{(i)}$ is bounded for all $1\leq i \leq n$. Denote
$$
R_{n,p,A,K,f} = f(A+K)-f(A) - \sum_{k=1}^{n-1} \dfrac{1}{k!} \frac{d^k}{dt^k}\Big(f(A+tK)\Big)\Big|_{t=0}.
$$
Then,
\begin{equation}\label{Taylor}
R_{n,p,A,K,f} = \left[ \Gamma^{A+K, A, \ldots, A}(f^{[n]}) \right] (K, \ldots, K),
\end{equation}
and we have the inequality
\begin{equation}\label{Taylorineq}
\|R_{n,p,A,K,f}\|_p \leq c_{p,n} \|f^{(n)}\|_{\infty} \|K\|_{np}^n.
\end{equation}
\label{Contcase}
Let $1 < p < \infty$, let $A$ and $K$ be selfadjoint operators in $\mathcal{H}$ with $K\in \mathcal{S}^p(\mathcal{H})$. Let $n \in\mbox{${\mathbb N}$}$ and $f\in C^n(\mathbb{R})$.  Assume that either $A$ is bounded or $f^{(i)}$ is bounded for all $1\leq i\leq n$. Consider the function
$$\varphi : t\in \mathbb{R} \mapsto f(A+tK) - f(A) \in \mathcal{S}^p(\mathcal{H}).$$
Then $\varphi$ belongs to $C^n(\mathbb{R},\Sc^p(\mbox{${\mathcal H}$} ))$ and for every integer $1 \leq k \leq n$ and $t\in \mathbb{R}$,
\begin{equation*}
\dfrac{1}{k!} \varphi^{(k)}(t) = \left[ \Gamma^{A+tK, A+tK, \ldots, A+tK}(f^{[k]}) \right] (K, \ldots, K).
\end{equation*}
It is well-known that $f^{[n]}$ is symmetric under permutation of its arguments. Therefore, for all $1 \leq i \leq n$ and for all $x_0, \ldots, x_n \in \mathbb{R}$,
\begin{align*}
&f^{[n]} (x_0,x_1,\ldots,x_n) \\
& \ \ \ \ = \dfrac{f^{[n-1]}(x_0,\ldots,x_{i-1}, x_{i+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{i-2}. x_{i},x_{i+1},\ldots,x_n)}{x_{i-1}-x_i}
\end{align*}
 if $x_{i-1} \neq x_i$ and
$$
f^{[n]} (x_0,x_1,\ldots,x_n) = \partial_i f^{[n-1]}(x_1,\ldots,x_n)
$$
if $x_{i-1}=x_i.$

claim:
Auxiliary lemmas
\label{SubAux}


In this subsection, we will prove important technical lemmas that will be used in Section $\ref{ProofofMR}$. 


\begin{lemma}\label{MOIcomm}
Let $1 < p < \infty$, $n \in \mathbb{N}, n \geq 1$. Let $A \in \mathcal{B}(\mathcal{H})$ be a selfadjoint operator and let $Z_1, \ldots, Z_n \in \mathcal{S}^p(\mathcal{H})$ be such that $A$ and $Z_i$ commute, for every $1\leq i\leq n$. Let $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n)}$ is bounded. Then
$$
\left[ \Gamma^{A, \ldots, A}(f^{[n]}) \right] (Z_1, \ldots, Z_n) = \dfrac{1}{n!} f^{(n)}(A)Z_1\ldots Z_n.
$$
\end{lemma}

\begin{proof}
In this proof, we will use the notation introduced before the statement of Theorem $\ref{BddnessMOI}$. For any $k\geq 1$, we let $\psi_k := \varphi_{n,g_k}$ to be the function defined as in the proof of Theorem $\ref{BddnessMOI}$. For any bounded Borel function $g$, we let $\tilde{g}$ to be the function defined on $\mathbb{R}$ by $\tilde{g}_k(x) = g(x, \ldots, x), x\in \mathbb{R}$. Let us prove first that for any $k\geq 1$,
$$
\left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) = \tilde{\psi}_k(A)Z_1\ldots Z_n.
$$
Fix $k\geq 1$. $A$ is bounded so $\sigma(A) \subset \mathbb{R}$ is bounded and by definition,
$$\Gamma^{A, \ldots, A}(\psi_k) = \Gamma^{A, \ldots, A}(\phi_k)$$
where $\phi_k$ is the class in $L^{\infty}(\lambda_A \times \cdots \times \lambda_A)$ of the restriction of $\psi_k$ to $\sigma(A)^{n+1}$. $g_k$ is continuous on the compact $I= \text{conv}(\sigma(A))$ so there exists a sequence $(P^k_j)_{j\geq 1}$ of polynomial functions converging uniformly to $g_k$ on $I$. For any $j\geq 1$, define $Q^k_j = \varphi_{n, P^k_j}$. It is easy to see that $(Q^k_j)_{j\geq 1}$ converges uniformly to $\psi_k$ on $\sigma(A)^{n+1}$. According to \eqref{DDint}, $Q^k_j = (R^k_j)^{[n]}$ where $R^k_j$ is a polynomial function on $\mathbb{R}$ such that $(R^k_j)^{(n)} = P^k_j$. Hence $Q^k_j$ is a $(n+1)$-variable polynomial function, and in particular, $Q^k_j \in \text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$. Note that for an elementary tensor $g = g_1 \otimes \cdots \otimes g_{n+1} \in \text{Bor}(\mathbb{R}) \otimes \cdots \otimes \text{Bor}(\mathbb{R})$, we have
\begin{align*}
\left[ \Gamma^{A, \ldots, A}(g) \right] (Z_1, \ldots, Z_n)
& = g_1(A)Z_1g_2(A)\ldots g_n(A)Z_ng_{n+1}(A) \\
& = g_1(A)\ldots g_{n+1}(A) Z_1 \ldots Z_n \\
& = \tilde{g}(A) Z_1 \ldots Z_n.
\end{align*}
By linearity, this implies that for any $j \geq 1$,
\begin{equation}\label{eqcomm0}
\left[ \Gamma^{A, \ldots, A}(Q^k_j) \right] (Z_1, \ldots, Z_n) = \tilde{Q}^k_j(A)Z_1\ldots Z_n.
\end{equation}
For any $j\geq 1$, we let $v^k_j \in \text{Bor}(\mathbb{R})$ be such that $v^k_j = P^k_j$ on $I$ and  $v^k_j \to g_k$ uniformly on $\mathbb{R}$. Then
$$
\Gamma^{A, \ldots, A}(\varphi_{n, P^k_j}) = \Gamma^{A, \ldots, A}(\varphi_{n, v^k_j})
$$
and by Theorem $\ref{BddnessMOI}$, there exists a constant $c_{p,n}$ such that
\begin{align*}
& \| \left[ \Gamma^{A, \ldots, A}(Q^k_j) \right] (Z_1, \ldots, Z_n) - \left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) \|_p \\
& = \| \left[ \Gamma^{A, \ldots, A}(\varphi_{n, v^k_j} - \varphi_{n, g_k}) \right] (Z_1, \ldots, Z_n) \|_p \\
& \leq c_{p,n} \| v^k_j - g_k\|_{\infty} \|Z_1\|_p \cdots \|Z_n\|_p \\
& \underset{j\to \infty}{\longrightarrow} 0.
\end{align*}
Note that $(\tilde{Q}^k_j)_{j\geq 1}$ converges uniformly to $\tilde{\phi}_k$ on $\sigma(A)$. Hence, $\tilde{Q}^k_j(A)$ converges to $\tilde{\psi}_k(A)$ in $\mathcal{B}(\mathcal{H})$ so that the right-hand side of \eqref{eqcomm0} converges in $\mathcal{S}^p(\mathcal{H})$ to $\tilde{\psi}_k(A)Z_1\ldots Z_n$. By taking the limit on $j$ in \eqref{eqcomm0} we get
\begin{equation}\label{eqcomm}
\left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) = \tilde{\psi}_k(A)Z_1\ldots Z_n.
\end{equation}
Recall that, from the proof of Theorem $\ref{BddnessMOI}$, the sequence $(\psi_k)_{k\geq 1}$ $w^*$-converges to $f^{[n]}$ for the $w^*$-topology of $L^{\infty}(\lambda_A \times \cdots \times \lambda_A)$ and that $(\Gamma^{A, \ldots, A}(\psi_k))_{k\geq 1} \subset \mathcal{B}_n(\mathcal{S}^p(\mathcal{H}))$ is bounded. Hence, by Lemma $\ref{LemmeUB}$,
$$
\left[ \Gamma^{A, \ldots, A}(\psi_k) \right] (Z_1, \ldots, Z_n) \underset{k \to \infty}{\longrightarrow} \left[ \Gamma^{A, \ldots, A}(f^{[n]}) \right] (Z_1, \ldots, Z_n)
$$
weakly in $\mathcal{S}^p(\mathcal{H})$. On the other hand, $(\tilde{\psi}_k)_{k\geq 1}$ is bounded and is pointwise convergent to $\tilde{f}^{[n]}=\dfrac{1}{n!}f^{(n)}$ so $(\tilde{\psi}_k(A))_{k\geq 1}$ converges strongly to $\dfrac{1}{n!} f^{(n)}(A)$ (see e.g. the proof of \cite[Proposition 3.1]{CLSS}). This implies that the right-hand side of \eqref{eqcomm} converges in $\mathcal{S}^p(\mathcal{H})$ to $\dfrac{1}{n!} f^{(n)}(A)Z_1\ldots Z_n.$ We conclude the proof by taking the limit on $k$ in \eqref{eqcomm}, in the weak topology of $\mathcal{S}^p(\mathcal{H})$.

\end{proof}


From now on, we will adopt the following notation: if $X$ is an operator on $\mathcal{H}$, then for any integer $k$, we denote by $(X)^{k}$ the tuple consisting of $k$ copies of $X$.


\begin{lemma}\label{simplification5}
Let $1 < p < \infty$, $n\in\mathbb{N}, n\geq 2$. Let $A, K$ be selfadjoint operators in $\mathcal{H}$ with $K\in \mathcal{S}^p(\mathcal{H})$ and let $X_1, \ldots, X_{n-1} \in \mathcal{S}^p(\mathcal{H})$. Let $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n)}$ is bounded. Assume that either $A$ is bounded or $f^{(n-1)}$ is bounded. Let $1 \leq j \leq n$. Define $\psi : t\in \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ by
$$
\psi(t) = \left[ \Gamma^{(A+tK)^j, (A)^{n-j}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}), t\in \mathbb{R}.
$$
Then we have, for any $t\in \mathbb{R}$,
\begin{align}\label{simplification5eq}
\begin{split}
& \psi(t) - \psi(0) \\
& \ \ \ \ = t \sum_{k=1}^{j} \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k}}(f^{[n]}) \right](X_1, \ldots, X_{j-k}, K, X_{j-k+1}, \ldots, X_{n-1}).
\end{split}
\end{align}
In particular, $\psi$ is continuous in $0$.
\end{lemma}


\begin{proof}
We have the following decomposition
\begin{align*}
&\psi(t) - \psi(0) \\
& = \sum_{k=1}^j \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k-1}}(f^{[n-1]}) - \Gamma^{(A+tK)^{j-k},(A)^{n-j+k}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}).
\end{align*}
For any $1\leq k\leq j$, we have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k-1}}(f^{[n-1]}) - \Gamma^{(A+tK)^{j-k},(A)^{n-j+k}}(f^{[n-1]}) \right](X_1, \ldots, X_{n-1}) \\
& = t \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k}}(f^{[n]}) \right](X_1, \ldots, X_{j-k}, K, X_{j-k+1}, \ldots, X_{n-1}),
\end{align*}
from which we deduce \eqref{simplification5eq}.

For the continuity of $\psi$ in $0$, note that by Theorem $\ref{BddnessMOI}$ there exists a constant $c_{p,n} > 0$ such that
\begin{align*}
& \| \psi(t) - \psi(0) \|_p \\
& \leq |t| \sum_{k=1}^{j} \| \left[ \Gamma^{(A+tK)^{j-k+1},(A)^{n-j+k}}(f^{[n]}) \right](X_1, \ldots, X_{j-k}, K, X_{j-k+1}, \ldots, X_{n-1}) \|_p \\
& \leq |t| j c_{p,n} \|f^{(n)} \|_{\infty} \|K\|_p \prod_{i=1}^{n-1} \| X_i \|_p,
\end{align*}
which converges to $0$ as $t$ goes to $0$.

\end{proof}



\begin{lemma}\label{simplification3}
Let $1 < p < \infty$, $n \in\mbox{${\mathbb N}$}, n\geq 2$. Let $A$ be a selfadjoint operator in $\mathcal{H}$ and $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n)}$ is bounded. Assume that either $A$ is bounded or $f^{(n-1)}$ is bounded. Let $X_0 \subset (\mathcal{S}^p(\mathcal{H}))_{\text{sa}}$ be a dense subset. Assume that for any $K_0 \in X_0$, the map $\psi_0 : t\in \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ defined by
$$
\psi_0(t) = \left[ \Gamma^{A+tK_0,\ldots,A+tK_0}(f^{[n-1]}) \right](K_0, \ldots, K_0), t\in \mathbb{R},
$$
is differentiable in $0$ with
$$
\psi_0'(0) = n \left[ \Gamma^{A,\ldots,A}(f^{[n]}) \right](K_0, \ldots, K_0).
$$
Let $K \in \mathcal{S}^p(\mathcal{H})$ selfadjoint and define $\psi : t\in \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ by
$$
\psi(t) = \left[ \Gamma^{A+tK,\ldots,A+tK}(f^{[n-1]}) \right](K, \ldots, K), t\in \mathbb{R}.
$$
Then $\psi$ is differentiable in $0$ and
$$
\psi'(0) = n \left[ \Gamma^{A,\ldots,A}(f^{[n]}) \right](K, \ldots, K).
$$
\end{lemma}


\begin{proof}
Let $K\in \mathcal{S}^p(\mathcal{H})$ selfadjoint and show that $\psi$ is differentiable in $0$ with
$$
\psi'(0) = n \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K).
$$
Let $\epsilon > 0$ and choose $K_0 \in X_0$ such that $\|K-K_0\|_p \leq \epsilon$. By assumption, $\psi_0$ is differentiable in $0$ and
$$
\psi_0'(0) = n \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0).
$$
Hence, there exists $\mu > 0$ such that for any $|t| < \mu$,
\begin{equation}\label{psiepsilon0}
\|\psi_0(t) - \psi_0(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \leq |t| \epsilon.
\end{equation}
Define $\tilde{\psi} : \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ by
$$
\tilde{\psi}(t) = \left[\Gamma^{A+tK_0, \ldots A+tK_0}(f^{[n-1]}) \right](K, \ldots, K), t\in \mathbb{R}.
$$
By Lemma $\ref{simplification5}$ we have
\begin{align*}
\tilde{\psi}(t) - \tilde{\psi}(0)
& = t \sum_{k=1}^n \left[ \Gamma^{(A+tK_0)^{n-k+1},(A)^k}(f^{[n]}) \right]((K)^{n-k}, K_0, (K)^{k-1}) \\
& = t \sum_{k=1}^n \left[ \Gamma^{(A+tK_0)^{n-k+1},(A)^k}(f^{[n]}) \right](K_0, \ldots, K_0) + t\psi_{\epsilon}(t) \\
& = \psi_0(t) - \psi_0(0) + t\psi_{\epsilon}(t)
\end{align*}
where
$$
\psi_{\epsilon}(t) = \sum_{k=1}^n \left( \Gamma_{A,K_0,k,t}((K)^{n-k}, K_0, (K)^{k-1}) - \Gamma_{A,K_0,k,t}(K_0,\ldots,K_0) \right).
$$
with $\Gamma_{A,K_0,k,t} = \Gamma^{(A+tK_0)^{n-k+1},(A)^k}(f^{[n]})$.
By Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\alpha > 0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that for any $1 \leq k \leq n$ and any $t\in \mathbb{R}$, 
$$
\| \Gamma_{A,K_0,k,t}((K)^{n-k}, K_0, (K)^{k-1}) - \Gamma_{A,K_0,k,t}(K_0, \ldots, K_0) \|_p \leq \alpha \epsilon
$$
so that we have the estimate $\| \psi_{\epsilon}(t) \| \leq n \alpha \epsilon.$ By the estimate \eqref{psiepsilon0} and triangle inequality, we deduce that for any $|t| < \mu$,
\begin{align}\label{psiepsilon4}
\begin{split}
& \| \tilde{\psi}(t) - \tilde{\psi}(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \\
& \leq \| \psi_0(t) - \psi_0(0)  - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p + |t| \| \psi_{\epsilon}(t) \|_p \\
& \leq |t| \epsilon (n\alpha + 1).
\end{split}
\end{align}

By Lemma $\ref{simplification5}$ we have
\begin{align*}
\psi(t) - \tilde{\psi}(t) = t \sum_{k=1}^{n} \left[ \Gamma^{(A+tK)^{n-k+1}, (A+tK_0)^k}(f^{[n]})\right]((K)^{n-k}, K-K_0, (K)^{k-1}).
\end{align*}
Hence, by Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\beta>0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $t\in \mathbb{R}$
\begin{equation}\label{psiepsilon2}
\| \psi(t) - \tilde{\psi}(t) \|_p \leq n \beta |t| \epsilon.
\end{equation}

Let also $\gamma>0$ be a constant depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that
\begin{equation}\label{psiepsilon3}
\| \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) - \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) \|_p \leq \gamma \epsilon.
\end{equation}

Finally, by triangle inequality and noting that $\psi(0) = \tilde{\psi}(0)$ we have, by \eqref{psiepsilon2}, \eqref{psiepsilon4} and \eqref{psiepsilon3}, 
\begin{align*}
& \| \psi(t) - \psi(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) \|_p \\
& \leq \| \psi(t) - \tilde{\psi}(t)\|_p \\
& \ \ \ \ + \| \tilde{\psi}(t) - \tilde{\psi}(0) - n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0)\|_p \\
& \ \ \ \ + \| n t \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K_0, \ldots, K_0) - nt \left[\Gamma^{A, \ldots A}(f^{[n]}) \right](K, \ldots, K) \|_p \\
& \leq |t| \epsilon (n\beta + n\alpha + n\gamma  + 1),
\end{align*}
for any $|t| < \mu$. This concludes the proof.

\end{proof}


\begin{lemma}\label{simplification4}
Let $1 < p < \infty$, let $A \in \mathcal{B}(\mathcal{H})$ be a selfadjoint operator on $\mathcal{H}$ and let $K=K^* \in \mathcal{S}^p(\mathcal{H})$. Let $n\geq 2$ and let $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n)}$ is bounded. Let $\nu : \mathbb{R} \to (\mathcal{B}(\mathcal{H}))_{\text{sa}}$ be such that $\nu(0)=A$ and $\nu$ is $\mathcal{S}^p$-differentiable in $0$ with $\nu'(0)=K$. Define $\psi, \tilde{\psi} : \mathbb{R} \to \mathcal{S}^p(\mathcal{H})$ by
$$
\psi(t) = \left[ \Gamma^{A+tK,\ldots,A+tK}(f^{[n-1]}) \right](K, \ldots, K), t\in \mathbb{R},
$$
and
$$
\tilde{\psi}(t) = \left[ \Gamma^{\nu(t),\ldots,\nu(t)}(f^{[n-1]}) \right](K, \ldots, K), t\in \mathbb{R}.
$$
If $\tilde{\psi}$ is differentiable in $0$, then $\psi$ is also differentiable in $0$ and $\psi'(0) = \tilde{\psi}'(0)$.
\end{lemma}

\begin{proof}
Let $\epsilon > 0$. By assumption, there exists $\mu_1 > 0$ such that for any $|t| < \mu_1$,
\begin{equation}\label{nu1}
\| \tilde{\psi}(t) - \tilde{\psi}(0) - t \tilde{\psi}'(0) \|_p \leq |t| \epsilon.
\end{equation}
Moreover, $\nu(0)=A$ and $\nu'(0) = K$ in $\mathcal{S}^p(\mathcal{H})$, so there exists $\mu_2 > 0$ such that for any $|t| < \mu_2$,
\begin{equation*}
\left\| \frac{(A+tK) - \mu(t)}{t} \right\|_p = \left\| \frac{\mu(t)-A}{t} -K \right\|_p \leq \epsilon.
\end{equation*}
We have, by Proposition $\ref{simplification0}$,
\begin{align*}
& \dfrac{\psi(t) - \tilde{\psi}(t)}{t}  \\
& = \dfrac{1}{t} \sum_{k=1}^n \left[ \Gamma^{(A+tK)^{n-k+1}, (\nu(t))^{k-1}}(f^{[n-1]})-\Gamma^{(A+tK)^{n-k}, (\nu(t))^k}(f^{[n-1]}) \right](K, \ldots, K) \\
& = \sum_{k=1}^{n} \left[ \Gamma^{(A+tK)^{n-k+1}, (\nu(t))^k}(f^{[n]})\right]\left( (K)^{n-k}, \frac{(A+tK) - \mu(t)}{t} , (K)^{k-1} \right).
\end{align*}
Hence, by Remark $\ref{Ineqmulti}$ and Theorem $\ref{BddnessMOI}$, there exists a constant $\alpha > 0$ depending only on $p, n, \|f^{(n)}\|_{\infty}$ and $\|K\|_p$ such that, for any $t\in \mathbb{R}$,
\begin{equation}\label{nu2}
\| \psi(t) - \tilde{\psi}(t) \|_p \leq |t| n \alpha \epsilon.
\end{equation}
Finally, by \eqref{nu1} and \eqref{nu2} and by triangle inequality we have, noting that $\psi(0) = \tilde{\psi}(0)$,
\begin{align*}
\| \psi(t) - \psi(0) - t \tilde{\psi}'(0) \|_p
& \leq \| \psi(t) -  \tilde{\psi}(t)\|_p + \| \tilde{\psi}(t) - \tilde{\psi}(0) - t \tilde{\psi}'(0) \|_p \\
& \leq (n\alpha + 1) |t| \epsilon,
\end{align*}
for any $|t| < \text{min}(\mu_1, \mu_2)$, which proves the claim.

\end{proof}


The following lemma will allow us to reduce the question of differentiability of $\varphi$ defined in \eqref{defofvarphi} for an unbounded operator $A$ to the question of differentiability for a bounded operator.


\begin{lemma}\label{reducbdd}
Let $1 < p < \infty$, $A,K,Y$ be selfadjoint operators in $\mathcal{H}$ with $K$ bounded and $Y\in \mathcal{S}^p(\mathcal{H})$. Let $n \in\mbox{${\mathbb N}$}, n\geq 1$ and let $f$ be $n$-times differentiable on $\mathbb{R}$ with $f^{(n)}$ bounded. Let $m\geq 1$ be an integer. We let $E_m = \chi_{[-m,m]}(A), A_m = AE_m, K_m = E_m K E_m$ and $Y_m = E_m Y E_m$. Then
\begin{equation}\label{reducbddeq}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(f^{[n]}) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(f^{[n]}) \right](Y_m, \ldots, Y_m).
\end{equation}
\end{lemma}


\begin{proof}
We first assume that $Y\in \mathcal{S}^2(\mathcal{H})$. Note that the projection $E_m$ commutes with $A + K_m$ so that for any $g\in C_b(\mathbb{R})$ we have, by \cite[(7.25)]{KPSS},
$$
E_m g(A + K_m) = g(A_m + K_m) = g(A + K_m) E_m .
$$
From this equality, we easily deduce that for any $\phi \in C_b(\mathbb{R}) \otimes \cdots \otimes C_b(\mathbb{R})$,
\begin{equation}\label{reducbddeq2}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(\phi) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(\phi) \right](Y_m, \ldots, Y_m).
\end{equation}
By approximation, this implies that \eqref{reducbddeq2} holds true whenever $\phi$ belongs to the uniform closure of $C_b(\mathbb{R})\otimes \cdots \otimes  C_b(\mathbb{R})$, which contains in particular $C_0(\mathbb{R}^{n+1})$.

Assume now that $\phi \in C_b(\mathbb{R}^{n+1})$. Let
$(g_k)_{k\geq 1}$ be a sequence of functions in
$C_0(\mathbb{R})$ satisfying the following two properties:
$$
\forall\, k\in\mbox{${\mathbb N}$}, \quad 0\leq g_k\leq 1,
\qquad\hbox{and}\qquad\forall\, r\in \mathbb{R},\quad
g_k(r)\overset{k\to\infty}{\longrightarrow} 1.
$$
For any $k\geq 1, \phi g_k \in C_0(\mathbb{R}^{n+1})$, so the latter implies that
\begin{equation}\label{reducbddeq1}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(\phi g_k) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(\phi g_k) \right](Y_m, \ldots, Y_m).
\end{equation}
By Lebesgue's dominated convergence theorem, the properties satisfied by the sequence $(g_k)_{k\geq 1}$ imply that $(\phi g_k)_{k\geq 1}$ converges to $\phi$ for the $w^*$-topology of $L^{\infty}\left(\prod_{i=1}^n \lambda_{A + K_m}\right)$ and $L^{\infty}\left(\prod_{i=1}^n \lambda_{A_m + K_m}\right)$. Hence, by the $w^*$-continuity of multiple operator integrals, we obtain, by taking the limit on $k$ in \eqref{reducbddeq1},
\begin{equation}\label{reducbddeq3}
\left[\Gamma^{A+K_m, \ldots, A+K_m}(\phi) \right](Y_m, \ldots, Y_m) 
= \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(\phi) \right](Y_m, \ldots, Y_m).
\end{equation}

For any $k\geq 1$, let $\phi_k = \varphi_{n,g_k}$ as defined in the proof of Theorem $\ref{BddnessMOI}$. Then $(\varphi_{n,g_k})_{k\geq 1} \subset C_b(\mathbb{R}^{n+1})$ and the sequence $w^*$-converges to $f^{[n]}$ for the $w^*$-topologies of $L^{\infty}\left(\prod_{i=1}^n \lambda_{A + K_m}\right)$ and $L^{\infty}\left(\prod_{i=1}^n \lambda_{A_m + K_m}\right)$. Hence, $\phi_k$ satisfies \eqref{reducbddeq3} for any $k\geq 1$ and by the $w^*$-continuity of multiple operator integrals, we get that $\phi$ satisfies \eqref{reducbddeq}. 

In the case $1 < p < \infty$, we approximate $Y \in \mathcal{S}^p(\mathcal{H})$ by a sequence $(Y_j)_{j\geq 1}$ of elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$ and then pass to the limit in the equality
\begin{align*}
&\left[\Gamma^{A+K_m, \ldots, A+K_m}(f^{[n]}) \right]((Y_j)_m, \ldots, (Y_j)_m) \\
& \ \ \ \ = \left[\Gamma^{A_m+K_m, \ldots, A_m+K_m}(f^{[n]}) \right]((Y_j)_m, \ldots, (Y_j)_m)
\end{align*}
as $j \to \infty$, using the estimate in Theorem $\ref{BddnessMOI}$ and the fact that $(Y_j)_m \underset{j \to \infty}{\longrightarrow} Y_m$ in $\mathcal{S}^p(\mathcal{H})$.
\end{proof}

