\includegraphics[height=7cm]{01-res.pdf}
\end{center}
\caption{Leading large-order growth of the $\Phi_{(0,1)}$-sector in the resonant free-energy. The original weighted-sequence $F_k^{(0,1)}\, \frac{2\pi\mathrm{i} A^k}{\Gamma(k)}$ is plotted in red, while in blue we plot its corresponding $\mathrm{RT}_{(0,1)}(0,k,5)$. The purple line shows the value to which these sequences converge, $S^{(1)}_{\boldsymbol{e}_1} F^{(1,1)}_0 = \frac{2\sqrt{2}}{3} \approx 0.9428$.
}
\label{fig:01-res}
