Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a $K$-dense, cover-preserving and cover-reflecting functor with the covering-lifting property (for instance, a dense morphism of sites $({\cal C}, J)\to ({\cal D}, K)$ - cf. Corollary \ref{corequivalencecovliftproperty}). Suppose that $K$ is generated by a collection $K'$ of families of arrows which is stable under pullback and such that every $K'$-covering family on an object in the image of $F$ contains the image $F(R)$ under $F$ of some $J$-covering family $R$. If $F$ is $J'$-full and $J'$-faithful, where $J'$ is the Grothendieck topology generated by the sieves $R$ such that $F(R)\in K'$, then $J=J'$.	
\label{thmhyperconnectedlocalicfactorization}
	Let $F:({\cal C}, J)\to ({\cal D}, K)$ be a morphism of small-generated sites. Then the hyperconnected-localic factorization of the geometric morphism $\Sh(F)\circ \Sh(i_{K}^{s}):\Sh({\cal D}_{K}^{s}, C_{K}^{s})\simeq \Sh({\cal D}, K) \to \Sh({\cal C}, J)$ induced by $F$ can be identified with the factorization $\Sh(F^{s})\circ \Sh(i_{F}^{s})$, where
	${\cal D}_{F}^{s}$ is the full subcategory of ${\cal D}_{K}^{s}$ on the objects of the form $(F(c), S)$ for an object $c$ of $\cal C$ and a $K$-closed sieve $S$ on $F(c)$, $C_{K}^{s}|_{{\cal D}_{F}^{s}}$ is the Grothendieck topology induced by $C_{K}^{s}$ on ${\cal D}_{F}^{s}$, $i_{F}^{s}:({\cal D}_{F}^{s}, C_{K}^{s}|_{{\cal D}_{F}^{s}})\to ({\cal D}_{K}^{s}, C_{K}^{s})$ is the morphism of sites given by the canonical inclusion functor ${\cal D}_{F}^{s}\hookrightarrow {\cal D}_{K}^{s}$, and $F_{s}$ is the morphism of sites $({\cal C}, J)\to ({\cal D}_{F}^{s}, C_{K}^{s}|_{{\cal D}_{F}^{s}})$ given by the functor $F$.

	Let $F:{\cal D}\to {\cal C}$ be a continuous comorphism of sites (also regarded as a weak morphism of sites) $({\cal D}, K)\to ({\cal C}, J)$. Then:
	\begin{enumerate}[(i)]
		\item The geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ is essential, and 
		\[
		(C_{F})_{!}\cong \Sh(F)^{\ast} \dashv \Sh(F)_{\ast}\cong (C_{F})^{\ast}=D_{F}:=(-\circ F^{\textup{op}}) \dashv (C_{F})_{\ast}
		\]

		\item The weak morphisms $\Sh(F)$ and $C_{F}$ form an adjoint pair in the $2$-category of Grothendieck toposes, weak morphisms and geometric transformations between them ($\Sh(F)$ being the right adjoint and $C_{F}$ the left adjoint); indeed, $\Sh(F)^{\ast}$ is left adjoint to $(C_{F})^{\ast}$. 

		In particular, if $F$ is a morphism of sites then the geometric morphisms $\Sh(F)$ and $C_{F}$ form an adjoint pair in the $2$-category $\mathfrak{Btop}$ of Grothendieck toposes, geometric morphisms and geometric transformations. 

		\item The weak morphism $\Sh(F):\Sh({\cal C}, J) \to \Sh({\cal D}, K)$ is local if and only if $C_{F}$ is an inclusion, that is, if and only if $F$ is $K$-faithful and $K$-full. 

		\item The canonical geometric transformation 
		\[
		1_{\Sh({\cal D}, K)} \to \Sh(F)\circ C_{F}
		\] 
		(given by the unit of the adjunction between $\Sh(F)$ and $C_{F}$  as in (ii)) is an isomorphism if (and only if) $F$ is $K$-faithful and $K$-full. In this case, if $F$ is moreover a morphism of sites $({\cal D}, K)\to ({\cal C}, J)$, the morphisms $C_{F}$ and $\Sh(F)$ realize the topos $\Sh({\cal D}, K)$ as a (coadjoint\footnote{Recall that a retract $(i, r)$ in a $2$-category (in the sense of section B1.1 of \cite{El}), where $r\circ i\cong 1$, is said to be \emph{coadjoint} if $i$ is left adjoint to $r$.}) retract of $\Sh({\cal C}, J)$ in the $2$-category $\mathfrak{Btop}$.		
	\end{enumerate}

