	Let $({\cal C}, J)$ be a site and $F:{\cal C}\to {\cal D}$ a functor. Let us suppose that $\tilde{K}$ is a Grothendieck topology on $\cal D$ generated by a pullback-stable family of sieves $K$ on $\cal D$. Then, if for every sieve $R$ in $K$ on an object of the form $F(c)$ there is a $J$-covering sieve $S$ on $c$ such that $F(S)\subseteq R$, $F$ is a comorphism of sites $({\cal C}, J)\to ({\cal D}, \tilde{K})$. 
\label{lemmafibrations}
	Let $p:{\cal C}\to {\cal D}$ be a fibration. Then
	\begin{enumerate}[(i)]
		\item For any presieve $P$  in $\cal C$, we have $\overline{p(\langle P\rangle )}^{i}=\langle p(P)\rangle $. 

		\item For any presieve $R$ on an object $p(c)$ in $\cal D$, $\langle S^{p}_{\overline{R}^{i}}\rangle =S^{p}_{\langle R\rangle }$. 

		\item For any presieve $P$ in $\cal C$, $S^{p}_{\overline{p(P)}^{i}}=\overline{P^{\textup{cart}}}^{v}$. In particular (cf. also (ii)), if $P$ entirely consists of cartesian arrows (whence $P^{\textup{cart}}=\overline{P}^{i}$) then $\langle S^{p}_{\overline{p(P)}^{i}}\rangle =S^{p}_{\langle p(P)\rangle }=\langle P\rangle $. 

		\item For any presieve $R$ on an object $p(c)$ in $\cal D$, $\overline{R}^{i}=\overline{p(S^{p}_{\overline{R}^{i}})}^{i}$; in particular, $\langle R\rangle =\langle p(S^{p}_{\overline{R}^{i}})\rangle $, so, if $R$ is a sieve, then $R=\langle p(S^{p}_{R})\rangle $. 

		\item For any sieve $R$ on an object $p(c)$ in $\cal D$, $S^{p}_{R}=\langle (S^{p}_{R})^{\textup{cart}}\rangle $.

		\item For any presieve $P$ on an object $c$ of $\cal C$ entirely consisting of cartesian arrows, and any arrow $f:c'\to c$ in $\cal C$, 
		\[
		\langle p(f^{\ast}(\langle P\rangle ))\rangle =p(f)^{\ast}(\langle p(P)\rangle ).
		\] 

		\item For any presieve $P$ on an object $c$ of $\cal C$ entirely consisting of cartesian arrows, the sieves of the form $f^{\ast}(\langle P\rangle )$, for an arrow $f:c'\to c$ in $\cal C$, have the property that they contain all the cartesian images of their arrows.
	\end{enumerate}	
\label{lemmainducedcanonicaltopology}
	Let $\cal C$ be a separating set for a Grothendieck topos $\cal E$ and  $S$ a sieve in $\cal C$ (regarded as a full subcategory of $\cal E$) such that the colimit in $\cal E$ of the diagram $D_{\overline{S}}$, where $\overline{S}$ is the sieve generated by $S$ in $\cal E$, lies in $\cal C$. Then the following conditions are equivalent:
