		\item $S$ is universally effective-epimorphic in $\cal C$.
	\end{enumerate} 
\label{lemmacartesianrelmono}
	Let $C:{\cal D}\to {\cal D}'$ be a fibration.
	\begin{enumerate}[(i)]
		\item Let $f:d\to d'$ be a cartesian arrow. Then for any parallel arrows $h, k:d''\to d$, if $C(f\circ h)=C(f\circ k)$ then $h=k$.

		\item Every arrow of $\cal D$ can be functorially (and uniquely up to unique isomorphism) factored as a vertical arrow followed by a cartesian arrow.

		\item Let $A:{\cal C}\to {\cal D}$ be a functor and $S$ a sieve in $\cal C$ which supports a functorial factorization $g=g_{c}\circ g_{v}$ for any arrow $g$ in $S$, such that $g_{c}$ lies in $S$, $A(g_{c})$ is a cartesian arrow and $A(g_{v})$ is a vertical arrow. [Note that if $B:{\cal C}\to {\cal D'}$ is a fibration and $A$ is a morphism of fibrations from $B$ to $C$, then every sieve $S$ containing the cartesian images of all its arrows admits such a functorial factorization of arrows.] Then any two objects $(f:c' \to c, \alpha:d\to A(c'))$ and $(g:c''\to c, \beta:d\to A(c''))$ of the category $(d\downarrow D^{A}_{S})$ belong to the same connected component if and only if the objects $(f:c' \to c, C(\alpha):C(d)\to C(A(c')))$ and $(g:c''\to c, C(\beta):C(d)\to C(A(c'')))$ of the category $(C(d)\downarrow D^{C\circ A}_{S})$ belong to the same connected component.
	\end{enumerate}	 
\label{lemmaslicetoposclassification}
	Let $A$ be an object of a topos $\cal E$. Then, for any topos $\cal F$, the geometric morphisms $g:{\cal F}\to {\cal E}\slash A$ correspond bijectively to the pairs $(f, \alpha)$, where $f$ is a geometric morphism ${\cal F}\to {\cal E}$ and $\alpha$ is an arrow $1_{\cal F}\to f^{\ast}(A)$ in $\cal F$ (naturally in $A$ and $\cal F$). More specifically:	
	\begin{itemize}
		\item given a geometric morphism $g:{\cal F}\to {\cal E}\slash A$, the pair associated with it is $(U_{A}\circ g, \alpha_{g})$, where $\alpha_{g}:1_{\cal F}\to g^{\ast}(U_{A}^{\ast}(A))$ is the arrow $g^{\ast}(\Delta_{A})$, where $\Delta_{A}:1_{{\cal E}\slash A}\to U_{A}^{\ast}(A)$ is the arrow given by the diagonal $A\to A\times A$ on the object $A$; 

		\item given a pair $(f, \alpha)$ consisting of a geometric morphism $f:{\cal F}\to {\cal E}$ and an arrow $\alpha:1_{\cal F} \to f^{\ast}(A)$, the geometric morphism $f_{\alpha}:{\cal F}\to {\cal E}\slash A$ corresponding to the pair $(f, \alpha)$ is defined by setting, for any object $[x:X\to A]$ of ${\cal E}\slash A$, $f_{\alpha}^{\ast}([x])\mono f^{\ast}(X)$ equal to the equalizer of the arrows $\alpha\circ !_{f^{\ast}(X)}$ and $f^{\ast}(x)$ (where $!_{f^{\ast}(X)}$ is the unique arrow $f^{\ast}(X)\to 1_{\cal F}$).
	\end{itemize} 		 
