\begin{corollary}\label{corfullsubcategorytopos}
	Let $({\cal C}, J)$ be a small-generated site. Then the full subcategory $a_{J}({\cal C})$ of $\Sh({\cal C}, J)$ on the objects of the form $l(c)$ for $c\in {\cal C}$ is equivalent to the category ${\cal C}_{J}$ defined as follows: 
	\begin{itemize}
		\item the objects of ${\cal C}_{J}$ are the objects of $\cal C$; 

		\item the arrows $c\to d$ are the collections $R$ of pairs of arrows $(f:e\to c,g:e\to d)$ where $e$ varies among the objects of $\cal C$ (we write $(f, g)\in R(e)$ to mean that $(f, g)\in R$ and $\textup{dom}(f)=\textup{dom}(g)=e$) satisfying the following properties:

		\begin{enumerate}[(i)]
			\item for any arrow $k:e'\to e$, if $(f,g)\in R$ then $(f\circ k, g\circ k)\in R$; 

			\item for any $e\in {\cal C}$ and any arrows $x:e\to c, y:e\to d$, if $\{f:e'\to e \mid\ (x\circ f, y\circ f)\in R\}\in J(e)$ then $(x, y)\in R$; 

			\item for any $e\in {\cal C}$ and any $(x, y), (x', y')\in R(e)$, if $x=x'$ then $\{f:e'\to e \mid y\circ f=y'\circ f\}\in J(e)$;

			\item for any $e\in {\cal C}$ and any $x:e\to c$, $\{f:e'\to e \mid \exists y:e'\to d \text{ such that } (x\circ f, y)\in R(e') \}\in J(e)$;
		\end{enumerate}

		\item the composite $S\ast R$ of two arrows $R:c\to d$ and $S:d\to a$ is given by the following formula: 
		\begin{equation*}\begin{split}
		(S\ast R)(e)&=\{(x:e\to c, z:e\to a) \mid \{f:e'\to e \mid \exists y:e'\to d\, \\
		& \quad\quad(x\circ f, y)\in R(e')\textup{ and } (y, z\circ f)\in S(e')\}\in J(e) \}
		\end{split}\end{equation*}
		for any $e\in {\cal C}$. 
	\end{itemize}

	One half of the equivalence ${\cal C}_{J}\simeq a_{J}({\cal C})$ is given by the functor ${\cal C}_{J}\to a_{J}({\cal C})$ acting on objects by sending any $c\in {\cal C}_{J}$ to $l(c)$ and any arrow $R:c\to c'$ in ${\cal C}_{J}$ to the arrow $l(c)\to l(c')$ in $a_{J}({\cal C})$ whose graph is $a_{J}(R)$.   

\end{corollary}\qed

\begin{corollary}\label{corfact}
	Let $A:{\cal C}\to {\cal E}$ be a functor from an essentially small category $\cal C$ to a Grothendieck topos $\cal E$, and $J$ be a Grothendieck topology on $\cal C$. Then the following conditions are equivalent:
	\begin{enumerate}[(i)]
		\item The weak morphism $(L_{A} \dashv R_{A})$ factors through the canonical geometric inclusion $i:\Sh({\cal C}, J)\hookrightarrow [{\cal C}^{\textup{op}}, \Set]$; 

		\item The functor $R_{A}$ takes values in $\Sh({\cal C}, J)$;

		\item The functor $L_{A}$ factors (necessarily uniquely up to isomorphism) through the associated sheaf functor $a_{J}:[{\cal C}^{\textup{op}}, \Set]\to \Sh({\cal C}, J)$.
	\end{enumerate} 
\end{corollary}\qed

\begin{proposition}\label{propcharcanonicalfunctors}
	Let $({\cal C}, J)$ and $({\cal D}, K)$ be small-generated sites. Then a functor $A:{\cal C}\to {\cal D}$ is $(J, K)$-continuous if and only if it is cover-preserving (i.e., sends $J$-covering families to $K$-covering ones) and for any $J$-covering sieve $S$ on an object $c$ and any commutative square of the form
	\[
	\xymatrix{
		d \ar[r] \ar[d]  & A(c') \ar[d]^{A(f)} \\
		A(c'') \ar[r]^{A(g)} & A(c),
	} 
	\]	
	where $f:c'\to c$ and $g:c''\to c$ are arbitrary arrows of $S$, there is a $K$-covering family $\{d_{i}\to d \mid i\in I\}$ such that for each $i\in I$, the composites $d_{i}\to A(c')$ and $d_{i}\to A(c'')$ belong to the same connected component of the category $(d_{i}\downarrow D^{A}_{S})$.  
\end{proposition}\qed

\begin{proposition}
	Any weak morphism $F:({\cal C}, J)\to ({\cal D}, K)$ of small-generated sites induces a weak geometric morphism $\Sh(F):\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ such that the following diagram commutes: 
	$$
	\xymatrix{
		{\mathcal C} \ar[r]^F \ar[d]_{l} &{\cal D} \ar[d]^{l'} \\
		\Sh({\cal C}, J) \ar[r]^{\Sh(F)^{\ast}} & \Sh({\cal D}, K)
	}
	$$ 

	Conversely, any weak geometric morphism $f=(f^{\ast}\dashv f_{\ast})$ such that $f^{\ast}\circ l$ factors through $l'$ is induced by a (necessarily unique, if $K$ is subcanonical) weak morphism of sites $({\cal C}, J)\to ({\cal D}, K)$.    
\end{proposition}\qed

\begin{proposition}\label{reminducedtopology}
	Let $f:{\cal E}\to [{\cal C}^{\textup{op}}, \Set]$ be a geometric morphism (equivalently, a flat functor $F:{\cal C}\to {\cal E}$). Then there exists a Grothendieck topology $J_{f}$ (resp. $J_{F}$) on $\cal C$, called the Grothendieck topology \emph{induced} by $f$ (resp. $F$) whose covering sieves are precisely the sieves which are sent by $f^{\ast}$ (resp. by $F$) to epimorphic families in $\cal E$. This applies in particular to a morphism of small-generated sites $G:({\cal C}, J)\to ({\cal D}, K)$, yielding a Grothendieck topology $J_{G}$ on $\cal C$ whose covering sieves are exactly those whose image under $G$ are $K$-covering families (cf. Theorem \ref{Morphismsmaalgenerated}(ii)).	  
\end{proposition}\qed

\begin{proposition}
The geometric morphism $C_{F}:\Sh({\cal D}, K)\to \Sh({\cal C}, J)$ induced by a comorphism of sites $F:({\cal D}, K)\to ({\cal C}, J)$ is an equivalence if and only if the following conditions are satisfied:
\begin{enumerate}[(i)]
	\item for every object $d$ of $\cal D$ there exist a $K$-covering sieve $\{g_{i}:d_{i}\to d \mid i\in I\}$ on $d$ and  relations $R_{i}$ from $\textup{Hom}_{\cal C}(F(-),F(d_{i}))$ to $\textup{Hom}_{\cal D}(-,d)$ satisfying all the conditions of Lemma \ref{lemmacomorphisminclusion} but condition (iv); 

	\item $J=K^{F}$, that is, if a sieve $S$ on an object $c\in {\cal C}$ satisfies the property that for every object $d$ of $\cal D$ and arrow $x:F(d)\to c$ there exists a $K$-covering sieve $T$ on $d$ such that for every $g\in T$, $x\circ F(g)\in S$ then $S$ is $J$-covering;  

	\item for every object $c$ of $\cal C$ and any set $A$ of arrows of the form $x:F(d)\to c$ for an object $d$ of $\cal D$ which is functorial (in the sense that if $x\in A$ then $x\circ F(g)\in A$ for any arrow $g:d'\to d$ in $\cal D$) and $K$-closed (in the sense that for any $K$-covering sieve $T$ on $d$, if $x\circ F(t)\in A$ for every $t\in T$ then $x\in A$) there exists a ($J$-closed) sieve $S$ on $c$ such that 	
	\begin{equation*}\begin{split}
	A &= \{x:F(d)\to c \mid d\in {\cal D}\textup{, } \{t:\textup{dom}(t)\to d \mid x\circ F(t)\in S\}\in K(d)\}. 
	\end{split}\end{equation*}
\end{enumerate}	
	In particular, if $F$ is $K$-full and $K$-faithful and $J$-dense then $C_{F}$ is an equivalence. 
\end{proposition}\qed

