	\[
	z_{A}:(C_{A})_{!} \circ a_{J} \to a_{K}\circ \textup{Lan}_{A^{\textup{op}}}
	\]
	defined above, is an isomorphism.

	Let $F:{\cal C}\to {\cal E}$ and $G:{\cal D}\to {\cal E}$ be fibrations and $H$ a morphism of fibrations $F\to G$, that is, a functor $H:{\cal C}\to {\cal D}$ which sends cartesian arrows to cartesian arrows and such that there is an isomorphism $G\circ H\cong F$. Then $H$ is $(M^{F}_{L}, M^{G}_{L})$-continuous.   	
\label{corliftalongdiscretefibration}
